/// 菜单的像素尺寸（本机 Excel 365 实测：宽 246、行高 26、图标 16）
const CTX_W: f32 = 246.0;
const CTX_ROW_H: f32 = 26.0;
const CTX_STRIP_H: f32 = 34.0;

fn ctx_menu_height(rows: &[CtxRow]) -> f32 {
    let mut h = 4.0;
    for r in rows {
        h += if r.strip {
            CTX_STRIP_H
        } else if r.is_sep() {
            8.0
        } else {
            CTX_ROW_H
        };
    }
    h + 4.0
}

fn ctx_row_focusable(rows: &[CtxRow], i: usize) -> bool {
    rows.get(i)
        .map(|r| !r.is_sep() && !r.strip && (r.act.is_some() || !r.children.is_empty()))
        .unwrap_or(false)
}

/// 上下移动键盘焦点；跳过分隔线和粘贴图标条，首尾循环。
fn next_ctx_row(rows: &[CtxRow], from: usize, dir: i32) -> Option<usize> {
    let n = rows.len();
    if n == 0 {
        return None;
    }
    let mut i = from as i32;
    for _ in 0..n {
        i = (i + dir).rem_euclid(n as i32);
        if ctx_row_focusable(rows, i as usize) {
            return Some(i as usize);
        }
    }
    None
}

fn ctx_row_top(rows: &[CtxRow], idx: usize, start: f32) -> f32 {
    let mut y = start;
    for r in rows.iter().take(idx) {
        y += if r.strip {
            CTX_STRIP_H
        } else if r.is_sep() {
            8.0
        } else {
            CTX_ROW_H
        };
    }
    y
}

/// 状态栏统计累加器（UI-25）：计数=非空格；数值统计只吃 Number。
#[derive(Default, Clone, Copy)]
pub(crate) struct StatsAcc {
    pub count: u64,
    pub nums: u64,
    pub sum: f64,
    pub min: f64,
    pub max: f64,
}

impl StatsAcc {
    fn add(&mut self, v: Option<f64>) {
        self.count += 1;
        if let Some(v) = v {
            if self.nums == 0 {
                self.min = v;
                self.max = v;
            } else {
                self.min = self.min.min(v);
                self.max = self.max.max(v);
            }
            self.nums += 1;
            self.sum += v;
        }
    }

    pub(crate) fn text(&self, mask: u8) -> String {
        fn num(v: f64) -> String {
            let mut s = format!("{v:.4}");
            while s.contains('.') && (s.ends_with('0') || s.ends_with('.')) {
                s.pop();
            }
            if s == "-0" {
                s = "0".into();
            }
            s
        }
        let mut parts: Vec<String> = Vec::new();
        if mask & 1 != 0 && self.nums > 0 {
            parts.push(format!("平均值: {}", num(self.sum / self.nums as f64)));
        }
        if mask & 2 != 0 && self.count > 0 {
            parts.push(format!("计数: {}", self.count));
        }
        if mask & 4 != 0 && self.nums > 0 {
            parts.push(format!("数值计数: {}", self.nums));
        }
        if mask & 8 != 0 && self.nums > 0 {
            parts.push(format!("求和: {}", num(self.sum)));
        }
        if mask & 16 != 0 && self.nums > 0 {
            parts.push(format!("最小值: {}", num(self.min)));
        }
        if mask & 32 != 0 && self.nums > 0 {
            parts.push(format!("最大值: {}", num(self.max)));
        }
        parts.join("    ")
    }
}

/// UI-25：统计要排除的行 —— 手动隐藏、分级/组合隐藏、当前筛选隐藏。
///
/// 口径来自本机 Excel 16.0 (Build 20326) 状态栏 UIA 实测
/// （`implementation-evidence/ui25-hidden-marker.txt`）：
/// - 手动隐藏第 2 行后选 A1:A4（1,2,text,4）：计数 3、求和 5、平均 2.5（第 2 行排除）；
/// - 折叠分级隐藏第 7-8 行后选 A6:A8（7,8）：计数 1、求和 7（同样排除）；
/// - 手动隐藏 B 列后选 A1:B1（1,100）：计数 2、求和 101（隐藏列**仍计入**）。
///
/// 隐藏列因此不参与过滤：Excel 状态栏按行隐藏生效，和 SUBTOTAL 的行语义一致。
pub(crate) fn stats_hidden_rows(sheet: &sheetcore::model::Sheet) -> std::collections::HashSet<u32> {
    let mut skip = (*sheet.hidden_rows).clone();
    skip.extend(sheet.hidden_rows_user.iter().copied());
    if skip.is_empty() {
        if let Some(f) = &sheet.filter {
            skip.extend(f.hidden_rows(sheet));
        }
    }
    skip
}

/// Visit each selected, non-empty cell once. Rows from iter_rect are ordered, so
/// filter comparisons and formatted lookup values are reused across each row.
fn visit_stats_values(
    sheet: &sheetcore::model::Sheet,
    rects: &[(u32, u32, u32, u32)],
    cancel: Option<&std::sync::atomic::AtomicBool>,
    mut visit: impl FnMut(Option<f64>),
) {
    let filter_check_needed = sheet.hidden_rows.is_empty()
        && sheet
            .filter
            .as_ref()
            .is_some_and(|f| !f.allows.is_empty() || !f.criteria.is_empty());
    let row_hidden = |r: u32| -> bool {
        if sheet.rows.size(r) <= 0.0
            || sheet.hidden_rows.contains(&r)
            || sheet.hidden_rows_user.contains(&r)
        {
            return true;
        }
        if filter_check_needed {
            if let Some(f) = &sheet.filter {
                let (fr1, fc1, fr2, fc2) = f.range;
                if r > fr1 && r <= fr2 {
                    for (col, allowed) in &f.allows {
                        if *col >= fc1 && *col <= fc2 {
                            let v = sheet.get(r, *col).map(|c| c.value.display()).unwrap_or_default();
                            if !allowed.contains(&v) {
                                return true;
                            }
                        }
                    }
                    for (col, crit) in &f.criteria {
                        if *col >= fc1 && *col <= fc2 {
                            let v = sheet.get(r, *col).map(|c| c.value.display()).unwrap_or_default();
                            if !crit.matches(&v) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        false
    };

    for (i, &rect) in rects.iter().enumerate() {
        let mut previous_row = None;
        let mut hidden = false;
        let mut add = |r, c, cell: &sheetcore::Cell| {
            if previous_row != Some(r) {
                previous_row = Some(r);
                hidden = row_hidden(r);
            }
            if !hidden && !rects[..i].iter().any(|&(r1, c1, r2, c2)| {
                r1 <= r && r <= r2 && c1 <= c && c <= c2
            }) {
                visit(match &cell.value {
                    Value::Number(n) => Some(*n),
                    _ => None,
                });
            }
        };
        let (r1, c1, r2, c2) = rect;
        let area = (u64::from(r2.saturating_sub(r1)) + 1)
            * (u64::from(c2.saturating_sub(c1)) + 1);
        if area <= 4096 {
            for r in r1..=r2 {
                for c in c1..=c2 {
                    if let Some(cell) = sheet.get(r, c).filter(|cell| !cell.is_blank()) {
                        add(r, c, cell);
                    }
                }
            }
        } else {
            for (key, cell) in sheet.iter_rect(rect) {
                if cancel.is_some_and(|c| c.load(std::sync::atomic::Ordering::Relaxed)) {
                    return;
                }
                add(key.row, key.col, cell);
            }
        }
        if cancel.is_some_and(|c| c.load(std::sync::atomic::Ordering::Relaxed)) {
            return;
        }
    }
}

#[cfg(test)]
pub(crate) fn collect_stats_values(
    sheet: &sheetcore::model::Sheet,
    rects: &[(u32, u32, u32, u32)],
) -> Vec<Option<f64>> {
    let mut vals = Vec::new();
    visit_stats_values(sheet, rects, None, |v| vals.push(v));
    vals
}

/// 多选区统计入口（状态栏用）；隐藏行口径见 [`stats_hidden_rows`]。
pub(crate) fn status_stats_rects(
    sheet: &sheetcore::model::Sheet,
    rects: &[(u32, u32, u32, u32)],
    mask: u8,
) -> String {
    let mut acc = StatsAcc::default();
    visit_stats_values(sheet, rects, None, |v| acc.add(v));
    acc.text(mask)
}

/// 状态栏统计文本（C25）：单矩形兼容入口；按位掩码输出 Excel 同名项。
pub(crate) fn status_stats_text(
    sheet: &sheetcore::model::Sheet,
    rect: (u32, u32, u32, u32),
    mask: u8,
) -> String {
    status_stats_rects(sheet, &[rect], mask)
}

#[derive(Clone, PartialEq)]
struct StatsKey {
    sheet: u64,
    doc_gen: u64,
    epoch: u64,
    cells: u64,
    rows: u64,
    visibility: (u64, u64),
    rects: Vec<(u32, u32, u32, u32)>,
    mask: u8,
}

struct FrameProbe {
    limit: usize,
    previous_start: Option<std::time::Instant>,
    builds: Vec<f64>,
    intervals: Vec<f64>,
}

impl FrameProbe {
    fn from_env() -> Option<Self> {
        let limit = std::env::var("SC_FRAME_LOG").ok()?.parse().ok()?;
        (limit > 0).then(|| Self { limit, previous_start: None, builds: Vec::new(), intervals: Vec::new() })
    }

    fn sample(&mut self, start: std::time::Instant) -> bool {
        let Some(previous) = self.previous_start.replace(start) else { return false };
        self.intervals.push((start - previous).as_secs_f64() * 1000.0);
        self.builds.push(start.elapsed().as_secs_f64() * 1000.0);
        if self.builds.len() < self.limit { return false; }
        for (tag, label, samples) in [
            ("cpu", "帧 update() 耗时", &mut self.builds),
            ("frame", "帧相邻 update() 开始间隔", &mut self.intervals),
        ] {
            let avg = samples.iter().sum::<f64>() / samples.len() as f64;
            let (n, p50, p95, max) = probe_stats(samples);
            eprintln!("[{tag}] {n} {label}：avg={avg:.2}ms p50={p50:.2}ms p95={p95:.2}ms max={max:.2}ms");
        }
        true
    }
}

struct StatsJob {
    key: StatsKey,
    done: std::sync::mpsc::Receiver<String>,
    cancel: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

impl Drop for StatsJob {
    fn drop(&mut self) {
        self.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
    }
}

impl SheetApp {
    fn selection_stats_label(
        &mut self, ctx: &egui::Context, rects: &[(u32, u32, u32, u32)], area: u64, mask: u8,
    ) -> String {
        use std::sync::atomic::Ordering;
        let sheet = self.wb.sheet(self.sheet_idx);
        let key = StatsKey {
            sheet: sheet.identity, doc_gen: self.doc_gen, epoch: self.wb_epoch,
            cells: sheet.cell_revision(), rows: sheet.rows.revision(),
            visibility: (sheet.hidden_rows.revision(), sheet.hidden_rows_user.revision()),
            rects: rects.to_vec(), mask,
        };
        // A moving selection can supersede a worker on every frame. Keep at most
        // one worker and discard results for a superseded selection or document.
        if let Some(job) = &self.stats_job {
            if job.key != key {
                job.cancel.store(true, Ordering::Relaxed);
            }
            match job.done.try_recv() {
                Ok(result) => {
                    if !job.cancel.load(Ordering::Relaxed) && job.key == key {
                        self.stat_cache = Some((key.clone(), result));
                    }
                    self.stats_job = None;
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => self.stats_job = None,
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }
        if mask == 0 || area == 0 { return String::new(); }
        if let Some((_, result)) = self.stat_cache.as_ref().filter(|(k, _)| *k == key) {
            return result.clone();
        }
        if area <= 4096 {
            let result = status_stats_rects(sheet, rects, mask);
            self.stat_cache = Some((key, result.clone()));
            return result;
        }
        if self.stats_job.is_none() {
            let snapshot = sheet.selection_stats_snapshot();
            let rects = rects.to_vec();
            let wake = ctx.clone();
            let (tx, done) = std::sync::mpsc::channel();
            let cancel = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
            let stop = cancel.clone();
            std::thread::spawn(move || {
                let mut acc = StatsAcc::default();
                visit_stats_values(&snapshot, &rects, Some(&stop), |v| acc.add(v));
                let _ = tx.send(acc.text(mask));
                wake.request_repaint();
            });
            self.stats_job = Some(StatsJob { key, done, cancel });
        }
        "计算中…".into()
    }
}

/// UI-25 状态栏统计菜单：六项开关 + 复制当前结果。
fn stats_mask_menu(ui: &mut egui::Ui, mask: &mut u8, stat: &str) {
    for (bit, name) in [
        (1u8, "平均值"),
        (2, "计数"),
        (4, "数值计数"),
        (8, "求和"),
        (16, "最小值"),
        (32, "最大值"),
    ] {
        let mut on = *mask & bit != 0;
        if ui.checkbox(&mut on, name).changed() {
            if on {
                *mask |= bit;
            } else {
                *mask &= !bit;
            }
        }
    }
    ui.separator();
    if ui
        .add_enabled(!stat.is_empty() && stat != "计算中…", egui::Button::new("复制统计结果"))
        .clicked()
    {
        ui.ctx().copy_text(stat.to_string());
        ui.close_menu();
    }
}

