    /// 无界面自检：按 XML 命令直接触发一次（截图验证功能区连线用）
    fn ribbon_probe(&mut self, ctx: &egui::Context) {
        if self.ribbon_probe_done || self.tasks.open_rx.is_some() {
            return;
        }
        if let Ok(v) = std::env::var("SC_RIBBON_SEL") {
            let n: Vec<u32> = v
                .split(',')
                .filter_map(|x| x.trim().parse().ok())
                .collect();
            if n.len() == 4 {
                self.sel = (n[0], n[1]);
                self.sel_end = (n[2], n[3]);
            }
        }
        if let Ok(list) = std::env::var("SC_RIBBON_ACTION") {
            self.ribbon_probe_done = true;
            for one in list.split(';').filter(|s| !s.is_empty()) {
                self.ribbon_action(one, ctx);
                if std::env::var("SC_RIBBON_LOG").is_ok() {
                    eprintln!(
                        "[ribbon] 动作 {one} → 状态「{}」 表格 {} 个",
                        self.status,
                        self.wb.sheet(self.sheet_idx).tables.len()
                    );
                }
            }
        }
        if std::env::var("SC_RIBBON_CHART").is_ok() {
            self.ribbon_probe_done = true;
            if let Some((i, _)) = self
                .wb
                .sheets
                .iter()
                .enumerate()
                .find(|(_, sh)| !sh.charts.is_empty())
            {
                self.sheet_idx = i;
                self.chart_sel = Some(0);
                self.ribbon_tab = 101;
            } else {
                eprintln!("[ribbon] 整簿没有图表");
            }
        }
        if let Ok(id) = std::env::var("SC_RIBBON_ITEMS") {
            self.ribbon_probe_done = true;
            if let Some(items) = self.ribbon.find_dropdown(&id) {
                self.ribbon_popup = Some(ribbon::ui::Popup {
                    kind: ribbon::ui::PopupKind::Items(items),
                    pos: egui::pos2(200.0, 200.0),
                    opened_at: 0.0,
                });
            } else {
                eprintln!("[ribbon] 找不到下拉 {id}");
            }
        }
        if let Ok(m) = std::env::var("SC_RIBBON_MENU") {
            self.ribbon_probe_done = true;
            if std::env::var("SC_SEED_CLIP").is_ok() && self.clip.is_none() {
                let mut cells = Vec::new();
                for r in 0..=1u32 {
                    let mut row = Vec::new();
                    for c in 0..=1u32 {
                        let cell = self.wb.sheet(self.sheet_idx).get(r, c).cloned().unwrap_or_else(|| Cell {
                            value: Value::Text(cell_name(r, c).into()),
                            formula: None,
                        });
                        let st = self.wb.sheet(self.sheet_idx).style_of(r, c);
                        row.push((cell, st));
                    }
                    cells.push(row);
                }
                self.clip = Some(Clip { deferred: None,
                    sheet: self.sheet_idx,
                    source_rows: None,
                    rect: (0, 0, 1, 1),
                    cells,
                    merges: Vec::new(),
                    cut: false,
                });
            }
            let (menu_id, pos) = if let Some((id_part, xy)) = m.split_once('@') {
                let mut parts = xy.split(',').filter_map(|s| s.trim().parse::<f32>().ok());
                let x = parts.next().unwrap_or(200.0);
                let y = parts.next().unwrap_or(184.0);
                (id_part.to_string(), egui::pos2(x, y))
            } else {
                let p = match m.as_str() {
                    "PasteMenu" => egui::pos2(12.0, 184.0),
                    "ConditionalFormatting" => egui::pos2(670.0, 184.0),
                    "FormatAsTable" => egui::pos2(730.0, 184.0),
                    "FormatMenu" => egui::pos2(920.0, 184.0),
                    "FillMenu" => egui::pos2(980.0, 158.0),
                    "FindSelect" => egui::pos2(1130.0, 184.0),
                    "ChartMenu" => egui::pos2(260.0, 184.0),
                    _ => egui::pos2(200.0, 184.0),
                };
                (m, p)
            };
            if let Some(menu) = self.ribbon.find_menu(&menu_id) {
                self.ribbon_popup = Some(ribbon::ui::Popup {
                    kind: ribbon::ui::PopupKind::Menu(menu),
                    pos,
                    opened_at: 0.0,
                });
                if let Ok(sub_id) = std::env::var("SC_RIBBON_SUB") {
                    if let Some(sub_menu) = self.ribbon.find_menu(&sub_id) {
                        self.ribbon_sub = Some((
                            menu_id,
                            sub_menu,
                            egui::pos2(pos.x + 220.0, pos.y + 4.0),
                        ));
                    }
                }
            } else {
                eprintln!("[ribbon] 找不到菜单 {menu_id}");
            }
        }
    }

    /// 无界面自检：编辑 → 撤销 → 重做 → 格式撤销
    fn undo_probe(&mut self) {
        if std::env::var("SC_UNDO_TEST").is_err() || self.tasks.open_rx.is_some() || self.probe_done {
            return;
        }
        self.probe_done = true;
        let (r, c) = (1u32, 1u32);
        let orig = self
            .wb
            .sheet(self.sheet_idx)
            .get(r, c)
            .map(|x| x.value.display())
            .unwrap_or_default();
        // 1) 编辑
        self.sel = (r, c);
        self.editing = Some(EditState::new("999".into()));
        self.commit_edit(None);
        let after_edit = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        // 2) 撤销
        self.do_undo(false);
        let after_undo = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        // 3) 重做
        self.do_undo(true);
        let after_redo = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        // 4) 格式：加粗后撤销
        self.sel = (r, c);
        self.apply_style(|st| st.bold = !st.bold);
        let bold_after = self.wb.styles.get(self.wb.sheet(self.sheet_idx).style_of(r, c)).bold;
        self.do_undo(false);
        let bold_undo = self.wb.styles.get(self.wb.sheet(self.sheet_idx).style_of(r, c)).bold;
        // 5) 清除后撤销
        self.sel = (r, c);
        self.wb
            .sheet_mut(self.sheet_idx)
            .set(r, c, Cell { value: Value::Empty, formula: None });
        self.undo.push(sheetcore::undo::Action {
            label: "清除".into(),
            merges: None,
            snap_before: None,
            snap_after: None,
            by_site: 0,
            pictures: None,
            shapes: None,
            deltas: vec![sheetcore::undo::CellDelta {
                sheet: self.sheet_idx,
                row: r,
                col: c,
                before: Cell { value: Value::Number(7.0), formula: None },
                after: Cell { value: Value::Empty, formula: None },
                before_style: 0,
                after_style: 0,
            }],
            focus: (self.sheet_idx, r, c),
            refresh_sizes: None,
        });
        self.do_undo(false);
        let clear_undo = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        eprintln!(
            "[undo] 原值={orig} 编辑后={after_edit} 撤销后={after_undo} 重做后={after_redo} 加粗={bold_after} 撤销后={bold_undo} 清除撤销={clear_undo} 深度={:?}",
            self.undo.depth()
        );
    }

    /// 把远端做过的结构改动套到当前工作簿上。
    /// 文件每次重新读入（Loaded/Recalced）都会得到「未改结构」的版本，
    /// 所以换过一次就要从头再套一遍。
    fn sync_history(&mut self) {
        if self.struct_history.is_empty() {
            return;
        }
        if self.wb_epoch != self.history_last_epoch {
            self.history_planted = 0;
            self.history_last_epoch = self.wb_epoch;
        }
        if self.history_planted >= self.struct_history.len() {
            return;
        }
        let items: Vec<(usize, sheetcore::structural::Structural)> =
            self.struct_history[self.history_planted..].to_vec();
        for (sheet, op) in items.iter() {
            if *sheet < self.wb.sheets.len() {
                // 格子由快照给（已经是新坐标），这里只搬合并/条件格式等结构
                self.wb
                    .sheet_mut(*sheet)
                    .apply_structural_structure_only(op);
            }
        }
        self.history_planted = self.struct_history.len();
        self.doc_gen = self.doc_gen.wrapping_add(1);
    }

    fn lock_now(&self) -> u64 {
        self.t0.elapsed().as_millis() as u64
    }

    /// 这个格子现在能不能由我编辑
    fn lock_holder(&self, row: u32, col: u32) -> Option<String> {
        self.lock_holder_on(self.sheet_idx, row, col)
    }

    fn lock_holder_on(&self, sheet: usize, row: u32, col: u32) -> Option<String> {
        // 离线时也认本地租约表：表里已有他人持有时，不能因为暂时没连网就放行
        let site = self.net.as_ref().map(|n| n.site).unwrap_or(0);
        if self.locks.is_locked_by_other(sheet, row, col, site) {
            self.locks
                .holder(sheet, row, col)
                .map(|h| h.name.clone())
        } else {
            None
        }
    }

    /// 开始编辑：没联网直接开；联网先申请租约，批准后才开
    /// 工作表受保护时阻止一切改内容的操作
    /// 只读查询：当前选区是否因后台构图或工作表保护而被禁止编辑（供菜单/功能区灰态判定，不改 status）
    pub(crate) fn is_edit_blocked(&self) -> bool {
        if self.deps_pending {
            return true;
        }
        if self.wb.sheet(self.sheet_idx).protection.is_some() {
            let rects = self.sel_rects();
            if self.rects_have_locked(&rects) {
                return true;
            }
        }
        false
    }

    fn edit_blocked(&mut self) -> bool {
        if self.deps_pending {
            self.status = "大型工作簿正在后台构建依赖图，请稍候再编辑".into();
            return true;
        }
        if self.wb.sheet(self.sheet_idx).protection.is_some() {
            let rects = self.sel_rects();
            if self.rects_have_locked(&rects) {
                self.status =
                    "工作表受保护：选中区域含锁定单元格，只能在未锁定区域编辑".into();
                return true;
            }
        }
        false
    }

    /// 受保护表上某格是否锁定（没有样式的格子按 Excel 默认视为锁定）
    fn cell_locked_on(&self, sheet: usize, r: u32, c: u32) -> bool {
        let sid = self.wb.sheet(sheet).style_of(r, c);
        self.wb.styles.get(sid).locked
    }

    /// 受保护表的选择权限：Excel 的「选定锁定单元格 / 选定未锁定单元格」被关掉时点不进去。
    fn sel_blocked_at(&self, r: u32, c: u32) -> bool {
        let Some(p) = self.wb.sheet(self.sheet_idx).protection.as_ref() else {
            return false;
        };
        if !p.sheet {
            return false;
        }
        if self.cell_locked_on(self.sheet_idx, r, c) {
            !p.perms.select_locked
        } else {
            !p.perms.select_unlocked
        }
    }

    /// 整块选区门禁：名称框、鼠标拖选、Shift+点击、Shift+方向键都走这里；
    /// 任何一格被禁选就整批拒绝，不能只看起点/终点。
    fn rect_sel_blocked(&self, a: (u32, u32), b: (u32, u32)) -> bool {
        let (r1, c1) = (a.0.min(b.0), a.1.min(b.1));
        let (r2, c2) = (a.0.max(b.0), a.1.max(b.1));
        let total = (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64;
        if total > 200_000 {
            let Some(p) = self.wb.sheet(self.sheet_idx).protection.as_ref() else {
                return false;
            };
            if !p.sheet {
                return false;
            }
            return !(p.perms.select_locked && p.perms.select_unlocked);
        }
        for r in r1..=r2 {
            for c in c1..=c2 {
                if self.sel_blocked_at(r, c) {
                    return true;
                }
            }
        }
        false
    }

    fn block_selection(&mut self) {
        self.status = "工作表受保护：不允许选择该区域的单元格（审阅 → 撤销保护后可改）".into();
    }

    /// 选区里是否含锁定单元格；超大选区直接算「含锁定」，避免逐格扫描卡住界面
    fn rects_have_locked(&self, rects: &[(u32, u32, u32, u32)]) -> bool {
        let total: u64 = rects
            .iter()
            .map(|(r1, c1, r2, c2)| (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64)
            .sum();
        if total > 200_000 {
            return true;
        }
        rects.iter().any(|(r1, c1, r2, c2)| {
            (*r1..=*r2)
                .any(|r| (*c1..=*c2).any(|c| self.cell_locked_on(self.sheet_idx, r, c)))
        })
    }

    /// 受保护表是否允许这项操作（未受保护一律允许）
    fn prot_can(&self, op: sheetcore::protection::ProtOp) -> bool {
        match self.wb.sheet(self.sheet_idx).protection.as_ref() {
            Some(p) => p.can(op),
            None => true,
        }
    }

    /// 需要整表权限的操作（插入/删除行列、排序、筛选）：没授权就拒绝并说明原因
    fn prot_denied(&mut self, op: sheetcore::protection::ProtOp, what: &str) -> bool {
        if self.wb.sheet(self.sheet_idx).protection.is_none() || self.prot_can(op) {
            return false;
        }
        self.status =
            format!("工作表受保护：没有「{what}」权限（审阅 → 撤销保护后可改）");
        true
    }

    /// 统一写入门禁：所有直接改模型的入口先过这里。
    /// - 后台依赖未就绪、工作表受保护 → 拒绝；
    /// - 目标区域里**任何一格**被别人锁定 → 整批拒绝，不做部分写入。
    fn write_preflight(&mut self, keys: &[(u32, u32)], what: &str) -> bool {
        self.write_preflight_on(self.sheet_idx, keys, what)
    }

    /// 指定工作表的统一门禁（跨表剪切等场景不能只看当前表）
    fn write_preflight_on(&mut self, sheet: usize, keys: &[(u32, u32)], what: &str) -> bool {
        self.write_preflight_on_op(sheet, keys, what, None)
    }

    /// 带权限类别的写入前检查：`Some(op)` 表示这次操作由该权限放行，
    /// 不再逐格要求未锁定（Excel 的「排序」「插入行」等权限就是这样生效的）。
    fn write_preflight_op(
        &mut self,
        keys: &[(u32, u32)],
        what: &str,
        op: sheetcore::protection::ProtOp,
    ) -> bool {
        self.write_preflight_on_op(self.sheet_idx, keys, what, Some(op))
    }

    fn write_preflight_on_op(
        &mut self,
        sheet: usize,
        keys: &[(u32, u32)],
        what: &str,
        op: Option<sheetcore::protection::ProtOp>,
    ) -> bool {
        if self.deps_pending {
            self.status = "大型工作簿正在后台构建依赖图，请稍候再操作".into();
            return false;
        }
        if let Some(p) = self.wb.sheet(sheet).protection.as_ref() {
            let allowed = match op {
                Some(op) => p.can(op),
                None => !keys.iter().any(|(r, c)| self.cell_locked_on(sheet, *r, *c)),
            };
            if !allowed {
                let name = self.wb.sheet(sheet).name.clone();
                self.status = match op {
                    Some(_) => format!("工作表「{name}」受保护：没有{what}的权限"),
                    None => format!("工作表「{name}」受保护：目标区域含锁定单元格，不能{what}"),
                };
                return false;
            }
        }
        if let Some(net) = self.net.as_ref() {
            if let Some((_, holder, r, c)) = net.host_lock_conflict_cells(sheet, keys) {
                self.status = format!("{holder} 正在编辑 {}，不能{what}", cell_name(r, c));
                return false;
            }
        }
        if self.locks.is_empty() { return true; }
        for (r, c) in keys {
            if let Some(holder) = self.lock_holder_on(sheet, *r, *c) {
                self.status = format!("{holder} 正在编辑 {}，不能{what}", cell_name(*r, *c));
                return false;
            }
        }
        true
    }

    fn begin_edit(&mut self, initial: Option<String>) {
        self.begin_edit_at(initial, EditSpot::Grid);
    }

    /// 进入编辑并指定焦点位置。没在编辑时按当前格进；已在编辑时只搬焦点、不重置缓冲
    /// （在编辑栏点一下不能把刚打的字清掉）。
    fn focus_edit(&mut self, spot: EditSpot) {
        if let Some(ed) = self.editing.as_mut() {
            ed.spot = spot;
            ed.focus_requested = true;
            return;
        }
        self.begin_edit_at(None, spot);
    }

    pub(crate) fn toggle_ai_assistant(&mut self, force_open: Option<bool>) {
        let next = force_open.unwrap_or(!self.ai.open);
        if next {
            self.filter_popup = None;
            if !self.finish_pending_edit() {
                return;
            }
            self.ai.request_input_focus = true;
        }
        self.ai.open = next;
    }

    fn begin_edit_at(&mut self, initial: Option<String>, spot: EditSpot) {
        if self.edit_blocked() {
            return;
        }
        self.begin_nav_rect();
        let (r, c) = self.sel;
        // UI-11.6：编辑会话记住所属表与目标格，跨表取引用后仍写回原格
        self.edit_sheet = Some(self.sheet_idx);
        self.edit_sel = Some((r, c));
        if let Some(net) = self.net.as_ref() {
            if let Some((_, holder, _, _)) = net.host_lock_conflict_cells(self.sheet_idx, &[(r, c)]) {
                self.status = format!("{} 正在编辑 {}，请稍后", holder, cell_name(r, c));
                return;
            }
        }
        if let Some(holder) = self.lock_holder(r, c) {
            self.status = format!("{} 正在编辑 {}，请稍后", holder, cell_name(r, c));
            return;
        }
        let target_lock = (self.sheet_idx, r, c);
        if self.my_lock.is_some_and(|prev| prev != target_lock)
            || self.requested_lock.is_some_and(|prev| prev != target_lock)
        {
            self.release_lock();
        }
        // 乐观零延迟立即开启编辑框（消除按回车切到下一格时的网络往返等待与漏字），
        // 同时强制将 TextEdit 光标锚定在当前缓冲末尾（杜绝复用上一格旧光标导致倒序或覆盖）。
        let buf = initial.unwrap_or_else(|| {
            match self.wb.sheet(self.sheet_idx).get(r, c) {
                Some(cell) => cell
                    .formula
                    .as_deref()
                    .map(|f| sheetcore::xlinks::display_formula(&self.wb, f))
                    .unwrap_or_else(|| cell.value.display()),
                None => String::new(),
            }
        });
        let caret = buf.chars().count();
        self.editing = Some(EditState {
            buf,
            spot,
            complete_idx: 0,
            alt_frame: u64::MAX,
            caret,
            caret_override: Some(caret),
            focus_requested: true,
        });
        self.pending_edit = None;
        if let Some(net) = self.net.as_ref().filter(|n| n.is_live()) {
            let name = self.my_name.clone();
            self.requested_lock = Some(target_lock);
            net.request_lock(self.sheet_idx, r, c, &name);
        }
        self.status = format!("正在编辑 {}", cell_name(r, c));
    }

    /// 编辑结束/放弃，立即交还已确认及在途申请的编辑租约（消除快速回车切格时的孤儿锁残留）
    fn release_lock(&mut self) {
        let confirmed = self.my_lock.take();
        let requested = self.requested_lock.take();
        let site = self.net.as_ref().map(|n| n.site).unwrap_or(0);
        if let Some((sheet, row, col)) = confirmed {
            if let Some(net) = self.net.as_ref() {
                net.release_lock(sheet, row, col);
            }
            self.locks.release(sheet, row, col, site);
        }
        if let Some((sheet, row, col)) = requested {
            if confirmed != Some((sheet, row, col)) {
                if let Some(net) = self.net.as_ref() {
                    net.release_lock(sheet, row, col);
                }
                self.locks.release(sheet, row, col, site);
            }
        }
        self.pending_edit = None;
    }

    /// 编辑中定期续期，防止长时间思考时被判定超时
    fn renew_lock_if_needed(&mut self) {
        if self.my_lock.is_none() {
            return;
        }
        if self.lock_renew.elapsed().as_secs() < 8 {
            return;
        }
        self.lock_renew = std::time::Instant::now();
        if let (Some(net), Some((sheet, row, col))) = (self.net.as_ref(), self.my_lock) {
            let name = self.my_name.clone();
            net.request_lock(sheet, row, col, &name);
        }
    }


    /// 记一步撤销：先 capture，改完 finish
    fn txn_begin(&self, keys: &[(u32, u32)]) -> Vec<sheetcore::undo::CellDelta> {
        sheetcore::undo::capture(self.wb.sheet(self.sheet_idx), self.sheet_idx, keys)
    }

    fn txn_end(&mut self, label: &str, before: Vec<sheetcore::undo::CellDelta>) {
        let deltas = sheetcore::undo::finish(before, self.wb.sheet(self.sheet_idx));
        self.record_deltas(label, deltas);
    }

    fn record_deltas(&mut self, label: &str, deltas: Vec<sheetcore::undo::CellDelta>) {
        self.record_deltas_and_merges(label, deltas, None);
    }

    fn record_deltas_and_merges(&mut self, label: &str, deltas: Vec<sheetcore::undo::CellDelta>, merges: Option<sheetcore::undo::MergeEdit>) {
        if deltas.is_empty() && merges.is_none() {
            return;
        }
        self.record_revision(label, &deltas);
        let focus = (self.sheet_idx, self.sel.0, self.sel.1);
        self.undo.push(sheetcore::undo::Action {
            label: label.to_string(),
            merges,
            deltas,
            focus,
            snap_before: None,
            snap_after: None,
            by_site: 0,
            pictures: None,
            shapes: None,
            refresh_sizes: None,
        });
    }


    fn protected_workbook(&self) -> bool {
        self.wb.encryption.is_some() || self.wb.source_encryption.is_some()
    }

    fn apply_recalculated_workbook(&mut self, mut calculated: Workbook) {
        // The callers have checked the document generation. A save can still
        // acknowledge sheet edits and adopt a new path during that generation.
        for (live, result) in self.wb.sheets.iter_mut().zip(&mut calculated.sheets) {
            if live.identity == result.identity {
                live.take_calculation(result);
                std::mem::swap(live, result);
            }
        }
        self.wb.sheets = calculated.sheets;
        // The open worker also refreshes external link caches before evaluation.
        self.wb.links = calculated.links;
        self.wb.calc_pending = calculated.calc_pending;
        self.wb.calc_pending_sheets = calculated.calc_pending_sheets;
    }

    fn set_workbook_open_password(&mut self, password: String) {
        let shared = self.net.is_some();
        if shared {
            self.leave_session();
        }
        self.wb.encryption = Some(sheetcore::crypto::EncryptionSettings::new(password));
        self.wb.dirty = true;
        self.status = if shared {
            "已断开协作并设置打开密码，保存后生效"
        } else {
            "已设置打开密码，保存后生效"
        }.into();
    }

    fn reload_revisions(&mut self) {
        if self.protected_workbook() {
            return;
        }
        // 默认仅保留本次会话内存修订记录，不在用户工作簿目录旁生成任何修订文件；
        // 仅在 SC_REV_REVERT 无界面验收测试下读取系统临时目录中的缓存日志。
        if std::env::var("SC_REV_REVERT").is_ok() {
            if let Some(path) = &self.wb.path {
                self.rev = sheetcore::revision::load(path, 200);
            }
        }
    }

    fn add_revision(&mut self, path: &std::path::Path, entry: sheetcore::revision::Entry) {
        if !self.protected_workbook() && !entry.remote && std::env::var("SC_REV_REVERT").is_ok() {
            let _ = sheetcore::revision::append(path, &entry);
        }
        self.rev.push(entry);
        if self.rev.len() > 200 {
            self.rev.remove(0);
        }
    }

    fn peer_display_name(&self, site: u32) -> String {
        self.peers_list
            .iter()
            .find(|(s, _, _)| *s == site)
            .map(|(_, n, _)| n.clone())
            .unwrap_or_else(|| format!("用户#{site}"))
    }

    /// 远端改动也进日志（只展示，不给撤回）
    fn record_remote_ops(
        &mut self,
        ops: &[sheetcore::sync::Op],
        befores: Vec<Option<sheetcore::model::Cell>>,
    ) {
        let Some(path) = self.wb.path.clone() else {
            return;
        };
        for (op, before) in ops.iter().zip(befores.into_iter()) {
            let Some(sheet) = self.wb.sheets.get(op.sheet) else {
                continue;
            };
            let sheet_name = sheet.name.clone();
            let b = before.unwrap_or_default();
            let a = sheet.get(op.row, op.col).cloned().unwrap_or_default();
            if b.value == a.value && b.formula == a.formula {
                continue;
            }
            let who = self.peer_display_name(op.site);
            let mut e = sheetcore::revision::Entry::new(&who, op.site, "远端编辑", &sheet_name);
            e.remote = true;
            e.cells.push(sheetcore::revision::Change {
                r: op.row,
                c: op.col,
                before: sheetcore::revision::Snap::from_cell(&b),
                after: sheetcore::revision::Snap::from_cell(&a),
                before_style: None,
                after_style: None,
            });
            self.add_revision(&path, e);
        }
    }

    fn record_remote_note_revision(
        &mut self,
        site: u32,
        label: &str,
        sheet_idx: usize,
        note: String,
    ) {
        if site == 0 {
            return;
        }
        let Some(path) = self.wb.path.clone() else {
            return;
        };
        let Some(sheet) = self.wb.sheets.get(sheet_idx) else {
            return;
        };
        let who = self.peer_display_name(site);
        let mut e = sheetcore::revision::Entry::new(&who, site, label, &sheet.name);
        e.remote = true;
        e.note = note;
        self.add_revision(&path, e);
    }

    /// 把一次动作写进修订日志（本地动作）
    fn record_revision(&mut self, label: &str, deltas: &[sheetcore::undo::CellDelta]) {
        self.record_revision_sample(label, deltas, deltas.len());
    }

    fn record_revision_sample(&mut self, label: &str, deltas: &[sheetcore::undo::CellDelta], total: usize) {
        let Some(path) = self.wb.path.clone() else {
            return; // 没保存过的新文件还不知道日志放哪
        };
        let sheet_idx = deltas.first().map(|d| d.sheet).unwrap_or(self.sheet_idx);
        let sheet = self.wb.sheet(sheet_idx).name.clone();
        let my_site = self.net.as_ref().map(|n| n.site).unwrap_or(0);
        let mut e = sheetcore::revision::Entry::new(&self.my_name, my_site, label, &sheet);
        let mut only_style = true;
        for d in deltas.iter().take(sheetcore::revision::MAX_CELLS) {
            if d.before.value != d.after.value || d.before.formula != d.after.formula {
                only_style = false;
            }
            let (bs, as_) = if d.before_style != d.after_style {
                (
                    Some(self.wb.styles.get(d.before_style).clone()),
                    Some(self.wb.styles.get(d.after_style).clone()),
                )
            } else {
                (None, None)
            };
            e.cells.push(sheetcore::revision::Change {
                r: d.row,
                c: d.col,
                before: sheetcore::revision::Snap::from_cell(&d.before),
                after: sheetcore::revision::Snap::from_cell(&d.after),
                before_style: bs,
                after_style: as_,
            });
        }
        if only_style && total > 0 {
            e.note = "格式变更".into();
        }
        if total > sheetcore::revision::MAX_CELLS {
            e.note = format!("共 {total} 格，只记前 {} 格", sheetcore::revision::MAX_CELLS);
        }
        self.add_revision(&path, e);
    }

    // ===== 剪贴板 =====
    /// 选区 → Excel/WPS 可粘贴的 HTML 表格（含合并、字体、填充、边框、对齐、公式）。
    fn selection_html(&self, si: usize, rect: (u32, u32, u32, u32)) -> String {
        Self::clipboard_html(&self.wb, si, rect)
    }

    fn clipboard_html(wb: &Workbook, si: usize, rect: (u32, u32, u32, u32)) -> String {
        let (r1, c1, r2, c2) = rect;
        let sh = wb.sheet(si);
        let merges: Vec<(u32, u32, u32, u32)> = sh
            .merges
            .iter()
            .filter(|(a, b, c, d)| *a >= r1 && *b >= c1 && *c <= r2 && *d <= c2)
            .copied()
            .collect();
        let mut covered = std::collections::HashSet::new();
        for &(a, b, c, d) in &merges {
            for rr in a..=c {
                for cc in b..=d {
                    if (rr, cc) != (a, b) {
                        covered.insert((rr, cc));
                    }
                }
            }
        }
        let mut out = String::from(
            "<table border=\"0\" cellspacing=\"0\" cellpadding=\"2\" style=\"border-collapse:collapse\">",
        );
        for r in r1..=r2 {
            out.push_str("<tr>");
            for c in c1..=c2 {
                if covered.contains(&(r, c)) {
                    continue;
                }
                let span = merges.iter().find(|(a, b, _, _)| *a == r && *b == c);
                let (cs, rs) = match span {
                    Some((_, _, er, ec)) => (ec - c + 1, er - r + 1),
                    None => (1, 1),
                };
                let cell = sh.get(r, c).cloned().unwrap_or_default();
                let sid = sh.style_of(r, c);
                let st = wb.styles.get(sid);
                let mut css = String::new();
                if !st.font.is_empty() {
                    css.push_str(&format!("font-family:{};", st.font.replace('"', "")));
                }
                if st.size > 0.0 {
                    css.push_str(&format!("font-size:{}pt;", st.size));
                }
                if st.bold {
                    css.push_str("font-weight:bold;");
                }
                if st.italic {
                    css.push_str("font-style:italic;");
                }
                let mut deco = Vec::new();
                if st.underline {
                    deco.push("underline");
                }
                if st.strikethrough {
                    deco.push("line-through");
                }
                if !deco.is_empty() {
                    css.push_str(&format!("text-decoration:{};", deco.join(" ")));
                }
                css.push_str(&format!("color:#{:02X}{:02X}{:02X};", st.color[0], st.color[1], st.color[2]));
                if let Some(fill) = st.fill {
                    css.push_str(&format!("background:#{:02X}{:02X}{:02X};", fill[0], fill[1], fill[2]));
                }
                if !st.format.is_empty() {
                    css.push_str(&format!("mso-number-format:'{}';", st.format.replace("\\", "").replace("'", "")));
                }
                match st.halign {
                    1 => css.push_str("text-align:left;"),
                    2 => css.push_str("text-align:center;"),
                    3 => css.push_str("text-align:right;"),
                    _ => {}
                }
                match st.valign {
                    1 => css.push_str("vertical-align:top;"),
                    2 => css.push_str("vertical-align:middle;"),
                    3 => css.push_str("vertical-align:bottom;"),
                    _ => {}
                }
                if st.wrap
                    || sheetcore::style::format_value_in(wb.date_system, &cell.value, &st.format)
                        .contains('\n')
                {
                    css.push_str("white-space:pre-wrap;");
                }
                for (i, b) in st.border.iter().enumerate() {
                    if b.style > 0 {
                        let width = match b.style {
                            2 => "2px",
                            3 | 4 => "3px",
                            _ => "1px",
                        };
                        let side = ["left", "right", "top", "bottom"][i];
                        css.push_str(&format!(
                            "border-{side}:{width} solid #{:02X}{:02X}{:02X};",
                            b.color[0], b.color[1], b.color[2]
                        ));
                    }
                }
                let mut attrs = String::new();
                if cs > 1 {
                    attrs.push_str(&format!(" colspan=\"{cs}\""));
                }
                if rs > 1 {
                    attrs.push_str(&format!(" rowspan=\"{rs}\""));
                }
                if !css.is_empty() {
                    attrs.push_str(&format!(" style=\"{css}\""));
                }
                if let Some(f) = &cell.formula {
                    attrs.push_str(&format!(" x:fmla=\"{}\"", html_escape(f)));
                }
                if let sheetcore::model::Value::Number(n) = &cell.value {
                    attrs.push_str(&format!(" x:num=\"{n}\""));
                }
                let text = html_escape(&sheetcore::style::format_value_in(
                    wb.date_system,
                    &cell.value,
                    &st.format,
                ));
                out.push_str(&format!("<td{attrs}>{text}</td>"));
            }
            out.push_str("</tr>");
        }
        out.push_str("</table>");
        out
    }

    fn retire_previous_clipboard(&mut self) {
        if let Some(owner) = self.clipboard_owner.take() {
            owner.after_replacement();
        }
    }

    fn clip_copy(&mut self, cut: bool, ctx: &egui::Context) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let rect = (r1, c1, r2, c2);
        let full_columns = !cut && office_clipboard::delayed::is_full_columns(rect);
        let area = u64::from(r2 - r1 + 1) * u64::from(c2 - c1 + 1);
        if !full_columns && area > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64 {
            self.status = "选区太大（超过 50 万格），请缩小区域或使用整列复制".into();
            return;
        }
        let si = self.sheet_idx;
        // Excel 的筛选复制只带走可见行；hidden_rows 是被筛选/分级折叠掉的行，
        // hidden_rows_user 是用户手动隐藏的行，Excel 仍会复制后者。
        let filter_hidden = &self.wb.sheet(si).hidden_rows;
        let filtered = filter_hidden.iter().any(|row| (r1..=r2).contains(row));
        if full_columns && column_clip::intersects_array(self.wb.sheet(si), c1, c2) {
            self.status = "整列包含数组公式或溢出区域，请选中具体数据区域后复制".into();
            return;
        }
        if full_columns && self.wb.sheet(si).merges.iter().any(|&(top, left, bottom, right)| {
            left <= c2 && right >= c1 && (left < c1 || right > c2 || top > bottom || bottom >= sheetcore::sync::MAX_ROWS)
        }) {
            self.status = "整列选区不能完整表示合并单元格，请确认合并范围并选中涉及的全部列".into();
            return;
        }
        if full_columns && filtered {
            self.status = "整列包含筛选隐藏行，请选中要复制的数据区域".into();
            return;
        }
        if full_columns || (area > 1_024 && !filtered
            && std::env::var_os("SC_CLIP_LOG").is_none() && std::env::var_os("SC_CLIP_DUMP").is_none())
        {
            let range = std::sync::Arc::new(office_clipboard::delayed::Range::new(&self.wb, si, rect));
            let owner = office_clipboard::delayed::Owner::publish(range.clone());
            if full_columns && owner.is_none() {
                self.status = "系统剪贴板正忙，请重新复制整列".into();
                return;
            }
            self.clip_stamp = if owner.is_none() {
                let plain = range.text();
                ctx.copy_text(plain.clone());
                Some(plain)
            } else { None };
            self.retire_previous_clipboard();
            self.clipboard_owner = owner;
            let merges = self.wb.sheet(si).merges.iter().copied()
                .filter(|&(a,b,c,d)| a >= r1 && b >= c1 && c <= r2 && d <= c2).collect();
            self.clip_pic = None;
            self.clip = Some(Clip { sheet: si, rect, deferred: Some(range), cells: Vec::new(), merges, source_rows: None, cut });
            self.status = format!("已{} {} 行 × {} 列", if cut { "剪切" } else { "复制" }, r2 - r1 + 1, c2 - c1 + 1);
            return;
        }
        let visible_rows: Vec<u32> = (r1..=r2)
            .filter(|r| !filter_hidden.contains(r))
            .collect();
        let filtered_copy = visible_rows.len() != (r2 - r1 + 1) as usize;
        let mut cells = Vec::with_capacity(visible_rows.len());
        let mut tsv = String::new();
        for &r in &visible_rows {
            let mut row = Vec::with_capacity((c2 - c1 + 1) as usize);
            for c in c1..=c2 {
                let cell = self.wb.sheet(si).get(r, c).cloned().unwrap_or(sheetcore::model::Cell {
                    value: sheetcore::model::Value::Empty,
                    formula: None,
                });
                let st = self.wb.sheet(si).style_of(r, c);
                let style = self.wb.styles.get(st);
                if c != c1 { tsv.push('\t'); }
                tsv.push_str(&sheetcore::style::format_value_in(self.wb.date_system, &cell.value, &style.format));
                row.push((cell, st));
            }
            tsv.push('\n');
            cells.push(row);
        }
        if filtered_copy {
            // XMLSS/HTML 不能表达非连续行；筛选复制先按 Excel 的可见单元格语义
            // 压紧成纯文本，保证粘贴不把隐藏行带回来，也不让 Excel 误用带隐藏行的块。
            ctx.copy_text(tsv.clone());
            self.retire_previous_clipboard();
            self.clip_stamp = Some(tsv);
            let visible_count = visible_rows.len();
            self.clip_pic = None;
            self.clip = Some(Clip { deferred: None,
                sheet: si,
                rect: (r1, c1, r2, c2),
                source_rows: Some(visible_rows),
                cells,
                merges: Vec::new(),
                cut,
            });
            self.status = format!(
                "已{}可见行（{} 行 × {} 列；筛选隐藏 {} 行）",
                if cut { "剪切" } else { "复制" },
                visible_count,
                c2 - c1 + 1,
                (r2 - r1 + 1) as usize - visible_count
            );
            return;
        }
        let html = self.selection_html(si, (r1, c1, r2, c2));
        if std::env::var("SC_CLIP_LOG").is_ok() {
            eprintln!("[clip-html] {html}");
        }
        let xmlss = office_clipboard::selection_xmlss(&self.wb, si, (r1, c1, r2, c2));
        if let Ok(path) = std::env::var("SC_CLIP_DUMP") {
            if let Err(e) = std::fs::write(&path, &xmlss) {
                eprintln!("[clip] dump failed: {e}");
            }
        }
        if std::env::var("SC_CLIP_LOG").is_ok() {
            eprintln!("[clip-xmlss] {}", &xmlss[..xmlss.len().min(400)]);
        }
        let html_ok = office_clipboard::write_office_clipboard(&xmlss, &html, &tsv);
        if !html_ok {
            ctx.copy_text(tsv.clone());
        }
        self.retire_previous_clipboard();
        self.clip_stamp = Some(tsv);
        let merges = self.wb.sheet(si).merges.iter()
            .filter(|(a, b, c, d)| *a >= r1 && *b >= c1 && *c <= r2 && *d <= c2)
            .copied()
            .collect();
        self.clip_pic = None;
        self.clip = Some(Clip { deferred: None, sheet: si, rect: (r1, c1, r2, c2), source_rows: None, cells, merges, cut });
        self.status = format!(
            "已{} {:?}（{} 行 × {} 列）",
            if cut { "剪切" } else { "复制" },
            (r1, c1, r2, c2),
            r2 - r1 + 1,
            c2 - c1 + 1
        );
    }

    // A native delayed owner identifies the source even if another program later
    // copies identical plain text or publishes an Office-only clipboard.
    fn deferred_clip_current(&self) -> Option<bool> {
        self.clip.as_ref()?.deferred.as_ref()?;
        self.clipboard_owner.as_ref().map(|owner| owner.is_current())
    }

    fn system_paste_text(&self) -> Option<String> {
        (self.deferred_clip_current() != Some(true)).then(Self::read_clipboard_text).flatten()
    }

    fn internal_clip_for(&self, text: Option<&str>, trust_unstamped: bool) -> Option<&Clip> {
        let clip = self.clip.as_ref()?;
        let current = self.deferred_clip_current().unwrap_or_else(|| {
            text.is_none_or(|text| match &self.clip_stamp {
                Some(stamp) => copied_text_matches(stamp, text),
                None => trust_unstamped || self.clip_matches(text, clip),
            })
        });
        current.then_some(clip)
    }

    /// values_only=true 时只贴值（不贴公式和格式）
    fn clip_paste(&mut self, values_only: bool, text: Option<String>) {
        let owns_range = self.deferred_clip_current() == Some(true);
        if let Some(clip) = self.clip.as_ref().filter(|clip| owns_range && office_clipboard::delayed::is_full_columns(clip.rect)) {
            if let Some(range) = clip.deferred.clone() {
                self.paste_full_columns(range.book(), clip.rect.1, clip.rect.3, values_only);
                return;
            }
        }
        if self.edit_blocked() {
            return;
        }
        // 所有入口共用同一份“最新系统剪贴板”：Ribbon/右键没传文本时主动读。
        let text = text.filter(|text| !text.is_empty()).or_else(|| {
            if owns_range { return None; }
            let sys = read_system_clip();
            (!sys.text.is_empty()).then_some(sys.text)
        });
        let (r, c) = self.sel;
        let si = self.sheet_idx;
        // 三个入口（Ribbon/右键/Ctrl+V）共用这一份判断：系统剪贴板比内部 clip 新时，
        // 富格式走 Office XMLSS/HTML，纯文本才退回 TSV。
        let use_internal = self.internal_clip_for(text.as_deref(), false).is_some();
        if !use_internal && !values_only {
            if let Some(block) = office_clipboard::read_table() {
                if std::env::var("SC_CLIP_LOG").is_ok() {
                    eprintln!("[clip] text={:?} block={:?}", text, Self::office_block_tsv(&block));
                }
                if self.paste_office_block(&block) {
                    return;
                }
            }
        }
        let mut tsv_paste = false;
        let mut rows: Vec<Vec<(sheetcore::model::Cell, u16)>> = Vec::new();
        let mut pasted_merges: Vec<(u32, u32, u32, u32)> = Vec::new();
        let mut cut_src: Option<(usize, Vec<(u32, u32)>)> = None;

        // Borrow the previous block only when it will actually be pasted. External plain
        // text must not copy or reformat the last internal selection.
        if let Some(clip) = self.clip.as_ref().filter(|_| use_internal) {
            if clip.cut && clip.deferred.as_ref().is_some_and(|range| {
                !self.wb.sheets.get(clip.sheet).is_some_and(|sh| range.matches_cut_source(sh))
            }) {
                self.status = "剪切源已更改，请重新剪切".into();
                return;
            }
            let (sr1, sc1, _, _) = clip.rect;
            let dr = r as i64 - sr1 as i64;
            let dc = c as i64 - sc1 as i64;
            let target_sheet_name = &self.wb.sheet(si).name;
            for (index, row) in clip.cells().iter().enumerate() {
                let row_shift = r as i64 + index as i64 - clip.source_row(index) as i64;
                let mut out = Vec::new();
                for (cell, st) in row {
                    let mut cell = cell.clone();
                    if !values_only {
                        if let Some(f) = &cell.formula {
                            let nf = sheetcore::refs::translate(f, row_shift, dc, target_sheet_name);
                            cell.formula = Some(nf.into());
                        }
                    } else {
                        cell.formula = None;
                    }
                    out.push((cell, if values_only { 0 } else { *st }));
                }
                rows.push(out);
            }
            if !clip.merges.is_empty() {
                pasted_merges = clip
                    .merges
                    .iter()
                    .map(|(a, b, c2, d)| {
                        (
                            (*a as i64 + dr).max(0) as u32,
                            (*b as i64 + dc).max(0) as u32,
                            (*c2 as i64 + dr).max(0) as u32,
                            (*d as i64 + dc).max(0) as u32,
                        )
                    })
                    .collect();
            }
            if clip.cut {
                let keys = (0..clip.cells().len()).flat_map(|index| {
                    let rr = clip.source_row(index);
                    (sc1..=clip.rect.3).map(move |cc| (rr, cc))
                }).collect();
                cut_src = Some((clip.sheet, keys));
            }
        } else if let Some(t) = text {
            rows = Self::parse_tsv(&t);
            tsv_paste = true;
        } else {
            self.status = if office_clipboard::has_xml_spreadsheet() {
                "无法导入剪贴板中的表格范围，请在源程序中选中具体数据区域后再复制"
            } else {
                "剪贴板是空的"
            }.into();
            return;
        }
        if rows.is_empty() {
            return;
        }

        // One transaction covers both sides of a cut, including overlapping cells.
        let h = rows.len() as u32;
        let w = rows.iter().map(|r| r.len()).max().unwrap_or(0) as u32;
        if (h as u64) * (w as u64) > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64 {
            self.status = "粘贴内容过大（单次最多支持 50 万个单元格）".into();
            return;
        }
        if h > 0 && w > 0 && (r.saturating_add(h - 1) > 1_048_575 || c.saturating_add(w - 1) > 16_383) {
            self.status = "粘贴区域超出工作表行列边界".into();
            return;
        }
        let mut touched = Vec::with_capacity(rows.iter().map(Vec::len).sum());
        for (i, row) in rows.iter().enumerate() {
            touched.extend((0..row.len()).map(|j| (si, r + i as u32, c + j as u32)));
        }
        if let Some((source, keys)) = &cut_src {
            touched.extend(keys.iter().map(|&(rr, cc)| (*source, rr, cc)));
            touched.sort_unstable();
            touched.dedup();
        }
        // 目标区或剪切源里任何一格被别人锁着 → 整批都不写
        let target_keys: Vec<(u32, u32)> = touched
            .iter()
            .filter(|(sheet, _, _)| *sheet == si)
            .map(|(_, rr, cc)| (*rr, *cc))
            .collect();
        if !self.write_preflight(&target_keys, "粘贴") {
            return;
        }
        if let Some((source, keys)) = &cut_src {
            if !self.write_preflight_on(*source, keys, "剪切") {
                return;
            }
        }
        let mut transactions = std::collections::BTreeMap::new();
        for &(sheet, rr, cc) in &touched {
            transactions.entry(sheet).or_insert_with(Vec::new).push((rr, cc));
        }
        let merge_edit = if values_only || tsv_paste {
            None
        } else {
            let source = self.clip.as_ref().filter(|_| cut_src.is_some());
            match self.paste_merge_edit((r, c, r + h - 1, c + w - 1), &pasted_merges, source) {
                Ok(edit) => edit,
                Err(message) => { self.status = message.into(); return; }
            }
        };
        let merge_changes = if let Some(edit) = &merge_edit {
            let Some(changes) = edit.apply(&mut self.wb.sheets, true) else {
                self.status = "粘贴区域中的合并单元格相互冲突".into();
                return;
            };
            changes
        } else { Vec::new() };
        let before: Vec<_> = transactions.into_iter().map(|(sheet, keys)| {
            (sheet, sheetcore::undo::capture(self.wb.sheet(sheet), sheet, &keys))
        }).collect();
        let paste_before = if cut_src.is_some() {
            Vec::new()
        } else {
            before.iter().flat_map(|(_, captured)| captured.iter()).map(|d| {
                (d.row, d.col, (!d.before.is_blank()).then(|| d.before.clone()), d.before_style)
            }).collect()
        };
        // Clear before writing: the clipboard already holds a source snapshot.
        if let Some((source, keys)) = &cut_src {
            for &(rr, cc) in keys {
                self.wb.sheet_mut(*source).set(rr, cc, Cell::default());
                self.wb.sheet_mut(*source).set_style(rr, cc, 0);
            }
        }
        for (i, row) in rows.iter().enumerate() {
            for (j, (cell, st)) in row.iter().enumerate() {
                let rr = r + i as u32;
                let cc = c + j as u32;
                self.wb.sheet_mut(si).set(rr, cc, cell.clone());
                if !values_only && !tsv_paste {
                    self.wb.sheet_mut(si).set_style(rr, cc, *st);
                }
            }
        }
        let label = if cut_src.is_some() { "剪切粘贴" } else if values_only { "粘贴数值" } else { "粘贴" };
        let mut deltas = Vec::new();
        for (sheet, captured) in before {
            let changes = sheetcore::undo::finish(captured, self.wb.sheet(sheet));
            if !changes.is_empty() {
                self.record_revision(label, &changes);
                deltas.extend(changes);
            }
        }
        if let Some(net) = &self.net {
            let styles: Vec<_> = deltas.iter().filter(|d| d.before_style != d.after_style)
                .map(|d| (d.sheet, d.row, d.col)).collect();
            self.broadcast_cell_styles(&styles);
            for (sheet, rect, on) in merge_changes { net.broadcast_merge(sheet, rect, on); }
        }
        self.undo.push(sheetcore::undo::Action {
            label: label.into(), deltas, focus: (si, r, c),
            merges: merge_edit,
            snap_before: None, snap_after: None, by_site: 0,
            pictures: None,
            shapes: None,
            refresh_sizes: None,
        });
        if cut_src.is_some() {
            self.clip = None;
        }
        // 重算 + 广播
        self.recalc_and_broadcast(&touched);
        if cut_src.is_none() && h > 0 && w > 0 {
            self.last_paste = Some(LastPasteState {
                sheet_idx: si,
                rect: (r, c, r + h - 1, c + w - 1),
                cells: rows,
                mode: if values_only { 1 } else { 0 },
                before: paste_before,
                popup_open: false,
            });
        } else {
            self.last_paste = None;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.status = format!("已粘贴 {h} 行 × {w} 列");
    }

    fn paste_merge_edit(
        &self,
        target: (u32, u32, u32, u32),
        incoming: &[(u32, u32, u32, u32)],
        cut: Option<&Clip>,
    ) -> Result<Option<sheetcore::undo::MergeEdit>, &'static str> {
        let overlaps = |a: (u32,u32,u32,u32), b: (u32,u32,u32,u32)| a.0 <= b.2 && b.0 <= a.2 && a.1 <= b.3 && b.1 <= a.3;
        let contains = |a: (u32,u32,u32,u32), b: (u32,u32,u32,u32)| a.0 <= b.0 && a.1 <= b.1 && a.2 >= b.2 && a.3 >= b.3;
        let mut affected = vec![self.sheet_idx];
        if let Some(clip) = cut.filter(|c| c.sheet != self.sheet_idx) {
            affected.push(clip.sheet);
        }
        let mut edits = Vec::new();
        for sheet in affected {
            let mut removed = Vec::new();
            for &rect in &self.wb.sheet(sheet).merges {
                if let Some(clip) = cut.filter(|c| c.sheet == sheet && overlaps(c.rect, rect)) {
                    if !contains(clip.rect, rect) || clip.source_rows.is_some() {
                        return Err("剪切区域包含部分合并单元格，请选择完整区域");
                    }
                    removed.push(rect);
                } else if sheet == self.sheet_idx && overlaps(target, rect) {
                    if !contains(target, rect) {
                        return Err("粘贴区域包含部分合并单元格，请选择完整区域");
                    }
                    removed.push(rect);
                }
            }
            let added = if sheet == self.sheet_idx { incoming } else { &[] };
            if let Some(edit) = sheetcore::undo::MergeEdit::between(sheet, &removed, added) {
                edits.push(edit);
            }
        }
        Ok(sheetcore::undo::MergeEdit::join(edits))
    }

    fn clip_matches(&self, text: &str, clip: &Clip) -> bool {
        if let Some(range) = &clip.deferred { return copied_text_matches(&range.text(), text); }
        let mut expect = String::new();
        for row in clip.cells().iter() {
            let mut line = Vec::new();
            for (cell, st) in row.iter() {
                let style = self.wb.styles.get(*st);
                line.push(sheetcore::style::format_value_in(
                    self.wb.date_system,
                    &cell.value,
                    &style.format,
                ));
            }
            expect.push_str(&line.join("\t"));
            expect.push('\n');
        }
        expect == text
    }

    fn parse_tsv(text: &str) -> Vec<Vec<(sheetcore::model::Cell, u16)>> {
        fn cell_of(field: &str, quoted: bool) -> (sheetcore::model::Cell, u16) {
            let leading_zero = field.len() > 1
                && field.starts_with('0')
                && field[1..].chars().all(|c| c.is_ascii_digit());
            let cell = if !quoted && field.starts_with('=') {
                sheetcore::model::Cell {
                    value: sheetcore::model::Value::Text(field.into()),
                    formula: Some(field.into()),
                }
            } else if quoted || leading_zero {
                sheetcore::model::Cell {
                    value: sheetcore::model::Value::Text(field.into()),
                    formula: None,
                }
            } else {
                sheetcore::model::Cell {
                    value: sheetcore::model::Value::parse_input(field),
                    formula: None,
                }
            };
            (cell, 0u16)
        }

        let mut rows = Vec::new();
        let mut row: Vec<(sheetcore::model::Cell, u16)> = Vec::new();
        let mut field = String::new();
        let mut quoted = false;
        let mut in_quotes = false;
        let mut chars = text.chars().peekable();
        while let Some(ch) = chars.next() {
            if in_quotes {
                if ch == '"' {
                    if chars.peek() == Some(&'"') {
                        field.push('"');
                        chars.next();
                    } else {
                        in_quotes = false;
                    }
                } else {
                    field.push(ch);
                }
                continue;
            }
            match ch {
                '"' => {
                    in_quotes = true;
                    quoted = true;
                }
                '\t' => {
                    row.push(cell_of(&field, quoted));
                    field.clear();
                    quoted = false;
                }
                '\r' => {}
                '\n' => {
                    row.push(cell_of(&field, quoted));
                    field.clear();
                    quoted = false;
                    rows.push(std::mem::take(&mut row));
                }
                _ => field.push(ch),
            }
        }
        if !field.is_empty() || quoted || !row.is_empty() {
            row.push(cell_of(&field, quoted));
            rows.push(row);
        }
        rows
    }

    /// 系统剪贴板文本 → 粘贴矩阵。与普通粘贴共用 parse_tsv，保留中间空行。
    fn parse_clip_text(text: &str) -> Vec<Vec<(sheetcore::model::Cell, u16)>> {
        Self::parse_tsv(text)
    }

    fn ensure_deps_ready_or_bg(&mut self) {
        let total_cells: usize = self.wb.sheets.iter().map(|s| s.len()).sum();
        if total_cells <= 1_200 {
            if !self.deps_built || self.deps.is_empty() {
                let has_formula = self
                    .wb
                    .sheets
                    .iter()
                    .any(|s| s.has_formulas());
                if has_formula {
                    self.deps = sheetcore::formula::deps::Deps::build(&self.wb).into();
                }
                self.deps_built = true;
                self.bg_deps_rx = None;
            }
            return;
        }
        if self.deps_built {
            return;
        }
        let has_any_formula = self
            .wb
            .sheets
            .iter()
            .any(|s| s.has_formulas());
        if !has_any_formula {
            self.deps = sheetcore::formula::deps::Deps::empty().into();
            self.deps_built = true;
            self.bg_deps_rx = None;
            return;
        }
        if self.bg_deps_rx.is_none() {
            let sk = self.wb.clone();
            let uid = self.doc_uid;
            let epoch = self.wb_epoch;
            let generation = self.doc_gen;
            let (tx, rx) = std::sync::mpsc::channel();
            self.bg_deps_rx = Some(rx);
            std::thread::spawn(move || {
                let deps = sheetcore::formula::deps::Deps::build(&sk);
                let _ = tx.send((uid, epoch, generation, Box::new(deps)));
            });
        }
    }

    fn request_silent_bg_recalc(&mut self) {
        self.tasks.needs_full = true;
        self.tasks.dirty_recalc_seeds.clear();
        self.cancel_silent_recalc();
    }

    fn update_dependency(&mut self, key: sheetcore::formula::deps::CellKey) {
        if self.deps.cell_needs_update(&self.wb, key) {
            std::sync::Arc::make_mut(&mut self.deps).update_cell(&self.wb, key);
        }
    }

    fn cancel_silent_recalc(&mut self) {
        if let Some(c) = self.bg_recalc_cancel.take() {
            c.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        self.bg_recalc_rx = None;
    }

    fn poll_silent_recalc(&mut self) {
        if self.tasks.saving.is_some() && self.tasks.recalc_pending() {
            self.cancel_silent_recalc();
        }
        if let Some(rx) = &self.bg_deps_rx {
            if let Ok((uid, epoch, generation, deps)) = rx.try_recv() {
                if uid == self.doc_uid && epoch == self.wb_epoch && generation == self.doc_gen {
                    self.deps = deps.into();
                    self.deps_built = true;
                }
                self.bg_deps_rx = None;
            }
        }
        if let Some(rx) = &self.bg_recalc_rx {
            match rx.try_recv() {
                Ok((uid, epoch, gen_at, calculated, d)) => {
                    self.bg_recalc_rx = None;
                    self.bg_recalc_cancel = None;
                    if uid == self.doc_uid && epoch == self.wb_epoch && gen_at == self.doc_gen {
                        if !calculated.apply(&mut self.wb) {
                            self.deps_built = false;
                            self.request_silent_bg_recalc();
                            return;
                        }
                        self.tasks.needs_full = false;
                        self.tasks.dirty_recalc_seeds.clear();
                        if let Some(d) = d {
                            self.deps = d.into();
                        }
                        self.deps_built = true;
                        self.cf_stats_gen = u64::MAX;
                        self.doc_gen = self.doc_gen.wrapping_add(1);
                        self.ai_recalculated(gen_at);
                    }
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    self.bg_recalc_rx = None;
                    self.bg_recalc_cancel = None;
                }
            }
        }
    }

    fn start_silent_recalc(&mut self, ctx: &egui::Context) {
        let pending_recalc = !self.wb.calc_manual && self.tasks.recalc_pending()
            && !self.ai_calculation_in_progress();
        if pending_recalc
            && self.bg_recalc_rx.is_none()
            && !self.tasks.busy
            && self.tasks.saving.is_none()
            && self
                .tasks
                .last_edit
                .map(|t| t.elapsed().as_millis() >= 250)
                .unwrap_or(true)
        {
            let wb_now = self.wb.clone();
            let revisions = wb_now.sheets.iter().map(|sh| sh.cell_revision()).collect();
            let incremental = (!self.tasks.needs_full && self.deps_built).then(|| {
                let seeds: Vec<_> = self.tasks.dirty_recalc_seeds.iter().copied().collect();
                (self.deps.clone(), seeds)
            });
            let uid = self.doc_uid;
            let epoch = self.wb_epoch;
            let doc_gen = self.doc_gen;
            let cancel = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
            self.bg_recalc_cancel = Some(cancel.clone());
            let (tx, rx) = std::sync::mpsc::channel();
            self.bg_recalc_rx = Some(rx);
            let wake = ctx.clone();
            std::thread::spawn(move || {
                use std::sync::atomic::Ordering;
                let mut wb2 = wb_now;
                let rebuilt = if let Some((deps, seeds)) = incremental {
                    if !sheetcore::formula::recalc_dirty_cancelable(&mut wb2, &deps, &seeds, &cancel) {
                        return;
                    }
                    None
                } else {
                    if !sheetcore::formula::recalc_all_force_impl(&mut wb2, Some(&cancel), None)
                        || cancel.load(Ordering::Relaxed) { return; }
                    Some(Box::new(sheetcore::formula::deps::Deps::build(&wb2)))
                };
                if !cancel.load(Ordering::Relaxed) {
                    let _ = tx.send((uid, epoch, doc_gen, CalculatedSnapshot { revisions, workbook: Box::new(wb2) }, rebuilt));
                    wake.request_repaint();
                }
            });
        } else if pending_recalc && self.bg_recalc_rx.is_none() {
            ctx.request_repaint_after(std::time::Duration::from_millis(260));
        }
    }

    fn fast_recalc_cells(&mut self, keys: &[(usize, u32, u32)]) {
        if keys.is_empty() {
            return;
        }
        // Bulk edits can replace thousands of formulas. The immediate-seed path
        // evaluates each of them before it budgets the dependent closure.
        if keys.len() > 2_000 {
            if self.manual_calc || self.wb.calc_manual || !self.deps_built
                || self.wb.sheets.iter().any(|s| !s.spill_shapes.is_empty() || !s.spilled.is_empty() || !s.arrays.is_empty())
                || keys.iter().any(|&k| self.deps.cell_needs_update(&self.wb, k)) {
                self.wb.calc_manual |= self.manual_calc;
                self.recalc_all_and_deps_adaptive();
            } else if !self.deps.is_empty() && !self.tasks.needs_full {
                self.tasks.dirty_recalc_seeds.extend(keys.iter().copied());
                self.cancel_silent_recalc();
            }
            return;
        }
        self.ensure_deps_ready_or_bg();
        if self.deps_built {
            for k in keys {
                self.update_dependency(*k);
            }
        }
        if self.manual_calc {
            self.wb.calc_manual = true;
            if self.deps_built {
                sheetcore::formula::mark_pending(&mut self.wb, &self.deps, keys);
            } else {
                self.wb.calc_pending = true;
                self.wb.calc_pending_sheets.extend(0..self.wb.sheets.len());
            }
            self.status = "手动计算：已标记待计算（按 F9 或“开始计算”重算）".into();
            return;
        }
        let plan = sheetcore::formula::recalc_interactive_plan(
            &mut self.wb,
            &self.deps,
            keys,
            self.deps_built,
        );
        use sheetcore::formula::InteractiveRecalc;
        match plan {
            InteractiveRecalc::BackgroundFull => self.request_silent_bg_recalc(),
            InteractiveRecalc::BackgroundDirty if !self.tasks.needs_full => {
                self.tasks.dirty_recalc_seeds.extend(keys.iter().copied());
                self.cancel_silent_recalc();
            }
            _ => {}
        }
    }

    fn broadcast_cells(&mut self, keys: &[(usize, u32, u32)]) {
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            let blank = sheetcore::Cell::default();
            for chunk in keys.chunks(sheetcore::sync::LIVE_OP_BATCH) {
                let ops = chunk.iter().map(|&(si, r, c)| {
                    peer.local_set(si, r, c, self.wb.sheet(si).get(r, c).unwrap_or(&blank))
                }).collect();
                net.broadcast_ops(ops);
            }
        }
    }

    fn broadcast_cell_styles(&self, keys: &[(usize, u32, u32)]) {
        let Some(net) = &self.net else { return };
        for chunk in keys.chunks(128) {
            for group in chunk.chunk_by(|a, b| a.0 == b.0) {
                let sheet = group[0].0;
                let Some(sh) = self.wb.sheets.get(sheet) else { continue };
                let items = group.iter().map(|&(_, r, c)| {
                    (r, c, self.wb.styles.get(sh.style_of(r, c)).clone())
                }).collect();
                net.broadcast_style(sheet, items);
            }
        }
    }

    fn recalc_and_broadcast(&mut self, keys: &[(usize, u32, u32)]) {
        self.fast_recalc_cells(keys);
        self.broadcast_cells(keys);
    }

    /// 双击填充柄时的终点：看左右相邻列谁有连续数据
    fn fill_down_limit(&self, c1: u32, c2: u32) -> u32 {
        let (_, _, r2, _) = self.sel_rect();
        let sh = self.wb.sheet(self.sheet_idx);
        let neighbour = if c1 > 0 && sh.get(r2 + 1, c1 - 1).is_some() {
            Some(c1 - 1)
        } else if sh.get(r2 + 1, c2 + 1).is_some() {
            Some(c2 + 1)
        } else {
            None
        };
        let Some(nc) = neighbour else {
            return r2;
        };
        let mut r = r2 + 1;
        while r < 1_048_576 && sh.get(r, nc).is_some() {
            r += 1;
        }
        r.saturating_sub(1)
    }

    /// Ctrl+D / Ctrl+R：用选区首行（首列）填满整个选区，公式按位移调整
    fn fill_cmd(&mut self, down: bool) {
        if self.edit_blocked() {
            return;
        }
        self.commit_edit(None);
        let (r1, c1, r2, c2) = self.sel_rect();
        if down && r2 == r1 {
            return;
        }
        if !down && c2 == c1 {
            return;
        }
        let area = (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64;
        if area > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64 {
            self.status = "填充范围过大（单次最多支持 50 万个单元格）".into();
            return;
        }
        // 实际被写的是尾端目标区（首行/首列只是源），门禁按真实写入范围收集
        let gate = if down {
            sheetcore::undo::rect_keys(r1 + 1, c1, r2, c2)
        } else {
            sheetcore::undo::rect_keys(r1, c1 + 1, r2, c2)
        };
        if !self.write_preflight(
            &gate,
            if down { "向下填充" } else { "向右填充" },
        ) {
            return;
        }
        let si = self.sheet_idx;
        let mut formulas = sheetcore::refs::FillFormulas::default();
        let mut changes = Vec::new();
        let mut filled_keys = Vec::new();
        let sh = self.wb.sheet_mut(si);
        for &(row, col) in &gate {
            let (sr, sc) = if down { (r1, col) } else { (row, c1) };
            let Some(source) = sh.get(sr, sc) else { continue };
            let after = Cell {
                value: source.value.clone(),
                formula: source.formula.as_deref().map(|f| formulas.translate(f, i64::from(row - sr), i64::from(col - sc)).into()),
            };
            if sh.get(row, col) == Some(&after) { continue; }
            let style = sh.style_of(row, col);
            let before = sh.get(row, col).cloned().unwrap_or_default();
            sh.set(row, col, after.clone());
            changes.push(sheetcore::undo::CellDelta {
                sheet: si, row, col, before, after, before_style: style, after_style: style,
            });
            filled_keys.push((si, row, col));
        }
        self.record_deltas(if down { "向下填充" } else { "向右填充" }, changes);
        self.recalc_and_broadcast(&filled_keys);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = if down {
            format!("已用首行填充 {}-{} 行", r1 + 1, r2 + 1)
        } else {
            format!("已用首列填充到第 {} 列", c2 + 1)
        };
    }

    #[cfg(test)]
    fn dv_visible_items(&self, r: u32, c: u32) -> Vec<String> {
        filter_dv_items(&self.dv_items(r, c), &self.dv_query)
    }

    fn refresh_dv_source(&mut self, r: u32, c: u32) {
        let generation = self.validation_generation();
        let key = (self.doc_uid, self.wb_epoch, self.wb.sheet(self.sheet_idx).identity, generation, r, c);
        if self.dv_source != Some(key) {
            self.dv_cache = self.dv_items(r, c);
            self.dv_source = Some(key);
            self.dv_filtered = None;
        }
    }

    fn refresh_dv_filter(&mut self) {
        let query = self.dv_query.trim();
        if query.is_empty() {
            self.dv_filtered = None;
        } else if !self.dv_filtered.as_ref().is_some_and(|(old, _)| old == query) {
            self.dv_filtered = Some((query.to_owned(), dv_matching_indices(&self.dv_cache, query)));
        }
    }

    fn dv_item_count(&self) -> usize {
        self.dv_filtered.as_ref().map_or(self.dv_cache.len(), |(_, indices)| indices.len())
    }

    fn dv_item_at(&self, index: usize) -> &String {
        let i = self.dv_filtered.as_ref().map_or(index, |(_, matches)| matches[index]);
        &self.dv_cache[i]
    }

    fn dv_items(&self, r: u32, c: u32) -> Vec<String> {
        let sheet = self.wb.sheet(self.sheet_idx);
        match sheetcore::dv::find(&sheet.dv, r, c) {
            Some(dv) if dv.kind == sheetcore::dv::DvKind::List => {
                sheetcore::dv::list_items_wb(&self.wb, self.sheet_idx, dv, r, c).unwrap_or_default()
            }
            _ => Vec::new(),
        }
    }

    /// Alt+↓ / 点击箭头：打开序列下拉，并把高亮放在当前值上（Excel 的行为）。
    fn dv_open_for_selection(&mut self) {
        let (r, c) = self.sel;
        if self.editing.is_some() {
            return;
        }
        self.refresh_dv_source(r, c);
        if self.dv_cache.is_empty() {
            self.status = "当前单元格没有可用的序列来源".into();
            return;
        }
        let cur = self.wb.sheet(self.sheet_idx).value(r, c).display();
        self.dv_query.clear();
        self.dv_filtered = None;
        self.dv_hilite = self.dv_cache.iter().position(|it| *it == cur).unwrap_or(0);
        self.dv_open = Some((r, c));
    }

    /// 验证下拉选中一项后真正写入：和手输同一套门禁、撤销事务与广播。
    fn dv_pick_apply(&mut self, dr: u32, dc: u32, v: &str) -> bool {
        if !self.write_preflight(&[(dr, dc)], "选择验证下拉值") {
            self.dv_open = None;
            return false;
        }
        let cell = Cell {
            value: Value::parse_input(v),
            formula: None,
        };
        let key = (self.sheet_idx, dr, dc);
        let txn = self.txn_begin(&[(dr, dc)]);
        self.wb.sheet_mut(self.sheet_idx).set(dr, dc, cell.clone());
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.txn_end("选择验证下拉值", txn);
        self.update_dependency(key);
        sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &[key]);
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            let op = peer.local_set(self.sheet_idx, dr, dc, &cell);
            net.broadcast_op(op);
        }
        self.status = format!("已选择 {v}");
        true
    }

    /// 填充柄：委托给 4 向智能填充引擎（保留原有签名）
    fn fill_to(&mut self, target_row: u32, vertical: bool) {
        self.smart_fill_to_mode(target_row, vertical, fill_seq::FillMode::Smart, true);
    }

    /// 按内容自适应列宽
    fn autofit_col(&mut self, ctx: &egui::Context, col: u32) {
        let mut width: f32 = 17.0;
        let mut saw_text = false;
        let (_, _, r2, _) = self.wb.sheet(self.sheet_idx).used_bounds().unwrap_or((0, 0, 0, 0));
        // Excel 的 AutoFit 不参与合并格：合并区宽度由用户/列宽决定，
        // 对合并格按整段文字加宽会把普通列撑得过大。
        let merges = self.wb.sheet(self.sheet_idx).merges.clone();
        for r in 0..=r2.min(5000) {
            if merges
                .iter()
                .any(|(a, b, c, d)| r >= *a && r <= *c && col >= *b && col <= *d)
            {
                continue;
            }
            let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, col) else {
                continue;
            };
            let st = {
                let sh = self.wb.sheet(self.sheet_idx);
                self.wb.styles.get(sh.style_of(r, col)).clone()
            };
            let txt = sheetcore::style::format_value_in(self.wb.date_system, &cell.value, &st.format);
            if txt.is_empty() {
                continue;
            }
            saw_text = true;
            // 列宽要按 Excel 的口径算，不能用屏幕字体的 galley：
            // Excel AutoFit 是「字符单位 + 固定内边距」，不是按字形 advance
            // 求和；用 Carlito 的 text_width 再除 7 会差 1–1.5 字符。
            let size = (if st.size > 0.0 { st.size } else { 11.0 }) * 4.0 / 3.0;
            let font_size = if st.size > 0.0 { st.size } else { 11.0 };
            let font = if st.font.trim().is_empty() { "等线" } else { st.font.as_str() };
            // 缩进按 xlsx 文件语义 3 字符/级；粗体按等线/宋体的实测像素量化增量。
            let chars = sheetcore::display::excel_autofit_chars_wrapped_at_size_font(
                &txt,
                st.bold,
                st.indent,
                st.wrap,
                font_size,
                font,
            );
            let w = chars * 8.0 + 5.0;
            if std::env::var("SC_AUTOFIT").is_ok() {
                eprintln!(
                    "[autofit]   r{r} txt={:?} len={} chars={:.2} size={:.1} bold={} indent={}",
                    txt.chars().take(12).collect::<String>(),
                    txt.chars().count(),
                    chars,
                    size,
                    st.bold,
                    st.indent
                );
            }
            // 列宽模型是「内容宽 + 内边距」；chars 已含等线的 0.88 内边距。
            width = width.max(w);
        }
        if !saw_text {
            width = 72.0; // 空列保持 Excel 的默认列宽，不要缩成单字符
        }
        // 单字符内容 Excel 给 1.88 字符（约 20px），不能被 24px 下限顶到 2.38。
        let width = width.clamp(17.0, 1500.0);
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.cols.set(col, width);
            sh.layout_dirty = true;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!(
            "{} 列宽已自适应：{:.0}px",
            cell_name(0, col).trim_end_matches('1'),
            width
        );
    }

    /// 按内容自适应行高（自动换行时按折行数算，用真实字形量）
    fn autofit_row(&mut self, ctx: &egui::Context, row: u32) {
        let (_, c1, _, c2) = self
            .wb
            .sheet(self.sheet_idx)
            .used_bounds()
            .unwrap_or((0, 0, 0, 0));
        let mut best: f32 = 15.0;
        for c in c1..=c2 {
            let Some(cell) = self.wb.sheet(self.sheet_idx).get(row, c) else {
                continue;
            };
            let st = {
                let sh = self.wb.sheet(self.sheet_idx);
                self.wb.styles.get(sh.style_of(row, c)).clone()
            };
            let txt = sheetcore::style::format_value_in(self.wb.date_system, &cell.value, &st.format);
            if txt.is_empty() {
                continue;
            }
            let size = (if st.size > 0.0 { st.size } else { 11.0 }) * 4.0 / 3.0;
            let fname = if st.font.is_empty() { "默认" } else { &st.font };
            let font = if st.bold {
                let (fam, sz, _) = bold_font(fname, size);
                egui::FontId::new(sz, fam)
            } else {
                egui::FontId::new(size, cell_family(fname))
            };
            let col_w = self.wb.sheet(self.sheet_idx).cols.size(c);
            // Excel 自适应行高 = 文字高度 + 每折行 1px（单行 18+1=19px，
            // 三行 54+3=57px，和本机 Excel 的 14.25pt / 42.75pt 对齐）。
            let (h, lines) = if st.wrap {
                ctx.fonts(|f| {
                    let g = f.layout(
                        txt.clone(),
                        font.clone(),
                        egui::Color32::BLACK,
                        (col_w - 6.0).max(8.0),
                    );
                    (g.size().y, g.rows.len().max(1))
                })
            } else {
                (
                    ctx.fonts(|f| {
                        f.layout_no_wrap(txt.clone(), font.clone(), egui::Color32::BLACK)
                            .size()
                            .y
                    }),
                    1,
                )
            };
            if std::env::var("SC_AUTOFIT").is_ok() {
                eprintln!("[autofit] 行{row} c{c} galley={h:.1} lines={lines} wrap={}", st.wrap);
            }
            best = best.max(h + lines as f32);
        }
        let h = best.clamp(15.0, 409.0);
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.rows.set(row, h);
            sh.layout_dirty = true;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("第 {} 行行高已自适应：{:.0}px", row + 1, h);
    }

    // ===== 数据工具 =====
    fn clamp_rect_to_used(&self, rect: (u32, u32, u32, u32)) -> Option<(u32, u32, u32, u32)> {
        let (r1, c1, mut r2, mut c2) = rect;
        if (r2.saturating_sub(r1) as u64 + 1) * (c2.saturating_sub(c1) as u64 + 1) > 200_000 {
            let (_, _, ur2, uc2) = self.wb.sheet(self.sheet_idx).used_bounds()?;
            if ur2 < r1 || uc2 < c1 {
                return None;
            }
            r2 = r2.min(ur2);
            c2 = c2.min(uc2);
        }
        Some((r1, c1, r2, c2))
    }

    fn open_data_dlg(&mut self, tab: u8) {
        let raw = self.sel_rect();
        let (r1, c1, r2, c2) = self
            .clamp_rect_to_used(raw)
            .unwrap_or((raw.0, raw.1, raw.0, raw.3.min(raw.1 + 255)));
        let c2_ui = c2.min(c1 + 255);
        let header = sheetcore::sort_filter::has_header(self.wb.sheet(self.sheet_idx), r1, c1, r2, c2_ui);
        let keys = (c1..=c2_ui).map(|c| (c, true, c == c1)).collect();
        self.data_dlg = Some(DataDlg {
            tab,
            keys,
            header,
            delim: ",".into(),
            sort_mode: 1,
            custom: "高,中,低".into(),
            merge_consecutive: true,
            sort_by_row: false,
            split_fixed: false,
            widths: String::new(),
            col_modes: String::new(),
            quote: true,
            detect_types: true,
        });
    }

    fn run_sort(&mut self, dlg: &DataDlg) {
        let Some((r1, c1, r2, c2)) = self.clamp_rect_to_used(self.sel_rect()) else {
            self.status = "选区内没有可排序的数据".into();
            return;
        };
        let rect = (r1, c1, r2, c2);
        if dlg.sort_by_row {
            let row = self.sel.0.clamp(r1, r2);
            let asc = dlg.keys.first().map(|(_, a, _)| *a).unwrap_or(true);
            self.run_reorder(rect, data_reorder::Operation::Columns { row, asc });
            return;
        }
        let keys: Vec<sheetcore::data_tools::SortKey> = dlg
            .keys
            .iter()
            .filter(|(_, _, on)| *on)
            .map(|(c, asc, _)| sheetcore::data_tools::SortKey {
                col: *c,
                asc: *asc,
                ignore_case: true,
                mode: match dlg.sort_mode {
                    1 => sheetcore::data_tools::SortMode::Pinyin,
                    3 => sheetcore::data_tools::SortMode::Stroke,
                    2 => sheetcore::data_tools::SortMode::Custom(
                        dlg.custom
                            .split(['，', ',', '、', ';'])
                            .map(|x| x.trim().to_string())
                            .filter(|x| !x.is_empty())
                            .collect(),
                    ),
                    _ => sheetcore::data_tools::SortMode::Default,
                },
            })
            .collect();
        if keys.is_empty() {
            self.status = "至少选一列排序".into();
            return;
        }
        self.run_reorder(rect, data_reorder::Operation::Multi { keys, header: dlg.header });
    }

    /// 删除重复（旧入口/探针用）：全列比较、无对话框。
    fn run_dedup(&mut self) {
        let Some((r1, c1, r2, c2)) = self.clamp_rect_to_used(self.sel_rect()) else {
            self.status = "没有重复行".into();
            return;
        };
        let header = sheetcore::sort_filter::has_header(self.wb.sheet(self.sheet_idx), r1, c1, r2, c2);
        self.apply_dedup((r1, c1, r2, c2), header, &[]);
    }

    /// UI-17.2：打开去重对话框（选列 + 实时预览）。
    fn open_dedup_dialog(&mut self) {
        let raw = self.sel_rect();
        let rect = self
            .clamp_rect_to_used(raw)
            .unwrap_or((raw.0, raw.1, raw.0, raw.3.min(raw.1 + 255)));
        let c2_clamped = rect.3.min(rect.1 + 511);
        let rect = (rect.0, rect.1, rect.2, c2_clamped);
        let header = sheetcore::sort_filter::has_header(
            self.wb.sheet(self.sheet_idx),
            rect.0,
            rect.1,
            rect.2,
            rect.3,
        );
        let cols = vec![true; (rect.3 - rect.1 + 1) as usize];
        self.dedup_dlg = Some(DedupDlg {
            owner: (self.doc_uid, self.wb.sheet(self.sheet_idx).identity),
            preview: None,
            rect,
            header,
            cols,
            cached_dup: None,
        });
    }

    fn apply_dedup(&mut self, rect: (u32, u32, u32, u32), header: bool, cols: &[u32]) {
        let Some((r1, c1, r2, c2)) = self.clamp_rect_to_used(rect) else {
            self.status = "没有重复行".into();
            return;
        };
        self.run_reorder((r1, c1, r2, c2), data_reorder::Operation::Dedup { cols: cols.to_vec(), header });
    }

    /// UI-22：Ctrl+Q 命令搜索（数据来自 ribbon 控件，执行走同一 ribbon_action）。
    fn command_palette(&mut self, ctx: &egui::Context) {
        if ctx.input(|i| i.modifiers.ctrl && i.key_pressed(egui::Key::Q)) {
            self.palette_open = true;
            self.palette_q.clear();
            self.palette_idx = 0;
        }
        if !self.palette_open {
            return;
        }
        let all = palette::entries(self);
        let mut hits = palette::filter(&all, &self.palette_q);
        // UI-22.1：常用命令排前面（相同查询下次数多的优先）
        crate::cmdusage::rank(&mut hits, &crate::cmdusage::load());
        let max_idx = hits.len().saturating_sub(1);
        self.palette_idx = self.palette_idx.min(max_idx);
        // UI-22 验收要求方向键选择，不能只让 Enter 永远执行第一条。
        let down = ctx.input(|i| i.key_pressed(egui::Key::ArrowDown));
        let up = ctx.input(|i| i.key_pressed(egui::Key::ArrowUp));
        let nav_moved = (down || up) && !hits.is_empty();
        if std::env::var("SC_PALETTE_LOG").is_ok() {
            eprintln!(
                "[palette] down={down} up={up} idx={} hits={}",
                self.palette_idx,
                hits.len()
            );
        }
        if down && !hits.is_empty() {
            self.palette_idx = palette::step_index(self.palette_idx, hits.len(), 1);
        } else if up && !hits.is_empty() {
            self.palette_idx = palette::step_index(self.palette_idx, hits.len(), -1);
        }
        let mut open = true;
        let mut win_open = true;
        let mut clicked = false;
        let mut run: Option<String> = None;
        let screen = ctx.screen_rect();
        let pw = 516.0f32.min((screen.width() - 24.0).max(280.0));
        let px = screen.center().x - pw * 0.5;
        let py = (screen.top() + 56.0).min((screen.bottom() - 120.0).max(screen.top() + 8.0));
        // 轻柔背景遮罩：点击空白处即可收起命令搜索面板
        egui::Area::new(egui::Id::new("cmd_palette_backdrop"))
            .order(egui::Order::Middle)
            .fixed_pos(screen.min)
            .show(ctx, |ui| {
                let r = egui::Rect::from_min_size(screen.min, screen.size());
                ui.painter().rect_filled(r, 0.0, Color32::from_rgba_unmultiplied(15, 23, 42, 26));
                if ui.interact(r, egui::Id::new("cmd_palette_bg_click"), egui::Sense::click()).clicked() {
                    win_open = false;
                }
            });
        egui::Area::new(egui::Id::new("cmd_palette_card"))
            .order(egui::Order::Foreground)
            .fixed_pos(egui::pos2(px, py))
            .show(ctx, |ui| {
                egui::Frame::NONE
                    .fill(Color32::WHITE)
                    .stroke(Stroke::new(1.0, ui_kit::CARD_BORDER))
                    .corner_radius(egui::CornerRadius::same(10))
                    .shadow(egui::epaint::Shadow {
                        offset: [0, 14],
                        blur: 34,
                        spread: 0,
                        color: Color32::from_black_alpha(36),
                    })
                    .inner_margin(egui::Margin::same(14))
                    .show(ui, |ui| {
                        ui.set_width(pw - 28.0);
                        // 顶部搜索输入舱
                        let (srect, _) = ui.allocate_exact_size(
                            Vec2::new(ui.available_width(), 38.0),
                            Sense::hover(),
                        );
                        ui.painter().rect(
                            srect,
                            7.0,
                            Color32::from_rgb(248, 250, 253),
                            Stroke::new(1.5, ui_kit::BRAND_NAVY),
                            egui::StrokeKind::Inside,
                        );
                        ui_icons::draw(
                            ui.painter(),
                            Rect::from_center_size(
                                egui::pos2(srect.left() + 18.0, srect.center().y),
                                Vec2::splat(15.0),
                            ),
                            Icon::Find,
                            ui_kit::BRAND_NAVY,
                        );
                        let inner_te = Rect::from_min_max(
                            egui::pos2(srect.left() + 34.0, srect.top() + 5.0),
                            egui::pos2(srect.right() - 10.0, srect.bottom() - 5.0),
                        );
                        let mut child = ui.new_child(
                            egui::UiBuilder::new()
                                .max_rect(inner_te)
                                .layout(egui::Layout::left_to_right(egui::Align::Center)),
                        );
                        let te = child.add(
                            egui::TextEdit::singleline(&mut self.palette_q)
                                .frame(false)
                                .font(FontId::proportional(13.0))
                                .hint_text(
                                    egui::RichText::new("搜索功能命令，如：冻结窗格、条件格式、数据透视表、共享…")
                                        .size(12.5)
                                        .color(Color32::from_rgb(148, 163, 184)),
                                )
                                .desired_width(inner_te.width()),
                        );
                        if te.changed() {
                            self.palette_idx = 0;
                        }
                        te.request_focus();
                        ui.add_space(6.0);
                        ui.horizontal(|ui| {
                            ui.label(
                                egui::RichText::new(format!("匹配 {} 项命令", hits.len()))
                                    .size(11.0)
                                    .color(ui_kit::TEXT_WEAK),
                            );
                            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                                ui.label(
                                    egui::RichText::new("↑↓ 选择   Enter 执行   Esc 关闭")
                                        .size(11.0)
                                        .color(Color32::from_rgb(148, 163, 184)),
                                );
                            });
                        });
                        ui.add_space(4.0);
                        egui::ScrollArea::vertical()
                            .max_height(308.0)
                            .auto_shrink([false, true])
                            .show(ui, |ui| {
                                ui.spacing_mut().item_spacing.y = 2.0;
                                if hits.is_empty() {
                                    ui.add_space(18.0);
                                    ui.vertical_centered(|ui| {
                                        ui.label(
                                            egui::RichText::new("没有找到匹配的命令")
                                                .size(12.5)
                                                .color(ui_kit::TEXT_WEAK),
                                        );
                                    });
                                    ui.add_space(18.0);
                                }
                                for (i, e) in hits.iter().take(40).enumerate() {
                                    let selected = i == self.palette_idx;
                                    let rw = ui.available_width();
                                    let (rrect, resp) = ui.allocate_exact_size(
                                        Vec2::new(rw, 31.0),
                                        Sense::click(),
                                    );
                                    if selected {
                                        ui.painter().rect_filled(
                                            rrect,
                                            6.0,
                                            Color32::from_rgb(235, 243, 255),
                                        );
                                        let bar = Rect::from_min_size(
                                            egui::pos2(rrect.left() + 2.0, rrect.top() + 6.0),
                                            Vec2::new(3.0, rrect.height() - 12.0),
                                        );
                                        ui.painter().rect_filled(bar, 1.5, ui_kit::BRAND_NAVY);
                                    } else if resp.hovered() {
                                        ui.painter().rect_filled(rrect, 6.0, ui_kit::HOVER);
                                    }
                                    ui_kit::paint_medium(
                                        ui.painter(),
                                        egui::pos2(rrect.left() + 12.0, rrect.center().y),
                                        Align2::LEFT_CENTER,
                                        &e.label,
                                        12.5,
                                        if selected { ui_kit::BRAND_NAVY } else { ui_kit::TEXT },
                                    );
                                    let path_str = e.path();
                                    let pg = ui.painter().layout_no_wrap(
                                        path_str.clone(),
                                        FontId::proportional(11.0),
                                        ui_kit::TEXT_WEAK,
                                    );
                                    let chip = Rect::from_min_size(
                                        egui::pos2(
                                            rrect.right() - pg.size().x - 20.0,
                                            rrect.center().y - 10.0,
                                        ),
                                        Vec2::new(pg.size().x + 12.0, 20.0),
                                    );
                                    ui.painter().rect_filled(
                                        chip,
                                        4.0,
                                        if selected {
                                            Color32::from_rgb(219, 234, 254)
                                        } else {
                                            Color32::from_rgb(241, 245, 249)
                                        },
                                    );
                                    ui.painter().text(
                                        chip.center(),
                                        Align2::CENTER_CENTER,
                                        path_str,
                                        FontId::proportional(11.0),
                                        if selected { ui_kit::BRAND_NAVY } else { ui_kit::TEXT_WEAK },
                                    );
                                    if selected && nav_moved {
                                        resp.scroll_to_me(Some(egui::Align::Center));
                                    }
                                    if resp.clicked() {
                                        run = Some(e.action.clone());
                                        clicked = true;
                                    }
                                }
                            });
                    });
            });
        let esc = ctx.input(|i| i.key_pressed(egui::Key::Escape));
        if !win_open || clicked || esc {
            open = false;
        }
        if ctx.input(|i| i.key_pressed(egui::Key::Enter)) {
            if let Some(e) = hits.get(self.palette_idx) {
                run = Some(e.action.clone());
                open = false;
            }
        }
        if let Some(action) = run {
            if std::env::var("SC_PALETTE_LOG").is_ok() {
                eprintln!("[palette] run={action}");
            }
            self.ribbon_action(&action, ctx);
        }
        if !open && (esc || !win_open) {
            // Esc/关闭按钮把键盘交还网格：命令搜索的 TextEdit 必须同时 surrender，
            // 只 stop_text_input 不够，下一帧 wants_keyboard_input 仍会吞掉方向键。
            if let Some(id) = ctx.memory(|m| m.focused()) {
                ctx.memory_mut(|m| m.surrender_focus(id));
            }
            ctx.memory_mut(|m| m.stop_text_input());
            self.clear_grid_focus = true;
        }
        self.palette_open = open;
    }

    fn dedup_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.dedup_dlg.take() else { return };
        let (_, c1, _, c2) = dlg.rect;
        let chosen: Vec<u32> = (c1..=c2)
            .filter(|c| dlg.cols.get((c - c1) as usize).copied().unwrap_or(true))
            .collect();
        let sheet = self.wb.sheet(self.sheet_idx);
        if dlg.owner != (self.doc_uid, sheet.identity) { return; }
        if let Some(preview) = &dlg.preview {
            match preview.try_recv() {
                Ok(result) => { dlg.cached_dup = Some(result); dlg.preview = None; }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => dlg.preview = None,
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }
        let config = (dlg.header, dlg.cols.clone(), self.doc_gen, sheet.cell_revision());
        let mut dup = dlg.cached_dup.as_ref().filter(|(key, _)| key == &config).map(|(_, count)| *count);
        if dup.is_none() && !chosen.is_empty() && dlg.preview.is_none() {
            let rect = dlg.rect;
            let header = dlg.header;
            let area = u64::from(rect.2 - rect.0 + 1) * u64::from(rect.3 - rect.1 + 1);
            if area > 100_000 {
                let snapshot = sheet.search_snapshot();
                let columns = chosen.clone();
                let (tx, rx) = std::sync::mpsc::channel();
                let repaint = ctx.clone();
                std::thread::spawn(move || {
                    let count = sheetcore::data_tools::count_duplicates(&snapshot, rect, &columns, header);
                    let _ = tx.send((config, count));
                    repaint.request_repaint();
                });
                dlg.preview = Some(rx);
            } else {
                let count = sheetcore::data_tools::count_duplicates(sheet, rect, &chosen, header);
                dlg.cached_dup = Some((config, count));
                dup = Some(count);
            }
        }
        let mut open = true;
        let mut run = false;
        ui_kit::window(ctx, "删除重复", 360.0)
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.checkbox(&mut dlg.header, "数据包含标题");
                ui.separator();
                ui.label("用于判断重复的列：");
                egui::ScrollArea::vertical().max_height(240.0).show(ui, |ui| {
                    egui::Grid::new("dedup_cols").num_columns(2).show(ui, |ui| {
                        for c in c1..=c2 {
                            let i = (c - c1) as usize;
                            let name = self
                                .wb
                                .sheet(self.sheet_idx)
                                .get(dlg.rect.0, c)
                                .map(|x| x.value.display())
                                .unwrap_or_default();
                            let label = if dlg.header && !name.is_empty() {
                                format!("{} 列（{}）", col_label(c), name)
                            } else {
                                format!("{} 列", col_label(c))
                            };
                            let mut on = dlg.cols.get(i).copied().unwrap_or(true);
                            ui.checkbox(&mut on, label);
                            if i < dlg.cols.len() {
                                dlg.cols[i] = on;
                            }
                            ui.end_row();
                        }
                    });
                });
                ui.separator();
                ui.label(if chosen.is_empty() {
                    "至少要选一列".to_string()
                } else {
                    match dup {
                        Some(0) => "没有重复行".to_string(),
                        Some(count) => format!("预览：将删除 {count} 行重复"),
                        None => "正在计算重复行数…".to_string(),
                    }
                });
                ui.separator();
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui
                        .add_enabled(!chosen.is_empty(), egui::Button::new("执行"))
                        .clicked()
                    {
                        run = true;
                    }
                });
            });
        if run {
            let chosen_now: Vec<u32> = (c1..=c2)
                .filter(|c| dlg.cols.get((c - c1) as usize).copied().unwrap_or(true))
                .collect();
            self.apply_dedup(dlg.rect, dlg.header, &chosen_now);
        } else if open {
            self.dedup_dlg = Some(dlg);
        }
    }

    fn run_split(&mut self, dlg: &DataDlg) {
        let Some((r1, c1, r2, c2)) = self.clamp_rect_to_used(self.sel_rect()) else {
            self.status = "选区内没有可分列的数据".into();
            return;
        };
        let fixed = if dlg.split_fixed {
            match sheetcore::data_tools::parse_fixed_widths(&dlg.widths) {
                Some(w) => Some(w),
                None => {
                    self.status = "固定宽度要写正整数，逗号分隔，如 10,20,15".into();
                    return;
                }
            }
        } else {
            None
        };
        let opts = sheetcore::data_tools::SplitOpts {
            delim: dlg.delim.chars().next().unwrap_or(','),
            merge_consecutive: dlg.merge_consecutive && fixed.is_none(),
            quote: dlg.quote && fixed.is_none(),
            detect_types: dlg.detect_types,
            date_system: self.wb.date_system,
            fixed_widths: fixed,
            col_modes: parse_col_modes(&dlg.col_modes),
        };
        let dry = sheetcore::data_tools::text_to_columns_ex(
            self.wb.sheet_mut(self.sheet_idx),
            (r1, c1, r2, c2),
            &opts,
            true,
        );
        // 分列会向右写出 width 列：权限门禁和撤销都必须覆盖扩展后的区域
        let c2w = (c2 + dry.width.max(1) as u32 - 1).min(16_383);
        if (r2 - r1 + 1) as u64 * (c2w - c1 + 1) as u64 > 200_000 {
            self.status = "分列展开后超过 20 万格，请分批处理".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r1, c1, r2, c2w);
        if !self.write_preflight(&keys, "分列") {
            return;
        }
        if dry.overwritten > 0 && self.split_confirm != Some((self.doc_gen, dry.overwritten)) {
            self.split_confirm = Some((self.doc_gen, dry.overwritten));
            self.status = format!(
                "分列会覆盖右侧 {} 个非空格子，再点一次「执行」确认",
                dry.overwritten
            );
            return;
        }
        self.split_confirm = None;
        let txn = self.txn_begin(&keys);
        let report = sheetcore::data_tools::text_to_columns_ex(
            self.wb.sheet_mut(self.sheet_idx),
            (r1, c1, r2, c2),
            &opts,
            false,
        );
        let n = report.width;
        if !report.date_cells.is_empty() {
            let mut st = sheetcore::style::CellStyle::default();
            st.format = "yyyy-mm-dd".into();
            let id = self.wb.styles.intern(st);
            for (r, c) in &report.date_cells {
                self.wb.sheet_mut(self.sheet_idx).set_style(*r, *c, id);
            }
        }
        self.txn_end("分列", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.recalc_all_and_deps_adaptive();
        self.status = if n <= 1 {
            "没有找到分隔符".into()
        } else {
            format!("已分成 {n} 列")
        };
    }

    /// 打印预览：按页面设置分页，把每一页画成一张纸
    fn print_preview_window(&mut self, ctx: &egui::Context) {
        self.draw_print_preview_wps(ctx);
    }

    /// 打印页码范围（0 基闭区间）。None=全部；单页返回 (p,p)。
    fn print_page_span(&self, total: usize) -> Option<(usize, usize)> {
        let total = total.max(1);
        match self.print_range {
            1 => {
                let p = self.preview_page.min(total - 1);
                Some((p, p))
            }
            2 => {
                let a = (self.print_from.max(1) as usize - 1).min(total - 1);
                let b = (self.print_to.max(1) as usize - 1).min(total - 1);
                Some((a.min(b), b.max(a)))
            }
            _ => None,
        }
    }

    /// 真打印：先按页码范围导出 PDF，再按份数交给所选打印机。
    fn print_to_printer(&mut self) {
        let total = sheetcore::print::paginate(
            self.wb.sheet(self.sheet_idx),
            &self.wb.sheet(self.sheet_idx).page,
        )
        .pages
        .len()
        .max(1);
        let pages = self.print_page_span(total);
        let path = std::env::temp_dir().join(format!(
            "sheetcore-print-{}.pdf",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs())
                .unwrap_or(0)
        ));
        let regular = sheetcore::pdf::Font::parse(FONT_SANS.to_vec());
        let bold = sheetcore::pdf::Font::parse(FONT_SANS_BOLD.to_vec()).ok();
        let export = match regular {
            Ok(regular) => sheetcore::print::export_pdf_pages_with_fonts(
                &self.wb,
                self.sheet_idx,
                &path,
                regular,
                bold,
                self.wb.path.as_deref(),
                pages,
            ),
            Err(e) => Err(e),
        };
        match export {
            Ok(n) => {
                // 份数必须交给驱动：一个 PrintDocument 作业设置 Copies=N。
                // 旧实现循环起 N 个 Start-Process -Verb PrintTo，实际是 N 个单份作业，
                // 驱动看不到 Copies，也会在真实打印机上产生 N 个队列项。
                const PRINT_HELPER: &str = include_str!("../../../scripts/print_pdf.ps1");
                let helper = path.with_extension("ps1");
                let copies = self.print_copies.clamp(1, 99);
                let submitted = std::fs::write(&helper, PRINT_HELPER).and_then(|_| {
                    let mut cmd = hidden_console_cmd("powershell");
                    cmd.args(["-NoProfile", "-ExecutionPolicy", "Bypass", "-File"])
                        .arg(&helper)
                        .arg("-Path")
                        .arg(&path)
                        .arg("-Printer")
                        .arg(&self.page_setup_printer)
                        .arg("-Copies")
                        .arg(copies.to_string());
                    cmd.output()
                });
                let (ok, detail) = match submitted {
                    Ok(out) if out.status.success() => {
                        let text = String::from_utf8_lossy(&out.stdout);
                        let line = text
                            .lines()
                            .find(|l| l.starts_with("PRINTED=1"))
                            .unwrap_or("PRINTED=1");
                        (true, line.to_string())
                    }
                    Ok(out) => {
                        let err = String::from_utf8_lossy(&out.stderr);
                        (false, err.lines().last().unwrap_or("打印助手失败").to_string())
                    }
                    Err(e) => (false, e.to_string()),
                };
                let _ = std::fs::remove_file(&helper);
                self.status = if ok {
                    let target = if self.page_setup_printer.is_empty() {
                        "系统默认打印机".to_string()
                    } else {
                        self.page_setup_printer.clone()
                    };
                    format!(
                        "已提交 1 个打印任务（{copies} 份，{n} 页）到 {target}：{}（{detail}）",
                        path.display()
                    )
                } else {
                    format!("打印失败：{detail}")
                };
            }
            Err(e) => self.status = format!("生成打印文件失败：{e:#}"),
        }
    }

    fn export_pdf_dialog(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .set_file_name(format!("{}.pdf", self.wb.title()))
            .add_filter("PDF", &["pdf"])
            .save_file()
        else {
            return;
        };
        self.export_pdf_to(&path);
    }

    /// 导出当前工作表为 PDF（对话框与 SC_EXPORT_PDF 共用同一条路径）
    fn export_pdf_to(&mut self, path: &std::path::Path) {
        // PDF 用内嵌 SIL OFL 字体的常规+粗体两套（不再嵌 Windows 的 simhei.ttf）：
        // 粗体走 /F2 的真 700 字形，随包可分发。
        let regular = sheetcore::pdf::Font::parse(FONT_SANS.to_vec());
        let bold = sheetcore::pdf::Font::parse(FONT_SANS_BOLD.to_vec()).ok();
        match (regular, bold) {
            (Ok(regular), bold) => match sheetcore::print::export_pdf_pages_with_fonts(
                &self.wb,
                self.sheet_idx,
                path,
                regular,
                bold,
                self.wb.path.as_deref(),
                None,
            ) {
                Ok(n) => {
                    self.status = format!("已导出 {}", path.display());
                    eprintln!("[pdf] 已导出 {} 页 {}", n, path.display());
                }
                Err(e) => {
                    self.status = format!("导出失败：{e:#}");
                    eprintln!("[pdf] 导出失败 {e:#}");
                }
            },
            (Err(e), _) => {
                self.status = format!("导出失败：内嵌字体解析失败 {e:#}");
                eprintln!("[pdf] 内嵌字体解析失败 {e:#}");
            }
        }
    }

    /// 解一张图片并缓存纹理（解不出来就记 None，不反复重试）
    fn img_texture(
        &mut self,
        key: &str,
        part: &str,
        ctx: &egui::Context,
    ) -> Option<egui::TextureHandle> {
        if let Some(v) = self.img_cache.get(key) {
            return v.clone();
        }
        let loaded = (|| {
            let path = self.wb.path.as_ref()?;
            let bytes = sheetcore::pic::read_part(path, part)?;
            let img = image::load_from_memory(&bytes).ok()?.to_rgba8();
            let size = [img.width() as usize, img.height() as usize];
            let color = egui::ColorImage::from_rgba_unmultiplied(size, img.as_raw());
            Some(ctx.load_texture(key.to_string(), color, egui::TextureOptions::LINEAR))
        })();
        self.img_cache.insert(key.to_string(), loaded.clone());
        loaded
    }

    /// 内存字节的图片纹理（新插入、尚未保存）
    fn mem_texture(&mut self, key: &str, bytes: &[u8], ctx: &egui::Context) -> Option<egui::TextureHandle> {
        if let Some(v) = self.img_cache.get(key) {
            return v.clone();
        }
        let loaded = (|| {
            let img = image::load_from_memory(bytes).ok()?.to_rgba8();
            let size = [img.width() as usize, img.height() as usize];
            let color = egui::ColorImage::from_rgba_unmultiplied(size, img.as_raw());
            Some(ctx.load_texture(key.to_string(), color, egui::TextureOptions::LINEAR))
        })();
        self.img_cache.insert(key.to_string(), loaded.clone());
        loaded
    }

    /// 记录一次图片改动（插入/移动/缩放/删除）到撤销栈
    fn pic_commit(&mut self, label: &str, before: Vec<sheetcore::pic::Picture>) {
        let after = self.wb.sheet(self.sheet_idx).pictures.clone();
        if before == after {
            return;
        }
        self.wb.sheet_mut(self.sheet_idx).pictures_dirty = true;
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.undo.push(sheetcore::undo::Action {
            label: label.into(),
            merges: None,
            deltas: Vec::new(),
            focus: (self.sheet_idx, self.sel.0, self.sel.1),
            snap_before: None,
            snap_after: None,
            by_site: 0,
            pictures: Some(sheetcore::undo::PictureEdit {
                sheet: self.sheet_idx,
                before,
                after,
            }),
            shapes: None,
            refresh_sizes: None,
        });
    }

    /// 从文件读一张图，放进内存模型（不写盘；保存时才写回）
    fn insert_picture_file(&mut self, p: &std::path::Path) {
        let ext = p
            .extension()
            .map(|e| e.to_string_lossy().to_ascii_lowercase())
            .unwrap_or_else(|| "png".into());
        if !matches!(ext.as_str(), "png" | "jpg" | "jpeg" | "gif" | "bmp") {
            self.status = format!("不支持的图片格式：{ext}");
            return;
        }
        match std::fs::read(p) {
            Ok(bytes) => {
                let dims = match image::load_from_memory(&bytes) {
                    Ok(img) => (img.width(), img.height()),
                    Err(_) => {
                        self.status = "这张图无法解码（文件可能损坏）".into();
                        return;
                    }
                };
                let (w, h) = dims;
                let cols = ((w + 63) / 64).max(2);
                let rows = ((h + 19) / 20).max(2);
                let (r, c) = self.sel;
                let before = self.wb.sheet(self.sheet_idx).pictures.clone();
                let name = format!("图片 {}", before.len() + 1);
                self.wb.sheet_mut(self.sheet_idx).pictures.push(sheetcore::pic::Picture {
                    rect: (r, c, r + rows, c + cols),
                    off: [0; 4],
                    part: sheetcore::pic_write::memory_part(&bytes, &ext),
                    data: Some(std::sync::Arc::new(bytes)),
                    ext,
                    name,
                });
                self.pic_commit("插入图片", before);
                self.status = "已插入图片（保存后才写回文件，可撤销）".into();
            }
            Err(e) => self.status = format!("读图片失败：{e}"),
        }
    }

    /// Delete 命中选中的图片：删除并进撤销栈
    fn pic_delete(&mut self, i: usize) {
        let before = self.wb.sheet(self.sheet_idx).pictures.clone();
        if i >= before.len() {
            return;
        }
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.pictures.remove(i);
        }
        self.pic_sel = None;
        self.pic_commit("删除图片", before);
        self.status = "已删除图片（可撤销）".into();
    }

    /// 导入 CSV/TSV 到当前选区左上角
    fn import_csv(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .add_filter("CSV / TSV", &["csv", "tsv", "txt"])
            .pick_file()
        else {
            return;
        };
        self.open_csv_dialog(&path);
    }

    /// 选一个工作簿，把它的每张表复制到当前工作簿末尾（值 + 公式）
    fn import_workbook(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .add_filter("Excel 工作簿", &["xlsx", "xlsm", "xls"])
            .pick_file()
        else {
            return;
        };
        let other = match sheetcore::xlsx::load(&path) {
            Ok(w) => w,
            Err(e) => {
                self.status = format!("打开失败：{e:#}");
                return;
            }
        };
        let txn = self.txn_begin(&[]);
        let mut added: Vec<String> = Vec::new();
        for src in other.sheets.iter() {
            let mut name = src.name.clone();
            let mut n = 2;
            while self.wb.sheets.iter().any(|s| s.name == name) {
                name = format!("{} ({n})", src.name);
                n += 1;
            }
            let mut sheet = src.clone();
            sheet.name = name.clone();
            sheet.charts.clear();
            sheet.tables.clear();
            added.push(name);
            self.wb.sheets.push(sheet);
        }
        let n = added.len();
        if let Some(first) = self.wb.sheets.len().checked_sub(n) {
            self.sheet_idx = first;
        }
        self.sel = (0, 0);
        self.sel_end = self.sel;
        self.txn_end("导入工作簿", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = if n == 0 {
            "目标文件里没有工作表".into()
        } else {
            format!("已导入 {n} 张表：{}", added.join("、"))
        };
    }

    /// C09：选文件后先打开选项对话框（编码/引号/表头/文本列 + 真实预览）
    fn open_csv_dialog(&mut self, path: &std::path::Path) {
        self.csv_dlg = Some(CsvDlg::new(path));
    }

    fn csv_dlg_ui(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.csv_dlg.take() else { return };
        let loading = dlg.poll_loading();
        if loading {
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
        }
        let mut win_open = true;
        let mut close = false;
        let mut import = false;
        let mut changed = false;
        ui_kit::window(ctx, "导入 CSV 文本向导", 600.0)
            .open(&mut win_open)
            .collapsible(false)
            .resizable(true)
            .default_width(600.0)
            .show(ctx, |ui| {
                ui.label(format!("文件：{}", dlg.path.display()));
                if loading {
                    ui.label("正在读取 CSV…");
                }
                ui.add_enabled_ui(!loading, |ui| ui.horizontal(|ui| {
                    ui.label("编码");
                    let label = match dlg.enc {
                        None => "自动".to_string(),
                        Some(e) => e.id().to_string(),
                    };
                    egui::ComboBox::from_id_salt("csv_enc")
                        .selected_text(label)
                        .show_ui(ui, |ui| {
                            if ui.selectable_label(dlg.enc.is_none(), "自动（BOM/UTF-8/GB18030）").clicked() {
                                dlg.enc = None;
                                changed = true;
                            }
                            for e in [
                                sheetcore::csv::Encoding::Utf8,
                                sheetcore::csv::Encoding::Utf16Le,
                                sheetcore::csv::Encoding::Gb18030,
                            ] {
                                if ui.selectable_label(dlg.enc == Some(e), e.id()).clicked() {
                                    dlg.enc = Some(e);
                                    changed = true;
                                }
                            }
                        });
                    ui.separator();
                    ui.label("引号");
                    let mut q = dlg.quote.to_string();
                    if ui.add(egui::TextEdit::singleline(&mut q).desired_width(28.0)).changed() {
                        if let Some(c) = q.chars().next() {
                            dlg.quote = c;
                            changed = true;
                        }
                    }
                    ui.separator();
                    ui.checkbox(&mut dlg.header, "首行是表头");
                }));
                ui.label("勾选下面的列按文本导入（保留 00123、18 位账号这类前导零）：");
                egui::ScrollArea::both().max_height(260.0).show(ui, |ui| {
                    egui::Grid::new("csv_preview").striped(true).show(ui, |ui| {
                        let cols = dlg.cols;
                        for c in 0..cols {
                            let mut on = dlg.text_cols.contains(&(c as u32));
                            if ui.checkbox(&mut on, format!("第 {} 列", c + 1)).changed() {
                                if on {
                                    dlg.text_cols.insert(c as u32);
                                } else {
                                    dlg.text_cols.remove(&(c as u32));
                                }
                            }
                        }
                        ui.end_row();
                        for row in dlg.preview.iter().take(8) {
                            for c in 0..cols {
                                ui.label(row.get(c).cloned().unwrap_or_default());
                            }
                            ui.end_row();
                        }
                    });
                });
                if let Some(e) = &dlg.err {
                    ui.colored_label(egui::Color32::RED, e);
                }
                ui_kit::footer(ui, |ui| {
                    if !loading && !changed && dlg.err.is_none() {
                        if ui_kit::primary_button(ui, "导入").clicked() {
                            import = true;
                        }
                    } else {
                        ui.add_enabled(false, egui::Button::new("导入").min_size(Vec2::new(84.0, 32.0)));
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        close = true;
                    }
                });
            });
        if close || !win_open {
            return;
        }
        if import {
            let cols: Vec<u32> = dlg.text_cols.into_iter().collect();
            self.apply_csv_records(&dlg.path, dlg.delim, dlg.header, dlg.used_encoding, dlg.quote, &cols, dlg.preview);
        } else {
            if changed {
                dlg.reload();
            }
            self.csv_dlg = Some(dlg);
        }
    }

    fn import_csv_from(&mut self, path: &std::path::Path) {
        self.import_csv_choice(path, ',', false, None, '"', &[]);
    }

    /// C09：按用户在导入对话框里选的编码/引号/文本列导入，并把选择持久化到数据源。
    fn import_csv_choice(
        &mut self,
        path: &std::path::Path,
        delim: char,
        header: bool,
        enc: Option<sheetcore::csv::Encoding>,
        quote: char,
        text_cols: &[u32],
    ) {
        match csv_import::read_csv(path, Some(delim), enc, quote) {
            Ok(data) => self.apply_csv_records(path, data.delim, header, data.encoding, quote, text_cols, data.rows),
            Err(e) => self.status = format!("CSV 导入失败（没有写入任何格）：{e}"),
        }
    }

    fn apply_csv_records(
        &mut self,
        path: &std::path::Path,
        delim: char,
        header: bool,
        used_enc: sheetcore::csv::Encoding,
        quote: char,
        text_cols: &[u32],
        records: Vec<Vec<String>>,
    ) {
        if records.is_empty() {
            self.status = "这个文件里没有可导入的内容".into();
            return;
        }
        let (r0, c0) = self.sel;
        let keys: Vec<_> = records.iter().enumerate().flat_map(|(r, row)| {
            (0..row.len()).map(move |c| (r0 + r as u32, c0 + c as u32))
        }).collect();
        let txn = self.txn_begin(&keys);
        let size = sheetcore::external::import_csv_records(
            self.wb.sheet_mut(self.sheet_idx), records, header, text_cols, (0, 0), (r0, c0),
        );
        self.txn_end("导入 CSV", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let stored_path = sheetcore::external::store_path(&self.wb, path);
        let key = (stored_path.clone(), r0, c0);
        let existing = self.wb.sources.iter_mut().find(|src| match &src.kind {
            sheetcore::external::Kind::Csv { path: p, .. } => {
                (p.clone(), src.at.0, src.at.1) == key
            }
            _ => false,
        });
        let opts = sheetcore::external::CsvOpts {
            encoding: Some(used_enc),
            text_cols: text_cols.to_vec(),
            quote,
        };
        match existing {
            Some(src) => {
                src.rows = size.0;
                src.cols = size.1;
                src.csv_opts = Some(opts);
            }
            None => {
                let src = sheetcore::external::Source {
                    name: String::new(),
                    kind: sheetcore::external::Kind::Csv {
                        path: stored_path,
                        delim,
                        header,
                    },
                    at: (r0, c0),
                    rows: size.0,
                    cols: size.1,
                    csv_opts: Some(opts),
                };
                self.wb.sources.push(src);
                let mut n = self.wb.sources.len();
                loop {
                    let name = format!("_sc_src_{n}");
                    if !self.wb.sources.iter().any(|s| s.name == name) {
                        self.wb.sources.last_mut().unwrap().name = name;
                        break;
                    }
                    n += 1;
                }
            }
        }
        self.status = format!("已导入 {} 行 × {} 列", size.0, size.1);
    }

    /// 刷新数据：优先按登记过的数据源重读，没有就退回"上次导入"
    fn refresh_import(&mut self) {
        if self.wb.sources.is_empty() {
            match self.last_import.clone() {
                Some((path, r, c)) => {
                    self.sel = (r, c);
                    self.sel_end = (r, c);
                    self.import_csv_from(&path);
                }
                None => self.status = "还没有导入过外部数据".into(),
            }
            return;
        }
        let idx = self.sheet_idx;
        let sources = self.wb.sources.clone();
        let before_sizes: Vec<(String, u32, u32)> =
            sources.iter().map(|s| (s.name.clone(), s.rows, s.cols)).collect();
        // 刷新是一步可撤销操作：整表快照 + 源尺寸前后值
        let snap_before = sheetcore::undo::snapshot_sheet(self.wb.sheet(idx), idx);
        let mut ok = 0;
        let mut fail = 0;
        for mut src in sources {
            match sheetcore::external::refresh(&mut self.wb, idx, &src) {
                Ok((rows, cols)) => {
                    ok += 1;
                    // 行数变了就更新记录，下次保存写回去
                    if let Some(slot) = self.wb.sources.iter_mut().find(|s| s.name == src.name) {
                        slot.rows = rows;
                        slot.cols = cols;
                    }
                    src.rows = rows;
                }
                Err(_) => fail += 1,
            }
        }
        if ok > 0 {
            let snap_after = sheetcore::undo::snapshot_sheet(self.wb.sheet(idx), idx);
            let after_sizes: Vec<(String, u32, u32)> =
                self.wb.sources.iter().map(|s| (s.name.clone(), s.rows, s.cols)).collect();
            self.undo.push(sheetcore::undo::Action {
                label: "刷新外部数据".into(),
                merges: None,
                deltas: Vec::new(),
                focus: (idx, self.sel.0, self.sel.1),
                snap_before: Some(snap_before),
                snap_after: Some(snap_after),
                by_site: 0,
                pictures: None,
                shapes: None,
                refresh_sizes: Some((before_sizes, after_sizes)),
            });
        }
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = if fail == 0 {
            format!("已刷新 {ok} 个数据源")
        } else {
            format!("刷新完成：成功 {ok}，失败 {fail}")
        };
    }


/// 富格式块和 TSV 文本是否来自同一次复制（用于识别过期 HTML）。
fn office_block_tsv(block: &office_clipboard::OfficeBlock) -> String {
    let width = block
        .rows
        .iter()
        .map(|row| row.iter().map(|c| c.colspan.max(1) as usize).sum())
        .max()
        .unwrap_or(0);
    let mut tsv = String::new();
    for (i, row) in block.rows.iter().enumerate() {
        if i > 0 {
            tsv.push('\n');
        }
        let mut ci = 0usize;
        for cell in row {
            if ci > 0 {
                tsv.push('\t');
            }
            tsv.push_str(&cell.text.replace('\r', ""));
            ci += 1;
            for _ in 1..cell.colspan.max(1) {
                tsv.push('\t');
                ci += 1;
            }
        }
        while ci < width {
            tsv.push('\t');
            ci += 1;
        }
    }
    tsv
}

    /// 把从 Excel 复制来的块贴进来：值 + 格式 + 合并
    fn paste_office_block(&mut self, block: &office_clipboard::OfficeBlock) -> bool {
        if block.is_empty() {
            return false;
        }
        let (r0, c0) = self.sel;
        // Spans count toward the write footprint, including otherwise empty merged cells.
        let cols = block.rows.iter().map(|row| row.iter().map(|c| u64::from(c.colspan.max(1))).sum::<u64>()).max().unwrap_or(0);
        let rows = block.rows.iter().enumerate().map(|(i, row)| {
            i as u64 + u64::from(row.iter().map(|c| c.rowspan.max(1)).max().unwrap_or(1))
        }).max().unwrap_or(0);
        if rows.saturating_mul(cols) > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64
            || u64::from(r0) + rows > 1_048_576 || u64::from(c0) + cols > 16_384
        {
            self.status = "粘贴区域超过工作表边界或单次 50 万格上限".into();
            return true;
        }
        let (rows, cols) = (rows as u32, cols as u32);
        let keys = sheetcore::undo::rect_keys(r0, c0, r0 + rows - 1, c0 + cols - 1);
        if !self.write_preflight(&keys, "从 Excel 粘贴") { return true; }
        let si = self.sheet_idx;
        let mut incoming = Vec::new();
        for (ri, row) in block.rows.iter().enumerate() {
            let r = r0 + ri as u32;
            let mut c = c0;
            for cell in row {
                if cell.colspan > 1 || cell.rowspan > 1 {
                    incoming.push((r, c, r + cell.rowspan.max(1) - 1, c + cell.colspan.max(1) - 1));
                }
                c += cell.colspan.max(1);
            }
        }
        let merge_edit = match self.paste_merge_edit((r0, c0, r0 + rows - 1, c0 + cols - 1), &incoming, None) {
            Ok(edit) => edit,
            Err(message) => { self.status = message.into(); return true; }
        };
        if let Some(edit) = &merge_edit {
            let Some(changes) = edit.apply(&mut self.wb.sheets, true) else {
                self.status = "粘贴区域中的合并单元格相互冲突".into();
                return true;
            };
            if let Some(net) = &self.net {
                for (sheet, rect, on) in changes { net.broadcast_merge(sheet, rect, on); }
            }
        }
        let txn = self.txn_begin(&keys);
        let mut touched = Vec::new();
        for (ri, row) in block.rows.iter().enumerate() {
            let mut ci: u32 = 0;
            for cell in row {
                let r = r0 + ri as u32;
                let c = c0 + ci;
                touched.push((si, r, c));
                // 值：带公式的按缓存值类型走，之后统一重算
                let text = cell.text.trim();
                let value = if cell.formula.is_some() {
                    match cell.kind {
                        0 => text
                            .replace(',', "")
                            .parse::<f64>()
                            .map(Value::Number)
                            .unwrap_or(Value::Empty),
                        2 => Value::Bool(text == "1" || text.eq_ignore_ascii_case("true")),
                        4 => sheetcore::formula::ErrKind::from_text(text)
                            .map(Value::Error)
                            .unwrap_or(Value::Text(text.into())),
                        _ => {
                            if text.is_empty() {
                                Value::Empty
                            } else {
                                Value::Text(text.into())
                            }
                        }
                    }
                } else if let Some(raw) = cell.raw.as_deref() {
                    // HTML 的 x:num/x:str 是原始值；text 只是显示文本。日期按序列号
                    // 存回，配合 mso-number-format 保持类型和显示都正确。
                    if raw.is_empty() {
                        Value::Empty
                    } else if cell.kind == 2 {
                        Value::Bool(raw == "1" || raw.eq_ignore_ascii_case("true"))
                    } else if cell.kind == 0 {
                        match raw.replace(',', "").parse::<f64>() {
                            Ok(n) => Value::Number(n),
                            Err(_) => Value::Text(raw.into()),
                        }
                    } else {
                        Value::Text(raw.into())
                    }
                } else if text.is_empty() {
                    Value::Empty
                } else if cell.kind == 4 {
                    // 从 Excel 复制的错误格：还原成错误值，别当文本也别当 0
                    sheetcore::formula::ErrKind::from_text(text)
                        .map(Value::Error)
                        .unwrap_or_else(|| Value::Text(text.into()))
                } else if cell.kind == 3 {
                    // 从 Excel/WPS 复制的日期：XMLSS 给的是 ISO 文本，不是序列号。
                    // 按**目标簿的日期体系**重算序列号（1900/1904 差 1462 天），
                    // 顺手补一个日期格式，否则粘进来是 45293 这样的裸数字。
                    match sheetcore::clipboard_xmlss::iso_to_serial(self.wb.date_system, text) {
                        Some((serial, _)) => {
                            if cell.num_format.trim().is_empty() {
                                let sid = self.wb.styles.intern(sheetcore::style::CellStyle {
                                    format: "yyyy-mm-dd".into(),
                                    ..Default::default()
                                });
                                self.wb.sheet_mut(si).set_style(r, c, sid);
                            }
                            Value::Number(serial)
                        }
                        None => Value::Text(text.into()),
                    }
                } else if cell.kind == 0 {
                    // 只有 XMLSS 标成 Number 的才按数字落格；Text 一律保持文本，
                    // 否则 "00123" 这类前导零文本会被 f64 吃掉零（Excel 自己粘不丢）。
                    match text.replace(',', "").parse::<f64>() {
                        Ok(n) => Value::Number(n),
                        Err(_) => Value::Text(text.into()),
                    }
                } else {
                    Value::Text(text.into())
                };
                self.wb.sheet_mut(si).set(
                    r,
                    c,
                    Cell { value, formula: cell.formula.as_deref().map(|f| f.into()) },
                );

                // 格式
                let base_id = self.wb.sheet(si).style_of(r, c);
                let mut st = self.wb.styles.get(base_id).clone();
                let mut touched = false;
                if cell.bold != st.bold {
                    st.bold = cell.bold;
                    touched = true;
                }
                if cell.italic != st.italic {
                    st.italic = cell.italic;
                    touched = true;
                }
                if let Some(fill) = cell.fill {
                    st.fill = Some(fill);
                    touched = true;
                }
                if let Some(color) = cell.color {
                    st.color = color;
                    touched = true;
                }
                if cell.halign != 0 && cell.halign != st.halign {
                    st.halign = cell.halign;
                    touched = true;
                }
                if let Some(bc) = cell.border {
                    for side in st.border.iter_mut() {
                        if side.style == 0 {
                            side.style = 1;
                            side.color = bc;
                        }
                    }
                    touched = true;
                }
                // XML Spreadsheet 还带了字体名/字号/数字格式，HTML 那条路没有
                if !cell.font.is_empty() {
                    let f = sheetcore::style::normalize_font(&cell.font);
                    if f != st.font {
                        st.font = f;
                        touched = true;
                    }
                }
                if cell.size > 0.0 && (cell.size - st.size).abs() > 0.01 {
                    st.size = cell.size;
                    touched = true;
                }
                if !cell.num_format.is_empty() && cell.num_format != st.format {
                    st.format = cell.num_format.clone();
                    touched = true;
                }
                if touched {
                    let id = self.wb.styles.intern(st.clone());
                    self.wb.sheet_mut(si).set_style(r, c, id);
                }

                ci += cell.colspan.max(1);
            }
        }

        // Constants are precedents too. Replacing a formula also removes its old edges.
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.fast_recalc_cells(&touched);

        let deltas = sheetcore::undo::finish(txn, self.wb.sheet(si));
        if self.net.is_some() {
            let style_keys: Vec<_> = deltas.iter().filter(|d| d.before_style != d.after_style)
                .map(|d| (d.sheet, d.row, d.col)).collect();
            self.broadcast_cell_styles(&style_keys);
        }
        self.record_deltas_and_merges("从 Excel 粘贴", deltas, merge_edit);
        self.broadcast_cells(&touched);
        self.wb.dirty = true;
        self.sel_end = (r0 + rows - 1, c0 + cols - 1);
        self.status = format!("已粘贴 Excel 区域 {rows} 行 × {cols} 列（含格式与合并）");
        eprintln!("[paste] office 块 {rows}x{cols}");
        true
    }

    /// 把选区转成 Excel 表格对象（ListObject），首行当列名
    fn make_table(&mut self) {
        let raw = self.sel_rect();
        let (r1, c1, r2, c2) = self
            .clamp_rect_to_used(raw)
            .unwrap_or((raw.0, raw.1, raw.2.min(raw.0 + 1), raw.3.min(raw.1 + 1)));
        if r2 - r1 < 1 || c2 == c1 {
            self.status = "表格至少要两行两列（首行是列名）".into();
            return;
        }
        if c2 - c1 + 1 > 512 {
            self.status = "表格列数过多（最多支持 512 列），请缩小选区".into();
            return;
        }
        let mut names: Vec<String> = Vec::new();
        for c in c1..=c2 {
            let v = self
                .wb
                .sheet(self.sheet_idx)
                .get(r1, c)
                .map(|x| x.value.display())
                .unwrap_or_default();
            names.push(if v.trim().is_empty() {
                format!("列{}", c - c1 + 1)
            } else {
                v
            });
        }
        // 名字不能重复，Excel 也不允许
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        for i in 0..names.len() {
            let mut base = names[i].clone();
            let mut k = 2;
            while seen.contains(&base.to_lowercase()) {
                base = format!("{}_{k}", names[i]);
                k += 1;
            }
            seen.insert(base.to_lowercase());
            names[i] = base;
        }
        let existing: std::collections::HashSet<String> = self
            .wb
            .sheet(self.sheet_idx)
            .tables
            .iter()
            .map(|t| t.name.to_lowercase())
            .collect();
        let mut n = 1usize;
        while existing.contains(&format!("table{n}")) {
            n += 1;
        }
        let name = format!("Table{n}");
        let t = sheetcore::table::Table {
                column_ids: Vec::new(),
            name: name.clone(),
            display: name.clone(),
            range: (r1, c1, r2, c2),
            columns: names,
            header_row: true,
            totals_row: false,
        };
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.tables.push(t);
            sh.tables_dirty = true;
            // Excel 建表默认带筛选按钮
            sh.filter = Some(sheetcore::sort_filter::Filter::new(r1, c1, r2, c2));
            sh.filter_dirty = true;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已创建表格 {}（{}）", name, sheetcore::table::a1((r1, c1, r2, c2)));
    }

    /// 局域网实时协作中心：展示共享盘自动连线状态、本机地址、在线成员 ID、单元格编辑锁及跨表一键定位
    fn members_window(&mut self, ctx: &egui::Context) {
        if !self.members_open {
            return;
        }
        let mut open = true;
        let mut jump: Option<(usize, u32, u32)> = None;
        let mut do_host = false;
        let mut do_join = false;
        let mut do_leave = false;
        let mut do_fw = false;
        let mut toggle_dir_share: Option<bool> = None;

        let hosting = self.net.as_ref().map(|n| n.hosting).unwrap_or(false);
        let connected = self.net.is_some();
        let me = self.net.as_ref().map(|n| n.site);
        let cache_stale = self
            .collab_ui_cache
            .as_ref()
            .map(|(t, _, _, _)| t.elapsed().as_secs() >= 2)
            .unwrap_or(true);
        if cache_stale {
            let lock_host = if hosting {
                Some(format!("{}:{}", local_ip_hint(), self.active_net_port()))
            } else {
                self.wb
                    .path
                    .as_ref()
                    .and_then(|p| session_lock::read(p))
                    .map(|i| i.host)
            };
            let (marked, auto_net) = match self.wb.path.as_ref() {
                Some(p) => (
                    session_lock::is_dir_marked_shared(p),
                    session_lock::is_network_path(p),
                ),
                None => (false, false),
            };
            self.collab_ui_cache = Some((std::time::Instant::now(), lock_host, marked, auto_net));
        }
        let (_, cached_lock_host, marked, auto_net) = self
            .collab_ui_cache
            .clone()
            .unwrap_or((std::time::Instant::now(), None, false, false));
        let host_addr = if hosting {
            cached_lock_host.or_else(|| Some(format!("{}:{}", local_ip_hint(), self.active_net_port())))
        } else {
            cached_lock_host.or_else(|| {
                if !self.join_addr.trim().is_empty() {
                    Some(self.join_addr.trim().to_string())
                } else {
                    None
                }
            })
        };

        ui_kit::window(ctx, "局域网实时协作", 408.0)
            .open(&mut open)
            .default_width(408.0)
            .show(ctx, |ui| {
                // 1. 顶部实时会话状态卡片
                let (bg_col, bd_col, dot_col, headline) = if hosting {
                    (
                        Color32::from_rgb(240, 253, 244),
                        Color32::from_rgb(187, 247, 208),
                        Color32::from_rgb(22, 163, 74),
                        format!("正在实时共享 · 在线 {} 人", self.peers_list.len().max(1)),
                    )
                } else if connected {
                    (
                        Color32::from_rgb(239, 246, 255),
                        Color32::from_rgb(191, 219, 254),
                        ui_kit::BRAND_NAVY,
                        format!("已接入实时协同 · 在线 {} 人", self.peers_list.len().max(1)),
                    )
                } else {
                    (
                        Color32::from_rgb(248, 250, 252),
                        ui_kit::CARD_BORDER,
                        Color32::from_rgb(148, 163, 184),
                        "单机编辑模式".to_string(),
                    )
                };
                egui::Frame::NONE
                    .fill(bg_col)
                    .stroke(Stroke::new(1.0, bd_col))
                    .corner_radius(egui::CornerRadius::same(8))
                    .inner_margin(egui::Margin::same(12))
                    .show(ui, |ui| {
                        ui.set_width(ui.available_width());
                        ui.horizontal(|ui| {
                            let (drect, _) = ui.allocate_exact_size(Vec2::splat(10.0), Sense::hover());
                            ui.painter().circle_filled(drect.center(), 4.2, dot_col);
                            ui_kit::paint_medium(
                                ui.painter(),
                                egui::pos2(drect.right() + 6.0, drect.center().y),
                                Align2::LEFT_CENTER,
                                &headline,
                                12.5,
                                ui_kit::TEXT,
                            );
                        });
                        if let Some(addr) = &host_addr {
                            if connected {
                                ui.add_space(6.0);
                                ui.horizontal(|ui| {
                                    ui.label(
                                        egui::RichText::new(format!("会话地址：{addr}"))
                                            .monospace()
                                            .size(11.5)
                                            .color(ui_kit::TEXT),
                                    );
                                    if ui_kit::pill(ui, "复制地址", "复制 IP:端口 发送给其他用户手动加入").clicked() {
                                        ctx.copy_text(addr.clone());
                                        self.status = format!("已复制协作地址：{addr}");
                                    }
                                });
                            }
                        }
                    });

                // 2. 网盘/共享文件夹协同目录识别与一键标记
                if self.wb.path.is_some() {
                    ui.add_space(4.0);
                    ui.horizontal(|ui| {
                        let mut flag = marked || auto_net;
                        let chk = ui.checkbox(
                            &mut flag,
                            egui::RichText::new("将所在文件夹标记为协作目录").size(12.0),
                        );
                        if chk.changed() {
                            toggle_dir_share = Some(flag);
                        }
                    });
                }

                ui.add_space(6.0);

                if !connected {
                    dlg_section(ui, "手动连接");
                    ui.checkbox(&mut self.auto_share, "打开共享文件时自动协作");
                    ui.horizontal(|ui| {
                        if ui_kit::primary_button(ui, "开启局域网共享").clicked() {
                            do_host = true;
                        }
                        if ui_kit::secondary_button(ui, "放行防火墙").clicked() {
                            do_fw = true;
                        }
                    });
                    ui.add_space(6.0);
                    ui.horizontal(|ui| {
                        let w = (ui.available_width() - 78.0).max(140.0);
                        ui.allocate_ui_with_layout(
                            Vec2::new(w, 34.0),
                            egui::Layout::left_to_right(egui::Align::Center),
                            |ui| {
                                let r = ui_kit::text_input(
                                    ui,
                                    &mut self.join_addr,
                                    "输入对方 IP 或 IP:端口",
                                );
                                if r.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
                                    do_join = true;
                                }
                            },
                        );
                        if ui_kit::secondary_button(ui, "加入").clicked() {
                            do_join = true;
                        }
                    });
                } else {
                    dlg_section(ui, "在线协作成员与锁定状态");
                    egui::ScrollArea::vertical()
                        .max_height(210.0)
                        .auto_shrink([false, true])
                        .show(ui, |ui| {
                            ui.spacing_mut().item_spacing.y = 6.0;
                            for (site, name, color) in self.peers_list.clone() {
                                let is_me = Some(site) == me;
                                let c = ui_kit::peer_color(color);
                                // 检查该成员是否正在锁定编辑某格
                                let locked_cell = self
                                    .locks
                                    .iter()
                                    .find(|(_, h)| h.site == site)
                                    .map(|((sh, r, cc), _)| (sh, r, cc));
                                let cursor_cell = self
                                    .remote
                                    .get(&site)
                                    .map(|(sh, _, _, r, cc)| (*sh, *r, *cc))
                                    .or(if is_me {
                                        Some((self.sheet_idx, self.sel.0, self.sel.1))
                                    } else {
                                        None
                                    });
                                let target = locked_cell.or(cursor_cell);
                                let rw = ui.available_width();
                                let (row_rect, _) = ui.allocate_exact_size(
                                    Vec2::new(rw, 38.0),
                                    Sense::hover(),
                                );
                                ui.painter().rect(
                                    row_rect,
                                    7.0,
                                    Color32::from_rgb(250, 251, 253),
                                    Stroke::new(1.0, Color32::from_rgb(228, 233, 241)),
                                    egui::StrokeKind::Inside,
                                );
                                // 彩色圆形首字头像
                                let av = Rect::from_center_size(
                                    egui::pos2(row_rect.left() + 20.0, row_rect.center().y),
                                    Vec2::splat(24.0),
                                );
                                ui.painter().circle_filled(av.center(), 12.0, c);
                                let initial: String = name
                                    .chars()
                                    .next()
                                    .map(|ch| ch.to_uppercase().to_string())
                                    .unwrap_or_else(|| "U".to_string());
                                ui_kit::paint_medium(
                                    ui.painter(),
                                    av.center(),
                                    Align2::CENTER_CENTER,
                                    &initial,
                                    11.5,
                                    Color32::WHITE,
                                );
                                let disp_name = if is_me {
                                    format!("{name}（我）")
                                } else {
                                    name.clone()
                                };
                                ui_kit::paint_medium(
                                    ui.painter(),
                                    egui::pos2(av.right() + 9.0, row_rect.center().y),
                                    Align2::LEFT_CENTER,
                                    &disp_name,
                                    12.0,
                                    ui_kit::TEXT,
                                );
                                if let Some((sh, r, cc)) = target {
                                    let sh_name = self
                                        .wb
                                        .sheets
                                        .get(sh)
                                        .map(|s| s.name.as_str())
                                        .unwrap_or("Sheet1");
                                    let loc_txt = if locked_cell.is_some() {
                                        format!("编辑中 {}!{}", sh_name, cell_name(r, cc))
                                    } else {
                                        format!("{}!{}", sh_name, cell_name(r, cc))
                                    };
                                    let right_edge = if is_me {
                                        row_rect.right() - 10.0
                                    } else {
                                        row_rect.right() - 52.0
                                    };
                                    let lg = ui.painter().layout_no_wrap(
                                        loc_txt.clone(),
                                        FontId::proportional(11.0),
                                        Color32::PLACEHOLDER,
                                    );
                                    let extra_icon = if locked_cell.is_some() { 14.0 } else { 0.0 };
                                    let pill_w = lg.size().x + 14.0 + extra_icon;
                                    let pill_r = Rect::from_min_size(
                                        egui::pos2(right_edge - pill_w, row_rect.center().y - 10.5),
                                        Vec2::new(pill_w, 21.0),
                                    );
                                    let (pbg, pfg) = if locked_cell.is_some() {
                                        (
                                            Color32::from_rgb(254, 243, 199),
                                            Color32::from_rgb(180, 83, 9),
                                        )
                                    } else {
                                        (
                                            Color32::from_rgb(238, 242, 248),
                                            ui_kit::TEXT_WEAK,
                                        )
                                    };
                                    ui.painter().rect_filled(pill_r, 5.0, pbg);
                                    let mut tx_left = pill_r.left() + 7.0;
                                    if locked_cell.is_some() {
                                        ui_kit::draw_padlock(
                                            ui.painter(),
                                            Rect::from_center_size(
                                                egui::pos2(tx_left + 5.0, pill_r.center().y),
                                                Vec2::splat(11.0),
                                            ),
                                            pfg,
                                        );
                                        tx_left += 14.0;
                                    }
                                    ui.painter().text(
                                        egui::pos2(tx_left, pill_r.center().y),
                                        Align2::LEFT_CENTER,
                                        loc_txt,
                                        FontId::proportional(11.0),
                                        pfg,
                                    );
                                    if !is_me {
                                        let jrect = Rect::from_min_size(
                                            egui::pos2(row_rect.right() - 46.0, row_rect.center().y - 11.0),
                                            Vec2::new(38.0, 22.0),
                                        );
                                        let jresp = ui.interact(
                                            jrect,
                                            egui::Id::new(("peer_jump", site)),
                                            Sense::click(),
                                        );
                                        ui.painter().rect(
                                            jrect,
                                            5.0,
                                            if jresp.hovered() { ui_kit::HOVER } else { Color32::WHITE },
                                            Stroke::new(1.0, ui_kit::CARD_BORDER),
                                            egui::StrokeKind::Inside,
                                        );
                                        ui.painter().text(
                                            jrect.center(),
                                            Align2::CENTER_CENTER,
                                            "定位",
                                            FontId::proportional(11.0),
                                            ui_kit::BRAND_NAVY,
                                        );
                                        if jresp.on_hover_text("跳转到该用户当前所在工作表与单元格").clicked() {
                                            jump = Some((sh, r, cc));
                                        }
                                    }
                                }
                            }
                        });
                    ui.add_space(6.0);
                    ui.separator();
                    ui_kit::footer(ui, |ui| {
                        if ui_kit::secondary_button(ui, "断开协作").clicked() {
                            do_leave = true;
                        }
                        if ui_kit::secondary_button(ui, "放行防火墙").clicked() {
                            do_fw = true;
                        }
                    });
                }
            });

        if let Some(en) = toggle_dir_share {
            self.collab_ui_cache = None;
            if let Some(path) = self.wb.path.clone() {
                match session_lock::set_dir_marked_shared(&path, en) {
                    Ok(()) => {
                        if en {
                            self.auto_share = true;
                            if self.net.is_none() && self.can_auto_share(&path) {
                                self.start_host_auto(&path);
                            }
                        }
                        self.status = if en {
                            "已标记为协作目录，其他用户打开同一文件即可自动进入实时协作".into()
                        } else {
                            "已取消当前目录的协同共享标记".into()
                        };
                    }
                    Err(e) => self.status = format!("设置协同目录失败：{e}"),
                }
            }
        }
        if do_host {
            self.start_host();
        }
        if do_join {
            self.join_shared();
        }
        if do_leave {
            self.leave_session();
        }
        if do_fw {
            self.open_firewall_port();
        }
        if let Some((sh, r, c)) = jump {
            if sh < self.wb.sheets.len() && sh != self.sheet_idx {
                let _ = self.switch_sheet_view(sh);
            }
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
            self.status = format!("已定位到 {}", cell_name(r, c));
        }
        self.members_open = open;
    }


    /// 条件格式管理器：看规则、调顺序、删除、定位
    /// 按当前块/规则的先后重新编号 priority（1 起）。只在用户显式调序/删除后调用，
    /// 打开文件时不重排，保证 Excel 给的 priority 原样往返。
    fn renumber_cf(&mut self) {
        let sheet = self.wb.sheet_mut(self.sheet_idx);
        let mut p = 1u32;
        for b in sheet.cf.blocks.iter_mut() {
            for r in b.rules.iter_mut() {
                r.priority = p;
                p += 1;
            }
        }
    }

    /// UI-30：把旧菜单里的快捷规则原样放进窗口（规则数/数据条/图标集/色阶都在这里）
    fn cf_quick_window(&mut self, ctx: &egui::Context) {
        if !self.cf_quick {
            return;
        }
        let mut open = true;
        ui_kit::window(ctx, "条件格式快捷规则", 460.0)
            .open(&mut open)
            .default_width(420.0)
            .show(ctx, |ui| {
                self.toolbar_cf_items(ui);
            });
        self.cf_quick = open;
    }

    /// UI-30：数据验证快捷菜单（圈释无效、清除验证等）
    fn dv_quick_window(&mut self, ctx: &egui::Context) {
        if !self.dv_quick {
            return;
        }
        let mut open = true;
        ui_kit::window(ctx, "数据验证", 400.0)
            .open(&mut open)
            .default_width(360.0)
            .show(ctx, |ui| {
                self.toolbar_dv_items(ui);
            });
        self.dv_quick = open;
    }

    fn cf_manager(&mut self, ctx: &egui::Context) {
        if !self.cf_mgr {
            return;
        }
        let mut open = true;
        let mut del: Option<(usize, usize)> = None;
        let mut up: Option<usize> = None;
        let mut down: Option<usize> = None;
        let mut goto: Option<(u32, u32, u32, u32)> = None;
        let blocks = self.wb.sheet(self.sheet_idx).cf.blocks.clone();
        let unknown_ext = self.wb.sheet(self.sheet_idx).cf.unknown_ext;
        let dxf_unsupported = self.wb.sheet(self.sheet_idx).cf.dxf_unsupported;
        ui_kit::window(ctx, "条件格式管理", 460.0)
            .open(&mut open)
            .default_width(460.0)
            .show(ctx, |ui| {
                if dxf_unsupported {
                    ui.label(
                        egui::RichText::new(
                            "注意：差异格式含未建模的边框方向（对角/内部/起止边），保存会丢掉这些边，无法无损编辑。",
                        )
                        .color(egui::Color32::from_rgb(180, 95, 6)),
                    );
                    ui.separator();
                }
                if unknown_ext {
                    ui.label(
                        egui::RichText::new(
                            "注意：此表含本应用未建模的扩展条件格式（x14），保存会丢掉该扩展，无法无损编辑。",
                        )
                        .color(egui::Color32::from_rgb(180, 95, 6)),
                    );
                    ui.separator();
                }
                if blocks.is_empty() {
                    ui.label("这张表还没有条件格式规则");
                }
                for (bi, blk) in blocks.iter().enumerate() {
                    let range_text = blk
                        .ranges
                        .iter()
                        .map(|(r1, c1, r2, c2)| {
                            format!(
                                "{}{}:{}{}",
                                sheetcore::model::col_label(*c1),
                                r1 + 1,
                                sheetcore::model::col_label(*c2),
                                r2 + 1
                            )
                        })
                        .collect::<Vec<_>>()
                        .join(" ");
                    ui.horizontal(|ui| {
                        ui.label(egui::RichText::new(format!("区域 {range_text}")).strong());
                        if ui.small_button("定位").clicked() {
                            if let Some(r) = blk.ranges.first() {
                                goto = Some(*r);
                            }
                        }
                        if ui.small_button("上移").clicked() {
                            up = Some(bi);
                        }
                        if ui.small_button("下移").clicked() {
                            down = Some(bi);
                        }
                    });
                    for (ri, rule) in blk.rules.iter().enumerate() {
                        ui.horizontal(|ui| {
                            ui.label(format!("  · [{}] {}", rule.priority, rule.kind.describe()));
                            if rule.stop {
                                ui.label(egui::RichText::new("(命中即停)").weak());
                            }
                            if ui.small_button("删除").clicked() {
                                del = Some((bi, ri));
                            }
                        });
                    }
                    ui.separator();
                }
            });
        if let Some((bi, ri)) = del {
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            if let Some(blk) = sheet.cf.blocks.get_mut(bi) {
                if ri < blk.rules.len() {
                    blk.rules.remove(ri);
                }
                if blk.rules.is_empty() {
                    sheet.cf.blocks.remove(bi);
                }
            }
            sheet.cf_dirty = true;
            self.wb.dirty = true;
            self.renumber_cf();
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = "已删除一条条件格式规则".into();
        }
        if let Some(bi) = up {
            if bi > 0 {
                self.wb.sheet_mut(self.sheet_idx).cf.blocks.swap(bi, bi - 1);
                self.wb.sheet_mut(self.sheet_idx).cf_dirty = true;
                self.renumber_cf();
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = "规则已上移（优先级更高）".into();
            }
        }
        if let Some(bi) = down {
            let n = self.wb.sheet(self.sheet_idx).cf.blocks.len();
            if bi + 1 < n {
                self.wb.sheet_mut(self.sheet_idx).cf.blocks.swap(bi, bi + 1);
                self.wb.sheet_mut(self.sheet_idx).cf_dirty = true;
                self.renumber_cf();
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = "规则已下移".into();
            }
        }
        if let Some((r1, c1, _, _)) = goto {
            self.sel = (r1, c1);
            self.sel_end = (r1, c1);
            self.ensure_visible();
        }
        self.cf_mgr = open;
    }

    fn data_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.data_dlg.take() else { return };
        let mut open = true;
        let mut run = false;
        let title = if dlg.tab == 0 { "多级排序" } else { "分列" };
        ui_kit::window(ctx, title, 420.0)
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ctx, |ui| {
                if dlg.tab == 0 {
                    ui.checkbox(&mut dlg.header, "首行是标题");
                    ui.checkbox(&mut dlg.sort_by_row, "按行排序（以光标所在行为关键字，重排各列）");
                    if dlg.sort_by_row {
                        ui.label(egui::RichText::new("Excel 里关键字行在「选项→按行排序」里选；这里用光标所在行代替").weak());
                    }
                    ui.separator();
                    ui.label("按从上到下的顺序比较，可调级别：");
                    let mut up: Option<usize> = None;
                    let mut down: Option<usize> = None;
                    for i in 0..dlg.keys.len() {
                        let (c, asc, on) = &mut dlg.keys[i];
                        let cid = *c;
                        let mut is_on = *on;
                        let mut is_asc = *asc;
                        ui.horizontal(|ui| {
                            ui.checkbox(&mut is_on, format!("{} 列", cell_name(0, cid).trim_end_matches('1')));
                            egui::ComboBox::from_id_salt(format!("ord{cid}"))
                                .selected_text(if is_asc { "升序" } else { "降序" })
                                .width(70.0)
                                .show_ui(ui, |ui| {
                                    ui.selectable_value(&mut is_asc, true, "升序");
                                    ui.selectable_value(&mut is_asc, false, "降序");
                                });
                            if ui.add_enabled(is_on && i > 0, egui::Button::new("↑").small()).clicked() {
                                up = Some(i);
                            }
                            if ui
                                .add_enabled(is_on && i + 1 < dlg.keys.len(), egui::Button::new("↓").small())
                                .clicked()
                            {
                                down = Some(i);
                            }
                        });
                        dlg.keys[i] = (cid, is_asc, is_on);
                    }
                    if let Some(i) = up {
                        dlg.keys.swap(i, i - 1);
                    }
                    if let Some(i) = down {
                        dlg.keys.swap(i, i + 1);
                    }
                    ui.horizontal(|ui| {
                        ui.label("排序依据");
                        egui::ComboBox::from_id_salt("sortmode")
                            .selected_text(match dlg.sort_mode {
                                1 => "中文拼音",
                                2 => "自定义序列",
                                3 => "中文笔画",
                                _ => "字典序",
                            })
                            .width(100.0)
                            .show_ui(ui, |ui| {
                                ui.selectable_value(&mut dlg.sort_mode, 0, "字典序");
                                ui.selectable_value(&mut dlg.sort_mode, 1, "中文拼音");
                                ui.selectable_value(&mut dlg.sort_mode, 2, "自定义序列");
                                ui.selectable_value(&mut dlg.sort_mode, 3, "中文笔画")
                                    .on_hover_text(
                                        "按 Excel 笔画排序（xlStroke）的实测顺序；表外字符退回拼音序",
                                    );
                            });
                    });
                    if dlg.sort_mode == 2 {
                        ui.horizontal(|ui| {
                            ui.label("序列");
                            ui.add(
                                egui::TextEdit::singleline(&mut dlg.custom)
                                    .desired_width(220.0)
                                    .hint_text("高,中,低"),
                            );
                        });
                        ui.label(egui::RichText::new("序列里的项按书写顺序排，不在序列里的排在后面").weak());
                    }
                } else {
                    ui.horizontal(|ui| {
                        ui.radio_value(&mut dlg.split_fixed, false, "按分隔符");
                        ui.radio_value(&mut dlg.split_fixed, true, "按固定宽度");
                    });
                    if dlg.split_fixed {
                        ui.horizontal(|ui| {
                            ui.label("每列字符数");
                            ui.add(
                                egui::TextEdit::singleline(&mut dlg.widths)
                                    .desired_width(140.0)
                                    .hint_text("10,20,15"),
                            );
                        });
                        ui.label(egui::RichText::new("从选中列左边开始按字符数切，剩余部分留在最后一列").weak());
                    } else {
                        ui.horizontal(|ui| {
                            ui.label("分隔符");
                            ui.add(egui::TextEdit::singleline(&mut dlg.delim).desired_width(60.0));
                        });
                        ui.checkbox(&mut dlg.quote, "引号内的分隔符不拆（\"\" 表示一个引号）");
                        ui.checkbox(&mut dlg.merge_consecutive, "连续分隔符当一个（多个空格不产生空列）");
                    }
                    ui.horizontal(|ui| {
                        ui.label("列格式");
                        ui.add(
                            egui::TextEdit::singleline(&mut dlg.col_modes)
                                .desired_width(180.0)
                                .hint_text("常规,文本,日期,跳过"),
                        );
                    });
                    ui.label(egui::RichText::new("按列从左到右写：常规 / 文本 / 日期 / 跳过（跳过=该列不导入，后面的列左移）").weak());
                    ui.checkbox(&mut dlg.detect_types, "识别数字/日期（前导零保留为文本）");
                    let (r1, c1, _, _) = self.sel_rect();
                    let sample = self
                        .wb
                        .sheet(self.sheet_idx)
                        .get(r1, c1)
                        .map(|x| x.value.display())
                        .unwrap_or_default();
                    if !sample.is_empty() {
                        let fixed = if dlg.split_fixed {
                            sheetcore::data_tools::parse_fixed_widths(&dlg.widths)
                        } else {
                            None
                        };
                        let opts = sheetcore::data_tools::SplitOpts {
                            delim: dlg.delim.chars().next().unwrap_or(','),
                            merge_consecutive: dlg.merge_consecutive && fixed.is_none(),
                            quote: dlg.quote && fixed.is_none(),
                            detect_types: dlg.detect_types,
                            date_system: self.wb.date_system,
                            fixed_widths: fixed,
                            col_modes: parse_col_modes(&dlg.col_modes),
                        };
                        let fields = sheetcore::data_tools::split_fields(&sample, &opts);
                        ui.label(
                            egui::RichText::new(format!("预览：{} → {}", sample, fields.join(" | ")))
                                .weak(),
                        );
                    }
                }
                ui.separator();
                // 排序/分列对话框只有一个主动作：Enter 等同「执行」（Excel 里也是这样）
                if ui_kit::primary_button(ui, "执行").clicked() {
                    run = true;
                }
            });
        if run {
            if dlg.tab == 0 {
                self.run_sort(&dlg);
            } else {
                self.run_split(&dlg);
            }
        } else if open {
            self.data_dlg = Some(dlg);
        }
    }

    // ===== 查找替换 =====
fn search_opts(&self) -> sheetcore::search::SearchOpts {
        sheetcore::search::SearchOpts {
            match_case: self.find.match_case,
            whole_cell: self.find.whole_cell,
            in_formula: self.find.in_formula,
        }
    }

    fn search_order(&self) -> sheetcore::search::SearchOrder {
        if self.find.order_column {
            sheetcore::search::SearchOrder::ColumnMajor
        } else {
            sheetcore::search::SearchOrder::RowMajor
        }
    }

    /// 从 Ribbon/快捷键/搜索框开始一次新的查找会话：
    /// 旧会话锁定的选区快照必须清掉，否则下一次“全部替换”仍会作用到旧区域。
    /// 连续 Next 不走这里，会话内定位继续使用已锁定快照。
    fn find_open_new_session(&mut self) {
        self.find_navigation = None;
        self.find.session_rect = None;
        self.find.session_rects.clear();
        self.find.open = true;
    }

    /// scope==2 的选区快照：主矩形 + Ctrl 多选矩形；没有快照时退回当前选择。
    fn find_rects(&self) -> Vec<(u32, u32, u32, u32)> {
        if self.find.scope != 2 {
            return Vec::new();
        }
        if !self.find.session_rects.is_empty() {
            return self.find.session_rects.clone();
        }
        let mut rects = self.extra_sel.clone();
        rects.push(self.find.session_rect.unwrap_or_else(|| self.sel_rect()));
        rects.sort_unstable();
        rects.dedup();
        rects
    }

    fn lock_find_rects(&mut self) {
        if self.find.scope != 2 || !self.find.session_rects.is_empty() {
            return;
        }
        self.find.session_rect = Some(self.sel_rect());
        let mut rects = self.extra_sel.clone();
        rects.push(self.sel_rect());
        rects.sort_unstable();
        rects.dedup();
        self.find.session_rects = rects;
    }

    /// 当前范围（选区/工作表/工作簿）的全部命中，按选定顺序排序
    fn find_hits(&self) -> Vec<sheetcore::search::Hit> {
        let opts = self.search_opts();
        let needle = sheetcore::search::normalize_needle(&self.find.find, &opts);
        if needle.is_empty() {
            return Vec::new();
        }
        let order = self.search_order();
        match self.find.scope {
            1 => sheetcore::search::hits(&self.wb, None, &needle, &opts, order),
            2 => {
                let mut out = Vec::new();
                for (r1, c1, r2, c2) in self.find_rects() {
                    out.extend(sheetcore::search::hits_in_rect(
                        &self.wb,
                        self.sheet_idx,
                        (r1, c1, r2, c2),
                        &needle,
                        &opts,
                        order,
                    ));
                }
                match order {
                    sheetcore::search::SearchOrder::RowMajor => out.sort_unstable(),
                    sheetcore::search::SearchOrder::ColumnMajor => {
                        out.sort_unstable_by_key(|h| (h.sheet, h.col, h.row))
                    }
                }
                out.dedup();
                out
            }
            _ => sheetcore::search::hits(&self.wb, Some(self.sheet_idx), &needle, &opts, order),
        }
    }

    fn start_scan(&mut self, purpose: u8) {
        if purpose == 0 {
            self.find_summary(true);
        } else {
            self.start_replace_scan();
        }
    }

    fn cancel_find_scan(&mut self) {
        if self.find_scan.take().is_some() || self.indexing_find_summary() {
            self.find_navigation = None;
            self.status = "已取消扫描".into();
        }
    }

    /// 按匹配规则算出替换后的格子；没有实际变化时返回 None。
    /// 值模式默认不碰公式格：命中公式结果时必须由用户显式勾选“替换公式结果”。
    fn replacement_at(
        &self,
        sheet: usize,
        r: u32,
        c: u32,
        cell: &sheetcore::model::Cell,
    ) -> Option<sheetcore::model::Cell> {
        let opts = self.search_opts();
        let needle = sheetcore::search::normalize_needle(&self.find.find, &opts);
        if !sheetcore::search::cell_matches(&self.wb, sheet, r, c, &needle, &opts) {
            return None;
        }
        if !opts.in_formula && cell.formula.is_some() && !self.find.replace_formula_results {
            return None;
        }
        let text = sheetcore::search::cell_text_at(
            &self.wb,
            sheet,
            r,
            c,
            cell,
            opts.in_formula,
        )?;
        if opts.in_formula {
            let formula = cell.formula.as_deref()?;
            let next = if opts.whole_cell {
                self.find.replace.clone()
            } else {
                sheetcore::search::replace_in_text(
                    formula,
                    &self.find.find,
                    &self.find.replace,
                    self.find.match_case,
                )
            };
            if next == formula {
                return None;
            }
            let mut out = cell.clone();
            out.formula = Some(next.into());
            return Some(out);
        }
        let next = if opts.whole_cell {
            self.find.replace.clone()
        } else {
            sheetcore::search::replace_in_text(
                &text,
                &self.find.find,
                &self.find.replace,
                self.find.match_case,
            )
        };
        if next == text {
            return None;
        }
        Some(sheetcore::model::Cell {
            value: sheetcore::model::Value::parse_input(&next),
            formula: None,
        })
    }


    fn replace_current(&mut self) {
        let si = self.sheet_idx;
        let (r, c) = self.sel;
        let Some(cell) = self.wb.sheet(si).get(r, c).cloned() else {
            self.find_next(false);
            return;
        };
        if !self.find.in_formula
            && cell.formula.is_some()
            && !self.find.replace_formula_results
        {
            let msg = format!(
                "{} 是公式结果：值模式不替换公式，请勾选“替换公式结果”或切到公式模式",
                cell_name(r, c)
            );
            self.find_next(false);
            // find_next 会写“找到…”，这里要保留真正的拒绝原因
            self.status = msg;
            return;
        }
        let Some(new_cell) = self.replacement_at(self.sheet_idx, r, c, &cell) else {
            self.find_next(false);
            return;
        };
        if !self.write_preflight(&[(r, c)], "替换") {
            return;
        }
        let txn = self.txn_begin(&[(r, c)]);
        self.wb.sheet_mut(si).set(r, c, new_cell);
        self.txn_end("替换", txn);
        self.recalc_and_broadcast(&[(si, r, c)]);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已替换 {}", cell_name(r, c));
        self.find_next(false);
    }

    fn replace_all(&mut self) {
        // 后台查找完成后在当前文档一次提交，生成单个撤销步骤。
        self.start_scan(1);
    }

    fn apply_replace_hits(&mut self, hits: &[sheetcore::search::Hit]) {
        if hits.is_empty() {
            self.status = "没找到可替换的内容".into();
            return;
        }
        // 先算差异，再统一提交：命中数与实改数可对账
        let mut diffs: Vec<(usize, u32, u32, sheetcore::model::Cell)> = Vec::new();
        for h in hits.iter() {
            let Some(cell) = self.wb.sheet(h.sheet).get(h.row, h.col) else { continue };
            if let Some(new_cell) = self.replacement_at(h.sheet, h.row, h.col, cell) {
                diffs.push((h.sheet, h.row, h.col, new_cell));
            }
        }
        let formula_skips = if self.find.in_formula || self.find.replace_formula_results {
            0
        } else {
            hits.iter()
                .filter(|h| {
                    self.wb
                        .sheet(h.sheet)
                        .get(h.row, h.col)
                        .is_some_and(|c| c.formula.is_some())
                })
                .count()
        };
        if diffs.is_empty() {
            self.status = if formula_skips > 0 {
                format!(
                    "找到 {} 处，其中 {} 处是公式结果（未替换；勾选“替换公式结果”或切到公式模式）",
                    hits.len(),
                    formula_skips
                )
            } else {
                format!("找到 {} 处，替换后没有变化", hits.len())
            };
            return;
        }
        // 按表分组做保护/锁检查；任何一格不可写就整批拒绝
        let mut groups: std::collections::BTreeMap<usize, Vec<(u32, u32)>> =
            std::collections::BTreeMap::new();
        for (si, r, c, _) in diffs.iter() {
            groups.entry(*si).or_default().push((*r, *c));
        }
        for (si, keys) in groups.iter() {
            let mut keys = keys.clone();
            keys.sort_unstable();
            keys.dedup();
            if !self.write_preflight_on(*si, &keys, "全部替换") {
                return;
            }
        }
        // 多表单事务：逐表捕获，合并成一次撤销
        let mut before: std::collections::BTreeMap<usize, Vec<sheetcore::undo::CellDelta>> =
            std::collections::BTreeMap::new();
        for (si, keys) in groups.iter() {
            let mut keys = keys.clone();
            keys.sort_unstable();
            keys.dedup();
            before.insert(*si, sheetcore::undo::capture(self.wb.sheet(*si), *si, &keys));
        }
        for (si, r, c, cell) in diffs.iter() {
            self.wb.sheet_mut(*si).set(*r, *c, cell.clone());
        }
        let mut deltas: Vec<sheetcore::undo::CellDelta> = Vec::new();
        for (si, caps) in before.into_iter() {
            deltas.extend(sheetcore::undo::finish(caps, self.wb.sheet(si)));
        }
        if !deltas.is_empty() {
            self.record_revision("全部替换", &deltas);
            self.undo.push(sheetcore::undo::Action {
                label: "全部替换".into(),
                merges: None,
                deltas,
                focus: (diffs[0].0, diffs[0].1, diffs[0].2),
                snap_before: None,
                snap_after: None,
                by_site: 0,
                pictures: None,
                shapes: None,
                refresh_sizes: None,
            });
        }
        let keys: Vec<(usize, u32, u32)> =
            diffs.iter().map(|(si, r, c, _)| (*si, *r, *c)).collect();
        self.recalc_and_broadcast(&keys);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = if formula_skips > 0 {
            format!(
                "找到 {} 处，替换 {} 处，跳过 {} 处公式结果（可勾选“替换公式结果”）",
                hits.len(),
                diffs.len(),
                formula_skips
            )
        } else {
            format!(
                "找到 {} 处，替换 {} 处（{}）",
                hits.len(),
                diffs.len(),
                if diffs.len() < hits.len() { "其余替换后无变化" } else { "全部成功" }
            )
        };
    }

    // ===== 工作表 =====
    fn can_change_sheets(&mut self) -> bool {
        if self.net.is_some() {
            self.status = "协作期间暂不支持增删、改名或移动工作表，请先断开协作".into();
            return false;
        }
        if self.tasks.open_rx.is_some() {
            self.status = "正在加载或重算，完成后再调整工作表".into();
            return false;
        }
        self.finish_pending_edit()
    }

    /// Choosing synchronous or background recalculation only reads per-sheet counts.
    fn recalc_all_and_deps_adaptive(&mut self) {
        self.cancel_silent_recalc();
        self.bg_deps_rx = None;
        self.tasks.dirty_recalc_seeds.clear();
        self.tasks.needs_full = false;
        if self.wb.sheets.iter().all(|s| !s.has_formulas() && s.arrays.is_empty()
            && s.spilled.is_empty() && s.spill_shapes.is_empty()) {
            self.wb.calc_pending = false;
            self.wb.calc_pending_sheets.clear();
            self.deps = Default::default();
            self.deps_built = true;
            return;
        }
        if self.wb.sheets.iter().map(|sh| sh.len()).sum::<usize>() <= 2_000 {
            sheetcore::formula::recalc_all(&mut self.wb);
            self.deps = sheetcore::formula::deps::Deps::build(&self.wb).into();
            self.deps_built = true;
        } else if self.wb.calc_manual {
            sheetcore::formula::recalc_all(&mut self.wb); // Manual mode only marks sheets that contain formulas.
            self.deps_built = false;
        } else {
            self.deps_built = false;
            self.request_silent_bg_recalc();
        }
    }

    fn finish_sheet_change(&mut self) {
        // Operations without an inverse can invalidate indices and old formula qualifiers.
        self.undo = sheetcore::undo::UndoStack::new();
        self.refresh_after_sheet_change();
    }

    fn refresh_after_sheet_change(&mut self) {
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.clip = None;
        self.recalc_all_and_deps_adaptive();
        self.cf_stats_gen = u64::MAX;
        self.invalid_gen = u64::MAX;
    }

    fn set_sheet_name(&mut self, idx: usize, name: &str) -> bool {
        if !self.can_change_sheets() {
            return false;
        }
        if self.wb.sheets.get(idx).is_some_and(|sheet| sheet.name == name) {
            return true;
        }
        if !sheetcore::sheet_ops::rename_sheet(&mut self.wb, idx, name) {
            self.status = "工作表名称无效或已存在".into();
            return false;
        }
        self.finish_sheet_change();
        self.status = format!("已重命名为 {name}");
        true
    }

    fn add_sheet(&mut self) {
        if !self.can_change_sheets() {
            return;
        }
        let n = self.wb.sheets.len() + 1;
        let mut name = format!("Sheet{n}");
        let mut k = n;
        while self.wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
            k += 1;
            name = format!("Sheet{k}");
        }
        let index = self.wb.sheets.len();
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, index, sheetcore::model::Sheet::new(&name)) {
            self.status = "无法创建工作表：名称无效或已存在".into();
            return;
        }
        self.switch_sheet_view(index);
        self.finish_sheet_change();
        self.status = format!("已新建 {name}");
    }

    fn delete_sheet(&mut self, idx: usize) {
        if idx >= self.wb.sheets.len() || !self.can_change_sheets() {
            return;
        }
        if self.wb.sheets.len() <= 1 {
            self.status = "至少保留一张工作表".into();
            return;
        }
        let name = self.wb.sheets[idx].name.clone();
        let deleted_id = self.wb.sheet(idx).identity;
        let was_current = self.sheet_idx == idx;
        if was_current {
            self.remember_sheet_view();
        }
        if !sheetcore::sheet_ops::delete_sheet(&mut self.wb, idx) {
            return;
        }
        self.sheet_views.remove(&deleted_id);
        if self.sheet_idx > idx {
            self.sheet_idx -= 1;
        }
        self.sheet_idx = self.sheet_idx.min(self.wb.sheets.len() - 1);
        if was_current {
            self.load_sheet_view(self.sheet_idx);
        }
        self.finish_sheet_change();
        self.status = format!("已删除 {name}");
    }

    fn move_sheet(&mut self, idx: usize, delta: i32) {
        let to = idx as i32 + delta;
        if to < 0 || to as usize >= self.wb.sheets.len() {
            return;
        }
        if self.swap_sheet_positions(idx, to as usize) {
            self.sheet_idx = to as usize;
        }
    }

    fn swap_sheet_positions(&mut self, from: usize, to: usize) -> bool {
        if from == to || from >= self.wb.sheets.len() || to >= self.wb.sheets.len()
            || !self.can_change_sheets()
        {
            return false;
        }
        if !sheetcore::sheet_ops::move_sheet(&mut self.wb, from, to) {
            return false;
        }
        if self.sheet_idx == from {
            self.sheet_idx = to;
        } else if self.sheet_idx == to {
            self.sheet_idx = from;
        }
        self.finish_sheet_change();
        true
    }

    /// 撤销 / 重做
    /// QA-04.1：文件级快捷键。实测发现 Ctrl+S / Ctrl+Z / Ctrl+Y 此前完全没绑键，
    /// 只有功能区和快速访问按钮能点到（`grep "Key::Z"` 只命中自动化按键解析）。
    /// 返回 true 表示这一帧的按键已被消费。
    fn handle_file_shortcuts(&mut self, ctx: &egui::Context) -> bool {
        if self.editing.is_some() {
            return false; // 编辑态交给 TextEdit 自己处理文本级撤销
        }
        let (save, undo, redo_y, shift) = ctx.input(|i| {
            (
                i.modifiers.command && i.key_pressed(Key::S),
                i.modifiers.command && i.key_pressed(Key::Z),
                i.modifiers.command && i.key_pressed(Key::Y),
                i.modifiers.shift,
            )
        });
        if save {
            self.save(shift);
            return true;
        }
        if undo {
            self.do_undo(shift);
            return true;
        }
        if redo_y {
            self.do_undo(true);
            return true;
        }
        false
    }

    fn do_undo(&mut self, redo: bool) {
        self.apply_undo(redo);
    }

    /// True when the complete entry was applied without a conflict.
    fn apply_undo(&mut self, redo: bool) -> bool {
        if self.editing.is_some() {
            return false;
        }
        if self.net.is_some() && if redo { self.undo.redo_is_structure() } else { self.undo.undo_is_structure() } {
            self.status = "协作期间不能撤销或重做整表结构，请先断开协作".into();
            return false;
        }
        // 协作时：只回退仍然是我改成的样子的格子
        let mut mine: std::collections::HashSet<(usize, u32, u32)> = std::collections::HashSet::new();
        let site = self.net.as_ref().map(|n| n.site);
        if let Some(_site) = site {
            if let Some(peer) = self.peer.as_ref() {
                for (k, op) in peer.cells.iter() {
                    if op.site == site.unwrap() {
                        mine.insert(*k);
                    }
                }
            }
        }
        let my_site = site.unwrap_or(0);
        let locks = &self.locks;
        let net_ref = self.net.as_ref();
        let guard = |sheet: usize, row: u32, col: u32, _cur: &sheetcore::model::Cell| {
            if locks.is_locked_by_other(sheet, row, col, my_site) {
                return false;
            }
            if let Some(n) = net_ref {
                if n.host_lock_conflict_cells(sheet, &[(row, col)]).is_some() {
                    return false;
                }
            }
            site.is_none() || mine.contains(&(sheet, row, col))
        };
        let applied = if redo {
            self.undo.redo_workbook(&mut self.wb, guard)
        } else {
            self.undo.undo_workbook(&mut self.wb, guard)
        };
        let Some(applied) = applied else {
            self.status = if redo { "没有可重做的操作".into() } else { "没有可撤销的操作".into() };
            return false;
        };
        if applied.merge_conflict {
            self.status = format!(
                "{}：合并结构与当前表冲突或区域内有他人改动，已整体放弃（结构、内容和广播均未改动）",
                if redo { "重做" } else { "撤销" }
            );
            return false;
        }
        // 刷新类动作撤销/重做时把外源源尺寸一起还原
        if let Some(sizes) = &applied.refresh_sizes {
            for (name, rows, cols) in sizes {
                if let Some(src) = self.wb.sources.iter_mut().find(|s| &s.name == name) {
                    src.rows = *rows;
                    src.cols = *cols;
                }
            }
        };
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        // 重算受影响格子
        if applied.structural || applied.touched.len() > 2_000 {
            self.recalc_all_and_deps_adaptive();
        } else {
            let mut keys = applied.touched.clone();
            keys.sort_unstable();
            keys.dedup();
            self.fast_recalc_cells(&keys);
        }
        self.cf_stats_gen = u64::MAX;
        self.invalid_gen = u64::MAX;
        self.tasks.last_edit = Some(std::time::Instant::now());
        // 协作广播
        self.broadcast_cells(&applied.touched);
        let changed_styles = if applied.structural { &applied.touched } else { &applied.style_changes };
        self.broadcast_cell_styles(changed_styles);
        if let Some(net) = &self.net {
            // 合并结构也要同步；只发内容/样式会让对端留下旧的合并轮廓。
            for (sheet, rect, on) in applied.merge_changes.iter() {
                net.broadcast_merge(*sheet, *rect, *on);
            }
        }
        // 回到出事的格
        let (sheet, row, col) = applied.focus;
        let target = sheet.min(self.wb.sheets.len().saturating_sub(1));
        if target != self.sheet_idx {
            self.switch_sheet_view(target);
        }
        // 目标表自己的多选区不能带进这次撤销的落点；否则后续清除/格式会误伤远端区域。
        self.extra_sel.clear();
        self.sel = (row, col);
        self.sel_end = (row, col);
        self.nav_rect = None;
        self.ensure_visible();
        self.status = if redo {
            format!("重做：{}", applied.label)
        } else {
            format!("撤销：{}", applied.label)
        };
        if applied.skipped > 0 {
            self.status.push_str(&format!("（{} 格已被其他用户修改，已跳过）", applied.skipped));
        }
        applied.skipped == 0
    }

    /// 复制工作表：插到原表后面，名字自动去重
    fn duplicate_sheet(&mut self, i: usize) {
        if i >= self.wb.sheets.len() || !self.can_change_sheets() {
            return;
        }
        let mut copy = self.wb.sheets[i].clone();
        let base = copy.name.clone();
        let copy_name = |n| {
            let suffix = format!(" ({n})");
            let prefix: String = base.chars().take(31usize.saturating_sub(suffix.chars().count())).collect();
            format!("{prefix}{suffix}")
        };
        let mut n = 2;
        let mut name = copy_name(n);
        while self.wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
            n += 1;
            name = copy_name(n);
        }
        copy.name = name;
        copy.source_part = None;
        copy.edited = true;
        // Keep spill ownership so the next recalc clears and rebuilds its tail.
        if sheetcore::sheet_ops::insert_sheet(&mut self.wb, i + 1, copy) {
            self.switch_sheet_view(i + 1);
            self.finish_sheet_change();
        }
    }

    /// 已用区域的右下角
    fn used_end(&self) -> (u32, u32) {
        self.wb.sheet(self.sheet_idx).used_bounds()
            .map_or((0, 0), |(_, _, last_row, last_col)| (last_row, last_col))
    }

    /// Ctrl+方向：沿方向跳过空白，停在连续数据块的边缘（Excel 语义）
    fn jump_edge(&self, dr: i64, dc: i64) -> (u32, u32) {
        let sheet = self.wb.sheet(self.sheet_idx);
        let (mut r, mut c) = (self.sel.0 as i64, self.sel.1 as i64);
        let occupied = |r: i64, c: i64| -> bool {
            r >= 0
                && c >= 0
                && sheet
                    .get(r as u32, c as u32)
                    .map(|x| !x.is_blank())
                    .unwrap_or(false)
        };
        // 先跳过空白
        for _ in 0..4096 {
            let (nr, nc) = (r + dr, c + dc);
            if nr < 0 || nc < 0 {
                break;
            }
            if occupied(nr, nc) {
                break;
            }
            r = nr;
            c = nc;
        }
        // 再走到数据块末尾
        if occupied(r + dr, c + dc) {
            for _ in 0..4096 {
                let (nr, nc) = (r + dr, c + dc);
                if !occupied(nr, nc) {
                    break;
                }
                r = nr;
                c = nc;
            }
        }
        (r.max(0) as u32, c.max(0) as u32)
    }

    /// 打开单元格格式对话框，先读选区左上角的样式
    fn open_format_dialog(&mut self) {
        let (r, c) = self.sel;
        let id = self.wb.sheet(self.sheet_idx).style_of(r, c);
        let st = self.wb.styles.get(id).clone();
        self.fmt_tab = 0;
        self.fmt_state = FmtState {
            font: st.font.clone(),
            bold: st.bold,
            italic: st.italic,
            underline: st.underline,
            double_underline: st.double_underline,
            vertical_text: st.vertical_text,
            strikethrough: st.strikethrough,
            rotation: st.rotation,
            size: st.size,
            color: st.color,
            fill: st.fill,
            halign: st.halign,
            valign: st.valign,
            wrap: st.wrap,
            shrink_to_fit: st.shrink_to_fit,
            indent: st.indent,
            format: st.format.clone(),
            border: [
                st.border[0].style != 0,
                st.border[1].style != 0,
                st.border[2].style != 0,
                st.border[3].style != 0,
            ],
            border_inside_h: false,
            border_inside_v: false,
            locked: st.locked,
            hidden: st.hidden,
        };
        let fl = st.format.to_ascii_lowercase();
        self.fmt_num_cat = if st.format.is_empty() {
            0
        } else if st.format == "@" {
            9
        } else if fl.contains("[dbnum") {
            10
        } else if fl.contains('%') {
            6
        } else if fl.contains("e+") {
            8
        } else if fl.contains("hh") || fl.contains("mm:ss") {
            5
        } else if fl.contains("yy") || fl.contains("dd") {
            4
        } else if fl.contains('?') {
            7
        } else if st.format.contains("_*") {
            3
        } else if st.format.contains('¥') || st.format.contains('$') || st.format.contains('€') {
            2
        } else if st.format.contains("#,##0") || st.format.contains('0') {
            1
        } else {
            11
        };
        self.fmt_border_style = 1;
        self.fmt_border_color = [0, 0, 0];
        self.fmt_orig = self.fmt_state.clone();
        self.fmt_touched = FmtTouched::default();
        let (r1, c1, r2, c2) = self.sel_rect();
        self.fmt_mixed = self.fmt_mixed_for_rect(r1, c1, r2, c2);
        self.fmt_merge_pending = None;
        self.fmt_dlg = true;
    }

    /// 比较选中矩形内各格样式，供格式对话框显示“混合”。最多采样 20000 格，
    /// 避免整表选区拖住 UI；采样范围内有任何差异就标记对应字段。
    fn fmt_mixed_for_rect(&self, r1: u32, c1: u32, r2: u32, c2: u32) -> FmtMixed {
        let sh = self.wb.sheet(self.sheet_idx);
        let first_id = sh.style_of(r1, c1);
        let first = self.wb.styles.get(first_id).clone();
        let mut m = FmtMixed::default();
        let mut seen: u32 = 0;
        'outer: for r in r1..=r2 {
            for c in c1..=c2 {
                if seen >= 20_000 {
                    break 'outer;
                }
                seen += 1;
                let id = sh.style_of(r, c);
                if id == first_id {
                    continue;
                }
                let s = self.wb.styles.get(id);
                m.font |= s.font != first.font;
                m.size |= (s.size - first.size).abs() > f32::EPSILON;
                m.bold |= s.bold != first.bold;
                m.italic |= s.italic != first.italic;
                m.underline |= s.underline != first.underline;
                m.double_underline |= s.double_underline != first.double_underline;
                m.vertical_text |= s.vertical_text != first.vertical_text;
                m.strikethrough |= s.strikethrough != first.strikethrough;
                m.rotation |= s.rotation != first.rotation;
                m.color |= s.color != first.color;
                m.fill |= s.fill != first.fill;
                m.halign |= s.halign != first.halign;
                m.valign |= s.valign != first.valign;
                m.wrap |= s.wrap != first.wrap;
                m.shrink_to_fit |= s.shrink_to_fit != first.shrink_to_fit;
                m.indent |= s.indent != first.indent;
                m.format |= s.format != first.format;
                for i in 0..4 {
                    m.border[i] |= s.border[i] != first.border[i];
                }
                m.locked |= s.locked != first.locked;
                m.hidden |= s.hidden != first.hidden;
            }
        }
        m
    }

    /// 提交格式对话框：只覆盖用户改过的字段；未改直接确定不产生事务。
    /// 格式对话框的“当前值”预览：用活动格真实值和草稿格式渲染。
    fn format_dialog_preview(&self) -> String {
        let v = self
            .wb
            .sheet(self.sheet_idx)
            .value(self.sel.0, self.sel.1)
            .clone();
        sheetcore::style::format_value_in(self.wb.date_system, &v, &self.fmt_state.format)
    }

    /// 取消格式对话框：草稿只存在于 `fmt_state`，不碰文档/撤销/脏标记。
    fn cancel_format_dialog(&mut self) {
        self.fmt_merge_pending = None;
        self.fmt_dlg = false;
    }

    fn apply_format_dialog(&mut self) {
        let st = self.fmt_state.clone();
        let orig = self.fmt_orig.clone();
        let touched = self.fmt_touched.clone();
        let border_changed = st.border != orig.border || touched.border.iter().any(|x| *x);
        let want_font = st.font != orig.font || touched.font;
        let want_bold = st.bold != orig.bold || touched.bold;
        let want_italic = st.italic != orig.italic || touched.italic;
        let want_underline = st.underline != orig.underline || touched.underline;
        let want_double_u = st.double_underline != orig.double_underline || touched.double_underline;
        let want_vertical = st.vertical_text != orig.vertical_text || touched.vertical_text;
        let want_strike = st.strikethrough != orig.strikethrough || touched.strikethrough;
        let want_rotation = st.rotation != orig.rotation || touched.rotation;
        let want_size = (st.size - orig.size).abs() > f32::EPSILON || touched.size;
        let want_color = st.color != orig.color || touched.color;
        let want_fill = st.fill != orig.fill || touched.fill;
        let want_halign = st.halign != orig.halign || touched.halign;
        let want_valign = st.valign != orig.valign || touched.valign;
        let want_wrap = st.wrap != orig.wrap || touched.wrap;
        let want_shrink = st.shrink_to_fit != orig.shrink_to_fit || touched.shrink_to_fit;
        let want_indent = st.indent != orig.indent || touched.indent;
        let want_format = st.format != orig.format || touched.format;
        let want_locked = st.locked != orig.locked || touched.locked;
        let want_hidden = st.hidden != orig.hidden || touched.hidden;
        let inside_h_changed = touched.border_inside_h;
        let inside_v_changed = touched.border_inside_v;
        let style_changed = border_changed
            || inside_h_changed
            || inside_v_changed
            || want_font
            || want_bold
            || want_italic
            || want_underline
            || want_double_u
            || want_vertical
            || want_strike
            || want_rotation
            || want_size
            || want_color
            || want_fill
            || want_halign
            || want_valign
            || want_wrap
            || want_shrink
            || want_indent
            || want_format
            || want_locked
            || want_hidden;

        if style_changed {
            let borders = st.border;
            let side_changed = [
                st.border[0] != orig.border[0] || touched.border[0],
                st.border[1] != orig.border[1] || touched.border[1],
                st.border[2] != orig.border[2] || touched.border[2],
                st.border[3] != orig.border[3] || touched.border[3],
            ];
            let all_sides_changed = side_changed.iter().all(|x| *x);
            let b_style = self.fmt_border_style.max(1);
            let b_col = self.fmt_border_color;
            let inside_h_on = st.border_inside_h;
            let inside_v_on = st.border_inside_v;
            let font = st.font.clone();
            let format = st.format.clone();
            let (r1, c1, r2, c2) = self.sel_rect();
            self.apply_style_xy(move |s, r, c| {
                if border_changed {
                    // 只改用户真正切换过的边；其余边的粗细/颜色原样保留。
                    for (i, on) in borders.iter().enumerate() {
                        if side_changed[i] {
                            s.border[i] = if *on {
                                sheetcore::style::Border { style: b_style, color: b_col }
                            } else {
                                sheetcore::style::Border::default()
                            };
                        }
                    }
                    // 四边同时由无到有且未显式勾内部边时，内部边不画；否则同步应用内部边
                    if all_sides_changed && borders.iter().all(|x| *x) && !inside_h_changed && !inside_v_changed {
                        if c > c1 { s.border[0].style = 0; }
                        if c < c2 { s.border[1].style = 0; }
                        if r > r1 { s.border[2].style = 0; }
                        if r < r2 { s.border[3].style = 0; }
                    }
                }
                if inside_h_changed {
                    let b = if inside_h_on { sheetcore::style::Border { style: b_style, color: b_col } } else { sheetcore::style::Border::default() };
                    if r > r1 && r <= r2 { s.border[2] = b; }
                    if r >= r1 && r < r2 { s.border[3] = b; }
                }
                if inside_v_changed {
                    let b = if inside_v_on { sheetcore::style::Border { style: b_style, color: b_col } } else { sheetcore::style::Border::default() };
                    if c > c1 && c <= c2 { s.border[0] = b; }
                    if c >= c1 && c < c2 { s.border[1] = b; }
                }
                if want_font { s.font = font.clone(); }
                if want_bold { s.bold = st.bold; }
                if want_italic { s.italic = st.italic; }
                if want_underline { s.underline = st.underline; }
                if want_double_u { s.double_underline = st.double_underline; }
                if want_vertical { s.vertical_text = st.vertical_text; }
                if want_strike { s.strikethrough = st.strikethrough; }
                if want_rotation { s.rotation = st.rotation; }
                if want_size { s.size = st.size; }
                if want_color { s.color = st.color; }
                if want_fill { s.fill = st.fill; }
                if want_halign { s.halign = st.halign; }
                if want_valign { s.valign = st.valign; }
                if want_wrap { s.wrap = st.wrap; }
                if want_shrink { s.shrink_to_fit = st.shrink_to_fit; }
                if want_indent { s.indent = st.indent; }
                if want_format { s.format = format.clone(); }
                if want_locked { s.locked = st.locked; }
                if want_hidden { s.hidden = st.hidden; }
            });
            self.status = "已应用格式".into();
        } else {
            self.status = "格式未修改".into();
        }
        self.fmt_dlg = false;
        self.commit_fmt_merge();
    }

    /// 名称管理器：名称是否是保留的单元格地址（A1、$A$1、R1C1、R、C）。
    fn reserved_cell_name(name: &str) -> bool {
        let n = name.trim();
        if n.is_empty() {
            return true;
        }
        let up = n.to_ascii_uppercase();
        if up == "R" || up == "C" {
            return true;
        }
        if sheetcore::sparse::parse_ref(&n.replace('$', "")).is_some() {
            return true;
        }
        let Some(rest) = up.strip_prefix('R') else {
            return false;
        };
        let Some((row, col)) = rest.split_once('C') else {
            return false;
        };
        !row.is_empty()
            && !col.is_empty()
            && row.bytes().all(|b| b.is_ascii_digit())
            && col.bytes().all(|b| b.is_ascii_digit())
    }

    fn valid_defined_name(name: &str) -> bool {
        let n = name.trim();
        n.chars().next().is_some_and(|c| c.is_alphabetic() || c == '_')
            && n.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '.')
            && !Self::reserved_cell_name(n)
    }

    /// 名称引用：单格/区域（可带表名）或 `={...}` 常量/`=公式(...)`。
    /// 明显错误的引用（如 `Sheet1!A1:`、`BOGUS`）不能静默保存。
    fn valid_name_refers(&self, raw: &str) -> bool {
        let s = raw.trim();
        if s.is_empty() {
            return false;
        }
        if let Some(rest) = s.strip_prefix('=') {
            let r = rest.trim();
            if r.starts_with('{') {
                return r.ends_with('}');
            }
            if r.contains('(') {
                return r.ends_with(')');
            }
            if r.parse::<f64>().is_ok() {
                return true;
            }
        }
        let (sheet_part, range_part) = match s.rsplit_once('!') {
            Some((sheet, range)) => (Some(sheet), range),
            None => (None, s),
        };
        if let Some(sheet) = sheet_part {
            let nm = sheet.trim_matches(|c| c == '\'');
            if !self
                .wb
                .sheets
                .iter()
                .any(|sh| sh.name.eq_ignore_ascii_case(nm))
            {
                return false;
            }
        }
        let clean = range_part.replace('$', "");
        let mut pieces = clean.split(':');
        let first = pieces.next();
        let second = pieces.next();
        let extra = pieces.next();
        let a = first.and_then(sheetcore::sparse::parse_ref);
        let b = match second {
            Some(s) => sheetcore::sparse::parse_ref(s),
            None => a,
        };
        extra.is_none() && a.is_some() && b.is_some()
    }

    /// 名称框：支持 A1、A1:B2、以及定义名称
    fn goto_name(&mut self) {
        let text = self.name_buf.trim().to_string();
        if text.is_empty() {
            return;
        }
        self.nav_rect = None;
        if !self.finish_pending_edit() {
            return;
        }
        let up = text.to_ascii_uppercase();
        let parts: Vec<&str> = up.split(':').collect();
        if parts.len() == 2 {
            if let (Some(a), Some(b)) = (
                sheetcore::sparse::parse_ref(parts[0]),
                sheetcore::sparse::parse_ref(parts[1]),
            ) {
                self.commit_edit(None);
                if self.rect_sel_blocked(a, b) {
                    self.block_selection();
                    return;
                }
                self.sel = a;
                self.sel_end = b;
                self.ensure_visible();
                return;
            }
        } else if let Some(a) = sheetcore::sparse::parse_ref(parts[0]) {
            self.commit_edit(None);
            if self.sel_blocked_at(a.0, a.1) {
                self.block_selection();
                return;
            }
            self.sel = a;
            self.sel_end = a;
            self.ensure_visible();
            return;
        }
        // 同名时当前表的局部名称优先，其次工作簿名称
        let mut local = None;
        let mut global = None;
        for (n, sh, body) in self.wb.names.iter() {
            if !n.eq_ignore_ascii_case(&text) {
                continue;
            }
            match *sh {
                Some(si) if si == self.sheet_idx => {
                    local = Some((*sh, body.clone()));
                    break;
                }
                Some(_) => {}
                None => global = Some((*sh, body.clone())),
            }
        }
        let hit = local.or(global);
        if let Some((_sh, body)) = hit {
            let body = body.trim_start_matches('=').trim();
            // 名称体可以是单格或区域：`Sheet1!$A$1:$B$3`、`$A$1:$B$3`、`A1`。
            let (sheet_part, range_part) = match body.rsplit_once('!') {
                Some((s, r)) => (Some(s), r),
                None => (None, body),
            };
            let clean = range_part.replace('$', "");
            let mut pieces = clean.split(':');
            let first = pieces.next();
            let second = pieces.next();
            let extra = pieces.next();
            let a = first.and_then(sheetcore::sparse::parse_ref);
            let b = match second {
                Some(s) => sheetcore::sparse::parse_ref(s),
                None => a,
            };
            if extra.is_none() {
                if let (Some(a), Some(b)) = (a, b) {
                    if let Some(sheet) = sheet_part {
                        let nm = sheet.trim_matches(|c| c == '\'');
                        if let Some(idx) = self
                            .wb
                            .sheets
                            .iter()
                            .position(|s| s.name.eq_ignore_ascii_case(nm))
                        {
                            if idx != self.sheet_idx && !self.switch_sheet_view(idx) {
                                return;
                            }
                        }
                    }
                    self.commit_edit(None);
                    if self.rect_sel_blocked(a, b) {
                        self.block_selection();
                        return;
                    }
                    self.sel = a;
                    self.sel_end = b;
                    self.ensure_visible();
                    return;
                }
            }
        }
        self.status = format!("找不到名称：{text}");
    }

    /// 提交当前编辑。缓冲的唯一所有者是 `self.editing`；数据验证不通过时不写、
    /// 不移动选区、保留编辑内容和协作租约（Excel 的「重试」）。返回是否真的写入。
    /// 数据验证警告/信息框的选择：是/确定→写入；否→回编辑框；取消→放弃本次输入。
    fn resolve_dv_alert(&mut self, choice: DvAlertChoice) {
        let Some(a) = self.dv_alert.take() else { return };
        // 只有“确定/是”才写入；取消（含信息框的 Esc）必须原样丢弃，
        // 否则用户按 Esc 却被写进去，还会平白多一条撤销记录。
        let commit = choice == DvAlertChoice::Primary;
        if commit {
            self.sel = (a.r, a.c);
            self.editing = Some(EditState::new(a.buf));
            self.dv_force_once = true;
            self.commit_edit(None);
        } else if choice == DvAlertChoice::Secondary {
            self.sel = (a.r, a.c);
            self.editing = Some(EditState::new(a.buf));
            self.status = a.msg;
        } else {
            self.status = format!("已取消输入：{}", a.msg);
        }
    }

    /// 警告/信息提示框。信息样式是“确定/取消”（Excel：取消则不写入），
    /// 警告样式是“是/否/取消”。Esc 一律等于取消。
    fn dv_alert_window(&mut self, ctx: &egui::Context) {
        let Some(a) = self.dv_alert.clone() else { return };
        let mut choice: Option<DvAlertChoice> = None;
        // 模态框期间 handle_keys 让路（dialog_modal），键盘在这里收：
        // Enter = 默认按钮（是/确定），Esc = 取消（三种样式一致，都不写入）。
        let key_choice = if ctx.input(|i| i.key_pressed(Key::Escape)) {
            Some(DvAlertChoice::Cancel)
        } else if ctx.input(|i| i.key_pressed(Key::Enter)) {
            Some(DvAlertChoice::Primary)
        } else {
            None
        };
        let mut win_open = true;
        ui_kit::window(ctx, a.title.clone(), 420.0)
            .open(&mut win_open)
            .collapsible(false)
            .resizable(false)
            .anchor(egui::Align2::CENTER_CENTER, [0.0, 0.0])
            .show(ctx, |ui| {
                ui_kit::state_banner(
                    ui,
                    if a.info_only {
                        ui_kit::StateKind::Empty
                    } else {
                        ui_kit::StateKind::Warn
                    },
                    &a.msg,
                    if a.info_only {
                        "点击「确定」接受此输入值，或点击「取消」放弃写入。"
                    } else {
                        "点击「是」接受此输入值，「否」返回继续修改，「取消」放弃写入。"
                    },
                );
                ui.add_space(10.0);
                ui_kit::footer(ui, |ui| {
                    if a.info_only {
                        if ui_kit::secondary_button(ui, "取消").clicked() {
                            choice = Some(DvAlertChoice::Cancel);
                        }
                        if ui_kit::primary_button(ui, "确定").clicked() {
                            choice = Some(DvAlertChoice::Primary);
                        }
                    } else {
                        if ui_kit::secondary_button(ui, "取消").clicked() {
                            choice = Some(DvAlertChoice::Cancel);
                        }
                        if ui_kit::secondary_button(ui, "否").clicked() {
                            choice = Some(DvAlertChoice::Secondary);
                        }
                        if ui_kit::primary_button(ui, "是").clicked() {
                            choice = Some(DvAlertChoice::Primary);
                        }
                    }
                });
            });
        if !win_open && choice.is_none() {
            choice = Some(DvAlertChoice::Cancel);
        }
        if let Some(c) = choice.or(key_choice) {
            self.resolve_dv_alert(c);
        }
    }

    fn finish_pending_edit(&mut self) -> bool {
        if self.dv_alert.is_none() && self.editing.is_some() {
            self.commit_edit(None);
        }
        self.editing.is_none() && self.dv_alert.is_none()
    }

    fn commit_edit(&mut self, advance: Option<(i32, i32)>) -> bool {
        let mut wrote = false;
        let shared_cells_only = self.only_shared_cell_edits() && self.net.as_ref().is_some_and(|n| !n.hosting)
            && !self.cse_pending;
        let link_count = self.wb.links.len();
        // UI-11.6：跨表取引用时视图停在别的表上，提交前先回到编辑所属表与原格
        self.return_to_edit_origin();
        // 编辑结束（或退回重试）都清掉点选引用的细框
        self.pick_rect = None;
        self.pick_anchor = None;
        self.pick_span = None;
        // 用户在警告框里点了“是”：这一笔跳过验证（一次性）
        let force = std::mem::replace(&mut self.dv_force_once, false);
        if let Some(ed) = self.editing.take() {
            let (r, c) = self.sel;
            // 数据验证：停止样式留在编辑框（Excel 的「重试」）；警告/信息样式先弹框，
            // 确认后才写入；showErrorMessage=0 时按 Excel 语义静默放行。
            let mut rejected: Option<String> = None;
            let mut pending_alert: Option<DvAlert> = None;
            if !force {
                let sheet = self.wb.sheet(self.sheet_idx);
                if let Some(dv) = sheetcore::dv::find(&sheet.dv, r, c) {
                    let probe = if ed.buf.starts_with('=') {
                        Value::Text(ed.buf.as_str().into())
                    } else {
                        Value::parse_input(&ed.buf)
                    };
                    let mut config_err: Option<String> = None;
                    let ok = if dv.kind == sheetcore::dv::DvKind::List {
                        let items = sheetcore::dv::list_items_wb(&self.wb, self.sheet_idx, dv, r, c);
                        if items.is_none() {
                            config_err = Some(format!("列表来源无法解析：{}", dv.f1));
                        }
                        if matches!(probe, Value::Empty) { dv.allow_blank } else {
                            let text = probe.display();
                            items.is_some_and(|items| items.contains(&text))
                        }
                    } else {
                        let mut calc = sheetcore::formula::Calc::new(&self.wb);
                        sheetcore::dv::validate_wb(&self.wb, self.sheet_idx, dv, &probe, r, c, |f, rr, cc| {
                        let (ar, ac) = sheetcore::dv::range_anchor(dv, rr, cc);
                        let shifted = sheetcore::cf::shift_formula(
                            f.trim_start_matches('='),
                            rr.saturating_sub(ar),
                            cc.saturating_sub(ac),
                        );
                        match sheetcore::formula::parse(&shifted) {
                            Ok(node) => calc.eval_node(&node, self.sheet_idx),
                            Err(e) => {
                                config_err = Some(format!("公式阈值无法解析：{f}（{e}）"));
                                sheetcore::formula::FValue::Error(sheetcore::formula::ErrKind::Value)
                            }
                        }
                        })
                    };
                    if !ok {
                        let msg = match &config_err {
                            Some(e) => format!("数据验证配置无效：{e}"),
                            None => sheetcore::dv::error_text(dv),
                        };
                        match dv.verdict(false) {
                            sheetcore::dv::DvVerdict::Reject => rejected = Some(msg),
                            sheetcore::dv::DvVerdict::AcceptSilently => {
                                // Excel 语义是静默放行，但配置坏了仍然要能看见诊断
                                if let Some(e) = &config_err {
                                    self.status = format!("数据验证配置无效：{e}");
                                }
                            }
                            sheetcore::dv::DvVerdict::AskWarning => {
                                pending_alert = Some(DvAlert {
                                    r,
                                    c,
                                    buf: ed.buf.clone(),
                                    info_only: false,
                                    title: dv.error_title.clone(),
                                    msg,
                                });
                            }
                            sheetcore::dv::DvVerdict::InformThenAccept => {
                                pending_alert = Some(DvAlert {
                                    r,
                                    c,
                                    buf: ed.buf.clone(),
                                    info_only: true,
                                    title: dv.error_title.clone(),
                                    msg,
                                });
                            }
                            sheetcore::dv::DvVerdict::Accept => {}
                        }
                    }
                }
            }
            if let Some(alert) = pending_alert {
                // 提示框期间不释放编辑租约：用户在框里选“是/否/取消”后才定稿
                self.dv_alert = Some(alert);
                self.editing = None;
                return false;
            }
            if let Some(msg) = rejected {
                self.status = msg;
                let mut again = ed.clone();
                again.buf = ed.buf.clone();
                self.editing = Some(again);
                return false;
            }
            let cell = if ed.buf.starts_with('=') {
                // 手输的 [预算.xlsx]Sheet!A1：先把工作簿登记成链接（能读到就带缓存），
                // 再折回 Excel 认的 [N] 形式
                let mut text = ed.buf.trim().to_string();
                if sheetcore::xlinks::is_external_formula(&text) {
                    let added = sheetcore::xlinks::absorb_formula(&mut self.wb, &text);
                    if added > 0 {
                        self.status = format!("已登记 {added} 个外部工作簿");
                    }
                    text = sheetcore::xlinks::raw_formula(&self.wb, &text);
                }
                crate::note_formula_use(&text);
                Cell { value: Value::Text(text.as_str().into()), formula: Some(text.as_str().into()) }
            } else {
                Cell { value: Value::parse_input(&ed.buf), formula: None }
            };
            let cell_clone = cell.clone();
            let txn = self.txn_begin(&[(r, c)]);
            self.wb.sheet_mut(self.sheet_idx).set(r, c, cell);
            wrote = true;
            self.txn_end("编辑单元格", txn);
            // 改表格标题行的文字 = 重命名该列（Excel 的行为），公式里的结构化引用跟着改
            let mut renamed: Option<(String, String)> = None;
            if let Some(Value::Text(v)) = self.wb.sheet(self.sheet_idx).get(r, c).map(|x| x.value.clone()) {
                let tb = self
                    .wb
                    .sheet(self.sheet_idx)
                    .tables
                    .iter()
                    .find(|t| r == t.range.0 && c >= t.range.1 && c <= t.range.3)
                    .cloned();
                if let Some(tb) = tb {
                    if let Some(old_col) = tb.columns.get((c - tb.range.1) as usize).cloned() {
                        if old_col != v.as_ref()
                            && sheetcore::table::rename_table_column(
                                &mut self.wb,
                                &tb.name,
                                &old_col,
                                v.as_ref(),
                            )
                        {
                            renamed = Some((old_col, v.to_string()));
                        }
                    }
                }
            }
            if let Some((old_col, new_col)) = renamed {
                self.status = format!("已重命名表格列：{old_col} → {new_col}");
                self.recalc_all_async();
            }
            self.wb.dirty = true;
            let key = (self.sheet_idx, r, c);
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.tasks.last_edit = Some(std::time::Instant::now());
            // Ctrl+Shift+Enter：按选区把这条公式登记成数组公式（保存时写 t="array" ref）
            if self.cse_pending {
                self.cse_pending = false;
                let (r1, c1, r2, c2) = self.sel_rect();
                if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 1 && ed.buf.starts_with('=') {
                    let sheet = self.wb.sheet_mut(self.sheet_idx);
                    sheet.arrays.retain(|(a, _)| *a != sheetcore::model::CellRef::new(r1, c1));
                    sheet.arrays.push((
                        sheetcore::model::CellRef::new(r1, c1),
                        (r1, c1, r2, c2),
                    ));
                    let rect = (r1, c1, r2, c2);
                    self.status = format!(
                        "已按数组公式写入 {}{}:{}{}",
                        sheetcore::model::col_label(c1),
                        r1 + 1,
                        sheetcore::model::col_label(c2),
                        r2 + 1
                    );
                    let _ = rect;
                }
            }
            // 先毫秒级即时求得当前编辑格自身值并立刻经 TCP 发出广播与释放租约，
            // 使对端机器在 1ms 内收到更新，绝不被本机下游公式重算拖慢！
            let seed_ok = if !self.manual_calc {
                sheetcore::formula::eval_formula_seeds_immediate(&mut self.wb, &[key])
            } else {
                true
            };
            if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
                let live_cell = self
                    .wb
                    .sheet(self.sheet_idx)
                    .get(r, c)
                    .cloned()
                    .unwrap_or(cell_clone);
                let op = peer.local_set(self.sheet_idx, r, c, &live_cell);
                net.broadcast_op(op);
                if shared_cells_only && self.wb.links.len() == link_count {
                    self.shared_cell_generation = Some((self.doc_uid, self.doc_gen));
                }
            }
            self.release_lock();
            self.fast_recalc_cells(&[key]);
            if !seed_ok {
                self.request_silent_bg_recalc();
            }
        }
        // 表格对象：在表格正下方继续输入时自动扩一行（Excel 的行为）；
        // 在右侧一列输入时扩一列。汇总行不自动越过。
        {
            let (rr, cc) = self.sel;
            let mut grew: Option<(String, (u32, u32, u32, u32))> = None;
            {
                let sheet = self.wb.sheet(self.sheet_idx);
                for t in sheet.tables.iter() {
                    if t.totals_row || !t.header_row {
                        continue;
                    }
                    let (r1, c1, r2, c2) = t.range;
                    if cc >= c1 && cc <= c2 && rr == r2 + 1 {
                        grew = Some((t.name.clone(), (r1, c1, r2 + 1, c2)));
                        break;
                    }
                    if rr >= r1 && rr <= r2 && cc == c2 + 1 {
                        grew = Some((t.name.clone(), (r1, c1, r2, c2 + 1)));
                        break;
                    }
                }
            }
            if let Some((name, range)) = grew {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                if let Some(t) = sh.tables.iter_mut().find(|t| t.name == name) {
                    t.range = range;
                    if range.3 as usize >= t.columns.len() {
                        let n = t.columns.len() + 1;
                        t.columns.push(format!("列{n}"));
                    }
                }
                sh.tables_dirty = true;
                // 表格带筛选时，筛选区域跟着扩大
                if let Some(f) = sh.filter.as_mut() {
                    if f.range.0 == range.0 && f.range.1 == range.1 {
                        f.range = range;
                    }
                }
                self.wb.dirty = true;
            }
        }
        // 文本被改写后旧的富文本段就失效了（避免保存时把旧分段盖回去）
        {
            let (rr, cc) = self.sel;
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            if let Some(runs) = sheet.rich.get(&(rr, cc)).cloned() {
                let t = sheetcore::richtext::runs_text(&runs);
                if t != sheet.value(rr, cc).display() {
                    sheet.rich.remove(&(rr, cc));
                    sheet.rich_dirty = true;
                }
            }
        }
        if wrote {
            if let Some((dr, dc)) = advance {
                self.advance_active(dr as i32, dc as i32);
            }
        }
        wrote
    }

    /// 取消编辑：丢弃缓冲、交还租约，不碰模型、不记撤销、不改 dirty。
    fn cancel_edit(&mut self) {
        self.return_to_edit_origin();
        self.editing = None;
        self.pick_rect = None;
        self.pick_anchor = None;
        self.pick_span = None;
        self.release_lock();
    }

    /// UI-11.6：把视图切回编辑会话所属的工作表与原格（跨表取引用后提交/取消时用）。
    fn return_to_edit_origin(&mut self) {
        let Some(es) = self.edit_sheet else {
            return;
        };
        if es != self.sheet_idx && es < self.wb.sheets.len() {
            self.remember_sheet_view();
            self.load_sheet_view(es);
        }
        if let Some(sel) = self.edit_sel {
            self.sel = sel;
        }
        self.edit_sheet = None;
        self.edit_sel = None;
    }

    /// UI-11.6：公式编辑中切工作表只换视图、不提交（Excel 里点另一张表页是接着取引用）。
    fn switch_sheet_for_ref(&mut self, idx: usize) -> bool {
        if idx >= self.wb.sheets.len() || idx == self.sheet_idx {
            return true;
        }
        let formula_edit = self
            .editing
            .as_ref()
            .is_some_and(|ed| ed.buf.starts_with('='));
        if !formula_edit {
            return self.switch_sheet_view(idx);
        }
        self.edit_sheet.get_or_insert(self.sheet_idx);
        self.edit_sel.get_or_insert(self.sel);
        self.remember_sheet_view();
        self.load_sheet_view(idx);
        let back = match (self.edit_sheet, self.edit_sel) {
            (Some(es), Some((r, c))) => self
                .wb
                .sheets
                .get(es)
                .map(|s| format!("{}!{}", sheet_ref_name(&s.name), cell_name(r, c)))
                .unwrap_or_default(),
            _ => String::new(),
        };
        // 跨表后原锚点在别的表上，引用区间不能横跨两张表：
        // 清掉锚点，让这张表上的第一次点选/拖动重新立锚（Excel 同样把新表当起点）
        self.pick_anchor = None;
        self.pick_rect = None;
        self.status = format!("点选引用（回车写回 {back}）");
        true
    }

    /// UI-11.6：跨表引用要带上工作表名；名字含空格/符号时按 Excel 规则加单引号。
    fn qualify_ref(&self, label: &str) -> String {
        match self.edit_sheet {
            Some(es) if es != self.sheet_idx => {
                let name = self
                    .wb
                    .sheets
                    .get(self.sheet_idx)
                    .map(|s| s.name.clone())
                    .unwrap_or_default();
                format!("{}!{label}", sheet_ref_name(&name))
            }
            _ => label.to_string(),
        }
    }

    /// UI-11.6：在表格上点一格 = 往公式缓冲里插引用（跨表时带表名）。
    fn insert_pick_reference(&mut self, r: u32, c: u32) -> String {
        let label = self.qualify_ref(&crate::cell_name(r, c));
        let mut span = None;
        if let Some(ed) = self.editing.as_mut() {
            let (buf, caret) = insert_reference(&ed.buf, ed.caret, &label);
            ed.buf = buf;
            ed.caret = caret;
            ed.caret_override = Some(caret);
            ed.focus_requested = true;
            span = Some((caret - label.chars().count(), caret));
        }
        self.pick_anchor = Some((r, c));
        self.pick_span = span;
        self.pick_rect = Some((r, c, r, c));
        self.status = format!("已插入引用 {label}");
        label
    }

    /// 让选区留在可视范围内（列宽行高不统一，只能按实际位置算）
    fn ensure_visible(&mut self) {
        let (r, c) = self.sel;
        let (cols, rows) = self.view_axes();
        let view_w = (self.last_view.x - HEAD_W).max(64.0);
        let view_h = (self.last_view.y - HEAD_H).max(44.0);
        let top = rows.pos(r);
        let bot = top + rows.size(r);
        if top < self.scroll.y {
            self.scroll.y = top;
        } else if bot > self.scroll.y + view_h {
            self.scroll.y = bot - view_h;
        }
        let left = cols.pos(c);
        let right = left + cols.size(c);
        if left < self.scroll.x {
            self.scroll.x = left;
        } else if right > self.scroll.x + view_w {
            self.scroll.x = right - view_w;
        }
    }

    /// 当前视口实际可见的数据行数（跳过隐藏行；含底部部分可见行）。
    fn visible_page_rows(&self) -> u32 {
        let (_, rows) = self.view_axes();
        let view_h = (self.last_view.y - HEAD_H).max(44.0);
        let top = self.scroll.y;
        let mut r = rows.index_at(top);
        let mut n = 0u32;
        let mut guard = 0u32;
        while r <= 1_048_575 && rows.pos(r) < top + view_h && guard < 8192 {
            if rows.size(r) > 0.0 {
                n += 1;
            }
            r += 1;
            guard += 1;
        }
        n.max(1)
    }

    /// 下一个可见行/列，跳过隐藏（尺寸为 0）的行/列。
    /// 到首/末边界且边界本身隐藏时，停在该方向最近的可见行；只有全表都隐藏才返回原值。
    fn next_visible_row(&self, from: u32, down: bool) -> u32 {
        const MAX_ROW: u32 = 1_048_575;
        let (_, rows) = self.view_axes();
        let visible = |r: u32| rows.size(r) > 0.0;
        let mut r = from;
        if down {
            while r < MAX_ROW {
                r += 1;
                if visible(r) {
                    return r;
                }
            }
            if visible(from) {
                return from;
            }
            // 下方没有可见行：回退到最近的可见行，绝不停在隐藏的末行。
            for r in (0..from).rev() {
                if visible(r) {
                    return r;
                }
            }
        } else {
            while r > 0 {
                r -= 1;
                if visible(r) {
                    return r;
                }
            }
            if visible(from) {
                return from;
            }
            // 上方没有可见行：前进到最近的可见行，绝不停在隐藏的首行。
            for r in (from + 1)..=MAX_ROW {
                if visible(r) {
                    return r;
                }
            }
        }
        from
    }

    /// 当前视口首/末可见数据行；和活动格无关，用来按原视口边界翻页。
    fn visible_page_bounds(&self) -> (u32, u32) {
        let (_, rows) = self.view_axes();
        let view_h = (self.last_view.y - HEAD_H).max(44.0);
        let top = self.scroll.y;
        let mut r = rows.index_at(top);
        let mut first = None;
        let mut last = self.sel.0;
        let mut guard = 0u32;
        while r <= 1_048_575 && rows.pos(r) < top + view_h && guard < 8192 {
            if rows.size(r) > 0.0 {
                first.get_or_insert(r);
                last = r;
            }
            r += 1;
            guard += 1;
        }
        (first.unwrap_or(self.sel.0), last)
    }

    /// PageUp/PageDown：按原视口边界翻页（保留一行重叠），同时保持活动格
    /// 在页内的相对位置；不能把新活动格直接当作新视口首行，否则会跳过中间行。
    fn page_move(&mut self, down: bool) {
        let step = self.visible_page_rows().saturating_sub(1).max(1);
        let (first, _last) = self.visible_page_bounds();
        let (mut r, c) = self.sel;
        let mut moved = 0u32;
        for _ in 0..step {
            let nr = self.next_visible_row(r, down);
            if nr == r {
                break;
            }
            r = nr;
            moved += 1;
        }
        if moved > 0 {
            // 视口首行跟着移动同样的可见行数，而不是贴着新活动格。
            let mut top = first;
            for _ in 0..moved {
                let nt = self.next_visible_row(top, down);
                if nt == top {
                    break;
                }
                top = nt;
            }
            let (_, rows) = self.view_axes();
            self.scroll.y = rows.pos(top);
        }
        self.sel = (r, c);
        self.sel_end = (r, c);
        self.extra_sel.clear();
        self.nav_rect = None;
        self.ensure_visible();
    }

    /// UI-16：把当前表的选区/滚动/缩放存到该表的 identity 下。
    fn remember_sheet_view(&mut self) {
        let Some(sh) = self.wb.sheets.get(self.sheet_idx) else {
            return;
        };
        let id = sh.identity;
        self.sheet_views.insert(
            id,
            SheetViewState {
                sel: self.sel,
                sel_end: self.sel_end,
                extra_sel: self.extra_sel.clone(),
                scroll: self.scroll,
                zoom: self.zoom,
                view_mode: self.view_mode,
                split_panes: self.split_panes,
                split_scroll: self.split_scroll,
            },
        );
    }

    /// UI-16：切到 idx 前先保存当前表视图；目标表没有记录时用新表默认视图。
    fn switch_sheet_view(&mut self, idx: usize) -> bool {
        if idx >= self.wb.sheets.len() {
            return false;
        }
        if idx == self.sheet_idx {
            return true;
        }
        if !self.finish_pending_edit() {
            return false;
        }
        self.remember_sheet_view();
        self.drop_merge_confirmation();
        self.format_painter = None;
        self.painter_double = false;
        self.load_sheet_view(idx);
        true
    }

    /// 把目标表自己的视图装回活动字段；调用方负责 sheet_idx 边界。
    fn load_sheet_view(&mut self, idx: usize) {
        self.sheet_idx = idx;
        let id = self.wb.sheet(idx).identity;
        let view = self
            .sheet_views
            .get(&id)
            .cloned()
            .unwrap_or_default();
        self.sel = view.sel;
        self.sel_end = view.sel_end;
        self.extra_sel = view.extra_sel;
        self.scroll = view.scroll;
        self.zoom = view.zoom;
        self.view_mode = view.view_mode;
        self.split_panes = view.split_panes;
        self.split_scroll = view.split_scroll;
        self.nav_rect = None;
    }

    /// Ctrl+PageUp/PageDown：在当前文档内切换可见工作表，跳过隐藏表。
    fn switch_sheet_relative(&mut self, delta: i32) {
        let n = self.wb.sheets.len();
        if n < 2 {
            return;
        }
        self.commit_edit(None);
        let mut i = self.sheet_idx as i32;
        for _ in 0..n {
            i = (i + delta).rem_euclid(n as i32);
            if !self.wb.sheets[i as usize].hidden {
                if self.switch_sheet_view(i as usize) {
                    self.status = format!("当前工作表：{}", self.wb.sheet(self.sheet_idx).name);
                }
                return;
            }
        }
    }

    /// 开始区域的 Tab/Enter 循环：多格选区记下原始矩形，单格不启用。
    fn begin_nav_rect(&mut self) {
        if let Some((r1, c1, r2, c2)) = self.nav_rect {
            if self.sel.0 < r1 || self.sel.0 > r2 || self.sel.1 < c1 || self.sel.1 > c2 {
                self.nav_rect = None;
            }
        }
        if self.nav_rect.is_none() {
            let rect = self.sel_rect();
            if rect.0 < rect.2 || rect.1 < rect.3 {
                self.nav_rect = Some(rect);
            }
        }
    }

    /// 列方向的下一个可见列：与 next_visible_row 相同的边界回退语义。
    fn next_visible_col(&self, from: u32, right: bool) -> u32 {
        const MAX_COL: u32 = 16_383;
        let (cols, _) = self.view_axes();
        let visible = |c: u32| cols.size(c) > 0.0;
        let mut c = from;
        if right {
            while c < MAX_COL {
                c += 1;
                if visible(c) {
                    return c;
                }
            }
            if visible(from) {
                return from;
            }
            for c in (0..from).rev() {
                if visible(c) {
                    return c;
                }
            }
        } else {
            while c > 0 {
                c -= 1;
                if visible(c) {
                    return c;
                }
            }
            if visible(from) {
                return from;
            }
            for c in (from + 1)..=MAX_COL {
                if visible(c) {
                    return c;
                }
            }
        }
        from
    }

    /// Enter/Tab 的活动格推进：多格选区在区域内循环，单格跳到下一个可见行/列。
    fn advance_active(&mut self, dr: i32, dc: i32) {
        self.begin_nav_rect();
        if let Some((r1, c1, r2, c2)) = self.nav_rect {
            let (mut r, mut c) = self.sel;
            if r < r1 || r > r2 || c < c1 || c > c2 {
                r = r1;
                c = c1;
            }
            let (cols, rows) = self.view_axes();
            let w = (c2 - c1 + 1) as u64;
            let h = (r2 - r1 + 1) as u64;
            let limit = w.saturating_mul(h).min(200_000);
            for _ in 0..limit {
                if dc > 0 {
                    c += 1;
                    if c > c2 {
                        c = c1;
                        if r < r2 {
                            r += 1;
                        } else {
                            r = r1;
                        }
                    }
                } else if dc < 0 {
                    if c <= c1 {
                        c = c2;
                        if r > r1 {
                            r -= 1;
                        } else {
                            r = r2;
                        }
                    } else {
                        c -= 1;
                    }
                } else if dr > 0 {
                    if r < r2 {
                        r += 1;
                    } else if c < c2 {
                        r = r1;
                        c += 1;
                    } else {
                        r = r1;
                        c = c1;
                    }
                } else if dr < 0 {
                    if r > r1 {
                        r -= 1;
                    } else if c > c1 {
                        r = r2;
                        c -= 1;
                    } else {
                        r = r2;
                        c = c2;
                    }
                }
                if rows.size(r) > 0.0 && cols.size(c) > 0.0 {
                    if self.sel_blocked_at(r, c) {
                        continue;
                    }
                    self.sel = (r, c);
                    self.ensure_visible();
                    return;
                }
            }
            return;
        }
        let (mut nr, mut nc) = if dr != 0 {
            (self.next_visible_row(self.sel.0, dr > 0), self.sel.1)
        } else if dc != 0 {
            (self.sel.0, self.next_visible_col(self.sel.1, dc > 0))
        } else {
            return;
        };
        let start = self.sel;
        let mut guard = 0;
        while self.sel_blocked_at(nr, nc) {
            let next = if dr != 0 {
                (self.next_visible_row(nr, dr > 0), nc)
            } else {
                (nr, self.next_visible_col(nc, dc > 0))
            };
            if next == (nr, nc) || next == start || guard > 20_000 {
                self.block_selection();
                return;
            }
            nr = next.0;
            nc = next.1;
            guard += 1;
        }
        self.sel = (nr, nc);
        self.sel_end = (nr, nc);
        self.extra_sel.clear();
        self.ensure_visible();
    }

    /// Ctrl+A：第一次选当前数据区域，第二次在已选整块时选全表（Excel 的两段行为）。
    fn select_region_or_all(&mut self) {
        self.commit_edit(None);
        let (r1, c1, r2, c2) =
            sheetcore::sort_filter::current_region(self.wb.sheet(self.sheet_idx), self.sel.0, self.sel.1);
        let already = self.sel == (r1, c1) && self.sel_end == (r2, c2);
        self.extra_sel.clear();
        self.nav_rect = None;
        if already {
            self.sel = (0, 0);
            self.sel_end = (1_048_575, 16_383);
            self.scroll = Vec2::ZERO;
            self.status = "已选择整个工作表".into();
        } else {
            self.sel = (r1, c1);
            self.sel_end = (r2, c2);
            self.ensure_visible();
            self.status = format!("已选择当前区域 {}:{}", cell_name(r1, c1), cell_name(r2, c2));
        }
    }

    fn select_whole_row(&mut self) {
        let (r1, _, r2, _) = self.sel_rect();
        self.extra_sel.clear();
        self.nav_rect = None;
        self.sel = (r1, 0);
        self.sel_end = (r2, 16_383);
        self.ensure_visible();
        self.status = if r1 == r2 {
            format!("已选择第 {} 行", r1 + 1)
        } else {
            format!("已选择第 {}–{} 行", r1 + 1, r2 + 1)
        };
    }

    fn select_whole_col(&mut self) {
        let (_, c1, _, c2) = self.sel_rect();
        self.extra_sel.clear();
        self.nav_rect = None;
        self.sel = (0, c1);
        self.sel_end = (1_048_575, c2);
        self.ensure_visible();
        self.status = if c1 == c2 {
            format!("已选择 {} 列", col_label(c1))
        } else {
            format!("已选择 {}–{} 列", col_label(c1), col_label(c2))
        };
    }

    /// 当前 KeyTips 页签下所有带 keytip 的可见命令（序列 → onAction）。
    fn keytip_actions(&self) -> Vec<(String, String)> {
        let Some(tab) = self.keytip_tab.and_then(|i| self.ribbon.tabs.get(i)) else {
            return Vec::new();
        };
        fn collect(nodes: &[ribbon::Node], out: &mut Vec<(String, String, String)>) {
            for n in nodes {
                match n {
                    ribbon::Node::Button(c) | ribbon::Node::Toggle(c) => {
                        if let Some(k) = &c.keytip {
                            out.push((k.clone(), c.action().to_string(), c.id.clone()));
                        }
                    }
                    ribbon::Node::Split { ctl, .. }
                    | ribbon::Node::DropDown { ctl, .. }
                    | ribbon::Node::Gallery { ctl, .. }
                    | ribbon::Node::ComboBox { ctl, .. }
                    | ribbon::Node::EditBox { ctl, .. }
                    | ribbon::Node::Slider { ctl, .. } => {
                        if let Some(k) = &ctl.keytip {
                            out.push((k.clone(), ctl.action().to_string(), ctl.id.clone()));
                        }
                    }
                    ribbon::Node::Menu(m) => {
                        if let Some(k) = &m.ctl.keytip {
                            out.push((k.clone(), m.ctl.action().to_string(), m.ctl.id.clone()));
                        }
                    }
                    ribbon::Node::Box { children, .. } => collect(children, out),
                    ribbon::Node::Label(_) | ribbon::Node::Spacer(_) | ribbon::Node::Separator => {}
                }
            }
        }
        let mut flat = Vec::new();
        for g in &tab.groups {
            collect(&g.children, &mut flat);
        }
        let mut out = Vec::new();
        for (k, action, id) in flat {
            let k = k.to_ascii_uppercase();
            if k.is_empty() {
                continue;
            }
            let st = self.ctl_state(&id);
            if !st.visible || !st.enabled || action.is_empty() {
                continue;
            }
            // 边框拆分按钮的 keytip B 对应菜单里的“所有框线”，而不是主按钮的下框线
            let action = if k == "B" && action == "BorderBottom" {
                "BordersAll".to_string()
            } else {
                action
            };
            if out.iter().any(|(x, _): &(String, String)| *x == k) {
                continue;
            }
            out.push((k, action));
        }
        out
    }

    /// 键盘：方向键移动、回车/制表符提交并移动、直接键入进入编辑。
    fn handle_keys(&mut self, ctx: &egui::Context) {
        // 保存/打开/新建/打印/撤销/重做由 crate::command 的命令表统一处理
        // （见 `handle_command_keys`），这里只剩网格自身的按键。
        // Ctrl+F1：和 Excel 一样收起/展开功能区
        if ctx.input(|i| i.modifiers.command && i.key_pressed(Key::F1)) {
            self.ribbon_collapsed = !self.ribbon_collapsed;
        }
        // F4：编辑公式时循环末尾引用的绝对/相对形式
        if self.editing.is_some() && ctx.input(|i| i.key_pressed(Key::F4)) {
            if let Some(ed) = self.editing.as_mut() {
                if cycle_formula_ref(&mut ed.buf) {
                    return;
                }
            }
        }
        // F9：Excel 同款“重算全部”，大文件走后台
        if self.editing.is_none() && ctx.input(|i| i.key_pressed(Key::F9)) {
            self.recalc_all_async();
            return;
        }
        // Shift+F10：在当前对象上打开单元格右键菜单（Excel 同款键盘入口）
        if self.editing.is_none()
            && self.ctx_menu.is_none()
            && ctx.input(|i| i.modifiers.shift && i.key_pressed(Key::F10))
        {
            let pos = ctx
                .input(|i| i.pointer.hover_pos())
                .filter(|p| ctx.screen_rect().contains(*p))
                .unwrap_or_else(|| ctx.screen_rect().center());
            self.keytips = false;
            self.keytip_tab = None;
            self.ctx_menu = Some(CtxMenuState {
                pos,
                frame: ctx.cumulative_pass_nr(),
                sub: None,
                kind: CtxKind::Cell,
                idx: 0,
                key: 0,
                sub_key: 0,
            });
            ctx.request_repaint();
            return;
        }
        // 右键菜单打开时，方向键/Enter/Esc 由菜单自己处理，不能穿透到网格
        if self.ctx_menu.is_some() {
            return;
        }

        if self.editing.is_none()
            && (self.format_painter.is_some()
                || self.merge_pending.is_some()
                || self.fmt_merge_pending.is_some())
            && ctx.input(|i| i.key_pressed(Key::Escape))
        {
            let had_painter = self.format_painter.is_some();
            let had_merge = self.merge_pending.is_some() || self.fmt_merge_pending.is_some();
            self.format_painter = None;
            self.painter_double = false;
            self.drop_merge_confirmation();
            self.status = match (had_painter, had_merge) {
                (true, true) => "格式刷与未确认的合并已取消".into(),
                (true, false) => "格式刷已取消".into(),
                _ => "已取消未确认的合并".into(),
            };
            return;
        }

        if self.editing.is_none()
            && !self.extra_sel.is_empty()
            && ctx.input(|i| i.key_pressed(Key::Escape))
        {
            self.extra_sel.clear();
            self.status = "已取消多块选区".into();
            return;
        }
        if !self.dialog_modal
            && ctx.input(|i| i.modifiers.command && i.modifiers.shift && !i.modifiers.alt && i.key_pressed(Key::A))
        {
            self.toggle_ai_assistant(None);
            return;
        }
        if self.editing.is_none() && ctx.wants_keyboard_input() {
            // 对话框/查找框有焦点时不要把按键当成网格快捷键。
            // egui 的 Tab 会先把焦点交给第一个可聚焦控件；网格不是控件，
            // 所以本帧先让 Tab 完成移动，帧末再把这次“顺带”得到的焦点清掉。
            if ctx.input(|i| i.key_pressed(Key::Tab))
                && !self.palette_open
                && !self.find.open
                && !self.dialog_modal
                && !self.ai.open
            {
                if let Some(id) = ctx.memory(|m| m.focused()) {
                    ctx.memory_mut(|m| m.surrender_focus(id));
                }
                ctx.memory_mut(|m| m.stop_text_input());
                self.clear_grid_focus = true;
            } else {
                return;
            }
        }
        if self.editing.is_some() {
            // 编辑框内的按键交给 TextEdit 自己处理
            if ctx.input(|i| i.key_pressed(Key::Escape)) {
                self.cancel_edit();
            }
            return;
        }
        // 模态对话框自己消费 Enter/Esc；不能把同一次按键再漏给网格。
        // `dialog_modal` 只覆盖查找/数据验证/函数向导，格式对话框用独立
        // `fmt_dlg` 开关，必须在 handle_keys 这里一并挡住。
        if self.dialog_modal || self.fmt_dlg || self.profile_open || self.about_open {
            return;
        }

        // 序列下拉打开时键盘接管：↑↓ 移动、Enter 选、Esc 关（Excel 的下拉键盘行为）
        if let Some((dr, dc)) = self.dv_open {
            self.refresh_dv_source(dr, dc);
            self.refresh_dv_filter();
            let count = self.dv_item_count();
            if self.dv_cache.is_empty() {
                self.dv_open = None;
            } else {
                if ctx.input(|i| i.key_pressed(Key::Escape)) {
                    self.dv_open = None;
                    self.status = "已关闭序列下拉（未写入）".into();
                    return;
                }
                if count > 0 && ctx.input(|i| i.key_pressed(Key::ArrowDown)) {
                    self.dv_hilite = (self.dv_hilite + 1) % count;
                    return;
                }
                if count > 0 && ctx.input(|i| i.key_pressed(Key::ArrowUp)) {
                    self.dv_hilite = (self.dv_hilite + count - 1) % count;
                    return;
                }
                if count > 0 && ctx.input(|i| i.key_pressed(Key::Enter)) {
                    let v = self.dv_item_at(self.dv_hilite.min(count - 1)).clone();
                    self.dv_open = None;
                    self.dv_pick_apply(dr, dc, &v);
                    return;
                }
            }
        }
        // Alt+↓：打开选中格的序列下拉。看事件自带的修饰键，别依赖全局 modifiers
        // （合成/远端会话里 InputState.modifiers 可能没跟着按键事件更新）。
        let alt_down = ctx.input(|i| {
            i.events.iter().any(|e| {
                matches!(
                    e,
                    egui::Event::Key { key: Key::ArrowDown, pressed: true, modifiers, .. }
                        if modifiers.alt
                )
            })
        });
        if alt_down {
            self.dv_open_for_selection();
            return;
        }

        // 常用选择/格式快捷键（编辑区由 TextEdit 优先处理，见上）
        let ctrl_shortcut = ctx.input(|i| i.modifiers.command && !i.modifiers.alt);
        // 文件级快捷键（Ctrl+S / Ctrl+Z / Ctrl+Y）单独抽出来，便于用真实 egui 事件做回归
        if self.handle_file_shortcuts(ctx) {
            return;
        }
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::B)) {
            self.ribbon_action("Bold", ctx);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::I)) {
            self.ribbon_action("Italic", ctx);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::U)) {
            self.ribbon_action("Underline", ctx);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| !i.modifiers.shift && i.key_pressed(Key::A)) {
            self.select_region_or_all();
            return;
        }
        // WPS 高频快捷键：Ctrl+Shift+L 筛选、Alt+= 求和、Ctrl+K 超链接、Ctrl+Tab 切文档、Ctrl+; 日期、Ctrl+Shift+; 时间
        if ctrl_shortcut && ctx.input(|i| i.modifiers.shift && i.key_pressed(Key::L)) {
            self.start_filter();
            return;
        }
        if ctx.input(|i| i.modifiers.alt && !i.modifiers.command && (i.key_pressed(Key::Equals) || i.key_pressed(Key::Plus))) {
            self.auto_sum();
            return;
        }
        if ctrl_shortcut && ctx.input(|i| !i.modifiers.shift && i.key_pressed(Key::K)) {
            let (r, c) = self.sel;
            let text = self.wb.sheet(self.sheet_idx).value(r, c).display();
            self.hyper_dlg = Some((String::new(), text));
            return;
        }
        if ctx.input(|i| i.modifiers.command && !i.modifiers.alt && i.key_pressed(Key::Tab)) && self.tabs.len() > 1 {
            let n = self.tabs.len();
            let rev = ctx.input(|i| i.modifiers.shift);
            let next = (self.active_tab + if rev { n - 1 } else { 1 }) % n;
            self.switch_tab(next);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| (i.modifiers.shift && i.key_pressed(Key::Semicolon)) || i.key_pressed(Key::Colon)) {
            self.insert_current_datetime(true);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| !i.modifiers.shift && i.key_pressed(Key::Semicolon)) {
            self.insert_current_datetime(false);
            return;
        }
        let (ctrl_space, shift_space) = ctx.input(|i| {
            (
                i.modifiers.command && i.key_pressed(Key::Space),
                i.modifiers.shift && !i.modifiers.command && i.key_pressed(Key::Space),
            )
        });
        if ctrl_space {
            self.select_whole_col();
            return;
        }
        if shift_space {
            self.select_whole_row();
            return;
        }
        if ctx.input(|i| i.key_pressed(Key::F5))
            || (ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::G)))
        {
            self.name_focus_request = true;
            self.status = "在名称框输入 A1、A1:B2 或定义名称，回车定位".into();
            return;
        }

        // 选中文本框时 Delete/Backspace 删掉它（Excel 同款）
        if self.editing.is_none() && !ctx.wants_keyboard_input() {
            if let Some(i) = self.tb_sel {
                if ctx.input(|i| i.key_pressed(Key::Delete) || i.key_pressed(Key::Backspace)) {
                    self.tb_delete(i);
                    return;
                }
            }
        }

        // Alt：显示页签字母提示（KeyTips）；再按页签字母进入命令级 KeyTips
        let alt_now = ctx.input(|i| i.modifiers.alt);
        if alt_now && !self.alt_down {
            self.keytips = true;
            self.keytip_tab = None;
            self.keytip_prefix.clear();
        }
        self.alt_down = alt_now;
        if self.keytips {
            // Esc 逐级返回：命令前缀 → 命令级 → 页签级 → 关闭
            if ctx.input(|i| i.key_pressed(Key::Escape)) {
                if !self.keytip_prefix.is_empty() {
                    self.keytip_prefix.clear();
                } else if self.keytip_tab.take().is_some() {
                    self.keytips = true;
                } else {
                    self.keytips = false;
                    self.keytip_prefix.clear();
                }
            } else if ctx.input(|i| i.pointer.any_click()) {
                self.keytips = false;
                self.keytip_tab = None;
                self.keytip_prefix.clear();
            } else if self.keytip_tab.is_some() {
                // 第二阶段：当前页签内按控件 keytip 序列执行命令。
                // Excel 的 "F" 后面还有组内字母（如 FP），所以先按前缀收窄，
                // 恰好命中完整序列才执行；Backspace 退回上一级。
                let actions = self.keytip_actions();
                if ctx.input(|i| i.key_pressed(Key::Backspace))
                    && !self.keytip_prefix.is_empty()
                {
                    self.keytip_prefix.pop();
                    return;
                }
                if let Some(ch) = pressed_key_char(ctx) {
                    let cand = format!("{}{}", self.keytip_prefix, ch);
                    let exact = actions
                        .iter()
                        .find(|(k, _)| k == &cand)
                        .map(|(_, a)| a.clone());
                    if let Some(action) = exact {
                        self.keytips = false;
                        self.keytip_tab = None;
                        self.keytip_prefix.clear();
                        self.ribbon_action(&action, ctx);
                        return;
                    }
                    if actions.iter().any(|(k, _)| k.starts_with(&cand)) {
                        self.keytip_prefix = cand;
                        return;
                    }
                }
            } else {
                // 第一阶段：页签字母
                let chosen = ctx.input(|i| {
                    let m = i.modifiers;
                    if m.alt || m.command || m.shift {
                        return None;
                    }
                    for (k, idx) in [
                        (Key::F, 0usize),
                        (Key::H, 1),
                        (Key::N, 2),
                        (Key::P, 3),
                        (Key::M, 4),
                        (Key::A, 5),
                        (Key::R, 6),
                        (Key::W, 7),
                    ] {
                        if i.key_pressed(k) {
                            return Some(idx);
                        }
                    }
                    None
                });
                if let Some(idx) = chosen {
                    if idx == 0 {
                        self.keytips = false;
                        self.backstage = true;
                        self.backstage_page = 0;
                    } else {
                        self.ribbon_tab = idx;
                        self.ribbon_collapsed = false;
                        self.keytip_tab = Some(idx);
                        self.keytip_prefix.clear();
                    }
                }
            }
        }
        if std::env::var("SC_KEYTIP_LOG").is_ok() && (self.keytips || self.keytip_tab.is_some()) {
            eprintln!(
                "[keytip] active={} tab={:?} ribbon_tab={}",
                self.keytips, self.keytip_tab, self.ribbon_tab
            );
        }
        let show_f_k = ctx.input(|i| i.modifiers.command && i.key_pressed(Key::Backtick));
        if show_f_k {
            self.show_formulas = !self.show_formulas;
            self.status = if self.show_formulas {
                "显示公式（再按 Ctrl+` 切回结果）".into()
            } else {
                "显示结果".into()
            };
        }
        let (copy_evt, cut_evt, paste_evt) = ctx.input(|i| {
            (
                i.events.iter().any(|e| matches!(e, egui::Event::Copy)),
                i.events.iter().any(|e| matches!(e, egui::Event::Cut)),
                i.events.iter().any(|e| matches!(e, egui::Event::Paste(_))),
            )
        });
        let (copy_k, cut_k, paste_k, paste_v_k, find_k, repl_k) = ctx.input(|i| {
            (
                i.modifiers.command && i.key_pressed(Key::C),
                i.modifiers.command && i.key_pressed(Key::X),
                i.modifiers.command && !i.modifiers.shift && !i.modifiers.alt && i.key_pressed(Key::V),
                i.modifiers.command && i.modifiers.shift && i.key_pressed(Key::V),
                i.modifiers.command && i.key_pressed(Key::F),
                i.modifiers.command && i.key_pressed(Key::H),
            )
        });
        if let Some(values_only) = self.grid_paste.as_ref().and_then(|hook| hook.take()) {
            self.clip_paste(values_only, None);
            return;
        }
        if copy_k || copy_evt {
            self.clip_copy(false, ctx);
            return;
        }
        if cut_k || cut_evt {
            self.clip_copy(true, ctx);
            return;
        }
        if paste_k || paste_v_k || paste_evt {
            let text = ctx.input(|i| {
                i.events.iter().find_map(|e| match e {
                    egui::Event::Paste(t) => Some(t.clone()),
                    _ => None,
                })
            });
            // 系统剪贴板没有新粘贴事件时，用内部剪贴板
            self.clip_paste(paste_v_k, text);
            return;
        }
        if find_k || repl_k {
            self.find.tab = if repl_k { 1 } else { 0 };
            self.find_open_new_session();
            return;
        }
        if ctx.input(|i| i.modifiers.command && i.modifiers.alt && i.key_pressed(Key::V)) {
            self.paste_special = true;
            return;
        }
        // Ctrl+方向：跳到数据边缘；Ctrl+Home/End：回到 A1 / 已用区域末尾
        let (ctrl, home, end, pgup, pgdn) = ctx.input(|i| {
            (
                i.modifiers.command,
                i.key_pressed(Key::Home),
                i.key_pressed(Key::End),
                i.key_pressed(Key::PageUp),
                i.key_pressed(Key::PageDown),
            )
        });
        if ctrl && (home || end) {
            self.commit_edit(None);
            let shift = ctx.input(|i| i.modifiers.shift);
            let (r, c) = if home {
                (0u32, 0u32)
            } else {
                self.used_end()
            };
            self.sel = (r, c);
            if !shift {
                self.sel_end = (r, c);
            }
            self.ensure_visible();
            return;
        }
        if !ctrl && home {
            // Excel 的 Home：回到本行 A 列
            self.commit_edit(None);
            let r = self.sel.0;
            self.sel = (r, 0);
            self.sel_end = (r, 0);
            self.ensure_visible();
            return;
        }
        if ctrl && (pgup || pgdn) {
            self.switch_sheet_relative(if pgdn { 1 } else { -1 });
            return;
        }
        if pgup || pgdn {
            self.commit_edit(None);
            self.page_move(pgdn);
            return;
        }
        if ctrl && (ctx.input(|i| i.key_pressed(Key::ArrowUp))
            || ctx.input(|i| i.key_pressed(Key::ArrowDown))
            || ctx.input(|i| i.key_pressed(Key::ArrowLeft))
            || ctx.input(|i| i.key_pressed(Key::ArrowRight)))
        {
            let (dr, dc) = ctx.input(|i| {
                (
                    if i.key_pressed(Key::ArrowDown) { 1i64 } else if i.key_pressed(Key::ArrowUp) { -1 } else { 0 },
                    if i.key_pressed(Key::ArrowRight) { 1i64 } else if i.key_pressed(Key::ArrowLeft) { -1 } else { 0 },
                )
            });
            self.commit_edit(None);
            let (r, c) = self.jump_edge(dr, dc);
            let shift = ctx.input(|i| i.modifiers.shift);
            self.sel = (r, c);
            if !shift {
                self.sel_end = (r, c);
            }
            self.ensure_visible();
            return;
        }
        if ctx.input(|i| i.modifiers.command && i.key_pressed(Key::Num1)) {
            self.open_format_dialog();
            return;
        }
        if ctx.input(|i| i.modifiers.command && !i.modifiers.shift && i.key_pressed(Key::D)) {
            self.fill_cmd(true);
            return;
        }
        if ctx.input(|i| i.modifiers.command && !i.modifiers.shift && i.key_pressed(Key::R)) {
            self.fill_cmd(false);
            return;
        }
        if ctx.input(|i| i.modifiers.command && !i.modifiers.shift && !i.modifiers.alt && i.key_pressed(Key::E)) {
            self.ribbon_action("FlashFill", ctx);
            return;
        }
        let (mut dr, mut dc) = (0i64, 0i64);
        let (mut commit, mut start_edit, mut del_clear, mut bksp_edit, mut cse) = (false, false, false, false, false);
        ctx.input(|i| {
            if i.key_pressed(Key::ArrowDown) { dr += 1 }
            if i.key_pressed(Key::ArrowUp) { dr -= 1 }
            if i.key_pressed(Key::ArrowRight) { dc += 1 }
            if i.key_pressed(Key::ArrowLeft) { dc -= 1 }
            if i.key_pressed(Key::Enter) {
                commit = true;
                dr = if i.modifiers.shift { -1 } else { 1 };
                cse = i.modifiers.command && i.modifiers.shift;
            }
            if i.key_pressed(Key::Tab) {
                commit = true;
                dc = if i.modifiers.shift { -1 } else { 1 };
            }
            if i.key_pressed(Key::F2) { start_edit = true }
            if i.key_pressed(Key::Delete) { del_clear = true }
            if i.key_pressed(Key::Backspace) { bksp_edit = true }
        });

        if commit && cse {
            self.cse_pending = true;
        }
        if del_clear || bksp_edit {
            if let Some(i) = self.pic_sel {
                self.pic_delete(i);
            } else {
                self.clear_values();
                if bksp_edit {
                    self.begin_edit(Some(String::new()));
                    return;
                }
            }
        }
        if commit || dr != 0 || dc != 0 {
            if commit {
                // Enter/Tab：有矩形选区时在区域内循环；单格跳到下一个可见行/列。
                self.advance_active(dr as i32, dc as i32);
            } else {
                self.nav_rect = None;
                let nr = if dr > 0 {
                    self.next_visible_row(self.sel.0, true)
                } else if dr < 0 {
                    self.next_visible_row(self.sel.0, false)
                } else {
                    self.sel.0
                };
                let nc = if dc > 0 {
                    self.next_visible_col(self.sel.1, true)
                } else if dc < 0 {
                    self.next_visible_col(self.sel.1, false)
                } else {
                    self.sel.1
                };
                let extend = ctx.input(|i| i.modifiers.shift);
                let blocked = if extend {
                    // Shift+方向键也是整块扩选，中间有禁选格就不能扩
                    self.rect_sel_blocked(self.sel_end, (nr, nc))
                } else {
                    self.sel_blocked_at(nr, nc)
                };
                if blocked {
                    self.block_selection();
                } else if extend {
                    // Shift+方向：锚点留在 sel_end，只移动活动格
                    self.sel = (nr, nc);
                } else {
                    self.sel = (nr, nc);
                    self.sel_end = (nr, nc);
                    self.extra_sel.clear();
                }
                self.ensure_visible();
            }
        }
        if start_edit {
            self.begin_edit(None);
        }
        // 直接打字（含中文输入法拼音 Preedit / 候选词 Commit）零延迟开启内联编辑，
        // 并就地消费已吸收的字符事件，杜绝同一帧后续 TextEdit 重复插入或首字母丢失。
        if self.editing.is_none() {
            let (typed, has_ime_preedit) = ctx.input_mut(|i| {
                let mut acc = String::new();
                let mut preedit = false;
                i.events.retain(|e| match e {
                    egui::Event::Text(t)
                        if !t.is_empty() && !t.chars().next().unwrap().is_control() =>
                    {
                        acc.push_str(t);
                        false
                    }
                    egui::Event::Ime(egui::ImeEvent::Commit(t))
                        if !t.is_empty() && !t.chars().next().unwrap().is_control() =>
                    {
                        acc.push_str(t);
                        false
                    }
                    egui::Event::Ime(egui::ImeEvent::Preedit(t)) if !t.is_empty() => {
                        preedit = true;
                        true
                    }
                    _ => true,
                });
                (acc, preedit)
            });
            if !typed.is_empty() {
                self.begin_edit(Some(typed));
            } else if has_ime_preedit {
                self.begin_edit(Some(String::new()));
            }
        }
    }

    /// 画表格：行列标题、单元格、选区、远端光标

    /// 选区矩形列表：主选区 + Ctrl+点击追加的块
    fn sel_rects(&self) -> Vec<(u32, u32, u32, u32)> {
        let mut v: Vec<(u32, u32, u32, u32)> = self.extra_sel.clone();
        v.push(self.sel_rect());
        v
    }

    /// 规范化后的选区 (r1, c1, r2, c2)
    fn sel_rect(&self) -> (u32, u32, u32, u32) {
        if let Some((r1, c1, r2, c2)) = self.nav_rect {
            // 活动格已经离开矩形（查找/撤销/外部跳转）时，即使某个入口忘了清
            // nav_rect，也不能再把旧矩形当成当前选区。
            if self.sel.0 >= r1 && self.sel.0 <= r2 && self.sel.1 >= c1 && self.sel.1 <= c2 {
                return (r1, c1, r2, c2);
            }
        }
        let (r1, r2) = (self.sel.0.min(self.sel_end.0), self.sel.0.max(self.sel_end.0));
        let (c1, c2) = (self.sel.1.min(self.sel_end.1), self.sel.1.max(self.sel_end.1));
        (r1, c1, r2, c2)
    }

    /// 选区左上角的样式（工具栏按钮显示当前状态）
    /// 小数位 +1/−1：把当前区域的小数格式改成 n±1 位
    fn decimals(&mut self, delta: i32) {
        let cur = self.current_style();
        let mut f = if cur.format.is_empty() {
            "#,##0".to_string()
        } else {
            cur.format.clone()
        };
        let chars: Vec<char> = f.chars().collect();
        if let Some(dot) = chars.iter().position(|c| *c == '.') {
            let mut end = dot + 1;
            while end < chars.len() && (chars[end] == '0' || chars[end] == '#') {
                end += 1;
            }
            if delta > 0 {
                f.insert(end, '0');
            } else if end > dot + 1 {
                f.remove(end - 1);
            } else {
                return;
            }
        } else if delta > 0 {
            f.push_str(".0");
        } else {
            return;
        }
        self.apply_style(move |s| s.format = f.clone());
    }

    /// 自动求和：当前格上方连续数字 → =SUM(首:末)
    fn auto_sum(&mut self) {
        self.auto_func("SUM");
    }

    /// WPS 自动求和 / 平均值 / 计数：委托给 auto_func_wps（上探空则左探，单格进确认编辑态）
    fn auto_func(&mut self, func: &str) {
        self.auto_func_wps(func);
    }

    /// 只清内容，保留格式/批注（Excel「清除内容」）
fn clear_values(&mut self) {
        self.clear_rects(ClearPart::Contents);
    }

    /// 清除格式（保留内容）
    fn clear_formats(&mut self) {
        self.clear_rects(ClearPart::Formats);
    }

    /// 清除全部（内容 + 格式），一次事务、一步撤销
    fn clear_all(&mut self) {
        self.clear_rects(ClearPart::All);
    }

    /// 统一的 ClearContents/ClearFormats/ClearAll 命令：整列/整行/全表走 O(sparse) 路径避免爆内存
    fn clear_rects(&mut self, part: ClearPart) {
        let rects = self.sel_rects();
        let total_area: u64 = rects
            .iter()
            .map(|&(r1, c1, r2, c2)| (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64)
            .fold(0u64, |a, b| a.saturating_add(b));
        let is_giant_axis = total_area > 200_000
            || rects.iter().any(|&(r1, c1, r2, c2)| {
                (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 200_000
            });
        let mut keys: Vec<(u32, u32)> = Vec::new();
        let mut axis_cols: Vec<(u32, u32)> = Vec::new();
        let mut axis_rows: Vec<(u32, u32)> = Vec::new();
        if is_giant_axis {
            let sh = self.wb.sheet(self.sheet_idx);
            let mut key_set = std::collections::BTreeSet::new();
            for &(r1, c1, r2, c2) in &rects {
                if r1 == 0 && r2 >= 1_000_000 && c1 == 0 && c2 >= 16_000 {
                    axis_cols.push((0, 16_383));
                    axis_rows.push((0, 1_048_575));
                } else if r1 == 0 && r2 >= 1_000_000 {
                    axis_cols.push((c1, c2));
                } else if c1 == 0 && c2 >= 16_000 {
                    axis_rows.push((r1, r2));
                }
                if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 <= 200_000 && total_area <= 200_000 {
                    for k in sheetcore::undo::rect_keys(r1, c1, r2, c2) {
                        key_set.insert(k);
                    }
                } else {
                    if part != ClearPart::Formats {
                        for (cr, _) in sh.iter() {
                            if cr.row >= r1 && cr.row <= r2 && cr.col >= c1 && cr.col <= c2 {
                                key_set.insert((cr.row, cr.col));
                            }
                        }
                    }
                    if part != ClearPart::Contents {
                        for k in sh.styles.keys() {
                            if k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2 {
                                key_set.insert((k.row, k.col));
                            }
                        }
                    }
                }
            }
            keys.extend(key_set);
        } else {
            for (r1, c1, r2, c2) in rects.iter().copied() {
                keys.extend(sheetcore::undo::rect_keys(r1, c1, r2, c2));
            }
            keys.sort_unstable();
            keys.dedup();
        }
        let what = match part {
            ClearPart::Contents => "清除内容",
            ClearPart::Formats => "清除格式",
            ClearPart::All => "清除全部",
        };
        if !self.write_preflight(&keys, what) {
            return;
        }
        let txn = self.txn_begin(&keys);
        for &(r, c) in keys.iter() {
            if part != ClearPart::Formats && self.wb.sheet(self.sheet_idx).get(r, c).is_some() {
                self.wb.sheet_mut(self.sheet_idx).set(
                    r,
                    c,
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Empty,
                        formula: None,
                    },
                );
            }
            if part != ClearPart::Contents {
                self.wb.sheet_mut(self.sheet_idx).set_style(r, c, 0);
            }
        }
        if part != ClearPart::Contents {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            if !axis_cols.is_empty() {
                sh.col_styles.retain(|&c, _| !axis_cols.iter().any(|&(c1, c2)| c >= c1 && c <= c2));
                sh.col_styles_dirty = true;
            }
            if !axis_rows.is_empty() {
                sh.row_styles.retain(|&r, _| !axis_rows.iter().any(|&(r1, r2)| r >= r1 && r <= r2));
                sh.row_styles_dirty = true;
            }
        }
        self.txn_end(what, txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        // 内容与格式是两条独立通道：清除全部必须同时发，不能只发内容
        if part != ClearPart::Contents {
            if let Some(net) = self.net.as_ref() {
                let items: Vec<(u32, u32, sheetcore::style::CellStyle)> = keys
                    .iter()
                    .map(|(r, c)| (*r, *c, sheetcore::style::CellStyle::default()))
                    .collect();
                net.broadcast_style(self.sheet_idx, items);
            }
        }
        if part != ClearPart::Formats {
            let keys3: Vec<(usize, u32, u32)> =
                keys.iter().map(|(r, c)| (self.sheet_idx, *r, *c)).collect();
            self.recalc_and_broadcast(&keys3);
        }
        self.status = format!("已{what}");
    }

    /// 单元格样式库的 5 个预设（真写入 CellStyle）
    fn apply_style_preset(&mut self, kind: &str) {
        match kind {
            "normal" => self.apply_style(|s| {
                let f = s.font.clone();
                *s = sheetcore::style::CellStyle {
                    font: f,
                    size: 11.0,
                    color: [0, 0, 0],
                    ..Default::default()
                };
            }),
            "title" => self.apply_style(|s| {
                s.bold = true;
                s.italic = false;
                s.size = 14.0;
                s.color = [31, 78, 121];
                s.fill = None;
            }),
            "heading" => self.apply_style(|s| {
                s.bold = true;
                s.size = 11.0;
                s.color = [31, 56, 100];
                s.fill = Some([217, 226, 243]);
            }),
            "good" => self.apply_style(|s| {
                s.bold = false;
                s.color = [0, 97, 0];
                s.fill = Some([198, 239, 206]);
            }),
            "bad" => self.apply_style(|s| {
                s.bold = false;
                s.color = [156, 0, 6];
                s.fill = Some([255, 199, 206]);
            }),
            _ => {}
        }
    }

    /// 填充：把选区第一行复制到其余行（值、公式、样式）
    fn fill_down(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if r2 <= r1 {
            self.status = "先选两行以上再填充".into();
            return;
        }
        if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 200_000 {
            self.status = "填充范围过大（超过 20 万格），请缩小选区".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        let txn = self.txn_begin(&keys);
        for cc in c1..=c2 {
            let src = self.wb.sheet(self.sheet_idx).get(r1, cc).cloned();
            let style_id = self.wb.sheet(self.sheet_idx).style_of(r1, cc);
            for rr in r1 + 1..=r2 {
                match &src {
                    Some(cell) => {
                        self.wb.sheet_mut(self.sheet_idx).set(rr, cc, cell.clone());
                    }
                    None => {
                        self.wb.sheet_mut(self.sheet_idx).remove(rr, cc);
                    }
                }
                self.wb.sheet_mut(self.sheet_idx).set_style(rr, cc, style_id);
            }
        }
        self.txn_end("填充", txn);
        let si = self.sheet_idx;
        let filled: Vec<(usize, u32, u32)> = ((r1 + 1)..=r2)
            .flat_map(|rr| (c1..=c2).map(move |cc| (si, rr, cc)))
            .collect();
        self.recalc_and_broadcast(&filled);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = "已向下填充".into();
    }

    /// 表格汇总行：加一行 SUBTOTAL(109,…)，再点一次去掉
    fn toggle_totals_row(&mut self, table_name: &str) {
        if self.edit_blocked() {
            return;
        }
        let Some(t) = self
            .wb
            .sheet(self.sheet_idx)
            .tables
            .iter()
            .find(|t| t.name == table_name)
            .cloned()
        else {
            return;
        };
        let (r1, c1, r2, c2) = t.range;
        if !t.totals_row && r2 >= 1_048_575 {
            self.status = "表格已触及工作表最后一行，无法追加汇总行".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r2, c1, (r2 + 1).min(1_048_575), c2);
        let txn = self.txn_begin(&keys);
        if t.totals_row {
            // 去掉：清掉汇总行，范围收回
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                for c in c1..=c2 {
                    sh.remove(r2, c);
                }
                if let Some(tb) = sh.tables.iter_mut().find(|x| x.name == table_name) {
                    tb.totals_row = false;
                    tb.range.2 = r2.saturating_sub(1);
                }
                sh.tables_dirty = true;
                if let Some(f) = sh.filter.as_mut() {
                    if f.range.0 == r1 && f.range.1 == c1 {
                        f.range.2 = r2.saturating_sub(1);
                    }
                }
            }
            self.status = "已去掉汇总行".into();
        } else {
            let row = r2 + 1;
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.set(
                    row,
                    c1,
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Text("总计".into()),
                        formula: None,
                    },
                );
                for c in (c1 + 1)..=c2 {
                    let a = sheetcore::model::cell_name(r1 + 1, c);
                    let b = sheetcore::model::cell_name(r2, c);
                    sh.set(
                        row,
                        c,
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Empty,
                            formula: Some(format!("SUBTOTAL(109,{a}:{b})").into()),
                        },
                    );
                }
                if let Some(tb) = sh.tables.iter_mut().find(|x| x.name == table_name) {
                    tb.totals_row = true;
                    tb.range.2 = row;
                }
                sh.tables_dirty = true;
                if let Some(f) = sh.filter.as_mut() {
                    if f.range.0 == r1 && f.range.1 == c1 {
                        f.range.2 = r2;
                    }
                }
            }
            self.status = "已加汇总行（SUBTOTAL 109，忽略筛选掉的行）".into();
        }
        self.recalc_all_and_deps_adaptive();
        self.txn_end("表格汇总行", txn);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
    }

    /// 拖动选区移动（dr/dc 可正可负）：值、样式、批注、富文本、超链接一起搬
    fn move_selection_by(&mut self, dr: i64, dc: i64) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 200_000 {
            self.status = "移动选区过大（超过 20 万格），操作已取消".into();
            return;
        }
        let nr1 = (r1 as i64 + dr).max(0) as u32;
        let nc1 = (c1 as i64 + dc).max(0) as u32;
        let nr2 = nr1 + (r2 - r1);
        let nc2 = nc1 + (c2 - c1);
        if (nr1, nc1) == (r1, c1) {
            return;
        }
        let area = (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64;
        if area > 200_000 {
            self.status = "移动范围过大（单次最多支持 20 万个单元格）".into();
            return;
        }
        let mut keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        keys.extend(sheetcore::undo::rect_keys(nr1, nc1, nr2, nc2));
        keys.sort_unstable();
        keys.dedup();
        if !self.write_preflight(&keys, "移动单元格") {
            return;
        }
        let txn = self.txn_begin(&keys);
        let mut cells: Vec<(u32, u32, sheetcore::model::Cell, Option<u16>)> = Vec::new();
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, c).cloned() {
                    let st = self.wb.sheet(self.sheet_idx).styles.get(&sheetcore::model::CellRef::new(r, c)).copied();
                    cells.push((r - r1, c - c1, cell, st));
                }
            }
        }
        let notes: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .iter()
            .filter(|(k, _)| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2)
            .map(|(k, v)| ((k.row - r1, k.col - c1), v.clone()))
            .collect();
        let rich: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .rich
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        let links: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .hyperlinks
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    sh.remove(r, c);
                    sh.styles.remove(&sheetcore::model::CellRef::new(r, c));
                }
            }
            // 先清掉源区域上的附属数据，再把快照写到目标（源/目标重叠也不会丢）
            let mut notes_changed = false;
            for r in r1..=r2 {
                for c in c1..=c2 {
                    if sh.notes.remove(&sheetcore::model::CellRef::new(r, c)).is_some() {
                        notes_changed = true;
                    }
                    if sh.rich.remove(&(r, c)).is_some() {
                        sh.rich_dirty = true;
                    }
                    if sh.hyperlinks.remove(&(r, c)).is_some() {
                        sh.hyperlinks_dirty = true;
                    }
                }
            }
            for ((r, c), mut n) in notes {
                n.r = nr1 + r;
                n.c = nc1 + c;
                sh.notes.insert(sheetcore::model::CellRef::new(nr1 + r, nc1 + c), n);
                notes_changed = true;
            }
            if notes_changed {
                sh.notes_dirty = true;
            }
            for ((r, c), v) in rich {
                sh.rich.insert((nr1 + r, nc1 + c), v);
                sh.rich_dirty = true;
            }
            for ((r, c), v) in links {
                sh.hyperlinks.insert((nr1 + r, nc1 + c), v);
                sh.hyperlinks_dirty = true;
            }
            for (dr0, dc0, cell, st) in cells {
                let (r, c) = (nr1 + dr0, nc1 + dc0);
                let mut cell = cell;
                if let Some(f) = &cell.formula {
                    if dr >= 0 && dc >= 0 {
                        cell.formula = Some(
                            sheetcore::cf::shift_formula(f, dr as u32, dc as u32).into(),
                        );
                    }
                }
                sh.set(r, c, cell);
                if let Some(id) = st {
                    sh.set_style(r, c, id);
                }
            }
        }
        self.txn_end("移动单元格", txn);
        self.sel = (nr1, nc1);
        self.sel_end = (nr2, nc2);
        let si = self.sheet_idx;
        let mut moved_keys: Vec<(usize, u32, u32)> = (r1..=r2)
            .flat_map(|r| (c1..=c2).map(move |c| (si, r, c)))
            .collect();
        for r in nr1..=nr2 {
            for c in nc1..=nc2 {
                let k = (si, r, c);
                if !moved_keys.contains(&k) {
                    moved_keys.push(k);
                }
            }
        }
        self.recalc_and_broadcast(&moved_keys);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = format!("已移动到 {}", sheetcore::model::cell_name(nr1, nc1));
    }

    /// Shift+拖动：把选区「插」到目标位置（整行下移 / 整列右移），Excel 的 shift 拖放
    fn shift_insert_by(&mut self, dr: i64, dc: i64) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 200_000 {
            self.status = "移动选区过大（超过 20 万格），操作已取消".into();
            return;
        }
        let nr1 = (r1 as i64 + dr).max(0) as u32;
        let nc1 = (c1 as i64 + dc).max(0) as u32;
        if (nr1, nc1) == (r1, c1) {
            return;
        }
        // 目标落在源块里就没意义
        if nr1 >= r1 && nr1 <= r2 && nc1 >= c1 && nc1 <= c2 {
            return;
        }
        let vertical = dr.abs() >= dc.abs();
        let mut gate = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        for (k, _) in self.wb.sheet(self.sheet_idx).iter() {
            if (vertical && k.row >= nr1) || (!vertical && k.col >= nc1) {
                gate.push((k.row, k.col));
            }
        }
        for k in self.wb.sheet(self.sheet_idx).styles.keys() {
            if (vertical && k.row >= nr1) || (!vertical && k.col >= nc1) {
                gate.push((k.row, k.col));
            }
        }
        // 空目标格没有 Cell/Style 可枚举，但别人可能正锁着它；租约表本身是稀疏的
        for ((si, r, c), _) in self.locks.iter() {
            if si == self.sheet_idx && ((vertical && r >= nr1) || (!vertical && c >= nc1)) {
                gate.push((r, c));
            }
        }
        gate.sort_unstable();
        gate.dedup();
        if !self.write_preflight(&gate, "插入并移动") {
            return;
        }
        // 1) 快照
        let mut cells: Vec<(u32, u32, sheetcore::model::Cell, Option<u16>)> = Vec::new();
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, c).cloned() {
                    let st = self
                        .wb
                        .sheet(self.sheet_idx)
                        .styles
                        .get(&sheetcore::model::CellRef::new(r, c))
                        .copied();
                    cells.push((r - r1, c - c1, cell, st));
                }
            }
        }
        // 2) 清源
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    sh.remove(r, c);
                    sh.styles.remove(&sheetcore::model::CellRef::new(r, c));
                }
            }
        }
        // 3) 在目标处插入空行/空列（走结构操作，合并/格式/验证会跟着挪）
        let idx = self.sheet_idx;
        let op = if vertical {
            sheetcore::structural::Structural::InsertRows {
                at: nr1,
                n: r2 - r1 + 1,
            }
        } else {
            sheetcore::structural::Structural::InsertCols {
                at: nc1,
                n: c2 - c1 + 1,
            }
        };
        let snap = if self.wb.sheet(idx).len() <= 200_000 {
            Some(sheetcore::undo::snapshot_structure(&self.wb, idx, &op))
        } else {
            None
        };
        sheetcore::structural::apply_structural_wb(&mut self.wb, idx, &op);
        // 4) 写回目标
        {
            let sh = self.wb.sheet_mut(idx);
            for (dr0, dc0, mut cell, st) in cells {
                if let Some(f) = cell.formula.clone() {
                    if dr >= 0 && dc >= 0 {
                        cell.formula =
                            Some(sheetcore::cf::shift_formula(&f, dr as u32, dc as u32).into());
                    }
                }
                let (r, c) = if vertical {
                    (nr1 + dr0, c1 + dc0)
                } else {
                    (r1 + dr0, nc1 + dc0)
                };
                sh.set(r, c, cell);
                if let Some(id) = st {
                    sh.set_style(r, c, id);
                }
            }
        }
        if let Some(before) = snap {
            let after = before.capture_after(&self.wb);
            let label = if vertical { "插入行并移动" } else { "插入列并移动" };
            self.undo
                .push_structure(label.to_string(), before, after, (idx, self.sel.0, self.sel.1));
        }
        self.recalc_all_and_deps_adaptive();
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.sel = (nr1, nc1);
        self.sel_end = (nr1 + (r2 - r1), nc1 + (c2 - c1));
        self.status = format!(
            "已插入到 {}（{}）",
            sheetcore::model::cell_name(nr1, nc1),
            if vertical { "整行下移" } else { "整列右移" }
        );
    }

    /// Ctrl+拖动选区边框：复制到新位置（源保留）
    fn copy_selection_by(&mut self, dr: i64, dc: i64) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 200_000 {
            self.status = "移动选区过大（超过 20 万格），操作已取消".into();
            return;
        }
        let nr1 = (r1 as i64 + dr).max(0) as u32;
        let nc1 = (c1 as i64 + dc).max(0) as u32;
        let nr2 = nr1 + (r2 - r1);
        let nc2 = nc1 + (c2 - c1);
        if (nr1, nc1) == (r1, c1) {
            return;
        }
        let area = (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64;
        if area > 200_000 {
            self.status = "复制范围过大（单次最多支持 20 万个单元格）".into();
            return;
        }
        let dst_keys = sheetcore::undo::rect_keys(nr1, nc1, nr2, nc2);
        if !self.write_preflight(&dst_keys, "复制单元格") {
            return;
        }
        let mut keys = dst_keys.clone();
        keys.extend(sheetcore::undo::rect_keys(r1, c1, r2, c2));
        let txn = self.txn_begin(&keys);
        // 先把源区域的快照取出来（不改源）
        let mut cells: Vec<(u32, u32, sheetcore::model::Cell, Option<u16>)> = Vec::new();
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, c).cloned() {
                    let st = self
                        .wb
                        .sheet(self.sheet_idx)
                        .styles
                        .get(&sheetcore::model::CellRef::new(r, c))
                        .copied();
                    cells.push((r - r1, c - c1, cell, st));
                }
            }
        }
        let notes: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .iter()
            .filter(|(k, _)| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2)
            .map(|(k, v)| ((k.row - r1, k.col - c1), v.clone()))
            .collect();
        let rich: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .rich
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        let links: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .hyperlinks
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            // 目标区域先清空（Excel 复制粘贴也是覆盖）
            let mut notes_changed = false;
            for r in nr1..=nr2 {
                for c in nc1..=nc2 {
                    sh.remove(r, c);
                    sh.styles.remove(&sheetcore::model::CellRef::new(r, c));
                    if sh.notes.remove(&sheetcore::model::CellRef::new(r, c)).is_some() {
                        notes_changed = true;
                    }
                    if sh.rich.remove(&(r, c)).is_some() {
                        sh.rich_dirty = true;
                    }
                    if sh.hyperlinks.remove(&(r, c)).is_some() {
                        sh.hyperlinks_dirty = true;
                    }
                }
            }
            for ((r, c), mut n) in notes {
                n.r = nr1 + r;
                n.c = nc1 + c;
                sh.notes.insert(sheetcore::model::CellRef::new(nr1 + r, nc1 + c), n);
                notes_changed = true;
            }
            if notes_changed {
                sh.notes_dirty = true;
            }
            for ((r, c), v) in rich {
                sh.rich.insert((nr1 + r, nc1 + c), v);
                sh.rich_dirty = true;
            }
            for ((r, c), v) in links {
                sh.hyperlinks.insert((nr1 + r, nc1 + c), v);
                sh.hyperlinks_dirty = true;
            }
            for (dr0, dc0, cell, st) in cells {
                let (r, c) = (nr1 + dr0, nc1 + dc0);
                let mut cell = cell;
                if let Some(f) = cell.formula.clone() {
                    // 相对引用按实际位移平移；往左上时 shift_formula 只接受无符号，保持原样更安全
                    if dr >= 0 && dc >= 0 {
                        cell.formula =
                            Some(sheetcore::cf::shift_formula(&f, dr as u32, dc as u32).into());
                    }
                }
                sh.set(r, c, cell);
                if let Some(id) = st {
                    sh.set_style(r, c, id);
                }
            }
        }
        self.txn_end("复制单元格", txn);
        self.sel = (nr1, nc1);
        self.sel_end = (nr2, nc2);
        let si = self.sheet_idx;
        let copied_keys: Vec<(usize, u32, u32)> = dst_keys
            .into_iter()
            .map(|(r, c)| (si, r, c))
            .collect();
        self.recalc_and_broadcast(&copied_keys);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = format!("已复制到 {}", sheetcore::model::cell_name(nr1, nc1));
    }

    /// 插入/删除单元格（down_or_up: true=插入；horizontal: true=右移/左移）
    fn shift_cells(&mut self, insert: bool, horizontal: bool) {
        if self.edit_blocked() {
            return;
        }
        self.commit_edit(None);
        let rect = self.sel_rect();
        // 整行/整列选择时直接走稀疏结构变更，避免展开千万格坐标卡死
        if rect.1 == 0 && rect.3 >= 16_383 {
            let n = rect.2 - rect.0 + 1;
            self.structural(if insert {
                sheetcore::structural::Structural::InsertRows { at: rect.0, n }
            } else {
                sheetcore::structural::Structural::DeleteRows { at: rect.0, n }
            });
            return;
        }
        if rect.0 == 0 && rect.2 >= 1_048_575 {
            let n = rect.3 - rect.1 + 1;
            self.structural(if insert {
                sheetcore::structural::Structural::InsertCols { at: rect.1, n }
            } else {
                sheetcore::structural::Structural::DeleteCols { at: rect.1, n }
            });
            return;
        }
        let used = self.wb.sheet(self.sheet_idx).used_bounds();
        let (kr1, kc1, kr2, kc2) = match used {
            Some((_, _, r2, c2)) => (rect.0, rect.1, r2.max(rect.2), c2.max(rect.3)),
            None => rect,
        };
        let area = (kr2 - kr1 + 1) as u64 * (kc2 - kc1 + 1) as u64;
        if area > 200_000 {
            self.status = "插入/删除单元格影响范围过大，请改用整行或整列插入/删除".into();
            return;
        }
        let mut keys = sheetcore::undo::rect_keys(kr1, kc1, kr2, kc2);
        // 公式引用可能被改到选区外，撤销要能一起还原
        for (cref, cell) in self.wb.sheet(self.sheet_idx).iter() {
            if cell.formula.is_some() {
                keys.push((cref.row, cref.col));
            }
        }
        if !self.write_preflight(&keys, if insert { "插入单元格" } else { "删除单元格" }) {
            return;
        }
        let txn = self.txn_begin(&keys);
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let shift = if horizontal {
                sheetcore::cells::Shift::Horizontal
            } else {
                sheetcore::cells::Shift::Vertical
            };
            if insert {
                sheetcore::cells::insert(sh, rect, shift, 1);
            } else {
                sheetcore::cells::delete(sh, rect, shift, 1);
            }
        }
        sheetcore::structural::apply_cell_shift_wb(&mut self.wb, self.sheet_idx, rect, horizontal, insert);
        self.txn_end(if insert { "插入单元格" } else { "删除单元格" }, txn);
        self.recalc_all_and_deps_adaptive();
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = if insert {
            if horizontal { "已插入单元格（右侧右移）" } else { "已插入单元格（下方下移）" }.into()
        } else if horizontal {
            "已删除单元格（左侧左移）".into()
        } else {
            "已删除单元格（上方上移）".into()
        };
    }

    /// 只给选区外沿加边框（style: 1=细线 2=粗线，默认纯黑）
    fn border_outer(&mut self, style: u8) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let color = self.last_border_color;
        self.apply_style_xy(move |s, r, c| {
            let b = sheetcore::style::Border { style, color };
            if r == r1 { s.border[sheetcore::style::BorderSide::Top.idx()] = b; }
            if c == c2 { s.border[sheetcore::style::BorderSide::Right.idx()] = b; }
            if r == r2 { s.border[sheetcore::style::BorderSide::Bottom.idx()] = b; }
            if c == c1 { s.border[sheetcore::style::BorderSide::Left.idx()] = b; }
        });
    }

    /// 算一遍简转繁的差异（不动数据），供预览对话框显示
    fn zh_preview_scan(&mut self) {
        let v = self.zh_preview_variant;
        let mut rows = Vec::new();
        let scan_sheet = |si: usize,
                          r1: u32,
                          c1: u32,
                          r2: u32,
                          c2: u32,
                          out: &mut Vec<(usize, u32, u32, String, String)>| {
            let sh = self.wb.sheet(si);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    let Some(cell) = sh.get(r, c) else { continue };
                    let sheetcore::model::Value::Text(t) = &cell.value else {
                        continue;
                    };
                    let new = sheetcore::zhconv::to_traditional_with(t, v);
                    if new.as_str() != t.as_ref() {
                        out.push((si, r, c, t.to_string(), new));
                    }
                }
            }
        };
        if self.zh_preview_all_sheets {
            let only = self.zh_preview_sheet;
            for si in 0..self.wb.sheets.len() {
                if let Some(only) = only {
                    if si != only {
                        continue;
                    }
                }
                let bounds = self.wb.sheet(si).used_bounds();
                if let Some((r1, c1, r2, c2)) = bounds {
                    if (r2 - r1) as u64 * (c2 - c1) as u64 <= 400_000 {
                        scan_sheet(si, r1, c1, r2, c2, &mut rows);
                    }
                }
                if rows.len() > 5000 {
                    break;
                }
            }
        } else {
            let (r1, c1, r2, c2) = self.sel_rect();
            if (r2 - r1) as u64 * (c2 - c1) as u64 <= 200_000 {
                scan_sheet(self.sheet_idx, r1, c1, r2, c2, &mut rows);
            }
        }
        self.zh_preview = rows;
    }

    /// 按预览列表逐条写入（跨表也用这个，一个撤销事务）
    fn zh_apply_preview(&mut self) {
        if self.edit_blocked() || self.zh_preview.is_empty() {
            return;
        }
        let v = self.zh_preview_variant;
        let items = self.zh_preview.clone();
        let cur = self.sheet_idx;
        let txn = self.txn_begin(&[(0, 0)]);
        let mut n = 0usize;
        let mut touched: Vec<usize> = Vec::new();
        for (si, r, c, old, _new) in items {
            let sh = self.wb.sheet_mut(si);
            let Some(cell) = sh.get(r, c).cloned() else {
                continue;
            };
            let sheetcore::model::Value::Text(t) = &cell.value else {
                continue;
            };
            if t.as_ref() != old.as_str() {
                continue;
            }
            let new = sheetcore::zhconv::to_traditional_with(t, v);
            let mut cell = cell;
            cell.value = sheetcore::model::Value::Text(new.into());
            sh.set(r, c, cell);
            n += 1;
            if !touched.contains(&si) {
                touched.push(si);
            }
        }
        self.sheet_idx = cur;
        self.txn_end("简转繁", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("简转繁：{n} 个单元格（{} 张表）", touched.len());
        self.zh_preview_dlg = false;
    }

    fn zh_preview_window(&mut self, ctx: &egui::Context) {
        if !self.zh_preview_dlg {
            return;
        }
        let mut open = true;
        let mut apply = false;
        let mut variant_changed = false;
        ui_kit::window(ctx, "简转繁预览", 660.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    if ui
                        .checkbox(&mut self.zh_preview_all_sheets, "所有工作表")
                        .changed()
                    {
                        self.zh_preview_sheet = None;
                        variant_changed = true;
                    }
                    if self.zh_preview_all_sheets {
                        let mut label = match self.zh_preview_sheet {
                            Some(i) => self.wb.sheet(i).name.clone(),
                            None => "全部表".to_string(),
                        };
                        egui::ComboBox::from_id_salt("zh_prev_sheet")
                            .selected_text(label.clone())
                            .width(96.0)
                            .show_ui(ui, |ui| {
                                if ui
                                    .selectable_value(&mut self.zh_preview_sheet, None, "全部表")
                                    .clicked()
                                {
                                    variant_changed = true;
                                    label = "全部表".into();
                                }
                                for i in 0..self.wb.sheets.len() {
                                    let name = self.wb.sheet(i).name.clone();
                                    if ui
                                        .selectable_value(
                                            &mut self.zh_preview_sheet,
                                            Some(i),
                                            &name,
                                        )
                                        .clicked()
                                    {
                                        variant_changed = true;
                                        label = name.clone();
                                    }
                                }
                            });
                    }
                    ui.separator();
                    ui.label("目标:");
                    variant_changed |= ui
                        .radio_value(
                            &mut self.zh_preview_variant,
                            sheetcore::zhconv::Variant::Generic,
                            "通用繁体",
                        )
                        .changed();
                    variant_changed |= ui
                        .radio_value(
                            &mut self.zh_preview_variant,
                            sheetcore::zhconv::Variant::Taiwan,
                            "台湾正体",
                        )
                        .changed();
                    variant_changed |= ui
                        .radio_value(
                            &mut self.zh_preview_variant,
                            sheetcore::zhconv::Variant::HongKong,
                            "香港繁体",
                        )
                        .changed();
                });
                ui.add_space(3.0);
                ui.label(
                    egui::RichText::new(format!(
                        "{} {} 个单元格会被改动（只列有差异的）",
                        if self.zh_preview_all_sheets {
                            "整簿内"
                        } else {
                            "选区内"
                        },
                        self.zh_preview.len()
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(2.0);
                egui::ScrollArea::vertical().max_height(330.0).show(ui, |ui| {
                    if self.zh_preview.is_empty() {
                        ui.label(egui::RichText::new("选区里没有需要转换的内容。").size(12.0));
                    }
                    for (si, r, c, old, new) in self.zh_preview.clone() {
                        ui.horizontal(|ui| {
                            let addr = if self.zh_preview_all_sheets {
                                let name = self.wb.sheet(si).name.clone();
                                format!("{name}!{}", cell_name(r, c))
                            } else {
                                cell_name(r, c)
                            };
                            ui.add_sized(
                                [110.0, 20.0],
                                egui::Label::new(
                                    egui::RichText::new(addr).size(11.5).monospace(),
                                )
                                .truncate(),
                            );
                            ui.add_sized(
                                [220.0, 20.0],
                                egui::Label::new(
                                    egui::RichText::new(old).size(11.5).color(ui_kit::TEXT_WEAK),
                                )
                                .truncate(),
                            );
                            ui.label(egui::RichText::new("→").size(11.5));
                            ui.add_sized(
                                [220.0, 20.0],
                                egui::Label::new(egui::RichText::new(new).size(11.5)).truncate(),
                            );
                        });
                    }
                });
                ui_kit::footer(ui, |ui| {
                    if ui
                        .add_enabled(
                            !self.zh_preview.is_empty(),
                            egui::Button::new("应用转换"),
                        )
                        .clicked()
                    {
                        apply = true;
                    }
                    if ui_kit::primary_button(ui, "取消").clicked() {
                        self.zh_preview_dlg = false;
                    }
                });
            });
        if variant_changed {
            let v = ui_prefs::variant_to_u8(self.zh_preview_variant);
            if self.prefs.zh_variant != v {
                self.prefs.zh_variant = v;
                self.prefs.save();
            }
            self.zh_preview_scan();
        }
        if apply {
            self.zh_apply_preview();
        }
        if !open {
            self.zh_preview_dlg = false;
        }
    }

    /// 只修指定的几格（双击列表行时用）
    fn proof_fix_cells(&mut self, cells: Vec<(u32, u32)>) {
        if self.edit_blocked() || cells.is_empty() {
            return;
        }
        let txn = self.txn_begin(&cells);
        let mut n = 0usize;
        for (r, c) in &cells {
            let sh = self.wb.sheet(self.sheet_idx);
            let Some(cell) = sh.get(*r, *c) else { continue };
            let sheetcore::model::Value::Text(t) = &cell.value else {
                continue;
            };
            let fixed = sheetcore::proof::fix_text(t, &self.proof_rules);
            if fixed.as_str() == t.as_ref() {
                continue;
            }
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
            cell.value = sheetcore::model::Value::Text(fixed.into());
            sh.set(*r, *c, cell);
            n += 1;
        }
        self.txn_end("校对修正", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.proof_rescan();
        self.status = format!("校对修正：{n} 个单元格");
    }

    /// 按当前规则修正：only_sel=true 只修当前选中的那一格
    fn proof_apply_fix(&mut self, only_sel: bool) {
        if self.edit_blocked() {
            return;
        }
        let mut targets: Vec<(u32, u32)> = if only_sel {
            let (r, c) = self.sel;
            self.proof_list
                .iter()
                .filter(|i| i.row == r && i.col == c)
                .map(|i| (i.row, i.col))
                .collect()
        } else {
            self.proof_list.iter().map(|i| (i.row, i.col)).collect()
        };
        targets.sort();
        targets.dedup();
        if targets.is_empty() {
            self.status = "没有可修正的单元格".into();
            return;
        }
        let txn = self.txn_begin(&targets);
        let mut n = 0usize;
        for (r, c) in &targets {
            let sh = self.wb.sheet(self.sheet_idx);
            let Some(cell) = sh.get(*r, *c) else { continue };
            let sheetcore::model::Value::Text(t) = &cell.value else {
                continue;
            };
            let fixed = sheetcore::proof::fix_text(t, &self.proof_rules);
            if fixed.as_str() == t.as_ref() {
                continue;
            }
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
            cell.value = sheetcore::model::Value::Text(fixed.into());
            sh.set(*r, *c, cell);
            n += 1;
        }
        self.txn_end("校对修正", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.proof_rescan();
        self.status = format!("校对修正：{n} 个单元格");
    }

    /// 收/展到第 k 级（Excel 左上角 1/2/3 按钮的语义）：级别 > k 的藏起来，≤ k 的露出来
    fn set_outline_level(&mut self, is_rows: bool, k: u8) {
        if self.edit_blocked() {
            return;
        }
        let (levels, n_hidden) = {
            let sh = self.wb.sheet(self.sheet_idx);
            let map = if is_rows {
                sh.row_levels.clone()
            } else {
                sh.col_levels.clone()
            };
            let mut hidden: Vec<u32> = Vec::new();
            for (idx, lv) in map.iter() {
                if *lv > k {
                    hidden.push(*idx);
                }
            }
            (map, hidden)
        };
        if levels.is_empty() {
            return;
        }
        let mut txn = Vec::new();
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let hid = if is_rows {
                &mut sh.hidden_rows_user
            } else {
                &mut sh.hidden_cols
            };
            for idx in levels.keys() {
                hid.remove(idx);
            }
            for idx in &n_hidden {
                hid.insert(*idx);
                txn.push(if is_rows {
                    (*idx, None)
                } else {
                    (0, Some(*idx))
                });
            }
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        for _ in txn {}
        self.status = format!(
            "{}分级显示：显示到第 {k} 级（隐藏 {} {}）",
            if is_rows { "行" } else { "列" },
            n_hidden.len(),
            if is_rows { "行" } else { "列" }
        );
    }

    /// 分级显示设置：明细位置（上/下、左/右）+ 是否显示分级符号
    fn outline_settings_window(&mut self, ctx: &egui::Context) {
        if !self.outline_set_dlg {
            return;
        }
        let mut open = true;
        let mut changed = false;
        let (mut below, mut right, mut symbols) = {
            let sh = self.wb.sheet(self.sheet_idx);
            (
                sh.outline_summary_below,
                sh.outline_summary_right,
                sh.outline_symbols,
            )
        };
        ui_kit::window(ctx, "设置分级显示", 420.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(egui::RichText::new("明细数据的表示方式").font(ui_kit::bold(ui_kit::T_BODY)));
                changed |= ui.radio_value(&mut below, true, "明细数据在下方").changed();
                changed |= ui.radio_value(&mut below, false, "明细数据在上方").changed();
                ui.add_space(4.0);
                changed |= ui.radio_value(&mut right, true, "明细数据在右侧").changed();
                changed |= ui.radio_value(&mut right, false, "明细数据在左侧").changed();
                ui.add_space(6.0);
                changed |= ui.checkbox(&mut symbols, "显示分级符号（+ / -）").changed();
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        self.outline_set_dlg = false;
                    }
                });
            });
        if changed {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.outline_summary_below = below;
                sh.outline_summary_right = right;
                sh.outline_symbols = symbols;
                sh.outline_pr_dirty = true;
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = format!(
                "分级显示：明细{}方 / 明细{}侧 / 符号{}",
                if below { "下" } else { "上" },
                if right { "右" } else { "左" },
                if symbols { "显示" } else { "隐藏" }
            );
        }
        if !open {
            self.outline_set_dlg = false;
        }
    }

    /// 按当前范围重扫：整表或选区
    fn proof_rescan(&mut self) {
        let all = sheetcore::proof::scan(self.wb.sheet(self.sheet_idx), &self.proof_rules);
        if self.proof_only_sel {
            let (r1, c1, r2, c2) = self.sel_rect();
            self.proof_list = all
                .into_iter()
                .filter(|i| i.row >= r1 && i.row <= r2 && i.col >= c1 && i.col <= c2)
                .collect();
        } else {
            self.proof_list = all;
        }
    }

    fn open_proof(&mut self) {
        self.proof_rescan();
        self.proof_dlg = true;
        self.status = if self.proof_list.is_empty() {
            "没有发现排版问题".into()
        } else {
            format!("发现 {} 处排版问题", self.proof_list.len())
        };
    }

    fn proof_window(&mut self, ctx: &egui::Context) {
        if !self.proof_dlg {
            return;
        }
        let mut open = true;
        let mut jump: Option<(u32, u32)> = None;
        let mut changed = false;
        let mut fix_all = false;
        let mut fix_one = false;
        let mut fix_cells: Vec<(u32, u32)> = Vec::new();
        ui_kit::window(ctx, "拼写检查", 600.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    changed |= ui
                        .checkbox(&mut self.proof_only_sel, "只查选区")
                        .on_hover_text("不勾就查整张表")
                        .changed();
                    if ui
                        .checkbox(&mut self.prefs.proof_group, "按类型分组")
                        .changed()
                    {
                        self.prefs.save();
                        changed = true;
                    }
                    ui.separator();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.double_space, "多个空格")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.edge_space, "首尾空格")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.full_width, "全角字母数字")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.repeat_punct, "重复标点")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.half_punct, "中文里的半角标点")
                        .changed();
                });
                ui.add_space(4.0);
                ui.label(
                    egui::RichText::new(format!(
                        "当前表共 {} 处（点一行跳到那个单元格）",
                        self.proof_list.len()
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(2.0);
                egui::ScrollArea::vertical().max_height(320.0).show(ui, |ui| {
                    if self.proof_list.is_empty() {
                        ui.label(egui::RichText::new("没有发现排版问题。").size(12.0));
                    }
                    // 按类型分组时先出一行小标题；顺序固定，方便对照
                    let group_mode = self.prefs.proof_group;
                    let mut items: Vec<sheetcore::proof::ProofIssue> = self.proof_list.clone();
                    if group_mode {
                        let order = |k: sheetcore::proof::ProofKind| -> u8 {
                            use sheetcore::proof::ProofKind::*;
                            match k {
                                EdgeSpace => 0,
                                DoubleSpace => 1,
                                FullWidth => 2,
                                RepeatPunct => 3,
                                HalfPunct => 4,
                            }
                        };
                        items.sort_by_key(|i| (order(i.kind), i.row, i.col));
                    }
                    let mut last_kind: Option<sheetcore::proof::ProofKind> = None;
                    for it in items {
                        if group_mode && last_kind != Some(it.kind) {
                            let n = self
                                .proof_list
                                .iter()
                                .filter(|x| x.kind == it.kind)
                                .count();
                            last_kind = Some(it.kind);
                            ui.add_space(2.0);
                            ui.label(
                                egui::RichText::new(format!("{}（{n}）", it.kind.detail()))
                                    .size(11.0)
                                    .strong()
                                    .color(ui_kit::ACCENT),
                            );
                        }
                        let row_resp = ui.horizontal(|ui| {
                            if ui
                                .add_sized(
                                    [64.0, 20.0],
                                    egui::Button::new(
                                        egui::RichText::new(cell_name(it.row, it.col))
                                            .size(11.5)
                                            .monospace(),
                                    )
                                    .frame(false),
                                )
                                .on_hover_text("双击就地修好这一格")
                                .clicked()
                            {
                                jump = Some((it.row, it.col));
                            }
                            ui.add_sized(
                                [150.0, 20.0],
                                egui::Label::new(egui::RichText::new(&it.text).size(11.5))
                                    .truncate(),
                            );
                            ui.label(
                                egui::RichText::new(it.kind.detail())
                                    .size(11.0)
                                    .color(ui_kit::TEXT_WEAK),
                            );
                        });
                        let resp = row_resp
                            .response
                            .interact(egui::Sense::click())
                            .on_hover_text("双击：跳过去并修好这一格");
                        if std::env::var("SC_PROOF_RECT").is_ok() {
                            let r = resp.rect;
                            eprintln!(
                                "[rect] {} center=({:.0},{:.0}) ppp={:.2} screen={:?}",
                                cell_name(it.row, it.col),
                                r.center().x,
                                r.center().y,
                                ui.ctx().pixels_per_point(),
                                ui.ctx().input(|i| i.pointer.latest_pos())
                            );
                        }
                        if std::env::var("SC_PROOF_RECT").is_ok()
                            && (resp.clicked() || resp.double_clicked())
                        {
                            eprintln!(
                                "[row] {} click={} dbl={}",
                                cell_name(it.row, it.col),
                                resp.clicked(),
                                resp.double_clicked()
                            );
                        }
                        if resp.double_clicked() {
                            jump = Some((it.row, it.col));
                            fix_cells.push((it.row, it.col));
                        }
                    }
                });
                ui.add_space(4.0);
                ui_kit::footer(ui, |ui| {
                    if ui
                        .add_enabled(
                            !self.proof_list.is_empty(),
                            egui::Button::new("修正全部"),
                        )
                        .on_hover_text("按当前规则修掉列表里的所有问题（可撤销）")
                        .clicked()
                    {
                        fix_all = true;
                    }
                    if ui
                        .add_enabled(
                            !self.proof_list.is_empty(),
                            egui::Button::new("修正此单元格"),
                        )
                        .clicked()
                    {
                        fix_one = true;
                    }
                    if ui.button("重新检查").clicked() {
                        self.proof_rescan();
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.proof_dlg = false;
                    }
                });
            });
        if !fix_cells.is_empty() {
            let cells = std::mem::take(&mut fix_cells);
            self.proof_fix_cells(cells);
        } else if fix_all {
            self.proof_apply_fix(false);
        } else if fix_one {
            self.proof_apply_fix(true);
        } else if changed {
            self.proof_list =
                sheetcore::proof::scan(self.wb.sheet(self.sheet_idx), &self.proof_rules);
        }
        if let Some((r, c)) = jump {
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        if !open {
            self.proof_dlg = false;
        }
    }

    /// 中文简繁转换：把选区里的文本单元格整段转换（词组优先，见 core::zhconv）
    fn zh_convert(&mut self, to_trad: bool, variant: sheetcore::zhconv::Variant) {
        if to_trad && self.prefs.zh_variant != ui_prefs::variant_to_u8(variant) {
            self.prefs.zh_variant = ui_prefs::variant_to_u8(variant);
            self.prefs.save();
        }
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        if (r2 - r1) as u64 * (c2 - c1) as u64 > 200_000 {
            self.status = "选区太大，先选一块再转换".into();
            return;
        }
        let mut keys: Vec<(u32, u32)> = Vec::new();
        let mut work: Vec<(u32, u32, String)> = Vec::new();
        {
            let sh = self.wb.sheet(self.sheet_idx);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    let Some(cell) = sh.get(r, c) else { continue };
                    let sheetcore::model::Value::Text(t) = &cell.value else {
                        continue;
                    };
                    let new = if to_trad {
                        sheetcore::zhconv::to_traditional_with(t, variant)
                    } else {
                        sheetcore::zhconv::to_simplified(t)
                    };
                    if new.as_str() != t.as_ref() {
                        keys.push((r, c));
                        work.push((r, c, new));
                    }
                }
            }
        }
        if work.is_empty() {
            self.status = "选区里没有需要转换的文本".into();
            return;
        }
        let txn = self.txn_begin(&keys);
        let n = work.len();
        for (r, c, text) in work {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(r, c).cloned().unwrap_or_default();
            cell.value = sheetcore::model::Value::Text(text.into());
            sh.set(r, c, cell);
        }
        self.txn_end(if to_trad { "简转繁" } else { "繁转简" }, txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let label = if to_trad {
            match variant {
                sheetcore::zhconv::Variant::Generic => "简转繁（通用）",
                sheetcore::zhconv::Variant::Taiwan => "简转繁（台湾正体）",
                sheetcore::zhconv::Variant::HongKong => "简转繁（香港繁体）",
            }
        } else {
            "繁转简"
        };
        self.status = format!("{label}：已转换 {n} 个单元格");
    }

    /// 清除内容（保留格式，和 Excel「清除内容」一致）
fn clear_selection(&mut self) {
        self.clear_rects(ClearPart::Contents);
    }

    /// 字体/填充颜色面板（Excel 的主题色 + 标准色）
    fn color_popup_window(&mut self, ctx: &egui::Context) {
        self.draw_wps_color_popup(ctx);
    }

    fn current_style(&self) -> sheetcore::style::CellStyle {
        let id = self.wb.sheet(self.sheet_idx).style_of(self.sel.0, self.sel.1);
        self.wb.styles.get(id).clone()
    }

    /// 对选区每个格子套用样式改动；只影响显示，不触发重算
    fn apply_style<F: Fn(&mut sheetcore::style::CellStyle)>(&mut self, f: F) {
        self.apply_style_xy(move |st, _r, _c| f(st));
    }

    /// 同上，但闭包能拿到格子坐标（画边框要用）
    fn apply_style_xy<F: Fn(&mut sheetcore::style::CellStyle, u32, u32)>(&mut self, f: F) {
        if self.deps_pending {
            self.status = "大型工作簿正在后台构建依赖图，请稍候再编辑".into();
            return;
        }
        if self.wb.sheet(self.sheet_idx).protection.is_some()
            && !self.prot_can(sheetcore::protection::ProtOp::FormatCells)
            && self.rects_have_locked(&self.sel_rects())
        {
            self.status =
                "工作表受保护：选区含锁定单元格，且未授予「设置单元格格式」权限".into();
            return;
        }
        let rects = self.sel_rects();
        let is_axis_rect = |(r1, c1, r2, c2): (u32, u32, u32, u32)| {
            (r1 == 0 && r2 >= 1_000_000) || (c1 == 0 && c2 >= 16_000)
        };
        if rects.iter().any(|&rc| is_axis_rect(rc)) {
            let mut sparse_keys: Vec<(u32, u32)> = Vec::new();
            let mut full_sheet = false;
            let mut full_cols: Vec<(u32, u32)> = Vec::new();
            let mut full_rows: Vec<(u32, u32)> = Vec::new();
            {
                let sh = self.wb.sheet(self.sheet_idx);
                let mut set = std::collections::BTreeSet::new();
                for &(r1, c1, r2, c2) in &rects {
                    if r1 == 0 && r2 >= 1_000_000 && c1 == 0 && c2 >= 16_000 {
                        full_sheet = true;
                        for k in sh.styles.keys() {
                            set.insert((k.row, k.col));
                        }
                    } else if r1 == 0 && r2 >= 1_000_000 {
                        full_cols.push((c1, c2));
                        for k in sh.styles.keys() {
                            if k.col >= c1 && k.col <= c2 {
                                set.insert((k.row, k.col));
                            }
                        }
                    } else if c1 == 0 && c2 >= 16_000 {
                        full_rows.push((r1, r2));
                        for k in sh.styles.keys() {
                            if k.row >= r1 && k.row <= r2 {
                                set.insert((k.row, k.col));
                            }
                        }
                    } else if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 <= 200_000 {
                        for k in sheetcore::undo::rect_keys(r1, c1, r2, c2) {
                            set.insert(k);
                        }
                    }
                }
                sparse_keys.extend(set);
            }
            if !self.write_preflight_op(&sparse_keys, "设置格式", sheetcore::protection::ProtOp::FormatCells) {
                return;
            }
            let txn = self.txn_begin(&sparse_keys);
            if full_sheet {
                let row_keys: Vec<u32> = self.wb.sheet(self.sheet_idx).row_styles.keys().copied().collect();
                for r in row_keys {
                    let old = self.wb.sheet(self.sheet_idx).row_styles.get(&r).copied().unwrap_or(0);
                    let mut st = self.wb.styles.get(old).clone();
                    f(&mut st, r, 0);
                    let id = self.wb.styles.intern(st);
                    self.wb.sheet_mut(self.sheet_idx).set_row_style(r, id);
                }
                for c in 0..16_384u32 {
                    let old = self.wb.sheet(self.sheet_idx).col_styles.get(&c).copied().unwrap_or(0);
                    let mut st = self.wb.styles.get(old).clone();
                    f(&mut st, 0, c);
                    let id = self.wb.styles.intern(st);
                    self.wb.sheet_mut(self.sheet_idx).set_col_style(c, id);
                }
            } else {
                for (c1, c2) in full_cols {
                    for c in c1..=c2 {
                        let old = self.wb.sheet(self.sheet_idx).col_styles.get(&c).copied().unwrap_or(0);
                        let mut st = self.wb.styles.get(old).clone();
                        f(&mut st, 0, c);
                        let id = self.wb.styles.intern(st);
                        self.wb.sheet_mut(self.sheet_idx).set_col_style(c, id);
                    }
                }
                for (r1, r2) in full_rows {
                    for r in r1..=r2 {
                        let old = self.wb.sheet(self.sheet_idx).row_styles.get(&r).copied().unwrap_or(0);
                        let mut st = self.wb.styles.get(old).clone();
                        f(&mut st, r, 0);
                        let id = self.wb.styles.intern(st);
                        self.wb.sheet_mut(self.sheet_idx).set_row_style(r, id);
                    }
                }
            }
            for &(r, c) in &sparse_keys {
                let old = self.wb.sheet(self.sheet_idx).style_of(r, c);
                let mut st = self.wb.styles.get(old).clone();
                f(&mut st, r, c);
                let id = self.wb.styles.intern(st);
                self.wb.sheet_mut(self.sheet_idx).set_style(r, c, id);
            }
            self.txn_end("设置格式", txn);
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            return;
        }
        let total: u64 = rects
            .iter()
            .map(|(r1, c1, r2, c2)| (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64)
            .sum();
        if total > 200_000 {
            self.status = "选区太大（超过 20 万格），不给整块刷格式".into();
            return;
        }
        let mut keys: Vec<(u32, u32)> = Vec::new();
        for (r1, c1, r2, c2) in rects.iter() {
            keys.extend(sheetcore::undo::rect_keys(*r1, *c1, *r2, *c2));
        }
                keys.sort_unstable();
        keys.dedup();
        // 受保护表上如果给了「设置单元格格式」权限，锁定格也要放行；
        // 没给权限时锁定格在进入本函数前就已被拒，未锁定格照常可改。
        let fmt_perm = self.wb.sheet(self.sheet_idx).protection.is_some()
            && self.prot_can(sheetcore::protection::ProtOp::FormatCells);
        let ok = if fmt_perm {
            self.write_preflight_op(&keys, "设置格式", sheetcore::protection::ProtOp::FormatCells)
        } else {
            self.write_preflight(&keys, "设置格式")
        };
        if !ok {
            return;
        }
let txn = self.txn_begin(&keys);
        let mut wire: Vec<(u32, u32, sheetcore::style::CellStyle)> = Vec::new();
        for (r1, c1, r2, c2) in rects.iter().copied() {
            for r in r1..=r2 {
                for c in c1..=c2 {
                    let old = self.wb.sheet(self.sheet_idx).style_of(r, c);
                    let mut st = self.wb.styles.get(old).clone();
                    f(&mut st, r, c);
                    let id = self.wb.styles.intern(st.clone());
                    self.wb.sheet_mut(self.sheet_idx).set_style(r, c, id);
                    wire.push((r, c, st));
                }
            }
        }
        if let Some(net) = self.net.as_ref() {
            net.broadcast_style(self.sheet_idx, wire);
        }
        self.txn_end("设置格式", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
    }

    /// 只给选区外沿加边框（内部各格不重复画）
    fn outer_border(&mut self, style: u8, color: [u8; 3]) {
        let (r1, c1, r2, c2) = self.sel_rect();
        self.apply_style_xy(move |st, r, c| {
            let mut b = st.border;
            // 左 右 上 下
            if c == c1 {
                b[0] = sheetcore::style::Border { style, color };
            }
            if c == c2 {
                b[1] = sheetcore::style::Border { style, color };
            }
            if r == r1 {
                b[2] = sheetcore::style::Border { style, color };
            }
            if r == r2 {
                b[3] = sheetcore::style::Border { style, color };
            }
            st.border = b;
        });
    }

    fn toggle_merge(&mut self, on: bool) {
        if self.edit_blocked() {
            return;
        }
        if !on {
            // 取消合并：先判选区内是否存在任何合并区域；无合并时零分配、零标脏、零重算立即返回
            let rects = self.sel_rects();
            let matching_merges: Vec<(u32, u32, u32, u32)> = self
                .wb
                .sheet(self.sheet_idx)
                .merges
                .iter()
                .copied()
                .filter(|&(mr1, mc1, mr2, mc2)| {
                    rects
                        .iter()
                        .any(|&(sr1, sc1, sr2, sc2)| mr1 <= sr2 && mr2 >= sr1 && mc1 <= sc2 && mc2 >= sc1)
                })
                .collect();
            if matching_merges.is_empty() {
                self.merge_pending = None;
                self.status = "所选区域没有合并单元格".into();
                return;
            }
            let total_merge_cells: u64 = matching_merges
                .iter()
                .map(|&(mr1, mc1, mr2, mc2)| (mr2 - mr1 + 1) as u64 * (mc2 - mc1 + 1) as u64)
                .sum();
            let mut gate_keys: Vec<(u32, u32)> = Vec::new();
            if total_merge_cells <= 200_000 {
                for &(mr1, mc1, mr2, mc2) in &matching_merges {
                    gate_keys.extend(sheetcore::undo::rect_keys(mr1, mc1, mr2, mc2));
                }
            } else {
                for &(mr1, mc1, _, _) in &matching_merges {
                    gate_keys.push((mr1, mc1));
                }
                for ((si, r, c), _) in self.locks.iter() {
                    if si == self.sheet_idx
                        && matching_merges
                            .iter()
                            .any(|&(mr1, mc1, mr2, mc2)| r >= mr1 && r <= mr2 && c >= mc1 && c <= mc2)
                    {
                        gate_keys.push((r, c));
                    }
                }
            }
            gate_keys.sort_unstable();
            gate_keys.dedup();
            if !self.write_preflight(&gate_keys, "取消合并") {
                return;
            }
            self.merge_pending = None;
            let before_merges = self.wb.sheet(self.sheet_idx).merges.clone();
            let single_anchor_merge = if self.sel == self.sel_end && self.extra_sel.is_empty() {
                self.wb.sheet(self.sheet_idx).merge_at(self.sel.0, self.sel.1)
            } else {
                None
            };
            {
                let sheet = self.wb.sheet_mut(self.sheet_idx);
                for &(sr1, sc1, sr2, sc2) in &rects {
                    sheet.unmerge_range(sr1, sc1, sr2, sc2);
                }
            }
            let after_merges = self.wb.sheet(self.sheet_idx).merges.clone();
            if before_merges != after_merges {
                self.undo.push(sheetcore::undo::Action {
                    label: "取消合并".into(),
                    merges: sheetcore::undo::MergeEdit::between(
                        self.sheet_idx,
                        &before_merges,
                        &after_merges,
                    ),
                    deltas: Vec::new(),
                    focus: (self.sheet_idx, self.sel.0, self.sel.1),
                    snap_before: None,
                    snap_after: None,
                    by_site: 0,
                    pictures: None,
                    shapes: None,
                    refresh_sizes: None,
                });
                if let Some((mr1, mc1, mr2, mc2)) = single_anchor_merge {
                    self.sel = (mr1, mc1);
                    self.sel_end = (mr2, mc2);
                }
                if let Some(net) = self.net.as_ref() {
                    for &(sr1, sc1, sr2, sc2) in &rects {
                        net.broadcast_merge(self.sheet_idx, (sr1, sc1, sr2, sc2), false);
                    }
                }
                // 取消合并完全不修改任何单元格的值或公式：绝不触发同步 Deps::build 与全表 recalc_all
                self.wb.dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.tasks.last_edit = Some(std::time::Instant::now());
                self.status = "已取消合并".into();
            } else {
                self.status = "所选区域没有合并单元格".into();
            }
            return;
        }

        let (r1, c1, r2, c2) = self.sel_rect();
        if r1 == r2 && c1 == c2 {
            self.status = "请选择两个以上单元格再合并".into();
            return;
        }
        let area = (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64;
        if area > 200_000 {
            self.status = "合并范围过大（单次最多支持 20 万个单元格）".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        if !self.write_preflight(&keys, "合并单元格") {
            return;
        }
        if self
            .wb
            .sheet(self.sheet_idx)
            .merges
            .iter()
            .any(|&m| m == (r1, c1, r2, c2))
        {
            self.merge_pending = None;
            self.status = "所选区域已是合并单元格".into();
            return;
        }
        // 合并只保留左上角内容；其余非空格会被删掉，先让用户确认。
        let mut loss = 0u64;
        let anchor: sheetcore::model::Cell;
        let mut removed_cells: Vec<(u32, u32, sheetcore::model::Cell)> = Vec::new();
        {
            let sheet = self.wb.sheet(self.sheet_idx);
            anchor = sheet.get(r1, c1).cloned().unwrap_or_default();
            for r in r1..=r2 {
                for c in c1..=c2 {
                    if r == r1 && c == c1 {
                        continue;
                    }
                    if let Some(cell) = sheet.get(r, c) {
                        if !cell.is_blank() {
                            loss += 1;
                            removed_cells.push((r, c, cell.clone()));
                        }
                    }
                }
            }
        }
        let confirmed = loss > 0
            && self.merge_pending.as_ref().is_some_and(|p| {
                p.wb_epoch == self.wb_epoch
                    && p.doc_gen == self.doc_gen
                    && p.sheet == self.sheet_idx
                    && p.rect == (r1, c1, r2, c2)
                    && p.anchor == anchor
                    && p.removed == removed_cells
            });
        if loss > 0 && !confirmed {
            let shown = if anchor.value.display().is_empty() {
                "（空）".to_string()
            } else {
                anchor.value.display()
            };
            self.merge_pending = Some(MergePending {
                wb_epoch: self.wb_epoch,
                doc_gen: self.doc_gen,
                sheet: self.sheet_idx,
                rect: (r1, c1, r2, c2),
                anchor,
                removed: removed_cells.clone(),
            });
            self.status = format!(
                "合并只保留左上角「{shown}」的内容，其余 {loss} 格内容会被删除；再点一次合并确认"
            );
            return;
        }
        self.merge_pending = None;
        let before_merges = self.wb.sheet(self.sheet_idx).merges.clone();
        let delta_keys: Vec<(u32, u32)> = removed_cells.iter().map(|(r, c, _)| (*r, *c)).collect();
        let deltas = self.txn_begin(&delta_keys);
        {
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            for (r, c, _) in removed_cells.iter() {
                sheet.set(*r, *c, sheetcore::model::Cell {
                    value: sheetcore::model::Value::Empty,
                    formula: None,
                });
            }
            // 合并区内非左上角若有批注：若锚点无批注则自动迁移至锚点，否则清理非锚点幽灵批注
            let anchor_key = sheetcore::model::CellRef::new(r1, c1);
            let mut non_anchor_keys: Vec<sheetcore::model::CellRef> = sheet
                .notes
                .keys()
                .copied()
                .filter(|k| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2 && *k != anchor_key)
                .collect();
            if !non_anchor_keys.is_empty() {
                non_anchor_keys.sort_by_key(|k| (k.row, k.col));
                for nk in non_anchor_keys {
                    if let Some(mut note) = sheet.notes.remove(&nk) {
                        if !sheet.notes.contains_key(&anchor_key) {
                            note.r = r1;
                            note.c = c1;
                            sheet.notes.insert(anchor_key, note);
                        }
                        sheet.notes_dirty = true;
                    }
                }
            }
            sheet.merge_range(r1, c1, r2, c2);
        }
        let after_merges = self.wb.sheet(self.sheet_idx).merges.clone();
        let deltas = sheetcore::undo::finish(deltas, self.wb.sheet(self.sheet_idx));
        let changed = before_merges != after_merges || !deltas.is_empty();
        if changed {
            self.undo.push(sheetcore::undo::Action {
                label: "合并单元格".into(),
                merges: sheetcore::undo::MergeEdit::between(
                    self.sheet_idx,
                    &before_merges,
                    &after_merges,
                ),
                deltas,
                focus: (self.sheet_idx, self.sel.0, self.sel.1),
                snap_before: None,
                snap_after: None,
                by_site: 0,
                pictures: None,
                shapes: None,
                refresh_sizes: None,
            });
        }
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            for (r, c, _) in removed_cells.iter() {
                let cell = self.wb.sheet(self.sheet_idx).get(*r, *c).cloned().unwrap_or_default();
                let op = peer.local_set(self.sheet_idx, *r, *c, &cell);
                net.broadcast_op(op);
            }
            net.broadcast_merge(self.sheet_idx, (r1, c1, r2, c2), true);
        }
        if !removed_cells.is_empty() {
            let touched: Vec<(usize, u32, u32)> = removed_cells
                .iter()
                .map(|(r, c, _)| (self.sheet_idx, *r, *c))
                .collect();
            self.fast_recalc_cells(&touched);
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.status = "已合并选区".into();
    }

    /// 格式对话框点「确定」：先落格式，再执行挂起的合并动作。
    fn commit_fmt_merge(&mut self) {
        if let Some(on) = self.fmt_merge_pending.take() {
            self.toggle_merge(on);
        }
    }

    /// 格式刷：把源区域样式按行列重复铺到当前选区，一次撤销。
    fn apply_format_painter(&mut self) {
        let Some(p) = self.format_painter.clone() else { return };
        if p.wb_epoch != self.wb_epoch || p.sheet != self.sheet_idx {
            self.format_painter = None;
            self.painter_double = false;
            self.status = "文档或工作表已切换，格式刷已取消".into();
            return;
        }
        if self.edit_blocked() {
            return;
        }
        let (tr1, tc1, tr2, tc2) = self.sel_rect();
        let area = (tr2 - tr1 + 1) as u64 * (tc2 - tc1 + 1) as u64;
        if area > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64 {
            self.status = "目标区域太大（超过 50 万格），格式刷不执行".into();
            return;
        }
        let (sr1, sc1, sr2, sc2) = p.rect;
        let sh = (sr2 - sr1 + 1) as u32;
        let sw = (sc2 - sc1 + 1) as u32;
        if sh == 0 || sw == 0 {
            self.format_painter = None;
            return;
        }
        let keys = sheetcore::undo::rect_keys(tr1, tc1, tr2, tc2);
        if !self.write_preflight(&keys, "格式刷") {
            return;
        }
        let si = self.sheet_idx;
        let mut changes = Vec::new();
        let mut wire = Vec::new();
        let sheet = &mut self.wb.sheets[si];
        for (row, col) in keys {
            let sid = p.styles[((row - tr1) % sh) as usize][((col - tc1) % sw) as usize];
            let before_style = sheet.style_of(row, col);
            if before_style != sid {
                let value = sheet.get(row, col).cloned().unwrap_or_default();
                changes.push(sheetcore::undo::CellDelta { sheet: si, row, col,
                    before: value.clone(), after: value, before_style, after_style: sid });
            }
            sheet.set_style(row, col, sid);
            if self.net.is_some() && before_style != sid {
                wire.push((row, col, self.wb.styles.get(sid).clone()));
            }
        }
        if let Some(net) = self.net.as_ref() {
            net.broadcast_style(si, wire);
        }
        self.record_deltas("格式刷", changes);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        if p.continuous {
            self.status = "格式刷（连续）：继续选择目标区域，Esc 结束".into();
        } else {
            self.format_painter = None;
            self.status = "已套用格式".into();
        }
    }

    /// 格式工具栏（第二行）
    // ===== 功能区（Excel 式分组）=====

    /// Excel 的「文件」后台视图：左侧一列导航，右侧整块内容。
    /// 打开时盖住功能区和表格，标题栏保留。
    /// 富文本：选中文字后加粗/改色/改字号
    fn rich_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.rich_dlg.take() else { return };
        let mut open = true;
        let mut apply = false;
        ui_kit::window(ctx, "富文本", 420.0).open(&mut open).show(ctx, |ui| {
            ui.label("先选中文字，再点下面的按钮；不选表示整格");
            let text = sheetcore::richtext::runs_text(&d.runs);
            let mut buf = text.clone();
            let out = egui::TextEdit::multiline(&mut buf)
                .desired_rows(4)
                .desired_width(380.0)
                .show(ui);
            if let Some(range) = out.cursor_range {
                let a = range.primary.ccursor.index;
                let b = range.secondary.ccursor.index;
                d.sel = if a <= b { (a, b) } else { (b, a) };
            }
            if out.response.changed() {
                d.runs = vec![sheetcore::richtext::RichRun::plain(buf)];
            }
            let (start, end) = if d.sel.0 == d.sel.1 {
                (0, d.runs.iter().map(|r| r.text.chars().count()).sum())
            } else {
                d.sel
            };
            ui.horizontal(|ui| {
                if ui.button("加粗").clicked() {
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &|r| {
                        r.bold = !r.bold
                    });
                }
                if ui.button("斜体").clicked() {
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &|r| {
                        r.italic = !r.italic
                    });
                }
                for (name, c) in [("红", [192, 0, 0]), ("蓝", [0, 70, 180]), ("绿", [16, 124, 65])] {
                    if ui.button(name).clicked() {
                        sheetcore::richtext::apply_range(&mut d.runs, start, end, &move |r| {
                            r.color = Some(c)
                        });
                    }
                }
                if ui.button("恢复默认").clicked() {
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &|r| {
                        r.bold = false;
                        r.italic = false;
                        r.color = None;
                        r.size = None;
                        r.font = None;
                    });
                }
            });
            ui.horizontal(|ui| {
                ui.label("字号");
                let mut sz = d.size.max(11.0) as f64;
                if ui_kit::spin(ui, &mut sz, 6.0, 72.0, 1.0, 54.0) {
                    d.size = sz as f32;
                }
                if ui.button("应用到选中").clicked() {
                    let sz = d.size.max(6.0);
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &move |r| {
                        r.size = Some(sz)
                    });
                }
            });
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "确定").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    open = false;
                }
            });
        });
        if apply {
            let runs = std::mem::take(&mut d.runs);
            let text = sheetcore::richtext::runs_text(&runs);
            let key = (d.r, d.c);
            {
                let sheet = self.wb.sheet_mut(self.sheet_idx);
                sheet.rich.insert(key, runs);
                sheet.rich_dirty = true;
                sheet.set(
                    d.r,
                    d.c,
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Text(text.into()),
                        formula: None,
                    },
                );
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = "富文本已应用（保存后 Excel 里能看到分段格式）".into();
            open = false;
        }
        if open {
            self.rich_dlg = Some(d);
        }
    }

    /// 打开超链接：外部地址交给系统默认程序，内部位置跳到对应表/格
    fn open_hyperlink(&mut self, link: &sheetcore::hyperlinks::Hyperlink) {
        if !link.location.is_empty() {
            let loc = link.location.trim_start_matches('#');
            if let Some((sheet, a1)) = loc.rsplit_once('!') {
                let sheet = sheet.trim_matches('\'');
                if let Some(i) = self.wb.sheets.iter().position(|s| s.name == sheet) {
                    if i != self.sheet_idx && !self.switch_sheet_view(i) {
                        return;
                    }
                }
                if let Some((r, c)) = parse_a1_ref(a1) {
                    self.sel = (r, c);
                    self.sel_end = self.sel;
                    self.ensure_visible();
                }
            }
            return;
        }
        if link.target.is_empty() {
            return;
        }
        let _ = std::process::Command::new("rundll32")
            .args(["url.dll,FileProtocolHandler", &link.target])
            .spawn();
        self.status = format!("已打开 {}", link.target);
    }

    /// 插入超链接对话框
    fn hyperlink_dialog(&mut self, ctx: &egui::Context) {
        let Some((mut url, mut text)) = self.hyper_dlg.take() else { return };
        let mut open = true;
        let mut apply = false;
        let mut close = false;
        ui_kit::window(ctx, "插入超链接", 380.0).open(&mut open).show(ctx, |ui| {
            dlg_section(ui, "链接");
            ui_kit::field(ui, "地址", |ui| {
                let r = ui.add(egui::TextEdit::singleline(&mut url).desired_width(260.0));
                ui_kit::autofocus(ui, &r);
            });
            ui_kit::field(ui, "显示文字", |ui| {
                ui.add(egui::TextEdit::singleline(&mut text).desired_width(260.0));
            });
            if !self.link_err.is_empty() {
                ui.colored_label(egui::Color32::from_rgb(190, 40, 40), &self.link_err);
            }
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "插入").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    close = true;
                }
            });
        });
        if apply {
            let url = url.trim().to_string();
            if url.is_empty() {
                self.link_err = "地址不能为空".into();
            } else {
                let (r, c) = self.sel;
                let show = if text.trim().is_empty() { url.clone() } else { text.trim().to_string() };
                {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    sh.set(
                        r,
                        c,
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Text(show.into()),
                            formula: None,
                        },
                    );
                    sh.hyperlinks.insert(
                        (r, c),
                        sheetcore::hyperlinks::Hyperlink {
                            external: true,
                            target: url.clone(),
                            location: String::new(),
                            tooltip: String::new(),
                            ..Default::default()
                        },
                    );
                    sh.hyperlinks_dirty = true;
                }
                self.wb.dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = format!("已插入超链接 {}", url);
                self.hyper_dlg = None;
                self.link_err.clear();
                return;
            }
        }
        if close {
            self.hyper_dlg = None;
            self.link_err.clear();
        } else {
            self.hyper_dlg = Some((url, text));
        }
    }

    /// 关于窗口：版本、协作方式、常用快捷键、许可
    /// 把一个符号插进当前编辑框；没在编辑就先进入编辑、接在原内容后面
    fn insert_symbol(&mut self, ch: char) {
        if let Some(e) = self.editing.as_mut() {
            e.buf.push(ch);
            return;
        }
        let (r, c) = self.sel;
        let mut buf = self.wb.sheet(self.sheet_idx).value(r, c).display();
        buf.push(ch);
        self.editing = Some(EditState::new(buf));
    }

    /// 单元格当前数值（数字才算，其它返回 None）
    fn cell_num(&self, r: u32, c: u32) -> Option<f64> {
        match self.wb.sheet(self.sheet_idx).get(r, c).map(|x| x.value.clone()) {
            Some(sheetcore::model::Value::Number(n)) => Some(n),
            _ => None,
        }
    }

    /// 把一个数字写进格子并按依赖图重算受影响的公式（不记撤销，求解器内部用）
    fn poke_cell(&mut self, deps: &sheetcore::formula::deps::Deps, r: u32, c: u32, v: f64) {
        let sh = self.wb.sheet_mut(self.sheet_idx);
        let mut cell = sh.get(r, c).cloned().unwrap_or_default();
        cell.value = sheetcore::model::Value::Number(v);
        cell.formula = None;
        sh.set(r, c, cell);
        let keys = [(self.sheet_idx, r, c)];
        sheetcore::formula::recalc_dirty(&mut self.wb, deps, &keys);
    }

    /// 单变量求解：找可变格的值，让目标格的公式等于目标值。
    /// 用割线法（两点割线 + 必要时二分兜底），最多 60 次，每次只重算受影响的公式。
    fn goal_seek_run(&mut self, tr: u32, tc: u32, goal: f64, vr: u32, vc: u32) -> Result<f64, String> {
        let Some(orig) = self.cell_num(vr, vc) else {
            return Err("可变单元格里必须是一个数字".into());
        };
        // 依赖图必须现建：大文件加载后 app 里可能是空 deps，靠它重算等于什么都不算
        let deps = sheetcore::formula::deps::Deps::build(&self.wb);
        let f = |app: &mut Self, x: f64| -> Option<f64> {
            app.poke_cell(&deps, vr, vc, x);
            app.cell_num(tr, tc).map(|v| v - goal)
        };
        let mut x0 = orig;
        let mut f0 = f(self, x0).ok_or("目标单元格不是数字（公式可能出错）")?;
        if f0.abs() < 1e-9 {
            return Ok(x0);
        }
        let step = if x0.abs() > 1e-9 { x0.abs() * 0.1 } else { 1.0 };
        let mut x1 = x0 + step;
        let mut f1 = f(self, x1).ok_or("目标单元格不是数字")?;
        let mut lo = f32::NAN;
        let mut hi = f32::NAN;
        for _ in 0..60 {
            if f1.abs() < 1e-9 {
                return Ok(x1);
            }
            if f0.abs() < 1e-9 {
                return Ok(x0);
            }
            // 记下括住根的区间，割线法跳飞时用二分
            if f0 * f1 < 0.0 {
                lo = x0 as f32;
                hi = x1 as f32;
            }
            let denom = f1 - f0;
            let mut next = if denom.abs() > 1e-15 {
                x1 - f1 * (x1 - x0) / denom
            } else {
                f32::NAN as f64
            };
            if !next.is_finite() || (lo.is_finite() && hi.is_finite() && (next < lo.min(hi) as f64 || next > lo.max(hi) as f64)) {
                next = if lo.is_finite() && hi.is_finite() {
                    ((lo as f64) + (hi as f64)) * 0.5
                } else {
                    x1 + step
                };
            }
            x0 = x1;
            f0 = f1;
            x1 = next;
            f1 = f(self, x1).ok_or("目标单元格不是数字")?;
            if (x1 - x0).abs() < 1e-12 * (1.0 + x1.abs()) {
                break;
            }
        }
        if f1.abs() < 1e-6 {
            // 重算只改了模型里的值，保存时公式格的缓存值要按「已编辑」重写
            self.poke_cell(&deps, vr, vc, x1);
            if let Some(cell) = self.wb.sheet(self.sheet_idx).get(tr, tc).cloned() {
                self.wb.sheet_mut(self.sheet_idx).set(tr, tc, cell);
            }
            Ok(x1)
        } else {
            self.poke_cell(&deps, vr, vc, orig);
            Err(format!("没有找到解（最后一次偏差 {:.6}）", f1))
        }
    }

    /// 解析 "A1" / "$B$2" 形式的地址
    fn parse_addr(s: &str) -> Option<(u32, u32)> {
        parse_a1_ref(s.trim().trim_start_matches('$').replace('$', "").as_str())
    }

    /// 按当前规则扫一遍：公式错误 / 数字存为文本 各自可以关掉
    fn scan_issues(&self) -> Vec<sheetcore::errors::Issue> {
        sheetcore::errors::scan_wb(&self.wb, self.sheet_idx)
            .into_iter()
            .filter(|i| match i.kind {
                sheetcore::errors::IssueKind::NumberAsText => self.ec.check_text,
                _ => self.ec.check_errors,
            })
            .collect()
    }

    /// 打开错误检查：重扫一遍当前表
    fn open_error_check(&mut self) {
        self.error_list = self.scan_issues();
        self.error_dlg = true;
        self.status = if self.error_list.is_empty() {
            "这张表没发现错误".into()
        } else {
            format!("找到 {} 处问题", self.error_list.len())
        };
    }

    fn error_window(&mut self, ctx: &egui::Context) {
        if !self.error_dlg {
            return;
        }
        let mut open = true;
        let mut jump: Option<(u32, u32)> = None;
        let mut ignore_sel = false;
        let mut ignore_all = false;
        let mut reset_ignored = false;
        let mut options_clicked = false;
        ui_kit::window(ctx, "错误检查", 600.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(format!(
                        "当前表共 {} 处（点一行跳到那个单元格）",
                        self.error_list.len()
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                if self.error_list.is_empty() {
                    ui.label(egui::RichText::new("没有发现错误。").size(12.0));
                }
                egui::ScrollArea::vertical().max_height(320.0).show(ui, |ui| {
                    for it in self.error_list.clone() {
                        ui.horizontal(|ui| {
                            let addr = cell_name(it.row, it.col);
                            if ui
                                .add_sized(
                                    [64.0, 20.0],
                                    egui::Button::new(
                                        egui::RichText::new(addr).size(11.5).monospace(),
                                    )
                                    .frame(false),
                                )
                                .clicked()
                            {
                                jump = Some((it.row, it.col));
                            }
                            ui.add_sized(
                                [120.0, 20.0],
                                egui::Label::new(
                                    egui::RichText::new(if it.text.is_empty() {
                                        "-"
                                    } else {
                                        it.text.as_str()
                                    })
                                    .size(11.5),
                                )
                                .truncate(),
                            );
                            ui.label(
                                egui::RichText::new(it.kind.detail())
                                    .size(11.0)
                                    .color(ui_kit::TEXT_WEAK),
                            );
                        });
                    }
                });
                ui.add_space(6.0);
                ui_kit::footer(ui, |ui| {
                    if ui.button("忽略此单元格").clicked() {
                        ignore_sel = true;
                    }
                    if ui.button("忽略全部").clicked() {
                        ignore_all = true;
                    }
                    if ui.button("重置忽略").clicked() {
                        reset_ignored = true;
                    }
                    if ui.button("选项…").clicked() {
                        options_clicked = true;
                    }
                    if ui.button("重新检查").clicked() {
                        self.error_list = self.scan_issues();
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.error_dlg = false;
                    }
                });
            });
        if let Some((r, c)) = jump {
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        if ignore_sel {
            let (r, c) = self.sel;
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.ignored_errors.insert((r, c));
            sh.ignored_errors_dirty = true;
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.error_list = self.scan_issues();
            self.status = format!("已忽略 {} 的错误", sheetcore::model::cell_name(r, c));
        }
        if ignore_all {
            let all: Vec<(u32, u32)> = self.error_list.iter().map(|i| (i.row, i.col)).collect();
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                for k in &all {
                    sh.ignored_errors.insert(*k);
                }
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            let n = all.len();
            self.error_list.clear();
            self.status = format!("已忽略 {n} 处错误");
        }
        if options_clicked {
            self.ec_options = true;
        }
        if reset_ignored {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.ignored_errors.clear();
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.error_list = self.scan_issues();
            self.status = "已重置忽略的错误".into();
        }
        if !open {
            self.error_dlg = false;
        }
    }

    /// 错误检查选项：背景检查开关、标记颜色、两条规则的开关（Excel「错误检查选项」那一页）
    fn ec_options_window(&mut self, ctx: &egui::Context) {
        if !self.ec_options {
            return;
        }
        let mut open = true;
        let mut changed = false;
        let mut reset_all = false;
        ui_kit::window(ctx, "错误检查选项", 470.0)
            .open(&mut open)
            .show(ctx, |ui| {
                if ui
                    .checkbox(&mut self.ec.background, "启用背景错误检查（在单元格左上角标出来）")
                    .changed()
                {
                    changed = true;
                }
                ui.horizontal(|ui| {
                    ui.add_sized([80.0, 20.0], egui::Label::new("标记颜色:"));
                    for (name, rgb) in [
                        ("绿", [40u8, 160, 40]),
                        ("红", [200, 40, 40]),
                        ("蓝", [40, 80, 200]),
                        ("橙", [210, 120, 20]),
                    ] {
                        let on = self.ec.color == rgb;
                        if ui.selectable_label(on, name).clicked() {
                            self.ec.color = rgb;
                            changed = true;
                        }
                        let (r, _) = ui.allocate_exact_size(egui::vec2(14.0, 14.0), egui::Sense::hover());
                        ui.painter().rect_filled(
                            r,
                            2.0,
                            Color32::from_rgb(rgb[0], rgb[1], rgb[2]),
                        );
                    }
                });
                ui.add_space(6.0);
                ui.separator();
                ui.add_space(2.0);
                ui.label(egui::RichText::new("检查规则").font(ui_kit::bold(ui_kit::T_BODY)));
                if ui
                    .checkbox(&mut self.ec.check_errors, "公式错误（#DIV/0!、#N/A、#NAME? 等）")
                    .changed()
                {
                    changed = true;
                }
                if ui
                    .checkbox(&mut self.ec.check_text, "数字以文本形式存储")
                    .changed()
                {
                    changed = true;
                }
                ui.add_space(6.0);
                if ui.button("重置所有忽略的错误").clicked() {
                    reset_all = true;
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        self.ec_options = false;
                    }
                });
            });
        if reset_all {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.ignored_errors.clear();
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            changed = true;
            self.status = "已重置本表忽略的错误".into();
        }
        if changed {
            self.ec.save();
            self.error_marks_key = (u64::MAX, u64::MAX);
            if self.error_dlg {
                self.error_list = self.scan_issues();
            }
        }
        if !open {
            self.ec_options = false;
        }
    }

    /// 方案管理器：保存/显示/删除/摘要
    fn scenario_window(&mut self, ctx: &egui::Context) {
        if !self.scen_dlg {
            return;
        }
        let mut open = true;
        let mut do_add = false;
        let mut do_show = false;
        let mut do_del = false;
        let mut do_summary = false;
        let list = self.wb.sheet(self.sheet_idx).scenarios.clone();
        let mut sel = self.scen_sel;
        ui_kit::window(ctx, "方案管理器", 580.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new("这张表里保存的方案（点一条可以装载到下面的名称/备注）")
                        .size(11.5)
                        .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(3.0);
                egui::ScrollArea::vertical().max_height(150.0).show(ui, |ui| {
                    if list.is_empty() {
                        ui.label(egui::RichText::new("还没有方案").size(11.5));
                    }
                    for (i, sc) in list.iter().enumerate() {
                        let mut label = format!("{}（{} 个单元格）", sc.name, sc.cells.len());
                        if !sc.comment.is_empty() {
                            label.push_str(&format!(" — {}", sc.comment));
                        }
                        if ui.selectable_label(sel == Some(i), label).clicked() {
                            sel = Some(i);
                            self.scen_name = sc.name.clone();
                            self.scen_comment = sc.comment.clone();
                        }
                    }
                });
                ui.add_space(4.0);
                ui.separator();
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("名称:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_name).desired_width(240.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("备注:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_comment).desired_width(240.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("可变单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_range).desired_width(120.0));
                    ui.label(
                        egui::RichText::new("例如 A1:C3")
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("结果单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_result).desired_width(120.0));
                    ui.label(
                        egui::RichText::new("可选；摘要里额外列出这些格子在每个方案下的值")
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
                if !self.scen_msg.is_empty() {
                    ui.add_space(3.0);
                    ui.label(egui::RichText::new(&self.scen_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui.button("添加/修改").clicked() {
                        do_add = true;
                    }
                    if ui.add_enabled(sel.is_some(), egui::Button::new("显示")).clicked() {
                        do_show = true;
                    }
                    if ui.add_enabled(sel.is_some(), egui::Button::new("删除")).clicked() {
                        do_del = true;
                    }
                    if ui.button("摘要").clicked() {
                        do_summary = true;
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.scen_dlg = false;
                    }
                });
            });
        self.scen_sel = sel;
        let rect = Self::parse_rect(&self.scen_range);
        if do_add {
            match (rect, self.scen_name.trim().is_empty()) {
                (Some(r), false) => {
                    let name = self.scen_name.trim().to_string();
                    let comment = self.scen_comment.trim().to_string();
                    let sc = sheetcore::scenarios::capture(
                        self.wb.sheet(self.sheet_idx),
                        &name,
                        &comment,
                        r,
                    );
                    let n = sc.cells.len();
                    {
                        let sh = self.wb.sheet_mut(self.sheet_idx);
                        if let Some(pos) = sh.scenarios.iter().position(|x| x.name == name) {
                            sh.scenarios[pos] = sc;
                        } else {
                            sh.scenarios.push(sc);
                        }
                        sh.scenarios_dirty = true;
                    }
                    self.wb.dirty = true;
                    self.scen_msg = format!("已保存方案「{name}」（{n} 个单元格）");
                    self.status = format!("方案「{name}」已保存");
                }
                (None, _) => self.scen_msg = "可变单元格地址写错了（例如 A1:C3）".into(),
                (_, true) => self.scen_msg = "名称不能为空".into(),
            }
        }
        if do_show {
            if let Some(i) = self.scen_sel {
                if let Some(sc) = self.wb.sheet(self.sheet_idx).scenarios.get(i).cloned() {
                    for ((r, c), v) in &sc.cells {
                        let val = sheetcore::scenarios::apply_value(v);
                        let sh = self.wb.sheet_mut(self.sheet_idx);
                        let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
                        cell.value = val;
                        cell.formula = None;
                        sh.set(*r, *c, cell);
                    }
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    self.deps = sheetcore::formula::deps::Deps::build(&self.wb).into();
                    sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &[]);
                    sheetcore::formula::recalc_all(&mut self.wb);
                    self.scen_msg = format!("已显示方案「{}」", sc.name);
                    self.status = format!("已切换到方案「{}」", sc.name);
                }
            }
        }
        if do_del {
            if let Some(i) = self.scen_sel {
                let removed = {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    if i < sh.scenarios.len() {
                        let n = sh.scenarios.remove(i).name;
                        sh.scenarios_dirty = true;
                        Some(n)
                    } else {
                        None
                    }
                };
                if let Some(n) = removed {
                    self.wb.dirty = true;
                    self.scen_sel = None;
                    self.scen_msg = format!("已删除方案「{n}」");
                }
            }
        }
        if do_summary {
            let res = if self.scen_result.trim().is_empty() {
                None
            } else {
                Self::parse_rect(&self.scen_result)
            };
            match self.build_scenario_summary(res) {
                Ok(name) => {
                    self.scen_msg = format!("已在「{name}」里生成摘要");
                    self.status = format!("方案摘要已生成：{name}");
                }
                Err(e) => self.scen_msg = e,
            }
        }
        if !open {
            self.scen_dlg = false;
        }
    }

    /// "A1:C3" / "A1" → (r1, c1, r2, c2)
    fn parse_rect(s: &str) -> Option<(u32, u32, u32, u32)> {
        let t = s.trim();
        if t.is_empty() {
            return None;
        }
        if let Some(r) = sheetcore::table::parse_a1(t) {
            return Some(r);
        }
        parse_a1_ref(t).map(|(r, c)| (r, c, r, c))
    }

    /// 生成「方案摘要」工作表（和 Excel 一样：每行一个方案）。
    /// 带 `results` 时，还会把每个方案下这些格子的计算结果一起写进去。
    fn build_scenario_summary(
        &mut self,
        results: Option<(u32, u32, u32, u32)>,
    ) -> Result<String, String> {
        let list = self.wb.sheet(self.sheet_idx).scenarios.clone();
        if list.is_empty() {
            return Err("还没有方案，先保存一个".into());
        }
        let mut keys: Vec<(u32, u32)> = Vec::new();
        for sc in &list {
            for (k, _) in &sc.cells {
                if !keys.contains(k) {
                    keys.push(*k);
                }
            }
        }
        keys.sort();
        let result_cells: Vec<(u32, u32)> = match results {
            Some((r1, c1, r2, c2)) => {
                let mut v = Vec::new();
                for r in r1..=r2 {
                    for c in c1..=c2 {
                        v.push((r, c));
                    }
                }
                v
            }
            None => Vec::new(),
        };
        // 先把「所有方案会动的格子」的当前值记下来，算完恢复
        let snapshot: Vec<((u32, u32), sheetcore::model::Value)> = keys
            .iter()
            .map(|(r, c)| {
                (
                    (*r, *c),
                    self.wb
                        .sheet(self.sheet_idx)
                        .get(*r, *c)
                        .map(|x| x.value.clone())
                        .unwrap_or_default(),
                )
            })
            .collect();
        // 逐个方案代值、重算、抓结果
        let mut rows: Vec<Vec<Vec<sheetcore::model::Value>>> = Vec::new();
        let deps = sheetcore::formula::deps::Deps::build(&self.wb);
        for sc in &list {
            for ((r, c), v) in &sc.cells {
                let val = sheetcore::scenarios::apply_value(v);
                let sh = self.wb.sheet_mut(self.sheet_idx);
                let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
                cell.value = val;
                cell.formula = None;
                sh.set(*r, *c, cell);
            }
            let seeds: Vec<_> = sc
                .cells
                .iter()
                .map(|((r, c), _)| (self.sheet_idx, *r, *c))
                .collect();
            sheetcore::formula::recalc_dirty(&mut self.wb, &deps, &seeds);
            let vals: Vec<sheetcore::model::Value> = result_cells
                .iter()
                .map(|(r, c)| {
                    self.wb
                        .sheet(self.sheet_idx)
                        .get(*r, *c)
                        .map(|x| x.value.clone())
                        .unwrap_or_default()
                })
                .collect();
            rows.push(vec![vals]);
        }
        // 恢复原状
        for ((r, c), v) in snapshot {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(r, c).cloned().unwrap_or_default();
            cell.value = v;
            sh.set(r, c, cell);
        }
        sheetcore::formula::recalc_all(&mut self.wb);

        let mut base = "方案摘要".to_string();
        let mut n = 1;
        while self.wb.sheets.iter().any(|s| s.name == base) {
            n += 1;
            base = format!("方案摘要{n}");
        }
        let mut sh = sheetcore::model::Sheet::new(&base);
        let mut put = |sh: &mut sheetcore::model::Sheet,
                       r: u32,
                       c: u32,
                       v: sheetcore::model::Value| {
            sh.set(
                r,
                c,
                sheetcore::model::Cell {
                    value: v,
                    formula: None,
                },
            );
        };
        put(&mut sh, 0, 0, sheetcore::model::Value::Text("方案摘要".into()));
        for (i, (r, c)) in keys.iter().enumerate() {
            put(
                &mut sh,
                1,
                i as u32 + 1,
                sheetcore::model::Value::Text(cell_name(*r, *c).into()),
            );
        }
        for (j, (r, c)) in result_cells.iter().enumerate() {
            put(
                &mut sh,
                1,
                keys.len() as u32 + j as u32 + 1,
                sheetcore::model::Value::Text(cell_name(*r, *c).into()),
            );
        }
        for (i, sc) in list.iter().enumerate() {
            let row = i as u32 + 2;
            put(&mut sh, row, 0, sheetcore::model::Value::Text(sc.name.clone().into()));
            for (j, k) in keys.iter().enumerate() {
                let v = sc
                    .cells
                    .iter()
                    .find(|(kk, _)| kk == k)
                    .map(|(_, v)| sheetcore::scenarios::apply_value(v))
                    .unwrap_or_default();
                put(&mut sh, row, j as u32 + 1, v);
            }
            for (j, v) in rows[i][0].iter().enumerate() {
                put(
                    &mut sh,
                    row,
                    keys.len() as u32 + j as u32 + 1,
                    v.clone(),
                );
            }
        }
        let idx = self.wb.sheets.len();
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, idx, sh) {
            return Err("新建摘要表失败".into());
        }
        self.switch_sheet_view(idx);
        self.sel = (0, 0);
        self.sel_end = (0, 0);
        self.finish_sheet_change();
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        Ok(base)
    }

    fn goal_window(&mut self, ctx: &egui::Context) {
        if !self.goal_dlg {
            return;
        }
        let mut open = true;
        let mut solve = false;
        ui_kit::window(ctx, "单变量求解", 420.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("目标单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_target).desired_width(150.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("目标值:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_goal).desired_width(150.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("可变单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_input).desired_width(150.0));
                });
                if !self.goal_msg.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(&self.goal_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "求解").clicked() {
                        solve = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        self.goal_dlg = false;
                    }
                });
            });
        if solve {
            let t = Self::parse_addr(&self.goal_target);
            let v = Self::parse_addr(&self.goal_input);
            let goal = self.goal_goal.trim().parse::<f64>();
            match (t, v, goal) {
                (Some((tr, tc)), Some((vr, vc)), Ok(g)) => {
                    let txn_keys = [(vr, vc)];
                    let txn = self.txn_begin(&txn_keys.into_iter().map(|(r, c)| (r, c)).collect::<Vec<_>>());
                    match self.goal_seek_run(tr, tc, g, vr, vc) {
                        Ok(x) => {
                            self.goal_msg = format!(
                                "求解成功：{}{} = {:.6}",
                                sheetcore::model::cell_name(vr, vc),
                                "，",
                                x
                            );
                            self.txn_end("单变量求解", txn);
                            self.wb.dirty = true;
                            self.doc_gen = self.doc_gen.wrapping_add(1);
                            self.status = format!("单变量求解：{}{} = {:.6}", sheetcore::model::cell_name(vr, vc), "", x);
                        }
                        Err(e) => self.goal_msg = e,
                    }
                }
                _ => self.goal_msg = "单元格地址或目标值写错了".into(),
            }
        }
        if !open {
            self.goal_dlg = false;
        }
    }

    /// 模拟运算表（列式单变量）：选区第一列是输入值，第二列顶行是公式，
    /// 按每个输入值代入后把结果填到第二列。
    /// 模拟运算表：列式单变量 / 行式单变量 / 双变量三种版式，按选区形状自动判断。
    /// - 双变量：公式在选区左上角，第一行是行输入值，第一列是列输入值
    /// - 列式单变量：公式在选区右上格的上方，第一列是输入值、第二列出结果
    /// - 行式单变量：公式在选区左下格的左边，第一行是输入值、第二行出结果
    fn data_table_run(
        &mut self,
        row_in: Option<(u32, u32)>,
        col_in: Option<(u32, u32)>,
    ) -> Result<(String, usize), String> {
        let (r1, c1, r2, c2) = self.sel_rect();
        let has_formula = |app: &Self, r: i64, c: i64| -> bool {
            if r < 0 || c < 0 {
                return false;
            }
            app.wb
                .sheet(app.sheet_idx)
                .get(r as u32, c as u32)
                .and_then(|x| x.formula.clone())
                .is_some()
        };
        // 判定版式
        let mode = if has_formula(self, r1 as i64, c1 as i64) && c2 > c1 && r2 > r1 {
            "two"
        } else if has_formula(self, r1 as i64 - 1, c2 as i64) {
            "col"
        } else if has_formula(self, r1 as i64 + 1, c1 as i64) {
            "row"
        } else {
            return Err(
                "认不出版式：双变量要求公式在选区左上角；                  单变量（列）要求公式在结果列上方；                 单变量（行）要求公式在结果行左侧"
                    .into(),
            );
        };
        let need_row = mode == "row" || mode == "two";
        let need_col = mode == "col" || mode == "two";
        if need_row && row_in.is_none() {
            return Err("这个版式需要「行输入引用单元格」".into());
        }
        if need_col && col_in.is_none() {
            return Err("这个版式需要「列输入引用单元格」".into());
        }
        let est_cells: u64 = match mode {
            "two" => (r2.saturating_sub(r1) as u64) * (c2.saturating_sub(c1) as u64),
            "col" => (r2.saturating_sub(r1) + 1) as u64,
            _ => c2.saturating_sub(c1) as u64,
        };
        if est_cells > 5_000 {
            return Err("模拟运算表输出区域超过 5000 个单元格上限，请缩小选区范围".into());
        }
        let (fcell, results_src): ((u32, u32), Vec<(u32, u32, Option<f64>, Option<f64>)>) = match mode {
            "two" => {
                let mut cells = Vec::new();
                for r in (r1 + 1)..=r2 {
                    for c in (c1 + 1)..=c2 {
                        let rv = self.cell_num(r, c1);
                        let cv = self.cell_num(r1, c);
                        cells.push((r, c, rv, cv));
                    }
                }
                ((r1, c1), cells)
            }
            "col" => {
                let mut cells = Vec::new();
                for r in r1..=r2 {
                    let cv = self.cell_num(r, c1);
                    cells.push((r, c2, None, cv));
                }
                ((r1 - 1, c2), cells)
            }
            _ => {
                let mut cells = Vec::new();
                for c in (c1 + 1)..=c2 {
                    let rv = self.cell_num(r1, c);
                    cells.push((r1 + 1, c, rv, None));
                }
                ((r1 + 1, c1), cells)
            }
        };
        if results_src.iter().all(|(_, _, rv, cv)| rv.is_none() && cv.is_none()) {
            return Err("选区里没有可用的输入值".into());
        }
        let deps = sheetcore::formula::deps::Deps::build(&self.wb);
        let orig_row = row_in.and_then(|(r, c)| self.cell_num(r, c));
        let orig_col = col_in.and_then(|(r, c)| self.cell_num(r, c));
        let mut done = 0usize;
        for (r, c, rv, cv) in results_src {
            if let (Some((ri, ci)), Some(v)) = (row_in, rv) {
                self.poke_cell(&deps, ri, ci, v);
            }
            if let (Some((ci2, cj2)), Some(v)) = (col_in, cv) {
                self.poke_cell(&deps, ci2, cj2, v);
            }
            let out = self
                .wb
                .sheet(self.sheet_idx)
                .get(fcell.0, fcell.1)
                .map(|x| x.value.clone())
                .unwrap_or_default();
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(r, c).cloned().unwrap_or_default();
            cell.value = out;
            cell.formula = None;
            sh.set(r, c, cell);
            done += 1;
        }
        if let (Some((ri, ci)), Some(v)) = (row_in, orig_row) {
            self.poke_cell(&deps, ri, ci, v);
        }
        if let (Some((ci2, cj2)), Some(v)) = (col_in, orig_col) {
            self.poke_cell(&deps, ci2, cj2, v);
        }
        let label = match mode {
            "two" => "双变量",
            "col" => "单变量（列）",
            _ => "单变量（行）",
        };
        Ok((label.to_string(), done))
    }

    fn dtable_window(&mut self, ctx: &egui::Context) {
        if !self.dtable_dlg {
            return;
        }
        let mut open = true;
        let mut run = false;
        ui_kit::window(ctx, "模拟运算表", 480.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(
                        "双变量：公式在选区左上角，首行是行输入值、首列是列输入值。
                         单变量（列）：公式在结果列上方，第一列是输入值。
                         单变量（行）：公式在结果行左侧，第一行是输入值。",
                    )
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    ui.add_sized([110.0, 20.0], egui::Label::new("行输入单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.dtable_row).desired_width(120.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([110.0, 20.0], egui::Label::new("列输入单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.dtable_col).desired_width(120.0));
                });
                if !self.dtable_msg.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(&self.dtable_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        run = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        self.dtable_dlg = false;
                    }
                });
            });
        if run {
            let rin = if self.dtable_row.trim().is_empty() {
                None
            } else {
                Self::parse_addr(&self.dtable_row)
            };
            let cin = if self.dtable_col.trim().is_empty() {
                None
            } else {
                Self::parse_addr(&self.dtable_col)
            };
            match self.data_table_run(rin, cin) {
                Ok((label, n)) => {
                    self.dtable_msg = format!("{label}：已填 {n} 个结果");
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    self.status = format!("模拟运算表（{label}）：已填 {n} 个结果");
                }
                Err(e) => self.dtable_msg = e,
            }
        }
        if !open {
            self.dtable_dlg = false;
        }
    }

