    /// 选择性粘贴对话框
    fn paste_special_dialog(&mut self, ctx: &egui::Context) {
        self.draw_paste_special_wps(ctx);
    }

    /// 执行选择性粘贴：内部剪贴板优先，其次系统剪贴板文本
    fn paste_special_apply(&mut self, ctx: &egui::Context) {
        let text = self.system_paste_text();
        self.paste_special_apply_text(ctx, text);
    }

    /// 系统剪贴板读取集中加锁：并行测试/多个 arboard 实例在 Windows 上会互相踩。
    fn read_clipboard_text() -> Option<String> {
        static IO: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let _g = IO.lock().ok()?;
        let text = read_system_clip().text;
        (!text.is_empty()).then_some(text)
    }

    /// text 是系统剪贴板文本；None/空 表示没有可粘贴的外部文本。
    fn paste_special_apply_text(&mut self, _ctx: &egui::Context, ext_text: Option<String>) {
        if self.edit_blocked() {
            return;
        }
        let (r0, c0) = self.sel;
        let target_sheet_name = self.wb.sheet(self.sheet_idx).name.clone();

        // 内部剪贴板：matrix 是要粘贴的格子，coords 记录每格在源表里的绝对坐标。
        // 外部文本没有源坐标，公式只能按原文粘贴（不偏移）。
        // 关键：内部 Clip 不能遮盖后复制到系统剪贴板的新内容——与普通粘贴同一判定。
        let internal = self.internal_clip_for(ext_text.as_deref(), true);
        if internal.is_some_and(|clip| office_clipboard::delayed::is_full_columns(clip.rect)) {
            if self.ps_op == 0 && !self.ps_transpose && !self.ps_skip_blanks && matches!(self.ps_kind, 0 | 1) {
                self.clip_paste(self.ps_kind == 1, ext_text);
            } else {
                self.status = "整列支持普通粘贴和粘贴数值，其他选项请先选中数据区域".into();
            }
            return;
        }
        let src_sheet_idx = internal.and_then(|clip| clip.live_sheet_index(&self.wb));
        let mut src_sheet_name: Option<String> = None;
        let (mut matrix, mut coords) = if let Some(clip) = internal {
            let sc1 = clip.rect.1;
            src_sheet_name = clip.deferred.as_ref().map(|range| range.book().sheet(0).name.clone())
                .or_else(|| self.wb.sheets.get(clip.sheet).map(|sh| sh.name.clone()));
            let mut coords: Vec<Vec<(u32, u32)>> = Vec::new();
            for (i, row) in clip.cells().iter().enumerate() {
                coords.push(
                    (0..row.len())
                        .map(|j| (clip.source_row(i), sc1 + j as u32))
                        .collect(),
                );
            }
            (clip.cells().to_vec(), Some(coords))
        } else {
            let text = ext_text.unwrap_or_default();
            if text.is_empty() {
                self.status = "剪贴板是空的".into();
                return;
            }
            // 与普通粘贴共用同一解析器：保留中间空行，= 开头按公式解析
            (Self::parse_clip_text(&text), None)
        };
        if matrix.is_empty() {
            self.status = "剪贴板是空的".into();
            return;
        }
        let init_h = matrix.len() as u64;
        let init_w = matrix.iter().map(|r| r.len()).max().unwrap_or(0) as u64;
        if init_h * init_w > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64 {
            self.status = "选择性粘贴范围过大（单次最多支持 50 万个单元格）".into();
            return;
        }
        if self.ps_transpose {
            let h = matrix.len();
            let w = matrix.iter().map(|r| r.len()).max().unwrap_or(0);
            let mut t = vec![
                vec![
                    (
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Empty,
                            formula: None,
                        },
                        0u16,
                    );
                    h
                ];
                w
            ];
            for (r, row) in matrix.iter().enumerate() {
                for (c, cell) in row.iter().enumerate() {
                    t[c][r] = cell.clone();
                }
            }
            matrix = t;
            if let Some(co) = coords.take() {
                let mut tc = vec![vec![(0u32, 0u32); h]; w];
                for (r, row) in co.iter().enumerate() {
                    for (c, rc) in row.iter().enumerate() {
                        tc[c][r] = *rc;
                    }
                }
                coords = Some(tc);
            }
        }
        let rows = matrix.len() as u32;
        let cols = matrix.iter().map(|r| r.len()).max().unwrap_or(0) as u32;
        if rows == 0 || cols == 0 {
            return;
        }
        if (rows as u64) * (cols as u64) > sheetcore::undo::MAX_DENSE_RECT_KEYS as u64 {
            self.status = "选择性粘贴范围过大（单次最多支持 50 万个单元格）".into();
            return;
        }
        if r0.saturating_add(rows - 1) > 1_048_575 || c0.saturating_add(cols - 1) > 16_383 {
            self.status = "选择性粘贴超出工作表行列边界".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r0, c0, r0 + rows - 1, c0 + cols - 1);
        if !self.write_preflight(&keys, "选择性粘贴") {
            return;
        }
        if self.ps_kind == 5 {
            if let (Some(co), Some(ssi)) = (&coords, src_sheet_idx) {
                if let Some(first_row) = co.first() {
                    let widths: Vec<f32> = first_row
                        .iter()
                        .map(|&(_sr, sc)| self.wb.sheet(ssi).cols.size(sc))
                        .collect();
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    for (j, w) in widths.iter().enumerate() {
                        sh.cols.set(c0 + j as u32, *w);
                    }
                    sh.layout_dirty = true;
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    self.status = format!("已粘贴 {} 列宽", widths.len());
                    return;
                }
            }
            self.status = "外部剪贴板不含源列宽信息".into();
            return;
        }
        let txn = self.txn_begin(&keys);
        let mut wire_styles: Vec<(u32, u32, sheetcore::style::CellStyle)> = Vec::new();
        for (i, row) in matrix.iter().enumerate() {
            for (j, (src, sid)) in row.iter().enumerate() {
                if self.ps_skip_blanks && src.is_blank() {
                    continue;
                }
                let (r, c) = (r0 + i as u32, c0 + j as u32);
                if self.ps_kind == 8 {
                    if let (Some(co), Some(ssi)) = (&coords, src_sheet_idx) {
                        let (sr, sc) = co[i][j];
                        let note = self
                            .wb
                            .sheet(ssi)
                            .notes
                            .get(&sheetcore::model::CellRef::new(sr, sc))
                            .cloned();
                        let sh = self.wb.sheet_mut(self.sheet_idx);
                        if let Some(mut n) = note {
                            let (ar, ac) = sh.merge_at(r, c).map(|(mr1, mc1, _, _)| (mr1, mc1)).unwrap_or((r, c));
                            n.r = ar;
                            n.c = ac;
                            sh.notes.insert(sheetcore::model::CellRef::new(ar, ac), n);
                            sh.notes_dirty = true;
                        }
                    }
                    continue;
                }
                if self.ps_kind == 9 {
                    if let (Some(co), Some(ssi)) = (&coords, src_sheet_idx) {
                        let (sr, sc) = co[i][j];
                        if let Some(dv) = sheetcore::dv::find(&self.wb.sheet(ssi).dv, sr, sc).cloned() {
                            let mut rule = dv;
                            rule.ranges = vec![(r, c, r, c)];
                            let sh = self.wb.sheet_mut(self.sheet_idx);
                            sh.dv.push(rule);
                            sh.dv_dirty = true;
                        }
                    }
                    continue;
                }
                let mut cell = self
                    .wb
                    .sheet(self.sheet_idx)
                    .get(r, c)
                    .cloned()
                    .unwrap_or(sheetcore::model::Cell {
                        value: sheetcore::model::Value::Empty,
                        formula: None,
                    });
                let dst_sid = self.wb.sheet(self.sheet_idx).style_of(r, c);
                let mut style = *sid;
                // 公式按“目标位置 - 源绝对坐标”平移；负偏移由 refs::translate 产出 #REF!
                let shifted_formula = |f: &str| -> String {
                    match (&coords, &src_sheet_name) {
                        (Some(co), Some(_)) => {
                            let (sr, sc) = co[i][j];
                            sheetcore::refs::translate(
                                f,
                                r as i64 - sr as i64,
                                c as i64 - sc as i64,
                                &target_sheet_name,
                            )
                        }
                        _ => f.to_string(),
                    }
                };
                match self.ps_kind {
                    1 => {
                        cell.value = src.value.clone();
                        cell.formula = None;
                    }
                    2 => {
                        if let Some(f) = &src.formula {
                            cell.formula = Some(shifted_formula(f).into());
                        } else {
                            cell.formula = None;
                            cell.value = src.value.clone();
                        }
                    }
                    3 => {
                        style = *sid;
                    }
                    4 => {
                        cell = src.clone();
                        if let Some(f) = &src.formula {
                            cell.formula = Some(shifted_formula(f).into());
                        } else {
                            cell.formula = None;
                        }
                        let mut st = self.wb.styles.get(*sid).clone();
                        st.border = [sheetcore::style::Border::default(); 4];
                        style = self.wb.styles.intern(st) as u16;
                    }
                    6 => {
                        cell.value = src.value.clone();
                        cell.formula = None;
                        let src_fmt = self.wb.styles.get(*sid).format.clone();
                        let mut st = self.wb.styles.get(dst_sid).clone();
                        st.format = src_fmt;
                        style = self.wb.styles.intern(st) as u16;
                    }
                    7 => {
                        if let Some(f) = &src.formula {
                            cell.formula = Some(shifted_formula(f).into());
                        } else {
                            cell.formula = None;
                            cell.value = src.value.clone();
                        }
                        let src_fmt = self.wb.styles.get(*sid).format.clone();
                        let mut st = self.wb.styles.get(dst_sid).clone();
                        st.format = src_fmt;
                        style = self.wb.styles.intern(st) as u16;
                    }
                    _ => {
                        cell = src.clone();
                        if let Some(f) = &src.formula {
                            cell.formula = Some(shifted_formula(f).into());
                        } else {
                            cell.formula = None;
                        }
                        style = *sid;
                    }
                }
                if self.ps_op != 0 && self.ps_kind != 3 {
                    // Excel 的“运算”是：目标原值 op 剪贴板值
                    let target_before = self
                        .wb
                        .sheet(self.sheet_idx)
                        .get(r, c)
                        .map(|x| x.value.clone())
                        .unwrap_or(sheetcore::model::Value::Empty);
                    if let (sheetcore::model::Value::Number(a), sheetcore::model::Value::Number(b)) =
                        (target_before, src.value.clone())
                    {
                        let v = match self.ps_op {
                            1 => Some(a + b),
                            2 => Some(a - b),
                            3 => Some(a * b),
                            _ => {
                                if b == 0.0 {
                                    None
                                } else {
                                    Some(a / b)
                                }
                            }
                        };
                        match v {
                            Some(v) => {
                                cell.value = sheetcore::model::Value::Number(v);
                            }
                            None => {
                                cell.value = sheetcore::model::Value::Error(
                                    sheetcore::formula::ErrKind::Div0,
                                );
                            }
                        }
                        cell.formula = None;
                    }
                }
                let sheet = self.wb.sheet_mut(self.sheet_idx);
                sheet.set(r, c, cell);
                if matches!(self.ps_kind, 0 | 3 | 4 | 6 | 7) {
                    sheet.set_style(r, c, style);
                    wire_styles.push((r, c, self.wb.styles.get(style).clone()));
                }
            }
        }
        self.txn_end("选择性粘贴", txn);
        // 与普通粘贴一致：值/公式和样式都同步给协作者
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            for (i, row) in matrix.iter().enumerate() {
                for j in 0..row.len() {
                    let (r, c) = (r0 + i as u32, c0 + j as u32);
                    let cell = self.wb.sheet(self.sheet_idx).get(r, c).cloned().unwrap_or_default();
                    let op = peer.local_set(self.sheet_idx, r, c, &cell);
                    net.broadcast_op(op);
                }
            }
            if !wire_styles.is_empty() {
                net.broadcast_style(self.sheet_idx, wire_styles);
            }
        }
        self.sel_end = (r0 + rows - 1, c0 + cols - 1);
        if !matches!(self.ps_kind, 3 | 8 | 9) {
            let si = self.sheet_idx;
            let touched: Vec<(usize, u32, u32)> = keys
                .iter()
                .map(|&(r, c)| (si, r, c))
                .collect();
            self.fast_recalc_cells(&touched);
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.status = format!("已选择性粘贴 {rows} 行 × {cols} 列");
    }

    /// 名称管理器：列出/新建/修改/删除定义名称
    fn name_manager_window(&mut self, ctx: &egui::Context) {
        if !self.name_mgr {
            return;
        }
        let mut open = self.name_mgr;
        let mut close = false;
        let mut del: Option<usize> = None;
        let mut start_edit: Option<usize> = None;
        let mut submit = false;
        let rows: Vec<(String, String)> = self
            .wb
            .names
            .iter()
            .map(|(name, sheet, refers)| {
                let scope = sheet
                    .and_then(|s| self.wb.sheets.get(s))
                    .map(|x| x.name.clone())
                    .unwrap_or_else(|| "工作簿".into());
                (name.clone(), format!("{refers}  （{scope}）"))
            })
            .collect();
        ui_kit::window(ctx, "名称管理器", 520.0)
            .open(&mut open)
            .resizable(true)
            .show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(220.0).show(ui, |ui| {
                    egui::Grid::new("nm_grid").striped(true).num_columns(3).show(ui, |ui| {
                        ui.strong("名称");
                        ui.strong("引用位置");
                        ui.strong("");
                        ui.end_row();
                        for (i, (name, refers)) in rows.iter().enumerate() {
                            ui.label(name);
                            ui.label(refers);
                            ui.horizontal(|ui| {
                                if ui.small_button("编辑").clicked() {
                                    start_edit = Some(i);
                                }
                                if ui.small_button("删除").clicked() {
                                    del = Some(i);
                                }
                            });
                            ui.end_row();
                        }
                    });
                });
                ui.separator();
                ui.horizontal(|ui| {
                    ui.label("名称");
                    ui.add(egui::TextEdit::singleline(&mut self.name_new).desired_width(120.0));
                    ui.label("引用");
                    ui.add(egui::TextEdit::singleline(&mut self.name_refers).desired_width(200.0));
                    ui.checkbox(&mut self.name_scope_local, "仅当前工作表");
                    if ui.button(if self.name_edit_idx.is_some() { "保存" } else { "新建" }).clicked() {
                        submit = true;
                    }
                });
                if !self.name_err.is_empty() {
                    ui.colored_label(egui::Color32::from_rgb(190, 40, 40), &self.name_err);
                }
                ui.weak("引用写法：Sheet1!$A$1:$B$3，或常量 ={\"甲\";\"乙\"}");
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "关闭").clicked() {
                        close = true;
                    }
                });
            });
        self.name_mgr = open && !close;
        if let Some(i) = start_edit {
            let item = self.wb.names.get(i).cloned();
            if let Some((name, sheet, refers)) = item {
                self.name_new = name;
                self.name_refers = refers;
                self.name_scope_local = sheet == Some(self.sheet_idx);
                self.name_edit_idx = Some(i);
            }
        }
        if let Some(i) = del {
            if i < self.wb.names.len() {
                self.wb.names.remove(i);
                self.wb.names_dirty = true;
                self.wb.dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.recalc_all_and_deps_adaptive();
                self.status = "已删除名称".into();
            }
        }
        if submit {
            let name = self.name_new.trim().to_string();
            let refers = self.name_refers.trim().to_string();
            let valid = Self::valid_defined_name(&name) && self.valid_name_refers(&refers);
            let dup = self
                .wb
                .names
                .iter()
                .enumerate()
                .any(|(k, (n, sh, _))| {
                    k != self.name_edit_idx.unwrap_or(usize::MAX)
                        && n.eq_ignore_ascii_case(&name)
                        && *sh == if self.name_scope_local { Some(self.sheet_idx) } else { None }
                });
            if !valid {
                self.name_err = "名称要以字母/下划线开头且不能是 A1/R1C1；引用要写成 Sheet1!$A$1:$B$3、={...} 或 =SUM(...)".into();
            } else if dup {
                self.name_err = "名称已存在".into();
            } else {
                self.name_err.clear();
                match self.name_edit_idx.take() {
                    Some(i) if i < self.wb.names.len() => {
                        self.wb.names[i].0 = name;
                        self.wb.names[i].1 = if self.name_scope_local { Some(self.sheet_idx) } else { None };
                        self.wb.names[i].2 = refers;
                    }
                    _ => self.wb.names.push((
                        name,
                        if self.name_scope_local { Some(self.sheet_idx) } else { None },
                        refers,
                    )),
                }
                self.wb.names_dirty = true;
                self.wb.dirty = true;
                self.name_new.clear();
                self.name_refers.clear();
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.recalc_all_and_deps_adaptive();
                self.status = "名称已保存".into();
            }
        }
    }

    /// 工作表保护：设置/撤销密码
    fn protect_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.protect_dlg.take() else { return };
        let mut open = true;
        let mut apply = false;
        let title = if d.unprotect { "撤销工作表保护" } else { "保护工作表" };
        ui_kit::window(ctx, title, 320.0).open(&mut open).show(ctx, |ui| {
            ui.add_space(4.0);
            ui.label(if d.unprotect {
                "输入保护密码（没有密码直接确定）"
            } else {
                "设置密码后，锁定单元格将不能编辑；留空表示只防误改、不设密码"
            });
            ui.add_space(6.0);
            ui.horizontal(|ui| {
                ui.label("密码");
                ui.add(
                    egui::TextEdit::singleline(&mut d.pw)
                        .password(true)
                        .desired_width(180.0),
                );
            });
            if !d.unprotect {
                ui.horizontal(|ui| {
                    ui.label("确认");
                    ui.add(
                        egui::TextEdit::singleline(&mut d.confirm)
                            .password(true)
                            .desired_width(180.0),
                    );
                });
                ui.add_space(6.0);
                ui.label(egui::RichText::new("允许此工作表的所有用户进行：").strong());
                egui::ScrollArea::vertical()
                    .max_height(210.0)
                    .show(ui, |ui| {
                        use sheetcore::protection::ProtPerms as P;
                        let mut row = |ui: &mut egui::Ui, label: &str, v: &mut bool| {
                            ui.checkbox(v, label);
                        };
                        let P {
                            select_locked,
                            select_unlocked,
                            format_cells,
                            format_columns,
                            format_rows,
                            insert_columns,
                            insert_rows,
                            delete_columns,
                            delete_rows,
                            insert_links,
                            sort,
                            auto_filter,
                            pivot_tables,
                            edit_objects,
                            edit_scenarios,
                        } = &mut d.perms;
                        row(ui, "选定锁定单元格", select_locked);
                        row(ui, "选定未锁定的单元格", select_unlocked);
                        row(ui, "设置单元格格式", format_cells);
                        row(ui, "设置列格式", format_columns);
                        row(ui, "设置行格式", format_rows);
                        row(ui, "插入列", insert_columns);
                        row(ui, "插入行", insert_rows);
                        row(ui, "删除列", delete_columns);
                        row(ui, "删除行", delete_rows);
                        row(ui, "插入超链接", insert_links);
                        row(ui, "排序", sort);
                        row(ui, "使用自动筛选", auto_filter);
                        row(ui, "使用数据透视表", pivot_tables);
                        row(ui, "编辑对象", edit_objects);
                        row(ui, "编辑方案", edit_scenarios);
                    });
            }
            if !d.err.is_empty() {
                ui.colored_label(egui::Color32::from_rgb(200, 60, 60), &d.err);
            }
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "确定").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    open = false;
                }
            });
        });
        if apply {
            if !d.unprotect && d.pw != d.confirm {
                d.err = "两次输入的密码不一致".into();
                self.protect_dlg = Some(d);
                return;
            }
            let sh = self.wb.sheet_mut(self.sheet_idx);
            if d.unprotect {
                let ok = sh
                    .protection
                    .as_ref()
                    .map(|p| p.verify(&d.pw))
                    .unwrap_or(false);
                if !ok {
                    d.err = "密码不正确".into();
                    self.protect_dlg = Some(d);
                    return;
                }
                sh.protection = None;
                sh.protect_dirty = true;
                self.wb.dirty = true;
                self.status = "已撤销工作表保护".into();
            } else {
                let mut p = sheetcore::protection::SheetProtection::new_with_password(&d.pw);
                p.perms = d.perms;
                // objects/scenarios 与「编辑对象/编辑方案」是同一件事的两种写法
                p.objects = !d.perms.edit_objects;
                p.scenarios = !d.perms.edit_scenarios;
                sh.protection = Some(p);
                sh.protect_dirty = true;
                self.wb.dirty = true;
                self.status = "工作表已保护".into();
            }
            open = false;
        }
        if open {
            self.protect_dlg = Some(d);
        }
    }

    /// 列宽/行高对话框（表头右键 → 列宽…/行高…）
    /// 页眉和页脚
    /// UI-26：打开页面设置。先记快照，取消时完整恢复。
    fn open_page_setup(&mut self) {
        if self.page_setup_open {
            return;
        }
        let page = self.wb.sheet(self.sheet_idx).page.clone();
        self.page_setup_sheet = self.wb.sheet(self.sheet_idx).identity;
        if std::env::var("SC_PAGE_LOG").is_ok() {
            eprintln!(
                "[page] landscape={} paper={} fit={} w={} h={} scale={} titles={:?} margins={:?}",
                page.landscape, page.paper, page.fit_to_page, page.fit_width, page.fit_height,
                page.scale, page.title_rows, page.margins
            );
        }
        self.page_setup_draft = page;
        self.page_setup_open = true;
        if self.page_setup_printers.is_empty() {
            self.refresh_printers();
        }
        if self.print_range == 2 {
            let total = sheetcore::print::paginate(
                self.wb.sheet(self.sheet_idx),
                &self.wb.sheet(self.sheet_idx).page,
            )
            .pages
            .len()
            .max(1) as u32;
            self.print_to = self.print_to.clamp(self.print_from.max(1), total);
        }
    }

    /// Only an accepted page setup becomes eligible for saving.
    fn apply_page_setup_draft(&mut self) {
        let draft = self.page_setup_draft.clone();
        if self.wb.sheet(self.sheet_idx).page == draft {
            return;
        }
        let sh = self.wb.sheet_mut(self.sheet_idx);
        sh.page = draft;
        sh.page_dirty = true;
        self.wb.dirty = true;
    }

    fn cancel_page_setup(&mut self) {
        self.page_setup_open = false;
        self.status = "已取消页面设置".into();
    }

    /// 系统打印机列表：第一行带 * 的是默认打印机。失败就只留“系统默认”。
    fn refresh_printers(&mut self) {
        self.page_setup_printers.clear();
        #[cfg(windows)]
        {
            let out = hidden_console_cmd("powershell")
                .args([
                    "-NoProfile",
                    "-Command",
                    "Get-CimInstance Win32_Printer | ForEach-Object { if ($_.Default) { '*' + $_.Name } else { $_.Name } }",
                ])
                .output();
            if let Ok(out) = out {
                let text = String::from_utf8_lossy(&out.stdout);
                for line in text.lines() {
                    let name = line.trim().trim_start_matches('\u{feff}');
                    if name.is_empty() {
                        continue;
                    }
                    let is_default = name.starts_with('*');
                    let name = name.trim_start_matches('*').trim().to_string();
                    if self.page_setup_printer.is_empty() && is_default {
                        self.page_setup_printer = name.clone();
                    }
                    if !self.page_setup_printers.contains(&name) {
                        self.page_setup_printers.push(name);
                    }
                }
            }
        }
    }

    /// Preview the draft while the workbook continues saving committed edits.
    fn page_setup_dialog(&mut self, ctx: &egui::Context) {
        if !self.page_setup_open {
            return;
        }
        if self.wb.sheet(self.sheet_idx).identity != self.page_setup_sheet {
            self.page_setup_open = false;
            return;
        }
        let sel = self.sel;
        let sel_rect = self.sel_rect();
        let printers = self.page_setup_printers.clone();
        let printer_cur = self.page_setup_printer.clone();
        let total_pages = sheetcore::print::paginate(
            self.wb.sheet(self.sheet_idx),
            &self.page_setup_draft,
        )
        .pages
        .len()
        .max(1) as u32;
        let mut draft = self.page_setup_draft.clone();
        let mut printer = printer_cur;
        let mut copies = self.print_copies;
        let mut range = self.print_range;
        let mut from = self.print_from;
        let mut to = self.print_to;
        let mut open = true;
        let mut ok = false;
        let mut cancel = false;
        let mut do_print = false;
        let mut do_export = false;

        ui_kit::window(ctx, "页面设置", 560.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(560.0).show(ui, |ui| {
                    dlg_section(ui, "纸张与方向");
                    ui.horizontal(|ui| {
                        let paper = draft.paper_label().to_string();
                        egui::ComboBox::from_id_salt("page_paper")
                            .selected_text(paper)
                            .width(120.0)
                            .show_ui(ui, |ui| {
                                for (code, name) in [
                                    (9u16, "A4"),
                                    (8, "A3"),
                                    (10, "A5"),
                                    (1, "Letter"),
                                    (4, "Legal"),
                                    (3, "Tabloid"),
                                    (5, "Statement"),
                                ] {
                                    ui.selectable_value(&mut draft.paper, code, name);
                                }
                            });
                        ui.selectable_value(&mut draft.landscape, false, "纵向");
                        ui.selectable_value(&mut draft.landscape, true, "横向");
                    });

                    dlg_section(ui, "页边距（毫米）");
                    let mut mm = [
                        draft.margins[0] * 25.4,
                        draft.margins[1] * 25.4,
                        draft.margins[2] * 25.4,
                        draft.margins[3] * 25.4,
                        draft.margins[4] * 25.4,
                        draft.margins[5] * 25.4,
                    ];
                    egui::Grid::new("page_margins").num_columns(2).show(ui, |ui| {
                        ui.label("左");
                        ui.add(egui::Slider::new(&mut mm[0], 0.0..=50.0).suffix(" mm"));
                        ui.end_row();
                        ui.label("右");
                        ui.add(egui::Slider::new(&mut mm[1], 0.0..=50.0).suffix(" mm"));
                        ui.end_row();
                        ui.label("上");
                        ui.add(egui::Slider::new(&mut mm[2], 0.0..=50.0).suffix(" mm"));
                        ui.end_row();
                        ui.label("下");
                        ui.add(egui::Slider::new(&mut mm[3], 0.0..=50.0).suffix(" mm"));
                        ui.end_row();
                        ui.label("页眉");
                        ui.add(egui::Slider::new(&mut mm[4], 0.0..=30.0).suffix(" mm"));
                        ui.end_row();
                        ui.label("页脚");
                        ui.add(egui::Slider::new(&mut mm[5], 0.0..=30.0).suffix(" mm"));
                        ui.end_row();
                    });
                    for i in 0..6 {
                        draft.margins[i] = mm[i] / 25.4;
                    }
                    ui.horizontal(|ui| {
                        ui.checkbox(&mut draft.center_h, "水平居中");
                        ui.checkbox(&mut draft.center_v, "垂直居中");
                        ui.checkbox(&mut draft.gridlines, "打印网格线");
                        ui.checkbox(&mut draft.headings, "打印行号列标");
                    });

                    dlg_section(ui, "缩放");
                    ui.horizontal(|ui| {
                        ui.selectable_value(&mut draft.fit_to_page, false, "缩放");
                        ui.add_enabled(
                            !draft.fit_to_page,
                            egui::Slider::new(&mut draft.scale, 10..=400).suffix("%"),
                        );
                        ui.selectable_value(&mut draft.fit_to_page, true, "调整为");
                        ui.add_enabled(
                            draft.fit_to_page,
                            egui::Slider::new(&mut draft.fit_width, 0..=10).text("页宽"),
                        );
                        ui.label("×");
                        ui.add_enabled(
                            draft.fit_to_page,
                            egui::Slider::new(&mut draft.fit_height, 0..=10).text("页高"),
                        );
                        ui.label("（0=自动）");
                    });

                    dlg_section(ui, "打印区域与重复标题");
                    ui.horizontal(|ui| {
                        let area = match draft.print_area {
                            Some((r1, c1, r2, c2)) => format!(
                                "{}:{}",
                                sheetcore::model::cell_name(r1, c1),
                                sheetcore::model::cell_name(r2, c2)
                            ),
                            None => "未设置（打印整个已用区域）".into(),
                        };
                        ui.label(format!("打印区域：{area}"));
                        if ui.button("用当前选区").clicked() {
                            draft.print_area = Some(sel_rect);
                        }
                        if ui.button("清除").clicked() {
                            draft.print_area = None;
                        }
                    });
                    ui.horizontal(|ui| {
                        let rows = draft
                            .title_rows
                            .map(|(a, b)| format!("第 {}–{} 行", a + 1, b + 1))
                            .unwrap_or_else(|| "无".into());
                        ui.label(format!("顶端标题行：{rows}"));
                        if ui.button("用选区行").clicked() {
                            draft.title_rows = Some((sel_rect.0, sel_rect.2));
                        }
                        if ui.button("用当前行").clicked() {
                            draft.title_rows = Some((sel.0, sel.0));
                        }
                        if ui.button("清除").clicked() {
                            draft.title_rows = None;
                        }
                    });
                    ui.horizontal(|ui| {
                        let cols = draft
                            .title_cols
                            .map(|(a, b)| format!("第 {}–{} 列", a + 1, b + 1))
                            .unwrap_or_else(|| "无".into());
                        ui.label(format!("左侧标题列：{cols}"));
                        if ui.button("用选区列").clicked() {
                            draft.title_cols = Some((sel_rect.1, sel_rect.3));
                        }
                        if ui.button("用当前列").clicked() {
                            draft.title_cols = Some((sel.1, sel.1));
                        }
                        if ui.button("清除").clicked() {
                            draft.title_cols = None;
                        }
                    });

                    dlg_section(ui, "页眉和页脚");
                    ui.add(
                        egui::TextEdit::singleline(&mut draft.header)
                            .desired_width(f32::INFINITY)
                            .hint_text("页眉，例如 &L左&C中&R右"),
                    );
                    ui.add(
                        egui::TextEdit::singleline(&mut draft.footer)
                            .desired_width(f32::INFINITY)
                            .hint_text("页脚，例如 第 &P 页，共 &N 页"),
                    );

                    dlg_section(ui, "分页符");
                    ui.horizontal(|ui| {
                        if ui
                            .add_enabled(sel.0 > 0, egui::Button::new(format!("在第 {} 行前插入水平分页", sel.0 + 1)))
                            .clicked()
                        {
                            draft.row_breaks.push(sel.0);
                            draft.row_breaks.sort_unstable();
                            draft.row_breaks.dedup();
                        }
                        if ui
                            .add_enabled(
                                !draft.row_breaks.is_empty(),
                                egui::Button::new(format!("清除水平分页（{}）", draft.row_breaks.len())),
                            )
                            .clicked()
                        {
                            draft.row_breaks.clear();
                        }
                    });
                    ui.horizontal(|ui| {
                        if ui
                            .add_enabled(sel.1 > 0, egui::Button::new(format!("在第 {} 列前插入垂直分页", sel.1 + 1)))
                            .clicked()
                        {
                            draft.col_breaks.push(sel.1);
                            draft.col_breaks.sort_unstable();
                            draft.col_breaks.dedup();
                        }
                        if ui
                            .add_enabled(
                                !draft.col_breaks.is_empty(),
                                egui::Button::new(format!("清除垂直分页（{}）", draft.col_breaks.len())),
                            )
                            .clicked()
                        {
                            draft.col_breaks.clear();
                        }
                    });

                    dlg_section(ui, "打印");
                    ui.horizontal(|ui| {
                        ui.label("打印机");
                        let text = if printer.is_empty() { "系统默认".to_string() } else { printer.clone() };
                        egui::ComboBox::from_id_salt("page_printer")
                            .selected_text(text)
                            .width(300.0)
                            .show_ui(ui, |ui| {
                                if ui.selectable_label(printer.is_empty(), "系统默认").clicked() {
                                    printer.clear();
                                }
                                for p in &printers {
                                    if ui.selectable_label(&printer == p, p).clicked() {
                                        printer = p.clone();
                                    }
                                }
                            });
                        if ui.button("刷新").clicked() {
                            self.page_setup_printers.clear();
                            self.refresh_printers();
                        }
                    });
                    ui.horizontal(|ui| {
                        ui.label("份数");
                        ui.add(egui::Slider::new(&mut copies, 1..=99));
                        ui.label("页码");
                        ui.selectable_value(&mut range, 0, "全部");
                        ui.selectable_value(&mut range, 1, "当前页");
                        ui.selectable_value(&mut range, 2, "自定义");
                        if range == 2 {
                            ui.add(egui::Slider::new(&mut from, 1..=total_pages.max(1)).text("从"));
                            ui.add(egui::Slider::new(&mut to, 1..=total_pages.max(1)).text("到"));
                        }
                    });
                    ui.label(format!("当前分页：共 {total_pages} 页"));
                    ui.horizontal(|ui| {
                        if ui.button("导出 PDF…").clicked() {
                            do_export = true;
                        }
                    });
                });
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        cancel = true;
                    }
                    if ui_kit::secondary_button(ui, "打印…").clicked() {
                        do_print = true;
                        ok = true;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });

        self.page_setup_draft = draft;
        self.page_setup_printer = printer;
        self.print_copies = copies;
        self.print_range = range;
        self.print_from = from;
        self.print_to = to;
        if ok {
            self.apply_page_setup_draft();
            self.page_setup_open = false;
            self.status = "页面设置已应用".into();
            if do_export {
                self.export_pdf_dialog();
            }
            if do_print {
                self.print_to_printer();
            }
        } else if cancel || !open {
            self.cancel_page_setup();
        }
    }

    fn header_footer_dialog(&mut self, ctx: &egui::Context) {
        if !self.hf_dlg {
            return;
        }
        let mut open = true;
        let mut ok = false;
        let mut header = self.wb.sheet(self.sheet_idx).page.header.clone();
        let mut footer = self.wb.sheet(self.sheet_idx).page.footer.clone();
        ui_kit::window(ctx, "页眉和页脚", 420.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                dlg_section(ui, "页眉");
                ui.add(
                    egui::TextEdit::singleline(&mut header)
                        .desired_width(f32::INFINITY)
                        .hint_text("例如：&L左&中&R右"),
                );
                dlg_section(ui, "页脚");
                ui.add(
                    egui::TextEdit::singleline(&mut footer)
                        .desired_width(f32::INFINITY)
                        .hint_text("例如：第 &P 页，共 &N 页"),
                );
                ui.label(
                    egui::RichText::new("可用代码：&L 左、&C 中、&R 右、&P 页码、&N 总页数、&D 日期")
                        .size(10.5)
                        .weak(),
                );
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });
        if ok {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.page.header = header;
            sh.page.footer = footer;
            sh.page_dirty = true;
            self.wb.dirty = true;
            self.hf_dlg = false;
            self.status = "已更新页眉页脚".into();
        } else if !open {
            self.hf_dlg = false;
        }
    }

    // ---------------------------------------------------------------- 迷你图

    /// 选区里第一条迷你图（上下文页签与状态都用它）
    fn spark_at_sel(&self) -> Option<sheetcore::sparkline::Sparkline> {
        let (r1, c1, r2, c2) = self.sel_rect();
        self.wb
            .sheet(self.sheet_idx)
            .sparklines
            .iter()
            .find(|s| s.r >= r1 && s.r <= r2 && s.c >= c1 && s.c <= c2)
            .cloned()
    }

    /// 选区里所有迷你图的锚点（排好序，编辑多条时用）
    fn spark_anchors_in_sel(&self) -> Vec<(u32, u32)> {
        let (r1, c1, r2, c2) = self.sel_rect();
        let mut v: Vec<(u32, u32)> = self
            .wb
            .sheet(self.sheet_idx)
            .sparklines
            .iter()
            .filter(|s| s.r >= r1 && s.r <= r2 && s.c >= c1 && s.c <= c2)
            .map(|s| (s.r, s.c))
            .collect();
        v.sort_unstable();
        v
    }

    /// 打开「创建迷你图」：数据默认取当前选区，位置默认选区右侧一格。
    fn spark_open_create(&mut self, kind: sheetcore::sparkline::SparkKind) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let single = r1 == r2 && c1 == c2;
        let source = if single {
            String::new()
        } else {
            format!("{}:{}", cell_name(r1, c1), cell_name(r2, c2))
        };
        let location = if single {
            cell_name(r2, c2 + 1)
        } else {
            cell_name(r2, c2 + 1)
        };
        self.spark_dlg = Some(SparkDlg {
            kind,
            source,
            location,
            ..Default::default()
        });
    }

    /// 打开「编辑迷你图」：用选区内第一条的属性填表，作用到选区内所有迷你图。
    fn spark_open_edit(&mut self) {
        let Some(sp) = self.spark_at_sel() else {
            self.status = "先选中一个带迷你图的单元格".into();
            return;
        };
        let own = self.wb.sheet(self.sheet_idx).name.clone();
        let anchors = self.spark_anchors_in_sel();
        let location = if anchors.len() == 1 {
            cell_name(sp.r, sp.c)
        } else {
            let rs: Vec<u32> = anchors.iter().map(|a| a.0).collect();
            let cs: Vec<u32> = anchors.iter().map(|a| a.1).collect();
            format!(
                "{}:{}",
                cell_name(*rs.iter().min().unwrap(), *cs.iter().min().unwrap()),
                cell_name(*rs.iter().max().unwrap(), *cs.iter().max().unwrap())
            )
        };
        self.spark_dlg = Some(SparkDlg {
            kind: sp.kind,
            source: sp.data_ref(&own),
            location,
            color: sp.color,
            markers: sp.markers,
            high: sp.high,
            low: sp.low,
            first: sp.first,
            last: sp.last,
            negative: sp.negative,
            axis: sp.axis,
            empty: sp.empty,
            edit: anchors,
            msg: String::new(),
        });
    }

    /// 对选区内所有迷你图改一处属性
    fn spark_apply_sel<F: Fn(&mut sheetcore::sparkline::Sparkline)>(&mut self, f: F) {
        let anchors = self.spark_anchors_in_sel();
        if anchors.is_empty() {
            self.status = "先选中带迷你图的单元格".into();
            return;
        }
        let sh = self.wb.sheet_mut(self.sheet_idx);
        for sp in sh.sparklines.iter_mut() {
            if anchors.contains(&(sp.r, sp.c)) {
                f(sp);
            }
        }
        sh.sparklines_dirty = true;
        self.wb.dirty = true;
        // 装载期的后台重算会整份替换 wb：改过模型必须同时推进 doc_gen
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已修改 {} 条迷你图", anchors.len());
    }

    /// 清除选区内的迷你图
    fn spark_delete_in_sel(&mut self) {
        let anchors = self.spark_anchors_in_sel();
        if anchors.is_empty() {
            self.status = "选区内没有迷你图".into();
            return;
        }
        let n = anchors.len();
        let sh = self.wb.sheet_mut(self.sheet_idx);
        sh.sparklines.retain(|s| !anchors.contains(&(s.r, s.c)));
        sh.sparklines_dirty = true;
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已清除 {n} 条迷你图");
    }

    /// 把对话框里的设置写进模型。返回错误文本（对话框里显示）。
    fn spark_commit(&mut self, d: &SparkDlg) -> Result<usize, String> {
        let own = self.wb.sheet(self.sheet_idx).name.clone();
        let src_txt = d.source.trim();
        if src_txt.is_empty() {
            return Err("请填写数据范围，例如 A1:E1".into());
        }
        let Some((sheet_name, srect)) = sheetcore::sparkline::parse_ref(src_txt) else {
            return Err(format!("数据范围「{src_txt}」看不懂，写成 A1:E1 或 Sheet1!A1:E1"));
        };
        let src_sheet = match sheet_name {
            Some(n) if n != own => {
                if !self.wb.sheets.iter().any(|s| s.name == n) {
                    return Err(format!("没有名为「{n}」的工作表"));
                }
                Some(n)
            }
            _ => None,
        };
        let loc_txt = d.location.trim();
        if loc_txt.is_empty() {
            return Err("请填写位置范围（迷你图放在哪个单元格）".into());
        }
        let Some((loc_sheet, loc)) = sheetcore::sparkline::parse_ref(loc_txt) else {
            return Err(format!("位置范围「{loc_txt}」看不懂"));
        };
        if let Some(n) = loc_sheet {
            if n != own {
                return Err("迷你图只能放在当前工作表上".into());
            }
        }
        let loc_rows = loc.2 - loc.0 + 1;
        let loc_cols = loc.3 - loc.1 + 1;
        let n_loc = loc_rows * loc_cols;
        let src_rows = srect.2 - srect.0 + 1;
        let src_cols = srect.3 - srect.1 + 1;
        if n_loc > 4096 {
            return Err("位置范围太大（上限 4096 格）".into());
        }
        // 数据区与位置怎么一一对应：单格 → 整段；多行单列 → 逐行；单行多列 → 逐列
        let mut plan: Vec<((u32, u32), (u32, u32, u32, u32))> = Vec::new();
        if n_loc == 1 {
            plan.push(((loc.0, loc.1), srect));
        } else if loc_cols == 1 && src_rows == loc_rows {
            for i in 0..loc_rows {
                plan.push(((loc.0 + i, loc.1), (srect.0 + i, srect.1, srect.0 + i, srect.3)));
            }
        } else if loc_rows == 1 && src_cols == loc_cols {
            for j in 0..loc_cols {
                plan.push(((loc.0, loc.1 + j), (srect.0, srect.1 + j, srect.2, srect.1 + j)));
            }
        } else {
            return Err(format!(
                "位置范围 {loc_rows} 行 × {loc_cols} 列，数据范围 {src_rows} 行 × {src_cols} 列：\
                 多格位置要和数据的行数或列数一一对应"
            ));
        }
        let base = sheetcore::sparkline::Sparkline {
            kind: d.kind,
            color: d.color,
            markers: d.markers,
            high: d.high,
            low: d.low,
            first: d.first,
            last: d.last,
            negative: d.negative,
            axis: d.axis,
            empty: d.empty,
            source_sheet: src_sheet,
            ..Default::default()
        };
        let sh = self.wb.sheet_mut(self.sheet_idx);
        // 编辑模式先摘掉被编辑的那几条，再按新设置写回去
        if !d.edit.is_empty() {
            sh.sparklines.retain(|s| !d.edit.contains(&(s.r, s.c)));
        }
        let mut made = 0usize;
        for ((r, c), rect) in plan {
            sh.sparklines.retain(|s| !(s.r == r && s.c == c));
            sh.sparklines.push(sheetcore::sparkline::Sparkline {
                r,
                c,
                rect,
                ..base.clone()
            });
            made += 1;
        }
        // 同一锚点保持按行列有序，写回时同格式的自动成组
        sh.sparklines.sort_by_key(|s| (s.c, s.r));
        sh.sparklines_dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let first = sh.sparklines.iter().find(|s| s.c == loc.1 && s.r >= loc.0).map(|s| (s.r, s.c));
        self.wb.dirty = true;
        if let Some((r, c)) = first {
            self.sel = (r, c);
            self.sel_end = (r, c);
        }
        self.status = format!("已创建 {made} 条迷你图");
        Ok(made)
    }

    // ---------------------------------------------------------------- 工作表视图 / 窗口

    fn views_key(&self) -> String {
        self.wb
            .path
            .as_ref()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default()
    }

    /// 把当前缩放/冻结/选区存成一个命名视图
    fn view_capture(&self, name: &str) -> ui_prefs::SavedView {
        ui_prefs::SavedView {
            name: name.to_string(),
            sheet: self.sheet_idx,
            zoom: self.zoom,
            freeze: self.wb.sheet(self.sheet_idx).freeze,
            sel: self.sel,
        }
    }

    /// 应用一个视图
    fn view_apply(&mut self, idx: usize) {
        let Some(v) = self.views.get(idx).cloned() else { return };
        let target = v.sheet.min(self.wb.sheets.len().saturating_sub(1));
        if target != self.sheet_idx && !self.switch_sheet_view(target) {
            return;
        }
        self.zoom = v.zoom.clamp(0.5, 2.5);
        self.wb.sheet_mut(self.sheet_idx).freeze = v.freeze;
        self.wb.sheet_mut(self.sheet_idx).freeze_dirty = true;
        self.sel = v.sel;
        self.sel_end = v.sel;
        self.view_active = Some(idx);
        self.ensure_visible();
        self.status = format!("已切换到工作表视图「{}」", v.name);
    }

    fn view_new_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut name) = self.view_new.clone() else { return };
        let mut open = true;
        let mut ok = false;
        ui_kit::window(ctx, "新建工作表视图", 360.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui_kit::field(ui, "名称", |ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut name)
                            .desired_width(220.0)
                            .hint_text("例如：看一季度"),
                    );
                });
                ui.label(
                    egui::RichText::new("保存当前缩放、冻结窗格和选区；视图存在本机（不进 xlsx）")
                        .size(10.5)
                        .weak(),
                );
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });
        if ok && !name.trim().is_empty() {
            let v = self.view_capture(name.trim());
            // 同名覆盖
            if let Some(i) = self.views.iter().position(|x| x.name == v.name) {
                self.views[i] = v;
                self.view_active = Some(i);
            } else {
                self.views.push(v);
                self.view_active = Some(self.views.len() - 1);
            }
            ui_prefs::save_views(&self.views_key(), &self.views);
            self.status = format!("已保存工作表视图「{}」", name.trim());
            self.view_new = None;
            return;
        }
        self.view_new = if open { Some(name) } else { None };
    }

    fn views_window(&mut self, ctx: &egui::Context) {
        if !self.views_open {
            return;
        }
        let mut open = true;
        let mut pick: Option<usize> = None;
        let mut del: Option<usize> = None;
        let views = self.views.clone();
        let active = self.view_active;
        ui_kit::window(ctx, "工作表视图", 420.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                if views.is_empty() {
                    ui.label("还没有保存的视图：用「视图 → 新建」把当前缩放/冻结/选区存下来。");
                }
                for (i, v) in views.iter().enumerate() {
                    ui.horizontal(|ui| {
                        let mark = if active == Some(i) { "● " } else { "　" };
                        if ui
                            .selectable_label(active == Some(i), format!("{mark}{}", v.name))
                            .clicked()
                        {
                            pick = Some(i);
                        }
                        ui.label(
                            egui::RichText::new(format!(
                                "{} 表 · {:.0}% · {}",
                                v.sheet + 1,
                                v.zoom * 100.0,
                                v.freeze
                                    .map(|(r, c)| format!("冻结 {r} 行 {c} 列"))
                                    .unwrap_or_else(|| "无冻结".into())
                            ))
                            .size(10.5)
                            .weak(),
                        );
                        if ui.small_button("删除").clicked() {
                            del = Some(i);
                        }
                    });
                }
            });
        if let Some(i) = pick {
            self.view_apply(i);
        }
        if let Some(i) = del {
            self.views.remove(i);
            self.view_active = None;
            ui_prefs::save_views(&self.views_key(), &self.views);
            self.status = "已删除视图".into();
        }
        self.views_open = open;
    }

    /// 取消隐藏：列出所有隐藏的表
    fn unhide_window(&mut self, ctx: &egui::Context) {
        if !self.unhide_open {
            return;
        }
        let mut open = true;
        let mut show_idx: Option<usize> = None;
        let hidden: Vec<(usize, String)> = self
            .wb
            .sheets
            .iter()
            .enumerate()
            .filter(|(_, s)| s.hidden)
            .map(|(i, s)| (i, s.name.clone()))
            .collect();
        ui_kit::window(ctx, "取消隐藏", 340.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                if hidden.is_empty() {
                    ui.label("当前工作簿没有被隐藏的工作表。");
                }
                for (i, name) in &hidden {
                    if ui.selectable_label(false, name).clicked() {
                        show_idx = Some(*i);
                    }
                }
                ui.label(
                    egui::RichText::new("选中一张表即可恢复显示").size(10.5).weak(),
                );
            });
        if let Some(i) = show_idx {
            let sh = self.wb.sheet_mut(i);
            sh.hidden = false;
            sh.hidden_dirty = true;
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = format!("已取消隐藏「{}」", self.wb.sheet(i).name);
            self.unhide_open = false;
            return;
        }
        self.unhide_open = open;
    }

    /// UI-16：把工作表移到指定插入位置（0..=len，len 为末尾）。
    fn move_sheet_to(&mut self, from: usize, target: usize) -> bool {
        let len = self.wb.sheets.len();
        if from >= len || target > len || from == target || from + 1 == target {
            return false;
        }
        if !self.can_change_sheets() {
            return false;
        }
        let active_id = self.wb.sheet(self.sheet_idx).identity;
        let mut dest = if target > from { target - 1 } else { target };
        dest = dest.min(len - 1);
        if dest == from {
            return false;
        }
        let mut cur = from;
        while cur < dest {
            if !sheetcore::sheet_ops::move_sheet(&mut self.wb, cur, cur + 1) {
                break;
            }
            cur += 1;
        }
        while cur > dest {
            if !sheetcore::sheet_ops::move_sheet(&mut self.wb, cur, cur - 1) {
                break;
            }
            cur -= 1;
        }
        if let Some(new_idx) = self.wb.sheets.iter().position(|s| s.identity == active_id) {
            self.sheet_idx = new_idx;
        }
        self.finish_sheet_change();
        self.status = format!(
            "已移动「{}」到第 {} 位",
            self.wb.sheet(cur).name,
            cur + 1
        );
        true
    }

    /// UI-16：复制工作表到指定插入位置（0..=len，len 为末尾）。
    fn copy_sheet_to(&mut self, from: usize, target: usize) -> bool {
        let len = self.wb.sheets.len();
        if from >= len {
            return false;
        }
        if !self.can_change_sheets() {
            return false;
        }
        // 插入会移动旧索引；先按稳定 identity 记住当前表视图，插完再按 ID 找回原表。
        let active_id = self.wb.sheet(self.sheet_idx).identity;
        self.remember_sheet_view();
        let mut copy = self.wb.sheets[from].clone();
        let base = copy.name.clone();
        let mut n = 2;
        let suffix = format!(" ({n})");
        let mut name = format!(
            "{}{suffix}",
            base.chars().take(31usize.saturating_sub(suffix.chars().count())).collect::<String>()
        );
        while self.wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
            n += 1;
            let suffix = format!(" ({n})");
            name = format!(
                "{}{suffix}",
                base.chars().take(31usize.saturating_sub(suffix.chars().count())).collect::<String>()
            );
        }
        copy.name = name.clone();
        copy.source_part = None;
        copy.charts.clear();
        copy.tables.clear();
        copy.hidden = false;
        copy.edited = true;
        let at = target.min(self.wb.sheets.len());
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, at, copy) {
            self.status = "复制工作表失败：名称无效或已存在".into();
            return false;
        }
        // 插入点可能等于旧索引；不能直接拿旧 sheet_idx 去 switch（会被 same-index 当成
        // 已切表而跳过 load_sheet_view）。先按 identity 恢复原活动表，再切到副本。
        self.sheet_idx = self
            .wb
            .sheets
            .iter()
            .position(|s| s.identity == active_id)
            .unwrap_or(at);
        self.switch_sheet_view(at);
        self.finish_sheet_change();
        self.status = format!("已复制为「{name}」");
        true
    }

    /// UI-16：移动或复制工作表的对话框。
    fn sheet_move_window(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.sheet_move_dlg else {
            return;
        };
        let len = self.wb.sheets.len();
        let src_name = self.wb.sheets.get(d.src).map(|s| s.name.clone()).unwrap_or_default();
        let names: Vec<String> = self.wb.sheets.iter().map(|s| s.name.clone()).collect();
        let mut open = true;
        let mut apply = false;
        ui_kit::window(ctx, "移动或复制工作表", 400.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(format!("源工作表：{}", src_name));
                ui.checkbox(&mut d.copy, "建立副本");
                ui.horizontal(|ui| {
                    ui.label("位置");
                    let selected = if d.target >= len {
                        "移到末尾".to_string()
                    } else {
                        format!("移到「{}」之前", names.get(d.target).cloned().unwrap_or_default())
                    };
                    egui::ComboBox::from_id_salt("sheet_move_target")
                        .selected_text(selected)
                        .width(220.0)
                        .show_ui(ui, |ui| {
                            for i in 0..=len {
                                let label = if i == len {
                                    "移到末尾".to_string()
                                } else {
                                    format!("移到「{}」之前", names.get(i).cloned().unwrap_or_default())
                                };
                                ui.selectable_value(&mut d.target, i, label);
                            }
                        });
                });
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked {
                        apply = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                });
            });
        if apply {
            let ok = if d.copy {
                self.copy_sheet_to(d.src, d.target)
            } else {
                self.move_sheet_to(d.src, d.target)
            };
            self.sheet_move_dlg = if open && !ok { Some(d) } else { None };
            return;
        }
        self.sheet_move_dlg = if open { Some(d) } else { None };
    }

    /// UI-16：工作表列表的搜索过滤（隐藏表不参与）。
    fn sheet_list_matches(&self, query: &str) -> Vec<usize> {
        let q = query.trim().to_lowercase();
        self.wb
            .sheets
            .iter()
            .enumerate()
            .filter(|(_, s)| !s.hidden)
            .filter(|(_, s)| q.is_empty() || s.name.to_lowercase().contains(&q))
            .map(|(i, _)| i)
            .collect()
    }

    /// UI-16：工作表列表，带搜索定位；大量工作表时不用横向找标签。
    fn sheet_list_window(&mut self, ctx: &egui::Context) {
        if !self.sheet_list_open {
            return;
        }
        let mut open = true;
        let mut query = self.sheet_list_query.clone();
        let mut pick: Option<usize> = None;
        let sheets: Vec<(usize, String, bool)> = self
            .wb
            .sheets
            .iter()
            .enumerate()
            .map(|(i, s)| (i, s.name.clone(), s.hidden))
            .collect();
        ui_kit::window(ctx, "工作表列表", 360.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.label("搜索");
                    ui.add(
                        egui::TextEdit::singleline(&mut query)
                            .desired_width(240.0)
                            .hint_text("输入表名"),
                    );
                });
                ui.separator();
                egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                    let matches = self.sheet_list_matches(&query);
                    let mut shown = 0usize;
                    for (i, name, hidden) in &sheets {
                        if *hidden || !matches.contains(i) {
                            continue;
                        }
                        shown += 1;
                        let label = if *i == self.sheet_idx {
                            format!("● {name}")
                        } else {
                            format!("　{name}")
                        };
                        if ui.selectable_label(*i == self.sheet_idx, label).clicked() {
                            pick = Some(*i);
                        }
                    }
                    if shown == 0 {
                        ui.weak("没有匹配的工作表");
                    }
                });
            });
        self.sheet_list_query = query;
        if let Some(i) = pick {
            if self.switch_sheet_view(i) {
                self.status = format!("当前工作表：{}", self.wb.sheet(self.sheet_idx).name);
                open = false;
            }
        }
        self.sheet_list_open = open;
    }

    /// 隐藏当前工作表（至少留一张可见）
    fn hide_current_sheet(&mut self) {
        // 隐藏会切表，必须先提交正在编辑的内容；验证拒绝时保留原表、编辑文本、选区。
        if !self.finish_pending_edit() {
            return;
        }
        let visible = self.wb.sheets.iter().filter(|s| !s.hidden).count();
        if visible <= 1 {
            self.status = "至少要留一张可见的工作表".into();
            return;
        }
        let i = self.sheet_idx;
        let name = self.wb.sheet(i).name.clone();
        self.remember_sheet_view();
        let sh = self.wb.sheet_mut(i);
        sh.hidden = true;
        sh.hidden_dirty = true;
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        // 切到下一张可见表，走统一入口（提交/清格式刷/加载视图）。
        if let Some(next) = self
            .wb
            .sheets
            .iter()
            .enumerate()
            .position(|(k, s)| k != i && !s.hidden)
        {
            let _ = self.switch_sheet_view(next);
        }
        self.status = format!("已隐藏「{name}」；视图 → 取消隐藏 可以恢复");
    }

    // ---------------------------------------------------------------- 辅助功能 / 批注导航

    fn a11y_scan(&mut self) {
        self.a11y_list = sheetcore::a11y::scan(&self.wb);
        self.status = format!("辅助功能检查器：{} 项", self.a11y_list.len());
    }

    fn a11y_window(&mut self, ctx: &egui::Context) {
        if !self.a11y_open {
            return;
        }
        let mut open = true;
        let mut jump: Option<(usize, (u32, u32))> = None;
        let mut rescan = false;
        let list = self.a11y_list.clone();
        ui_kit::window(ctx, "辅助功能检查器", 560.0)
            .open(&mut open)
            .resizable(true)
            .default_size([560.0, 380.0])
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    let n = list.len();
                    let (text, color) = if n == 0 {
                        ("一切就绪：没有发现辅助功能问题".to_string(), ui_kit::ACCENT)
                    } else {
                        (format!("发现 {n} 项需要处理"), Color32::from_rgb(192, 0, 0))
                    };
                    ui.label(egui::RichText::new(text).size(12.5).color(color));
                    if ui_kit::secondary_button(ui, "重新检查").clicked() {
                        rescan = true;
                    }
                });
                ui.separator();
                egui::ScrollArea::vertical().max_height(300.0).show(ui, |ui| {
                    egui::Grid::new("a11y_grid")
                        .num_columns(4)
                        .spacing([10.0, 4.0])
                        .striped(true)
                        .show(ui, |ui| {
                            ui.label(egui::RichText::new("工作表").size(11.0).weak());
                            ui.label(egui::RichText::new("位置").size(11.0).weak());
                            ui.label(egui::RichText::new("问题").size(11.0).weak());
                            ui.label(egui::RichText::new("建议").size(11.0).weak());
                            ui.end_row();
                            for it in &list {
                                ui.label(egui::RichText::new(&it.sheet_name).size(11.0));
                                match it.at {
                                    Some((r, c)) => {
                                        if ui.link(cell_name(r, c)).clicked() {
                                            jump = Some((it.sheet, (r, c)));
                                        }
                                    }
                                    None => {
                                        ui.label("—");
                                    }
                                }
                                ui.label(
                                    egui::RichText::new(format!(
                                        "{}：{}",
                                        it.kind.label(),
                                        it.detail
                                    ))
                                    .size(11.0),
                                );
                                ui.label(egui::RichText::new(it.kind.advice()).size(10.5).weak());
                                ui.end_row();
                            }
                        });
                });
            });
        if rescan {
            self.a11y_scan();
        }
        if let Some((si, (r, c))) = jump {
            let target = si.min(self.wb.sheets.len() - 1);
            if target != self.sheet_idx && !self.switch_sheet_view(target) {
                self.a11y_open = open;
                return;
            }
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        self.a11y_open = open;
    }

    /// 合并单元格内部任意坐标统一归一化到左上角锚点（绘制与保存批注均挂在锚点上）
    pub(crate) fn note_anchor(&self, r: u32, c: u32) -> (u32, u32) {
        self.wb
            .sheet(self.sheet_idx)
            .merge_at(r, c)
            .map(|(mr1, mc1, _, _)| (mr1, mc1))
            .unwrap_or((r, c))
    }

    /// 收集当前选区（含交集的合并区域锚点）内所有批注坐标
    pub(crate) fn comment_keys_in_sel(&self) -> Vec<sheetcore::model::CellRef> {
        let rects = self.sel_rects();
        let sh = self.wb.sheet(self.sheet_idx);
        let mut out: Vec<sheetcore::model::CellRef> = sh
            .notes
            .keys()
            .copied()
            .filter(|k| {
                if rects
                    .iter()
                    .any(|&(r1, c1, r2, c2)| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2)
                {
                    return true;
                }
                if let Some((mr1, mc1, mr2, mc2)) = sh.merge_at(k.row, k.col) {
                    if (k.row, k.col) == (mr1, mc1) {
                        return rects
                            .iter()
                            .any(|&(r1, c1, r2, c2)| mr1 <= r2 && mr2 >= r1 && mc1 <= c2 && mc2 >= c1);
                    }
                }
                false
            })
            .collect();
        out.sort_by_key(|k| (k.row, k.col));
        out.dedup();
        out
    }

    pub(crate) fn selection_has_comment(&self) -> bool {
        !self.comment_keys_in_sel().is_empty()
    }

    pub(crate) fn selection_has_merge(&self) -> bool {
        let rects = self.sel_rects();
        let sh = self.wb.sheet(self.sheet_idx);
        sh.merges.iter().any(|&(mr1, mc1, mr2, mc2)| {
            rects
                .iter()
                .any(|&(sr1, sc1, sr2, sc2)| mr1 <= sr2 && mr2 >= sr1 && mc1 <= sc2 && mc2 >= sc1)
        })
    }

    pub(crate) fn can_merge_selection(&self) -> bool {
        let (r1, c1, r2, c2) = self.sel_rect();
        if r1 == r2 && c1 == c2 {
            return false;
        }
        !self
            .wb
            .sheet(self.sheet_idx)
            .merges
            .iter()
            .any(|&m| m == (r1, c1, r2, c2))
    }

    pub(crate) fn has_pasteable_clip(&self) -> bool {
        self.clip.is_some()
            || self.clip_pic.is_some()
            || crate::office_clipboard::has_pasteable()
    }

    /// 统一打开批注编辑窗口（右键菜单、功能区、顶栏按钮、显示批注共用）：
    /// 提交挂起格内编辑 -> 合并锚点归一化 -> 锁与保护门禁 -> 自动聚焦 + 请求立即重绘。
    pub(crate) fn open_note_editor(&mut self, ctx: Option<&egui::Context>) {
        if self.edit_blocked() {
            return;
        }
        if self.editing.is_some() && !self.finish_pending_edit() {
            return;
        }
        let (r, c) = self.note_anchor(self.sel.0, self.sel.1);
        if !self.write_preflight(&[(r, c)], "编辑批注") {
            return;
        }
        let cur = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .get(&sheetcore::model::CellRef::new(r, c))
            .map(|n| n.text.clone())
            .unwrap_or_default();
        self.note_edit = Some((r, c, cur));
        self.note_edit_sheet = self.sheet_idx;
        self.note_focus_requested = true;
        if let Some(ctx) = ctx {
            ctx.request_repaint();
        }
    }

    /// 上一条/下一条批注：按行列排序在当前表里找
    fn note_step(&mut self, forward: bool) {
        let mut keys: Vec<(u32, u32)> = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .keys()
            .map(|k| (k.row, k.col))
            .collect();
        if keys.is_empty() {
            self.status = "当前表没有批注".into();
            return;
        }
        keys.sort_unstable();
        let cur = self.note_anchor(self.sel.0, self.sel.1);
        let target = if forward {
            keys.iter()
                .find(|k| **k > cur)
                .copied()
                .unwrap_or(keys[0])
        } else {
            keys.iter()
                .rev()
                .find(|k| **k < cur)
                .copied()
                .unwrap_or(*keys.last().unwrap())
        };
        self.sel = target;
        self.sel_end = target;
        self.ensure_visible();
        self.status = format!("批注 {}", cell_name(target.0, target.1));
    }

    /// 显示批注：有就打开编辑框，没有就提示
    fn note_show(&mut self) {
        let (r, c) = self.note_anchor(self.sel.0, self.sel.1);
        let has_cur = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .contains_key(&sheetcore::model::CellRef::new(r, c));
        if has_cur {
            self.open_note_editor(None);
        } else {
            // 找最近的一条批注并跳过去
            let mut keys: Vec<(u32, u32)> = self
                .wb
                .sheet(self.sheet_idx)
                .notes
                .keys()
                .map(|k| (k.row, k.col))
                .collect();
            if keys.is_empty() {
                self.status = "当前表没有批注".into();
                return;
            }
            keys.sort_unstable();
            let t = keys[0];
            self.sel = t;
            self.sel_end = t;
            self.ensure_visible();
            self.open_note_editor(None);
        }
    }

    // ---------------------------------------------------------------- 数据工具

    /// 预测工作表：线性回归 + 新建「预测」工作表
    fn forecast_run(&mut self, range: &str, periods: u32) -> Result<String, String> {
        let Some(raw_rect) = Self::parse_rect(range) else {
            return Err(format!("区域「{range}」看不懂，写成 A1:B13 或 A1:A13"));
        };
        let Some((r1, c1, r2, c2)) = self.clamp_rect_to_used(raw_rect) else {
            return Err("选区内没有数据".into());
        };
        // 数据列：取第一个至少有两个数字的列
        let mut col = None;
        for c in c1..=c2 {
            let n = (r1..=r2)
                .filter(|r| matches!(self.wb.sheet(self.sheet_idx).value(*r, c), Value::Number(_)))
                .count();
            if n >= 2 {
                col = Some(c);
                break;
            }
        }
        let Some(c) = col else {
            return Err("选区内没有至少两个数字的列".into());
        };
        let mut xs: Vec<f64> = Vec::new();
        let mut ys: Vec<f64> = Vec::new();
        for (i, r) in (r1..=r2).enumerate() {
            if let Value::Number(n) = self.wb.sheet(self.sheet_idx).value(r, c) {
                xs.push(i as f64 + 1.0);
                ys.push(n);
            }
        }
        let Some(f) = sheetcore::forecast::linear(&xs, &ys, periods as usize) else {
            return Err("数据太少或横轴没有变化，算不出回归".into());
        };
        // 新建工作表
        let mut name = "预测".to_string();
        let mut k = 2;
        while self.wb.sheets.iter().any(|s| s.name == name) {
            name = format!("预测{k}");
            k += 1;
        }
        let mut sh = sheetcore::Sheet::new(name.clone());
        sh.set(0, 0, Cell { value: Value::Text("期".into()), formula: None });
        sh.set(0, 1, Cell { value: Value::Text("原值".into()), formula: None });
        sh.set(0, 2, Cell { value: Value::Text("拟合值".into()), formula: None });
        sh.set(0, 3, Cell { value: Value::Text("预测值".into()), formula: None });
        for i in 0..ys.len() {
            let r = i as u32 + 1;
            sh.set(r, 0, Cell { value: Value::Number(i as f64 + 1.0), formula: None });
            sh.set(r, 1, Cell { value: Value::Number(ys[i]), formula: None });
            sh.set(r, 2, Cell { value: Value::Number(f.fitted[i]), formula: None });
        }
        let n = ys.len() as u32;
        for (k, v) in f.future.iter().enumerate() {
            let r = n + 1 + k as u32;
            sh.set(r, 0, Cell { value: Value::Number((n + 1 + k as u32) as f64), formula: None });
            sh.set(r, 3, Cell { value: Value::Number(*v), formula: None });
        }
        // 参数与拟合质量写在右侧，方便核对
        let info = [
            ("斜率 b", f.b),
            ("截距 a", f.a),
            ("R²", f.r2),
            ("残差标准差 σ", f.sigma),
            ("95% 区间半宽", 1.96 * f.sigma),
        ];
        sh.set(0, 5, Cell { value: Value::Text("回归参数".into()), formula: None });
        for (i, (k2, v)) in info.iter().enumerate() {
            let r = i as u32 + 1;
            sh.set(r, 5, Cell { value: Value::Text((*k2).into()), formula: None });
            sh.set(r, 6, Cell { value: Value::Number(*v), formula: None });
        }
        self.wb.sheets.push(sh);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let idx = self.wb.sheets.len() - 1;
        self.switch_sheet_view(idx);
        self.sel = (0, 0);
        self.sel_end = (0, 0);
        self.status = format!(
            "已生成「{name}」：y = {:.4} + {:.4}·x，R²={:.3}，外推 {} 期",
            f.a,
            f.b,
            f.r2,
            periods
        );
        Ok(self.status.clone())
    }

    /// 分类汇总
    fn subtotal_run(
        &mut self,
        range: &str,
        key: &str,
        value_cols: &str,
        f: sheetcore::subtotal::SubFn,
    ) -> Result<String, String> {
        let Some(raw_rect) = Self::parse_rect(range) else {
            return Err(format!("区域「{range}」看不懂"));
        };
        let Some(rect) = self.clamp_rect_to_used(raw_rect) else {
            return Err("选区内没有可分组的行".into());
        };
        let key_col = Self::parse_col(key)
            .ok_or_else(|| format!("分组列「{key}」看不懂，写成 A 或 1"))?;
        let mut cols: Vec<u32> = Vec::new();
        for part in value_cols.split([',', '，']) {
            let p = part.trim();
            if p.is_empty() {
                continue;
            }
            let c = Self::parse_col(p).ok_or_else(|| format!("汇总列「{p}」看不懂"))?;
            cols.push(c);
        }
        if cols.is_empty() {
            return Err("至少填一个汇总列".into());
        }
        if self.net.is_some() {
            return Err("分类汇总会插入多行并更新全簿引用。请先断开协作再执行。".into());
        }
        if !self.write_preflight_op(&[], "分类汇总", sheetcore::protection::ProtOp::InsertRows) {
            return Err(self.status.clone());
        }
        let idx = self.sheet_idx;
        // All summary rows are inserted after the first detail row. Capture the
        // union of reference locations that any of the insertions could change.
        let earliest = sheetcore::structural::Structural::InsertRows { at: rect.0 + 2, n: 1 };
        let before = sheetcore::undo::snapshot_structure(&self.wb, idx, &earliest);
        let rep = sheetcore::subtotal::try_subtotal_workbook(&mut self.wb, idx, rect, key_col, &cols, f)?;
        if rep.groups == 0 {
            return Err("选区内没有可分组的行".into());
        }
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb).into();
        let after = before.capture_after(&self.wb);
        self.undo.push_structure("分类汇总", before, after, (idx, self.sel.0, self.sel.1));
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("分类汇总：{} 组，插了 {} 行（{}）", rep.groups, rep.rows, f.label());
        Ok(self.status.clone())
    }

    /// 快速填充
    fn flashfill_run(
        &mut self,
        range: &str,
        src: &str,
        dst: &str,
        aux: &str,
    ) -> Result<String, String> {
        let Some(raw_rect) = Self::parse_rect(range) else {
            return Err(format!("区域「{range}」看不懂"));
        };
        let mut rect = raw_rect;
        if rect.2.saturating_sub(rect.0) > 200_000 {
            if let Some((_, _, ur2, _)) = self.wb.sheet(self.sheet_idx).used_bounds() {
                rect.2 = rect.2.min(ur2.max(rect.0));
            } else {
                return Err("选区内没有数据".into());
            }
        }
        if rect.2.saturating_sub(rect.0) > 200_000 {
            return Err("快速填充单次最多支持 20 万行，请缩小范围".into());
        }
        let src_col = Self::parse_col(src).ok_or_else(|| format!("源列「{src}」看不懂"))?;
        let dst_col = Self::parse_col(dst).ok_or_else(|| format!("目标列「{dst}」看不懂"))?;
        let aux_col = if aux.trim().is_empty() {
            None
        } else {
            Some(Self::parse_col(aux).ok_or_else(|| format!("辅助列「{aux}」看不懂"))?)
        };
        let out = sheetcore::flashfill::flash_fill(
            self.wb.sheet_mut(self.sheet_idx),
            src_col,
            dst_col,
            rect.0,
            rect.2,
            aux_col,
        )?;
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("规则快速填充：{}（填了 {} 格；按已识别规则，不是通用程序合成）", out.rule.label(), out.filled);
        Ok(self.status.clone())
    }

    /// 合并计算
    fn consolidate_run(
        &mut self,
        sources: &str,
        f: sheetcore::consolidate::ConsFn,
        row_labels: bool,
        col_labels: bool,
    ) -> Result<String, String> {
        let mut list: Vec<sheetcore::consolidate::Source> = Vec::new();
        for line in sources.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let (sheet, rng) = match line.rsplit_once('!') {
                Some((s, r)) => {
                    let s = s.trim().trim_matches('\'').replace("''", "'");
                    (s, r.to_string())
                }
                None => (self.wb.sheet(self.sheet_idx).name.clone(), line.to_string()),
            };
            let Some(rect) = Self::parse_rect(&rng) else {
                return Err(format!("引用「{line}」的区域看不懂"));
            };
            list.push(sheetcore::consolidate::Source { sheet, rect });
        }
        if list.is_empty() {
            return Err("至少填一行引用位置，例如 一月!A1:B10".into());
        }
        let at = self.sel;
        let rep = sheetcore::consolidate::consolidate(
            &mut self.wb,
            self.sheet_idx,
            at,
            &list,
            f,
            row_labels,
            col_labels,
        )?;
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!(
            "合并计算（{}）：{} 行 × {} 列，写在 {}",
            f.label(),
            rep.rows,
            rep.cols,
            cell_name(at.0, at.1)
        );
        Ok(self.status.clone())
    }

    /// 列字母或 1 起的列号
    fn parse_col(s: &str) -> Option<u32> {
        let t = s.trim().trim_end_matches("列");
        if t.is_empty() {
            return None;
        }
        if let Ok(n) = t.parse::<u32>() {
            return Some(n.saturating_sub(1));
        }
        let mut v = 0u32;
        for ch in t.chars() {
            if !ch.is_ascii_alphabetic() {
                return None;
            }
            v = v * 26 + (ch.to_ascii_uppercase() as u32 - 'A' as u32 + 1);
        }
        Some(v.saturating_sub(1))
    }

