    // ---------------------------------------------------------------- 切片器

    /// 插入切片器：绑到当前透视表的行字段，列出可勾选的取值
    fn slicer_open(&mut self) {
        let Some((si, spec, _)) = self.pivot_last.clone() else {
            self.status = "先插入一个数据透视表，切片器才有可筛选的字段".into();
            return;
        };
        let field = self
            .wb
            .sheet(si)
            .get(spec.source.0, spec.row_field)
            .map(|c| c.value.display())
            .unwrap_or_else(|| "行字段".into());
        let vals = sheetcore::formula::with_date_system(self.wb.date_system, || {
            sheetcore::pivot::row_values(self.wb.sheet(si), &spec)
        });
        if vals.is_empty() {
            self.status = "这个透视表的行字段没有可筛选的取值".into();
            return;
        }
        let items = vals
            .into_iter()
            .map(|v| {
                let on = !spec.exclude.iter().any(|e| e == &v);
                (v, on)
            })
            .collect();
        self.slicer = Some(SlicerUI {
            pos: egui::pos2(340.0, 320.0),
            sheet: si,
            field,
            items,
        });
        self.status = "切片器：取消勾选即可筛掉该值".into();
    }

    /// 把切片器勾选状态写回透视表规格并重算
    fn slicer_apply(&mut self) {
        let Some(s) = self.slicer.clone() else { return };
        let Some((si, mut spec, _)) = self.pivot_last.clone() else {
            return;
        };
        if si != s.sheet {
            return;
        }
        spec.exclude = s
            .items
            .iter()
            .filter(|(_, on)| !*on)
            .map(|(v, _)| v.clone())
            .collect();
        self.pivot_last = Some((si, spec, self.pivot_last.as_ref().unwrap().2));
        self.refresh_pivot();
        let hidden = self
            .slicer
            .as_ref()
            .map(|s| s.items.iter().filter(|(_, on)| !*on).count())
            .unwrap_or(0);
        self.status = format!("切片器：筛掉 {hidden} 个取值");
    }

    /// 切片器面板（浮在表上，可拖动标题栏）
    fn slicer_window(&mut self, ctx: &egui::Context) {
        let Some(mut s) = self.slicer.clone() else {
            return;
        };
        let mut close = false;
        let mut changed = false;
        let mut cleared = false;
        let id = egui::Id::new("slicer_panel");
        let mut pos = ctx
            .data(|d| d.get_temp::<egui::Pos2>(id.with("pos")))
            .unwrap_or(s.pos);
        let area = egui::Area::new(id.with("area"))
            .order(egui::Order::Middle)
            .fixed_pos(pos)
            .show(ctx, |ui| {
                egui::Frame::window(&ctx.style())
                    .fill(Color32::WHITE)
                    .stroke(Stroke::new(1.0, ui_kit::BORDER))
                    .corner_radius(4.0)
                    .inner_margin(egui::Margin::same(0))
                    .show(ui, |ui| {
                        ui.set_width(210.0);
                        let (trect, tresp) = ui.allocate_exact_size(
                            egui::vec2(210.0, 26.0),
                            egui::Sense::click_and_drag(),
                        );
                        ui.painter()
                            .rect_filled(trect, 0.0, Color32::from_rgb(243, 242, 241));
                        ui.painter().text(
                            egui::pos2(trect.left() + 8.0, trect.center().y),
                            egui::Align2::LEFT_CENTER,
                            format!("切片器：{}", s.field),
                            FontId::proportional(12.0),
                            ui_kit::TEXT,
                        );
                        let crect = Rect::from_min_size(
                            egui::pos2(trect.right() - 22.0, trect.top() + 4.0),
                            egui::vec2(18.0, 18.0),
                        );
                        let cresp = ui.interact(crect, id.with("close"), egui::Sense::click());
                        let k = 4.0;
                        let st = Stroke::new(1.1, ui_kit::TEXT);
                        ui.painter().line_segment(
                            [crect.center() + egui::vec2(-k, -k), crect.center() + egui::vec2(k, k)],
                            st,
                        );
                        ui.painter().line_segment(
                            [crect.center() + egui::vec2(k, -k), crect.center() + egui::vec2(-k, k)],
                            st,
                        );
                        if cresp.clicked() {
                            close = true;
                        }
                        if tresp.dragged() {
                            pos += tresp.drag_delta();
                        }
                        egui::Frame::none()
                            .inner_margin(egui::Margin::same(8))
                            .show(ui, |ui| {
                                egui::ScrollArea::vertical()
                                    .max_height(220.0)
                                    .show(ui, |ui| {
                                        for (v, on) in s.items.iter_mut() {
                                            if ui.checkbox(on, v.as_str()).changed() {
                                                changed = true;
                                            }
                                        }
                                    });
                                ui.add_space(4.0);
                                ui.horizontal(|ui| {
                                    if ui_kit::secondary_button(ui, "清除筛选").clicked() {
                                        cleared = true;
                                    }
                                    if ui_kit::primary_button(ui, "应用").clicked() {
                                        changed = true;
                                    }
                                });
                            });
                    });
            });
        let _ = area;
        ctx.data_mut(|d| d.insert_temp(id.with("pos"), pos));
        s.pos = pos;
        self.slicer = Some(s);
        if cleared {
            if let Some(sl) = self.slicer.as_mut() {
                for (_, on) in sl.items.iter_mut() {
                    *on = true;
                }
            }
            self.slicer_apply();
            return;
        }
        if changed {
            self.slicer_apply();
        }
        if close {
            self.slicer = None;
            self.status = "已关闭切片器（透视表保留当前筛选）".into();
        }
    }

    // ---------------------------------------------------------------- 文本框

    /// 本表文本框的屏幕矩形（相对表格原点；调用方自己加 gx(0)/gy(0)）
    fn tb_rect_px(&self, tb: &sheetcore::textbox::TextBox) -> (f32, f32, f32, f32) {
        let (cols, rows) = self.view_axes();
        tb.rect_px(&cols, &rows)
    }

    /// 新建文本框（像素矩形，相对表格原点）：写模型 + 记撤销 + 打开编辑框
    fn tb_create(&mut self, x: f32, y: f32, w: f32, h: f32) {
        let (cols, rows) = self.view_axes();
        let before = self.wb.sheet(self.sheet_idx).textboxes.clone();
        let mut tb = sheetcore::textbox::TextBox {
            text: String::new(),
            ..Default::default()
        };
        let max_id = before.iter().map(|t| t.id).max().unwrap_or(1);
        tb.id = max_id + 1;
        tb.name = format!("文本框 {}", before.len() + 1);
        tb.set_rect_px(&cols, &rows, x.max(0.0), y.max(0.0), w.max(60.0), h.max(24.0));
        let sh = self.wb.sheet_mut(self.sheet_idx);
        sh.textboxes.push(tb);
        sh.textboxes_dirty = true;
        let idx = sh.textboxes.len() - 1;
        let after = sh.textboxes.clone();
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.undo.push(sheetcore::undo::Action {
            label: "插入文本框".into(),
            merges: None,
            deltas: Vec::new(),
            focus: (self.sheet_idx, self.sel.0, self.sel.1),
            snap_before: None,
            snap_after: None,
            by_site: 0,
            pictures: None,
            shapes: Some(sheetcore::undo::ShapeEdit {
                sheet: self.sheet_idx,
                before,
                after,
            }),
            refresh_sizes: None,
        });
        self.tb_sel = Some(idx);
        self.status = "已插入文本框：在对话框里填文字".into();
    }

    /// 选中的文本框进编辑对话框
    fn tb_open_edit(&mut self, idx: usize) {
        if let Some(tb) = self.wb.sheet(self.sheet_idx).textboxes.get(idx).cloned() {
            self.tb_dlg = Some((idx, tb));
        }
    }

    /// 对话框「确定」：整组前后进撤销栈
    fn tb_commit(&mut self, idx: usize, draft: sheetcore::textbox::TextBox) {
        let before = self.wb.sheet(self.sheet_idx).textboxes.clone();
        let mut changed = false;
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            if let Some(tb) = sh.textboxes.get_mut(idx) {
                if *tb != draft {
                    *tb = draft;
                    changed = true;
                }
                sh.textboxes_dirty |= changed;
            }
        }
        if !changed {
            return;
        }
        let after = self.wb.sheet(self.sheet_idx).textboxes.clone();
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.undo.push(sheetcore::undo::Action {
            label: "修改文本框".into(),
            merges: None,
            deltas: Vec::new(),
            focus: (self.sheet_idx, self.sel.0, self.sel.1),
            snap_before: None,
            snap_after: None,
            by_site: 0,
            pictures: None,
            shapes: Some(sheetcore::undo::ShapeEdit {
                sheet: self.sheet_idx,
                before,
                after,
            }),
            refresh_sizes: None,
        });
        self.status = "文本框已更新".into();
    }

    /// 文本框拖动开始：手柄优先（缩放），其次点在框里（移动），绘制模式从起点画新框。
    /// 坐标是表格坐标（像素，相对表格原点）。
    fn tb_drag_begin(
        &mut self,
        pos: egui::Pos2,
        rects: &[(usize, (f32, f32, f32, f32))],
        tbs: &[sheetcore::textbox::TextBox],
    ) -> Option<TbDrag> {
        // 1) 已选中文本框的手柄
        if let Some(i) = self.tb_sel {
            if let Some((_, (x, y, w, h))) = rects.iter().find(|(k, _)| *k == i) {
                let r = Rect::from_min_size(egui::pos2(*x, *y), Vec2::new(*w, *h));
                if let Some(mode) = chart_handle_at(r, pos) {
                    return Some(TbDrag {
                        idx: i,
                        mode,
                        start: pos,
                        rect: (*x, *y, x + w, y + h),
                        before: tbs.to_vec(),
                    });
                }
            }
        }
        // 2) 绘制模式
        if self.tb_insert {
            return Some(TbDrag {
                idx: usize::MAX,
                mode: 1,
                start: pos,
                rect: (pos.x, pos.y, pos.x + 40.0, pos.y + 20.0),
                before: tbs.to_vec(),
            });
        }
        // 3) 点在框里：选中并整体移动
        for (i, (x, y, w, h)) in rects.iter().rev() {
            let r = Rect::from_min_size(egui::pos2(*x, *y), Vec2::new(*w, *h));
            if r.contains(pos) {
                self.tb_sel = Some(*i);
                return Some(TbDrag {
                    idx: *i,
                    mode: 0,
                    start: pos,
                    rect: (*x, *y, x + w, y + h),
                    before: tbs.to_vec(),
                });
            }
        }
        None
    }

    /// 拖动中：按手柄方向改矩形，写回模型（松手才进撤销栈）
    fn tb_drag_update(&mut self, d: &TbDrag, pos: egui::Pos2) {
        let dx = pos.x - d.start.x;
        let dy = pos.y - d.start.y;
        let (mut x0, mut y0, mut x1, mut y1) = d.rect;
        match d.mode {
            0 => {
                x0 += dx;
                x1 += dx;
                y0 += dy;
                y1 += dy;
            }
            1 => {
                x0 += dx;
                y0 += dy;
            }
            2 => y0 += dy,
            3 => {
                x1 += dx;
                y0 += dy;
            }
            4 => x1 += dx,
            5 => {
                x1 += dx;
                y1 += dy;
            }
            6 => y1 += dy,
            7 => {
                x0 += dx;
                y1 += dy;
            }
            _ => x0 += dx,
        }
        if x1 - x0 < 24.0 || y1 - y0 < 16.0 {
            return;
        }
        let (cols, rows) = self.view_axes();
        let sh = self.wb.sheet_mut(self.sheet_idx);
        if d.idx == usize::MAX {
            let mut tb = sheetcore::textbox::TextBox {
                name: format!("文本框 {}", sh.textboxes.len() + 1),
                id: sh.textboxes.iter().map(|t| t.id).max().unwrap_or(1) + 1,
                ..Default::default()
            };
            tb.set_rect_px(&cols, &rows, x0, y0, x1 - x0, y1 - y0);
            sh.textboxes.push(tb);
            sh.textboxes_dirty = true;
            self.tb_sel = Some(sh.textboxes.len() - 1);
        } else if let Some(tb) = sh.textboxes.get_mut(d.idx) {
            tb.set_rect_px(&cols, &rows, x0, y0, x1 - x0, y1 - y0);
            sh.textboxes_dirty = true;
        }
    }

    /// 松手：变化进撤销栈；绘制模式结束后直接打开编辑框
    fn tb_drag_end(&mut self, mut d: TbDrag) {
        if d.idx == usize::MAX {
            // 绘制模式：拖出来的就是最后一个
            if let Some(last) = self.wb.sheet(self.sheet_idx).textboxes.len().checked_sub(1) {
                d.idx = last;
                self.tb_sel = Some(last);
            }
        }
        let after = self.wb.sheet(self.sheet_idx).textboxes.clone();
        if after != d.before {
            let label = if d.mode == 0 { "移动文本框" } else { "调整文本框大小" };
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.undo.push(sheetcore::undo::Action {
                label: label.into(),
                merges: None,
                deltas: Vec::new(),
                focus: (self.sheet_idx, self.sel.0, self.sel.1),
                snap_before: None,
                snap_after: None,
                by_site: 0,
                pictures: None,
                shapes: Some(sheetcore::undo::ShapeEdit {
                sheet: self.sheet_idx,
                    before: d.before,
                    after,
                }),
                refresh_sizes: None,
            });
            self.status = format!("{label}（保存后写回 Excel）");
        }
        if self.tb_insert {
            self.tb_insert = false;
            self.tb_open_edit(d.idx);
        }
    }

    /// 删除选中的文本框
    fn tb_delete(&mut self, idx: usize) {
        let before = self.wb.sheet(self.sheet_idx).textboxes.clone();
        if idx >= before.len() {
            return;
        }
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.textboxes.remove(idx);
            sh.textboxes_dirty = true;
        }
        let after = self.wb.sheet(self.sheet_idx).textboxes.clone();
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.undo.push(sheetcore::undo::Action {
            label: "删除文本框".into(),
            merges: None,
            deltas: Vec::new(),
            focus: (self.sheet_idx, self.sel.0, self.sel.1),
            snap_before: None,
            snap_after: None,
            by_site: 0,
            pictures: None,
            shapes: Some(sheetcore::undo::ShapeEdit {
                sheet: self.sheet_idx,
                before,
                after,
            }),
            refresh_sizes: None,
        });
        self.tb_sel = None;
        self.status = "已删除文本框".into();
    }

    /// 文本框对话框：文字 / 字号 / 粗斜体 / 颜色 / 填充 / 边框 / 对齐 / 换行
    fn tb_dialog(&mut self, ctx: &egui::Context) {
        let Some((idx, mut d)) = self.tb_dlg.clone() else {
            return;
        };
        let mut open = true;
        let mut ok = false;
        let mut del = false;
        ui_kit::window(ctx, "设置文本框", 420.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui_kit::field(ui, "文字", |ui| {
                    ui.add(
                        egui::TextEdit::multiline(&mut d.text)
                            .desired_rows(3)
                            .desired_width(300.0)
                            .hint_text("可以分多行"),
                    );
                });
                ui.horizontal(|ui| {
                    ui_kit::field(ui, "字号", |ui| {
                        let mut v = d.size as f64;
                        if ui_kit::spin(ui, &mut v, 6.0, 72.0, 1.0, 64.0) {
                            d.size = v as f32;
                        }
                    });
                    ui.checkbox(&mut d.bold, "粗体");
                    ui.checkbox(&mut d.italic, "斜体");
                    ui.checkbox(&mut d.wrap, "自动换行");
                });
                ui.horizontal(|ui| {
                    ui.label(egui::RichText::new("对齐").size(12.0).weak());
                    for (v, name) in [(0u8, "左"), (1, "中"), (2, "右")] {
                        if ui.radio(d.align == v, name).clicked() {
                            d.align = v;
                        }
                    }
                });
                ui.add_space(2.0);
                let mut swatch_row = |ui: &mut egui::Ui, title: &str, cur: &mut Option<[u8; 3]>| {
                    ui.horizontal(|ui| {
                        ui.allocate_ui_with_layout(
                            egui::Vec2::new(64.0, 20.0),
                            egui::Layout::right_to_left(egui::Align::Center),
                            |ui| {
                                ui.label(egui::RichText::new(title).size(12.0).weak());
                            },
                        );
                        if ui.radio(cur.is_none(), "无").clicked() {
                            *cur = None;
                        }
                        for c in [
                            [0x00, 0x00, 0x00],
                            [0xFF, 0xFF, 0xFF],
                            [0xFF, 0xF2, 0xCC],
                            [0xDE, 0xEB, 0xF7],
                            [0x00, 0xB0, 0x50],
                            [0xFF, 0x00, 0x00],
                        ] {
                            let (r, resp) = ui
                                .allocate_exact_size(egui::Vec2::splat(18.0), egui::Sense::click());
                            ui.painter().rect_filled(
                                r.shrink(1.0),
                                2.0,
                                egui::Color32::from_rgb(c[0], c[1], c[2]),
                            );
                            ui.painter().rect_stroke(
                                r,
                                2.0,
                                egui::Stroke::new(1.0, ui_kit::BORDER),
                                egui::StrokeKind::Inside,
                            );
                            if *cur == Some(c) {
                                ui.painter().rect_stroke(
                                    r.expand(1.0),
                                    2.0,
                                    egui::Stroke::new(2.0, ui_kit::ACCENT),
                                    egui::StrokeKind::Inside,
                                );
                            }
                            if resp.clicked() {
                                *cur = Some(c);
                            }
                        }
                    });
                };
                let mut fill = d.fill;
                swatch_row(ui, "填充", &mut fill);
                d.fill = fill;
                let mut line = d.line;
                swatch_row(ui, "边框", &mut line);
                d.line = line;
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "删除").clicked() {
                        del = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });
        if del {
            self.tb_delete(idx);
            self.tb_dlg = None;
            return;
        }
        if ok {
            self.tb_commit(idx, d);
            self.tb_dlg = None;
            return;
        }
        self.tb_dlg = if open { Some((idx, d)) } else { None };
    }

    /// 「创建/编辑迷你图」对话框
    fn spark_dialog(&mut self, ctx: &egui::Context) {
        let Some(d0) = self.spark_dlg.clone() else { return };
        let mut d = d0;
        let mut open = true;
        let mut ok = false;
        let editing = !d.edit.is_empty();
        let title = if editing { "编辑迷你图" } else { "创建迷你图" };
        ui_kit::window(ctx, title, 460.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui_kit::field(ui, "数据范围", |ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut d.source)
                            .desired_width(300.0)
                            .hint_text("A1:E1（可带表名：Sheet2!A1:E1）"),
                    );
                });
                ui_kit::field(ui, "位置范围", |ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut d.location)
                            .desired_width(300.0)
                            .hint_text("F1"),
                    );
                });
                ui.add_space(4.0);
                ui.label(egui::RichText::new("类型").size(12.0).weak());
                ui.horizontal(|ui| {
                    for k in [
                        sheetcore::sparkline::SparkKind::Line,
                        sheetcore::sparkline::SparkKind::Column,
                        sheetcore::sparkline::SparkKind::WinLoss,
                    ] {
                        if ui.radio(d.kind == k, k.label()).clicked() {
                            d.kind = k;
                        }
                    }
                    // 右侧缩略预览：改什么都立刻能看到
                    let (rect, _) = ui.allocate_exact_size(
                        egui::Vec2::new(150.0, 22.0),
                        egui::Sense::hover(),
                    );
                    ui.painter().rect(
                        rect,
                        2.0,
                        egui::Color32::WHITE,
                        egui::Stroke::new(1.0, ui_kit::BORDER),
                        egui::StrokeKind::Inside,
                    );
                    let mut prev = sheetcore::sparkline::Sparkline {
                        kind: d.kind,
                        color: d.color,
                        markers: d.markers,
                        high: d.high,
                        low: d.low,
                        first: d.first,
                        last: d.last,
                        negative: d.negative,
                        axis: d.axis,
                        ..Default::default()
                    };
                    prev.empty = d.empty;
                    crate::spark_view::preview(&ui.painter().clone(), rect.shrink(3.0), &prev);
                });
                ui.add_space(2.0);
                ui.label(egui::RichText::new("颜色").size(12.0).weak());
                ui.horizontal(|ui| {
                    let palette: [[u8; 3]; 8] = [
                        [0x37, 0x60, 0x92],
                        [0x00, 0x70, 0xC0],
                        [0x00, 0xB0, 0x50],
                        [0xFF, 0xC0, 0x00],
                        [0xFF, 0x00, 0x00],
                        [0x70, 0x30, 0xA0],
                        [0x59, 0x59, 0x59],
                        [0x00, 0x00, 0x00],
                    ];
                    for c in palette {
                        let (rect, resp) =
                            ui.allocate_exact_size(egui::Vec2::splat(18.0), egui::Sense::click());
                        let on = d.color == c;
                        ui.painter().rect_filled(
                            rect.shrink(1.0),
                            2.0,
                            egui::Color32::from_rgb(c[0], c[1], c[2]),
                        );
                        if on {
                            ui.painter().rect_stroke(
                                rect,
                                2.0,
                                egui::Stroke::new(2.0, ui_kit::ACCENT),
                                egui::StrokeKind::Inside,
                            );
                        }
                        if resp.clicked() {
                            d.color = c;
                        }
                    }
                });
                ui.add_space(4.0);
                ui.label(egui::RichText::new("显示").size(12.0).weak());
                ui.horizontal(|ui| {
                    ui.checkbox(&mut d.markers, "标记");
                    ui.checkbox(&mut d.high, "高点");
                    ui.checkbox(&mut d.low, "低点");
                    ui.checkbox(&mut d.first, "首点");
                    ui.checkbox(&mut d.last, "末点");
                    ui.checkbox(&mut d.negative, "负点");
                    ui.checkbox(&mut d.axis, "坐标轴");
                });
                ui_kit::field(ui, "空单元格", |ui| {
                    egui::ComboBox::from_id_salt("spark_empty")
                        .selected_text(d.empty.label())
                        .width(220.0)
                        .show_ui(ui, |ui| {
                            for e in [
                                sheetcore::sparkline::EmptyAs::Gap,
                                sheetcore::sparkline::EmptyAs::Zero,
                                sheetcore::sparkline::EmptyAs::Connect,
                            ] {
                                if ui.selectable_label(d.empty == e, e.label()).clicked() {
                                    d.empty = e;
                                }
                            }
                        });
                });
                if !d.msg.is_empty() {
                    ui.add_space(2.0);
                    ui.label(
                        egui::RichText::new(&d.msg)
                            .size(11.0)
                            .color(egui::Color32::from_rgb(192, 0, 0)),
                    );
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });
        if ok {
            match self.spark_commit(&d) {
                Ok(_) => {
                    eprintln!(
                        "[spark] 已写 {} 条，dirty={}",
                        self.wb.sheet(self.sheet_idx).sparklines.len(),
                        self.wb.sheet(self.sheet_idx).sparklines_dirty
                    );
                    self.spark_dlg = None;
                }
                Err(e) => {
                    d.msg = e;
                    self.spark_dlg = Some(d);
                }
            }
        } else {
            self.spark_dlg = if open { Some(d) } else { None };
        }
    }

    /// 监视窗口：列出当前表的公式单元格
    fn watch_window(&mut self, ctx: &egui::Context) {
        if !self.watch_open {
            return;
        }
        let mut open = true;
        let mut jump: Option<(u32, u32)> = None;
        let rows: Vec<(u32, u32, String, String)> = {
            let sh = self.wb.sheet(self.sheet_idx);
            let mut out = Vec::new();
            if let Some((r1, c1, r2, c2)) = sh.used_bounds() {
                'scan: for r in r1..=r2.min(r1 + 2000) {
                    for c in c1..=c2.min(c1 + 200) {
                        if let Some(cell) = sh.get(r, c) {
                            if let Some(f) = &cell.formula {
                                out.push((r, c, f.to_string(), cell.value.display()));
                                if out.len() >= 200 { break 'scan; }
                            }
                        }
                    }
                }
            }
            out
        };
        ui_kit::window(ctx, "监视窗口", 560.0)
            .open(&mut open)
            .resizable(true)
            .default_size([560.0, 320.0])
            .show(ctx, |ui| {
                if rows.is_empty() {
                    ui.label("当前表没有公式单元格。");
                }
                egui::ScrollArea::vertical().max_height(280.0).show(ui, |ui| {
                    egui::Grid::new("watch_grid").num_columns(3).spacing([12.0, 4.0]).show(ui, |ui| {
                        ui.label(egui::RichText::new("单元格").size(11.0).weak());
                        ui.label(egui::RichText::new("公式").size(11.0).weak());
                        ui.label(egui::RichText::new("值").size(11.0).weak());
                        ui.end_row();
                        for (r, c, f, v) in &rows {
                            if ui.link(cell_name(*r, *c)).clicked() {
                                jump = Some((*r, *c));
                            }
                            ui.label(egui::RichText::new(f).monospace().size(11.0));
                            ui.label(egui::RichText::new(v).size(11.0));
                            ui.end_row();
                        }
                    });
                });
            });
        if let Some((r, c)) = jump {
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        self.watch_open = open;
    }

    /// 缩放对话框
    fn zoom_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut z) = self.zoom_dlg else { return };
        let mut open = true;
        let mut ok = false;
        ui_kit::window(ctx, "缩放", 240.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui_kit::field(ui, "百分比", |ui| {
                    let mut v = (z * 100.0).round() as f64;
                    if ui_kit::spin(ui, &mut v, 10.0, 400.0, 5.0, 80.0) {
                        z = v as f32 / 100.0;
                    }
                });
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });
        if ok {
            self.set_zoom(z);
            self.zoom_dlg = None;
        } else if open {
            self.zoom_dlg = Some(z);
        } else {
            self.zoom_dlg = None;
        }
    }

    fn size_dialog(&mut self, ctx: &egui::Context) {
        let Some((is_col, mut value)) = self.size_dlg else { return };
        let mut open = true;
        let mut apply = false;
        let title = if is_col { "列宽" } else { "行高" };
        ui_kit::window(ctx, title, 260.0).open(&mut open).show(ctx, |ui| {
            ui.add_space(4.0);
            ui_kit::field(ui, "像素", |ui| {
                let (lo, hi) = if is_col { (8.0, 1500.0) } else { (4.0, 409.0) };
                let mut vv = value as f64;
                if ui_kit::spin(ui, &mut vv, lo, hi, 1.0, 72.0) {
                    value = vv as f32;
                }
            });
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "确定").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    open = false;
                }
            });
        });
        if apply {
            let (r1, c1, r2, c2) = self.sel_rect();
            if is_col {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.cols.set_many((c1..=c2).map(|c| (c, value)));
                sh.layout_dirty = true;
                self.status = format!("列宽 {:.0} 像素", value);
            } else {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.rows.set_many((r1..=r2).map(|r| (r, value)));
                sh.layout_dirty = true;
                self.status = format!("行高 {:.0} 像素", value);
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            open = false;
        }
        if !open {
            self.size_dlg = None;
        }
    }

    fn backstage_ui(&mut self, ctx: &egui::Context) {
        if !self.backstage {
            return;
        }
        let screen = ctx.screen_rect();
        let top = ui_kit::TITLE_H;
        let mut close = ctx.input(|i| i.key_pressed(Key::Escape));
        let mut action: Option<u8> = None;
        egui::Area::new(egui::Id::new("backstage"))
            .order(egui::Order::Foreground)
            .fixed_pos(egui::pos2(screen.left(), top))
            .show(ctx, |ui| {
                let h = (screen.height() - top).max(100.0);
                ui.set_min_size(Vec2::new(screen.width(), h));
                let full = Rect::from_min_size(ui.min_rect().min, Vec2::new(screen.width(), h));
                ui.painter().rect_filled(full, 0.0, Color32::WHITE);
                let _block = ui.interact(full, egui::Id::new("bs_block"), Sense::click());
                let nav = Rect::from_min_size(full.min, Vec2::new(240.0, h));
                ui.painter()
                    .rect_filled(nav, 0.0, ui_kit::PAGE_BG);
                ui.painter().rect_filled(
                    Rect::from_min_max(
                        egui::pos2(nav.right(), nav.top()),
                        egui::pos2(nav.right() + 1.0, nav.bottom()),
                    ),
                    0.0,
                    ui_kit::CARD_BORDER,
                );
                // 返回箭头
                let back = Rect::from_min_size(nav.min + Vec2::new(10.0, 10.0), Vec2::splat(32.0));
                let bresp = ui.interact(back, egui::Id::new("bs_back"), Sense::click());
                if bresp.hovered() {
                    ui.painter().rect_filled(back, 5.0, ui_kit::HOVER_ON_PAGE);
                }
                let bc = back.center();
                let st = egui::Stroke::new(1.4, ui_kit::TEXT);
                ui.painter()
                    .line_segment([egui::pos2(bc.x + 5.0, bc.y - 5.0), egui::pos2(bc.x - 4.0, bc.y)], st);
                ui.painter()
                    .line_segment([egui::pos2(bc.x - 4.0, bc.y), egui::pos2(bc.x + 5.0, bc.y + 5.0)], st);
                if bresp.on_hover_text("返回（Esc）").clicked() {
                    close = true;
                }
                let items: [(&str, u8); 8] = [
                    ("开始主页", 7),
                    ("信息", 0),
                    ("新建", 1),
                    ("打开", 2),
                    ("打印", 3),
                    ("导出", 4),
                    ("共享", 5),
                    ("关闭", 6),
                ];
                let mut y = nav.top() + 56.0;
                for (label, page) in items {
                    let r = Rect::from_min_size(
                        egui::pos2(nav.left() + 10.0, y),
                        Vec2::new(nav.width() - 20.0, 34.0),
                    );
                    let resp = ui.interact(r, egui::Id::new(("bs_nav", page)), Sense::click());
                    let active = self.backstage_page == page;
                    if active {
                        ui.painter().rect(
                            r,
                            6.0,
                            Color32::WHITE,
                            Stroke::new(1.0, ui_kit::CARD_BORDER),
                            egui::StrokeKind::Inside,
                        );
                        ui.painter().rect_filled(
                            Rect::from_min_size(egui::pos2(r.left() + 4.0, r.center().y - 8.0), Vec2::new(3.0, 16.0)),
                            1.5,
                            ui_kit::ACCENT,
                        );
                    } else if resp.hovered() {
                        ui.painter().rect_filled(r, 6.0, ui_kit::HOVER_ON_PAGE);
                    }
                    if page == 7 {
                        ui_kit::draw_clean_icon(
                            ui.painter(),
                            Rect::from_center_size(egui::pos2(r.left() + 20.0, r.center().y), Vec2::splat(15.0)),
                            0,
                            ui_kit::BRAND_NAVY,
                        );
                        ui_kit::paint_medium(
                            ui.painter(),
                            egui::pos2(r.left() + 36.0, r.center().y),
                            Align2::LEFT_CENTER,
                            label,
                            12.5,
                            ui_kit::BRAND_NAVY,
                        );
                    } else {
                        ui.painter().text(
                            egui::pos2(r.left() + 16.0, r.center().y),
                            Align2::LEFT_CENTER,
                            label,
                            if active { ui_kit::medium_in(ctx, 12.5) } else { FontId::proportional(12.5) },
                            ui_kit::TEXT,
                        );
                    }
                    if resp.clicked() {
                        if page == 7 {
                            action = Some(7);
                        } else {
                            self.backstage_page = page;
                        }
                    }
                    y += if page == 7 { 42.0 } else { 37.0 };
                }
                // 内容区
                let content = Rect::from_min_max(
                    egui::pos2(nav.right() + 44.0, nav.top() + 40.0),
                    egui::pos2(full.right() - 44.0, full.bottom() - 24.0),
                );
                ui.scope_builder(
                    egui::UiBuilder::new()
                        .max_rect(content)
                        .layout(egui::Layout::top_down(egui::Align::Min)),
                    |ui| {
                        ui.spacing_mut().item_spacing = Vec2::new(6.0, 8.0);
                        let name = self
                            .wb
                            .path
                            .as_ref()
                            .and_then(|p| p.file_name())
                            .map(|s| s.to_string_lossy().to_string())
                            .unwrap_or_else(|| "未命名.xlsx".into());
                        match self.backstage_page {
                            0 => {
                                ui.label(egui::RichText::new("信息").size(26.0).color(ui_kit::TEXT));
                                ui.add_space(6.0);
                                ui.label(egui::RichText::new(&name).size(16.0).color(ui_kit::TEXT));
                                let path = self
                                    .wb
                                    .path
                                    .as_ref()
                                    .map(|p| p.display().to_string())
                                    .unwrap_or_else(|| "未保存".into());
                                ui.label(egui::RichText::new(path).size(12.0).color(ui_kit::TEXT_WEAK));
                                ui.add_space(10.0);
                                ui.separator();
                                ui.add_space(6.0);
                                ui.label(
                                    egui::RichText::new(format!(
                                        "工作表：{} 张    单元格：{} 个    外部链接：{}",
                                        self.wb.sheets.len(),
                                        self.wb.sheet(self.sheet_idx).len(),
                                        self.wb.links.len()
                                    ))
                                    .size(12.0),
                                );
                                if let Some(p) = self.wb.path.clone() {
                                    if let Ok(md) = std::fs::metadata(&p) {
                                        let size = md.len() as f64 / 1024.0;
                                        ui.label(
                                            egui::RichText::new(format!("文件大小：{size:.1} KB"))
                                                .size(12.0),
                                        );
                                    }
                                }
                                ui.add_space(8.0);
                                ui.separator();
                                ui.add_space(6.0);
                                ui.horizontal_wrapped(|ui| {
                                    if ui_kit::secondary_button(ui, "另存为…").clicked() {
                                        self.save(true);
                                        close = true;
                                    }
                                    if ui_kit::secondary_button(ui, "导出 PDF…").clicked() {
                                        self.export_pdf_dialog();
                                        close = true;
                                    }
                                    if ui_kit::secondary_button(ui, "保护工作表…").clicked() {
                                        self.protect_dlg = Some(ProtectDlg::default());
                                        close = true;
                                    }
                                    if ui_kit::secondary_button(ui, "检查更新").clicked() {
                                        self.check_update();
                                    }
                                    if ui_kit::secondary_button(ui, "设为默认应用").clicked() {
                                        self.register_file_association(true);
                                    }
                                });
                                ui.add_space(6.0);
                                if self.wb.encryption.is_some() {
                                    ui.label(
                                        egui::RichText::new("已设置打开密码（保存后为加密文件）")
                                            .size(12.5)
                                            .color(ui_kit::ACCENT),
                                    );
                                    if ui.button("取消打开密码").clicked() {
                                        self.wb.encryption = None;
                                        self.wb.dirty = true;
                                        self.status = "已取消打开密码，保存后生效".into();
                                    }
                                } else if ui.button("用密码加密…").clicked() {
                                    self.enc_dlg = Some((String::new(), String::new(), String::new()));
                                }

                            }
                            1 => {
                                ui.label(egui::RichText::new("新建工作簿").font(ui_kit::ui_bold_in(ctx, 22.0)).color(ui_kit::TEXT));
                                ui.add_space(12.0);
                                let previews = templates::previews();
                                ui.horizontal_wrapped(|ui| {
                                    ui.spacing_mut().item_spacing = Vec2::new(14.0, 14.0);
                                    for (ti, tpl) in templates::ALL.iter().enumerate() {
                                        let (card_r, resp) = ui.allocate_exact_size(Vec2::new(224.0, 132.0), Sense::click());
                                        if resp.hovered() {
                                            ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
                                        }
                                        Self::paint_template_card(ui.painter(), ti, card_r, tpl, &previews[ti], resp.hovered());
                                        if resp.clicked() {
                                            action = Some(10 + ti as u8);
                                        }
                                    }
                                });
                            }
                            2 => {
                                ui.label(egui::RichText::new("打开").font(ui_kit::ui_bold_in(ctx, 22.0)).color(ui_kit::TEXT));
                                ui.add_space(6.0);
                                if ui_kit::primary_button(ui, "浏览…").clicked() {
                                    action = Some(2);
                                }
                                ui.add_space(12.0);
                                ui.label(
                                    egui::RichText::new("最近使用的工作簿")
                                        .font(ui_kit::medium_in(ctx, 13.0))
                                        .color(ui_kit::TEXT),
                                );
                                let rec_entries = self.ensure_recent_cache().to_vec();
                                for ent in rec_entries.into_iter().take(8) {
                                    let r = ui.allocate_exact_size(
                                        Vec2::new(content.width().min(580.0), 30.0),
                                        Sense::click(),
                                    );
                                    if r.1.hovered() {
                                        ui.painter().rect_filled(r.0, 5.0, ui_kit::HOVER);
                                        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
                                    }
                                    ui.painter().text(
                                        egui::pos2(r.0.left() + 10.0, r.0.center().y),
                                        Align2::LEFT_CENTER,
                                        &ent.name,
                                        ui_kit::medium_in(ctx, 12.0),
                                        ui_kit::TEXT,
                                    );
                                    ui.painter().text(
                                        egui::pos2(r.0.left() + 268.0, r.0.center().y),
                                        Align2::LEFT_CENTER,
                                        &ent.short_dir,
                                        FontId::proportional(11.0),
                                        ui_kit::TEXT_WEAK,
                                    );
                                    if r.1.clicked() {
                                        self.open_any(ent.path);
                                        close = true;
                                    }
                                }
                            }
                            3 => {
                                ui.label(egui::RichText::new("打印").size(26.0).color(ui_kit::TEXT));
                                ui.add_space(10.0);
                                if ui_kit::primary_button(ui, "打印预览").clicked() {
                                    self.preview_page = 0;
                                    self.print_preview = true;
                                    close = true;
                                }
                            }
                            4 => {
                                ui.label(egui::RichText::new("导出").size(26.0).color(ui_kit::TEXT));
                                ui.add_space(10.0);
                                if ui_kit::primary_button(ui, "创建 PDF").clicked() {
                                    self.export_pdf_dialog();
                                    close = true;
                                }
                            }
                            5 => {
                                ui.label(egui::RichText::new("局域网实时共享").size(26.0).color(ui_kit::TEXT));
                                ui.add_space(10.0);
                                if self.net.is_none() {
                                    ui.horizontal(|ui| {
                                        if ui_kit::primary_button(ui, "共享到局域网").clicked() {
                                            self.start_host();
                                            self.members_open = true;
                                            close = true;
                                        }
                                        if ui_kit::secondary_button(ui, "加入其他用户会话…").clicked() {
                                            self.members_open = true;
                                            close = true;
                                        }
                                    });
                                } else {
                                    let hosting = self.net.as_ref().map(|n| n.hosting).unwrap_or(false);
                                    let addr = if hosting {
                                        Some(format!("{}:{}", local_ip_hint(), self.active_net_port()))
                                    } else {
                                        self.wb
                                            .path
                                            .as_ref()
                                            .and_then(|p| session_lock::read(p))
                                            .map(|i| i.host)
                                    };
                                    ui.label(
                                        egui::RichText::new(format!(
                                            "{} · 在线 {} 人",
                                            if hosting { "正在主持共享" } else { "已加入协作" },
                                            self.peers_list.len().max(1)
                                        ))
                                        .size(14.0)
                                        .color(ui_kit::ACCENT),
                                    );
                                    if let Some(addr) = addr {
                                        ui.add_space(4.0);
                                        ui.horizontal(|ui| {
                                            ui.label(
                                                egui::RichText::new(format!("协作地址：{addr}"))
                                                    .monospace()
                                                    .size(12.5)
                                                    .color(ui_kit::TEXT),
                                            );
                                            if ui_kit::secondary_button(ui, "复制地址").clicked() {
                                                ctx.copy_text(addr.clone());
                                                self.status = format!("已复制协作地址：{addr}");
                                            }
                                        });
                                    }
                                    ui.add_space(8.0);
                                    ui.horizontal(|ui| {
                                        if ui_kit::primary_button(ui, "打开协作面板").clicked() {
                                            self.members_open = true;
                                            close = true;
                                        }
                                        if ui_kit::secondary_button(ui, "断开协作").clicked() {
                                            self.leave_session();
                                        }
                                    });
                                }
                                ui.add_space(10.0);
                                if ui_kit::secondary_button(ui, "放行防火墙").clicked() {
                                    self.open_firewall_port();
                                }
                            }
                            _ => {
                                ui.label(egui::RichText::new("关闭").size(26.0).color(ui_kit::TEXT));
                                ui.add_space(10.0);
                                if ui_kit::primary_button(ui, "关闭当前工作簿").clicked() {
                                    action = Some(6);
                                }
                                ui.add_space(6.0);
                                ui.label(egui::RichText::new("有未保存的改动时会先提示保存。").size(12.0).color(ui_kit::TEXT_WEAK));
                            }
                        }
                    },
                );
            });
        match action {
            Some(1) => {
                self.open_in_new_tab(PathBuf::new());
                close = true;
            }
            Some(2) => {
                self.open();
                close = true;
            }
            Some(6) => {
                let idx = self.active_tab;
                self.request_close_tab(idx);
                close = true;
            }
            Some(7) => {
                if self.finish_pending_edit() {
                    self.show_start = true;
                    close = true;
                }
            }
            Some(k @ 10..=19) => {
                let ti = (k - 10) as usize;
                self.create_from_template(ti);
                close = true;
            }
            _ => {}
        }
        if close {
            self.backstage = false;
            self.ribbon_tab = 1;
        }
    }

    /// 追踪引用单元格：给选区里的公式格画「来源 → 本格」的箭头
    fn trace_precedents(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let used = self.wb.sheet(self.sheet_idx).used_bounds();
        let mut arrows: Vec<((u32, u32, u32, u32), (u32, u32))> = Vec::new();
        for r in r1..=r2.min(r1 + 20) {
            for c in c1..=c2.min(c1 + 20) {
                let Some(f) = self
                    .wb
                    .sheet(self.sheet_idx)
                    .get(r, c)
                    .and_then(|x| x.formula.clone())
                else {
                    continue;
                };
                for rect in sheetcore::formula::deps::refs_of(&self.wb, self.sheet_idx, &f) {
                    if rect.sheet != self.sheet_idx || rect.r1 < 0 || rect.c1 < 0 {
                        continue;
                    }
                    let (mut fr1, mut fc1) = (rect.r1 as u32, rect.c1 as u32);
                    let (mut fr2, mut fc2) = (rect.r2.max(0) as u32, rect.c2.max(0) as u32);
                    // 整列/整行引用会是巨大区域：裁到已用范围，否则箭头算到几千列外去
                    if let Some((_ur1, _uc1, ur2, uc2)) = used {
                        fr2 = fr2.min(ur2);
                        fc2 = fc2.min(uc2);
                        if fr1 > fr2 {
                            fr1 = fr2;
                        }
                        if fc1 > fc2 {
                            fc1 = fc2;
                        }
                    }
                    arrows.push(((fr1, fc1, fr2, fc2), (r, c)));
                    if arrows.len() >= 64 {
                        break;
                    }
                }
                if arrows.len() >= 64 {
                    break;
                }
            }
        }
        if arrows.is_empty() {
            self.status = "选中的单元格没有公式引用".into();
        } else {
            let n = arrows.len();
            self.trace_arrows = arrows;
            self.status = format!("已标出 {n} 条引用（移去箭头可清除）");
        }
    }

    /// 追踪从属单元格：找出哪些公式引用了选区，画「本格 → 它们」的箭头
    fn trace_dependents(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let keys: Vec<(u32, u32, String)> = self
            .wb
            .sheet(self.sheet_idx)
            .iter()
            .filter_map(|(k, cell)| {
                cell.formula
                    .as_ref()
                    .map(|f| (k.row, k.col, f.to_string()))
            })
            .collect();
        let mut arrows: Vec<((u32, u32, u32, u32), (u32, u32))> = Vec::new();
        for (r, c, f) in keys {
            let refs = sheetcore::formula::deps::refs_of(&self.wb, self.sheet_idx, &f);
            let hit = refs.iter().any(|x| {
                x.sheet == self.sheet_idx
                    && x.r1 <= r2 as i64
                    && x.r2 >= r1 as i64
                    && x.c1 <= c2 as i64
                    && x.c2 >= c1 as i64
            });
            if hit {
                arrows.push(((r1, c1, r2, c2), (r, c)));
                if arrows.len() >= 64 {
                    break;
                }
            }
        }
        if arrows.is_empty() {
            self.status = "没有公式引用选中的单元格".into();
        } else {
            let n = arrows.len();
            self.trace_arrows = arrows;
            self.status = format!("已标出 {n} 个从属单元格");
        }
    }

    /// 取（或新建）一个 dxf 索引；所有表保持同一份 dxfs，保证索引一致
    /// 当前选区所在的表格（用于上下文“表设计”页签）
    fn table_at_sel(&self) -> Option<sheetcore::table::Table> {
        let (r, c) = self.sel;
        self.wb
            .sheet(self.sheet_idx)
            .tables
            .iter()
            .find(|t| r >= t.range.0 && r <= t.range.2 && c >= t.range.1 && c <= t.range.3)
            .cloned()
    }

    /// 表设计页的“填充计算列”：把当前选区所在列已有的计算列公式
    /// 填到该表其余数据行。是明确的生产入口，不是只有测试调用。
    fn fill_table_calculated_column(&mut self) {
        self.commit_edit(None);
        let Some(t) = self.table_at_sel() else {
            self.status = "先把光标放在表格里".into();
            return;
        };
        let Some(ci) = self.sel.1.checked_sub(t.range.1).map(|c| c as usize) else {
            self.status = "当前列不在表格中".into();
            return;
        };
        let Some(col_name) = t.columns.get(ci).cloned() else {
            self.status = "当前列不在表格中".into();
            return;
        };
        let data_start = if t.header_row { t.range.0 + 1 } else { t.range.0 };
        let data_end = if t.totals_row {
            t.range.2.saturating_sub(1)
        } else {
            t.range.2
        };
        if data_start > data_end {
            self.status = "表格没有数据行".into();
            return;
        }
        let keys: Vec<(u32, u32)> = (data_start..=data_end)
            .map(|r| (r, t.range.1 + ci as u32))
            .collect();
        if !self.write_preflight(&keys, "填充计算列") {
            return;
        }
        let txn = self.txn_begin(&keys);
        let n = sheetcore::table::fill_calculated_column(
            self.wb.sheet_mut(self.sheet_idx),
            &t.name,
            &col_name,
        );
        if n == 0 {
            self.txn_end("填充计算列", txn);
            self.status = format!("列 {col_name} 没有可复制的公式");
            return;
        }
        self.txn_end("填充计算列", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已填充 {n} 个计算列单元格");
        let keys: Vec<(usize, u32, u32)> =
            keys.into_iter().map(|(r, c)| (self.sheet_idx, r, c)).collect();
        self.recalc_and_broadcast(&keys);
    }


    fn chart_at_sel(&self) -> Option<sheetcore::charts::Chart> {
        let i = self.chart_sel?;
        self.wb.sheet(self.sheet_idx).charts.get(i).cloned()
    }

    fn cf_dxf(&mut self, bold: bool, color: Option<[u8; 3]>, fill: Option<[u8; 3]>) -> usize {
        let want = sheetcore::cf::Dxf { bold, italic: false, color, fill, font: None, num_fmt: None, border: None };
        let mut idx = None;
        if let Some(s0) = self.wb.sheets.first() {
            if let Some(i) = s0.cf.dxfs.iter().position(|d| *d == want) {
                idx = Some(i);
            }
        }
        match idx {
            Some(i) => i,
            None => {
                let i = self.wb.sheets.first().map(|s| s.cf.dxfs.len()).unwrap_or(0);
                for sh in self.wb.sheets.iter_mut() {
                    sh.cf.dxfs.push(want.clone());
                }
                i
            }
        }
    }

    /// 给选区加一条条件格式规则
    fn add_cf(&mut self, kind: sheetcore::cf::CfKind) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let sheet = self.wb.sheet_mut(self.sheet_idx);
        // 新规则排在最后：priority 取现有最大值 +1（Excel 新建规则也是追加到末尾）
        let next = sheet
            .cf
            .blocks
            .iter()
            .flat_map(|b| b.rules.iter().map(|r| r.priority))
            .max()
            .unwrap_or(0)
            + 1;
        sheet.cf.blocks.push(sheetcore::cf::CfBlock {
            ranges: vec![(r1, c1, r2, c2)],
            rules: vec![sheetcore::cf::CfRule { kind, stop: false, priority: next }],
        });
        sheet.cf_dirty = true;
        self.wb.dirty = true;
        self.cf_stats_gen = u64::MAX;
        self.status = "已添加条件格式".into();
    }

    /// 清除与选区相交的条件格式
    fn clear_cf(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let sheet = self.wb.sheet_mut(self.sheet_idx);
        let before = sheet.cf.blocks.len();
        sheet.cf.blocks.retain(|b| {
            !b.ranges
                .iter()
                .any(|(a, bb, cc, d)| *a <= r2 && *cc >= r1 && *bb <= c2 && *d >= c1)
        });
        if sheet.cf.blocks.len() != before {
            sheet.cf_dirty = true;
            self.wb.dirty = true;
            self.cf_stats_gen = u64::MAX;
            self.status = "已清除所选范围的条件格式".into();
        } else {
            self.status = "所选范围没有条件格式".into();
        }
    }

